def _env_or(*names: str) -> Optional[str]:
    for name in names:
        value = os.getenv(name)
        if value is not None and value != "":
            return value
    return None


def _load_cli_config(path: Optional[str]) -> dict[str, Any]:
    if not path:
        return {}
    primary = Path(path).expanduser()
    candidates = [primary]
    if primary == Path(DEFAULT_CONFIG_PATH).expanduser():
        candidates.append(Path(LEGACY_CONFIG_PATH).expanduser())
    for config_path in candidates:
        if not config_path.exists():
            continue
        try:
            payload = json.loads(config_path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            continue
        if isinstance(payload, dict):
            return payload
    return {}


def _option_was_provided(argv: list[str], option_name: str) -> bool:
    return any(token == option_name or token.startswith(f"{option_name}=") for token in argv)


def _apply_cli_config_defaults(args: argparse.Namespace, argv: list[str]) -> argparse.Namespace:
    config = _load_cli_config(args.config)
    mapping: dict[str, str] = {
        "service_base_url": "service_base_url",
        "service_token": "service_token",
        "service_timeout_seconds": "service_timeout_seconds",
    }
    for arg_name, config_key in mapping.items():
        option_name = f"--{arg_name.replace("_", "-")}"
        if _option_was_provided(argv, option_name):
            continue
        current_value = getattr(args, arg_name)
        if current_value is not None:
            continue
        if config_key in config:
            setattr(args, arg_name, config[config_key])
    if args.service_timeout_seconds is None:
        args.service_timeout_seconds = DEFAULT_SERVICE_TIMEOUT_SECONDS
    else:
        args.service_timeout_seconds = float(args.service_timeout_seconds)
    return args


def _split_browser_args_env(value: Optional[str]) -> tuple[str, ...]:
    text = str(value or "").strip()
    if not text:
        return ()
    try:
        import shlex
        return tuple(shlex.split(text))
    except ValueError:
        return tuple(part for part in text.split() if part)


def _env_flag(name: str, default: bool) -> bool:
    value = os.getenv(name)
    if value is None:
        return default
    return value.strip().lower() in {"1", "true", "yes", "on"}


def _configure_logging(debug: bool) -> None:
    import logging

    level = logging.DEBUG if debug else logging.WARNING
    logging.basicConfig(
        level=level,
        format="%(asctime)s | %(levelname)s | %(name)s | %(message)s",
        force=True,
    )


def build_service(args: argparse.Namespace) -> ChatGPTAutomationService:
    resolved_profile_dir = str(resolve_profile_dir(getattr(args, "_browser_profile_dir", None) or getattr(args, "profile_dir", None)))
    settings = ChatGPTAutomationSettings(
        project_url=args.project_url,
        email=args.email,
        password=args.password,
        profile_dir=resolved_profile_dir,
        headless=args.headless,
        use_patchright=not args.use_playwright,
        browser_channel=args.browser_channel,
        password_file=args.password_file,
        disable_fedcm=not args.enable_fedcm,
        fail_fast_on_challenge=_env_flag("CHATGPT_FAIL_FAST_ON_CHALLENGE", False)
        or _env_flag("PROMPTBRANCH_RELEASE_LIVE_FAIL_FAST_ON_CHALLENGE", False),
        filter_no_sandbox=not args.keep_no_sandbox,
        max_retries=args.max_retries,
        retry_backoff_seconds=args.retry_backoff_seconds,
        slow_mo_ms=getattr(args, "slow_mo_ms", 0) or 0,
        debug=bool(getattr(args, "debug", False)),
        debug_artifact_dir=os.getenv("CHATGPT_DEBUG_ARTIFACT_DIR", "debug_artifacts"),
        dom_diagnostic_mode=os.getenv("CHATGPT_DOM_DIAGNOSTIC_MODE", "light"),
        pause_before_fill=bool(getattr(args, "pause_before_fill", False)),
        pause_after_fill=bool(getattr(args, "pause_after_fill", False)),
        pause_before_submit=bool(getattr(args, "pause_before_submit", False)),
        extra_browser_args=_split_browser_args_env(os.getenv("CHATGPT_BROWSER_EXTRA_ARGS")),
    )
    return ChatGPTAutomationService(settings)


def build_backend(args: argparse.Namespace) -> CommandBackend:
    resolved_profile_dir = str(resolve_profile_dir(getattr(args, "profile_dir", None)))
    args.profile_dir = resolved_profile_dir
    # Browser profiles and Promptbranch workflow state are separate authority
    # surfaces.  The browser still uses the resolved --profile-dir / repo-local
    # .pb_profile path, but joined multi-repo projects must read/write
    # conversation, task, workspace, and artifact state from the shared
    # project-scoped profile unless the operator explicitly supplied
    # --profile-dir as an override.
    conversation_state = _state_store_from_args(args)
    if getattr(args, "debug_browser", False):
        # Local visual debugging intentionally bypasses the Docker service so the
        # operator can inspect a headed localhost browser.  Docker remains the
        # default/release target when this flag is absent.
        args.service_base_url = None
        args.headless = False
        args.debug = True
        if getattr(args, "slow_mo_ms", 0) <= 0:
            args.slow_mo_ms = 100
    if args.service_base_url:
        return ServiceBackend(
            base_url=args.service_base_url,
            token=args.service_token,
            timeout=args.service_timeout_seconds,
            project_url=args.project_url,
            conversation_state=conversation_state,
        )
    return DirectBackend(
        build_service(args),
        conversation_state=conversation_state,
        project_url=args.project_url,
    )


async def cmd_login_check(backend: CommandBackend, args: argparse.Namespace) -> int:
    result = await backend.login_check(keep_open=args.keep_open)
    print(json.dumps(result, indent=2, ensure_ascii=False))
    return 0


def _project_list_payload(result: Any, *, current_only: bool = False) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    payload = dict(result) if isinstance(result, dict) else {"ok": False, "projects": []}
    raw_projects = payload.get("projects") if isinstance(payload.get("projects"), list) else []
    projects = [item for item in raw_projects if isinstance(item, dict)]
    if current_only:
        projects = [item for item in projects if item.get("is_current")]
    payload["projects"] = projects
    payload["count"] = len(projects)
    if current_only:
        payload["current_only"] = True
    return projects, payload


def _project_source_list_payload(result: Any) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    payload = dict(result) if isinstance(result, dict) else {"ok": False, "sources": []}
    raw_sources = payload.get("sources") if isinstance(payload.get("sources"), list) else []
    sources = [item for item in raw_sources if isinstance(item, dict)]
    payload["sources"] = sources
    payload["count"] = len(sources)
    payload["read_routing"] = source_list_read_routing(payload)
    return sources, payload


def _project_cache_from_args(args: argparse.Namespace) -> GlobalProjectCache:
    return GlobalProjectCache()


def _cache_project_list_result(args: argparse.Namespace, result: Any) -> dict[str, Any] | None:
    raw_projects = result.get("projects") if isinstance(result, dict) and isinstance(result.get("projects"), list) else None
    if not raw_projects:
        return None
    cache = _project_cache_from_args(args)
    return cache.store_projects([item for item in raw_projects if isinstance(item, dict)])


def _resolve_project_from_cache(args: argparse.Namespace, target: str) -> dict[str, Any] | None:
    cache = _project_cache_from_args(args)
    cached = cache.resolve(target)
    if not isinstance(cached, dict):
        return None
    project_url = str(cached.get("project_home_url") or cached.get("url") or "")
    if not project_url:
        return None
    return {
        "ok": True,
        "action": "project_resolve",
        "resolved_via": "global_cache",
        "project_url": project_url,
        "project_name": cached.get("name") or project_name_from_url(project_url),
        "project_slug": cached.get("project_slug"),
        "cache_file": str(cache.path),
    }


async def cmd_project_list(backend: CommandBackend, args: argparse.Namespace) -> int:
    result = await backend.list_projects(keep_open=args.keep_open)
    cache_payload = _cache_project_list_result(args, result)
    projects, payload = _project_list_payload(result, current_only=args.current)
    if cache_payload is not None:
        payload["cache_file"] = cache_payload.get("cache_file", str(_project_cache_from_args(args).path)) if isinstance(cache_payload, dict) else str(_project_cache_from_args(args).path)
        payload["cache_updated_at"] = cache_payload.get("updated_at") if isinstance(cache_payload, dict) else None
    if args.json:
        print(json.dumps(payload, indent=2, ensure_ascii=False))
        return 0
    if not projects:
        print("(no current project found)" if args.current else "(no projects found)")
        return 0
    for item in projects:
        marker = "*" if item.get("is_current") else " "
        name = str(item.get("name") or "<unnamed>")
        url = str(item.get("url") or "")
        print(f"{marker} {name}	{url}")
    return 0


def _choose_project_from_list(projects: list[dict[str, Any]], *, filter_text: Optional[str] = None) -> dict[str, Any]:
    filtered = projects
    if filter_text:
        needle = filter_text.strip().lower()
        filtered = [item for item in projects if needle in str(item.get("name") or "").lower()]
    if not filtered:
        raise ValueError("no projects matched the requested filter")
    if len(filtered) == 1:
        return filtered[0]

    print("Available projects:", file=sys.stderr)
    current_index = None
    for idx, item in enumerate(filtered, start=1):
        is_current = bool(item.get("is_current"))
        if is_current and current_index is None:
            current_index = idx
        marker = "*" if is_current else " "
        name = str(item.get("name") or "<unnamed>")
        url = str(item.get("url") or "")
        print(f"  {idx:>2}. {marker} {name}\t{url}", file=sys.stderr)

    prompt = "Select project number"
    if current_index is not None:
        prompt += f" [{current_index}]"
    prompt += ": "

    while True:
        print(prompt, end="", file=sys.stderr, flush=True)
        selection = input().strip()
        if not selection and current_index is not None:
            return filtered[current_index - 1]
        if selection.isdigit():
            index = int(selection)
            if 1 <= index <= len(filtered):
                return filtered[index - 1]
        exact = [item for item in filtered if str(item.get("name") or "") == selection]
        if len(exact) == 1:
            return exact[0]
        print("Invalid selection. Enter a number from the list or an exact visible project name.", file=sys.stderr)


def _selected_project_home_url(snapshot: dict[str, Any]) -> Optional[str]:
    candidate = snapshot.get('resolved_project_home_url') if isinstance(snapshot, dict) else None
    if isinstance(candidate, str):
        return project_home_url_from_url(candidate)
    return None


def _chat_list_payload(result: Any, *, current_conversation_url: Optional[str] = None) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    payload = dict(result) if isinstance(result, dict) else {"ok": False, "chats": []}
    raw_chats = payload.get("chats") if isinstance(payload.get("chats"), list) else []
    chats = [item for item in raw_chats if isinstance(item, dict)]
    current_id = conversation_id_from_url(current_conversation_url)
    normalized: list[dict[str, Any]] = []
    for item in chats:
        chat = dict(item)
        conversation_url = str(chat.get('conversation_url') or '')
        chat_id = str(chat.get('id') or conversation_id_from_url(conversation_url) or '')
        chat['id'] = chat_id
        chat['conversation_url'] = conversation_url
        chat['title'] = str(chat.get('title') or '(untitled)')
        chat['is_current'] = bool(current_id and chat_id == current_id)
        normalized.append(chat)
    if current_id and not any(str(item.get('id') or '') == current_id for item in normalized):
        normalized.append({
            'id': current_id,
            'title': '(current task)',
            'conversation_url': current_conversation_url,
            'is_current': True,
            'source': 'current_state',
        })
    payload['chats'] = normalized
    payload['count'] = len(normalized)
    payload['current_conversation_url'] = current_conversation_url
    source_counts = dict(payload.get('source_counts') or {}) if isinstance(payload.get('source_counts'), dict) else {}
    visibility_status, indexed_count, recent_count, indexed_observation_count = _task_list_visibility_status(source_counts, normalized)
    payload['source_counts'] = source_counts
    payload['visibility_status'] = visibility_status
    payload['indexed_task_count'] = indexed_count
    payload['indexed_observation_count'] = indexed_observation_count
    payload['recent_state_count'] = recent_count
    return normalized, payload



_INDEXED_TASK_SOURCES = {"snorlax", "project_endpoint", "dom", "history", "history_detail", "current_page"}
_LOCAL_TASK_SOURCES = {"recent_state", "current_state"}


def _indexed_observation_count(source_counts: dict[str, Any]) -> int:
    total = 0
    for source in _INDEXED_TASK_SOURCES:
        try:
            total += int(source_counts.get(source) or 0)
        except (TypeError, ValueError):
            continue
    return total


def _unique_indexed_task_count(chats: list[dict[str, Any]]) -> int:
    """Count unique task entries backed by indexed/backend observations.

    `source_counts` counts observations per source. When the same task appears
    in both snorlax and DOM, summing those source counts overstates the number
    of indexed tasks. The public `indexed_task_count` diagnostic is therefore
    derived from the merged task list, excluding local-only fallback rows.
    """
    indexed_ids: set[str] = set()
    anonymous_indexed_rows = 0
    for item in chats:
        if not isinstance(item, dict):
            continue
        source = str(item.get("source") or "").strip()
        if source in _LOCAL_TASK_SOURCES:
            continue
        if source and source not in _INDEXED_TASK_SOURCES:
            continue
        task_id = str(item.get("id") or conversation_id_from_url(item.get("conversation_url")) or "").strip()
        if task_id:
            indexed_ids.add(task_id)
        else:
            anonymous_indexed_rows += 1
    return len(indexed_ids) + anonymous_indexed_rows


def _task_list_visibility_status(source_counts: dict[str, Any], chats: list[dict[str, Any]]) -> tuple[str, int, int, int]:
    indexed_count = _unique_indexed_task_count(chats)
    indexed_observations = _indexed_observation_count(source_counts)
    recent_count = 0
    try:
        recent_count = int(source_counts.get("recent_state") or 0)
    except (TypeError, ValueError):
        recent_count = 0
    if indexed_count > 0:
        return "indexed", indexed_count, recent_count, indexed_observations
    if recent_count > 0 or any(str(item.get("source") or "") == "recent_state" for item in chats):
        return "recent_state_only", indexed_count, recent_count, indexed_observations
    return "missing", indexed_count, recent_count, indexed_observations

def _normalize_chat_title(value: str) -> str:
    return re.sub(r'\s+', ' ', (value or '')).strip().casefold()


def _looks_like_conversation_id(value: str) -> bool:
    return bool(re.fullmatch(r'[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}', str(value or '').strip(), re.IGNORECASE))


def _select_chat_from_list(chats: list[dict[str, Any]], target: str) -> dict[str, Any]:
    if not chats:
        raise ValueError('no chats were found for the current project')

    if str(target).isdigit():
        index = int(str(target))
        if 1 <= index <= len(chats):
            return chats[index - 1]
        raise ValueError(f'chat index out of range: {target}')

    exact_id = [item for item in chats if str(item.get('id') or '') == target]
    if len(exact_id) == 1:
        return exact_id[0]

    prefix_id = [item for item in chats if str(item.get('id') or '').startswith(str(target))]
    if len(prefix_id) == 1:
        return prefix_id[0]
    if len(prefix_id) > 1:
        raise ValueError(f'multiple chats matched id prefix: {target}')

    normalized_target = _normalize_chat_title(str(target))
    exact_title = [item for item in chats if _normalize_chat_title(str(item.get('title') or '')) == normalized_target]
    if len(exact_title) == 1:
        return exact_title[0]
    if len(exact_title) > 1:
        raise ValueError(f'multiple chats matched exact title: {target}')

    contains_title = [item for item in chats if normalized_target in _normalize_chat_title(str(item.get('title') or ''))]
    if len(contains_title) == 1:
        return contains_title[0]
    if len(contains_title) > 1:
        raise ValueError(f'multiple chats matched title fragment: {target}')

    raise ValueError(f'chat not found: {target}')


async def _resolve_chat_target(
    backend: Any,
    args: argparse.Namespace,
    target: Optional[str],
    *,
    keep_open: bool = False,
) -> dict[str, Any]:
    snapshot = backend.state_snapshot()
    current_conversation_url = snapshot.get('conversation_url') if isinstance(snapshot, dict) else None
    if not target:
        if isinstance(current_conversation_url, str) and current_conversation_url:
            return {
                'title': snapshot.get('conversation_id') or '(current chat)',
                'conversation_url': current_conversation_url,
                'id': conversation_id_from_url(current_conversation_url),
                'is_current': True,
            }
        raise ValueError('no current task is selected; run "pb task list" then "pb task use <task>", or pass "--task <task>"')

    if _looks_like_chatgpt_url(target) and conversation_id_from_url(target):
        return {
            'title': target,
            'conversation_url': target,
            'id': conversation_id_from_url(target),
            'is_current': bool(current_conversation_url and target == current_conversation_url),
        }

    if _looks_like_conversation_id(str(target)):
        project_home_url = _selected_project_home_url(snapshot) if isinstance(snapshot, dict) else None
        if project_home_url:
            conversation_url = (project_home_url[:-len('/project')] if project_home_url.endswith('/project') else project_home_url.rstrip('/')) + f'/c/{target}'
            return {
                'title': target,
                'conversation_url': conversation_url,
                'id': str(target),
                'is_current': bool(current_conversation_url and conversation_id_from_url(current_conversation_url) == str(target)),
            }

    if str(target).isdigit():
        project_home_url = _selected_project_home_url(snapshot) if isinstance(snapshot, dict) else None
        cache_loader = getattr(backend, 'task_list_cache', None)
        if callable(cache_loader):
            try:
                cached_chats = cache_loader(project_home_url, max_age_seconds=900.0)
            except TypeError:
                cached_chats = cache_loader(project_home_url)
            except Exception:
                cached_chats = []
            if cached_chats:
                try:
                    selected = _select_chat_from_list(cached_chats, str(target))
                    selected['_selected_from_task_list_cache'] = True
                    return selected
                except ValueError:
                    # A stale/short cache must not block live resolution.
                    pass

    async def load_chats(*, include_history_fallback: bool) -> list[dict[str, Any]]:
        result = await backend.list_project_chats(
            keep_open=keep_open,
            include_history_fallback=include_history_fallback,
        )
        chats, _ = _chat_list_payload(
            result,
            current_conversation_url=current_conversation_url if isinstance(current_conversation_url, str) else None,
        )
        return chats

    # Most `pb task use <n>` calls refer to an entry already present in the
    # indexed snorlax/DOM list. Resolve against that lightweight list first so
    # selection does not repeat the expensive global conversation-history scan.
    lightweight_chats = await load_chats(include_history_fallback=False)
    try:
        return _select_chat_from_list(lightweight_chats, str(target))
    except ValueError as light_error:
        if str(target).isdigit():
            # Numeric indexes beyond the lightweight list may require the deep
            # task list. Fall through to full enumeration only for that case.
            pass
        elif lightweight_chats and (
            str(light_error).startswith('multiple chats matched')
            or str(light_error).startswith('chat not found')
        ):
            pass
        elif lightweight_chats:
            raise

    full_chats = await load_chats(include_history_fallback=True)
    return _select_chat_from_list(full_chats, str(target))


async def cmd_chat_list(backend: Any, args: argparse.Namespace) -> int:
    snapshot = backend.state_snapshot()
    project_home_url = _selected_project_home_url(snapshot)
    if not project_home_url:
        print('error: no current project is selected', file=sys.stderr)
        return 2

    # v0.1.46: route task reads backend-first. Always collect the lightweight
    # indexed/project payload first. The expensive history fallback is allowed
    # only when explicitly requested and backend/indexed evidence is missing.
    initial_result = await backend.list_project_chats(
        keep_open=args.keep_open,
        include_history_fallback=False,
    )
    chats, payload = _chat_list_payload(initial_result, current_conversation_url=snapshot.get('conversation_url'))
    initial_routing = task_list_read_routing(
        payload,
        history_fallback_requested=bool(getattr(args, 'deep_history', False)),
        history_fallback_used=False,
    )
    history_fallback_used = False

    if bool(getattr(args, 'deep_history', False)) and not initial_routing.get('backend_first_satisfied'):
        fallback_result = await backend.list_project_chats(
            keep_open=args.keep_open,
            include_history_fallback=True,
        )
        chats, payload = _chat_list_payload(fallback_result, current_conversation_url=snapshot.get('conversation_url'))
        history_fallback_used = True

    payload['read_routing'] = task_list_read_routing(
        payload,
        history_fallback_requested=bool(getattr(args, 'deep_history', False)),
        history_fallback_used=history_fallback_used,
    )

    cache_writer = getattr(backend, 'remember_task_list', None)
    if callable(cache_writer):
        try:
            cache_writer(project_home_url, chats)
        except Exception:
            pass
    if args.json:
        print(json.dumps(payload, indent=2, ensure_ascii=False))
        return 0
    if not chats:
        print('(no chats found)')
        return 0
    for idx, item in enumerate(chats, start=1):
        marker = '*' if item.get('is_current') else ' '
        print(f"{idx:>3}. {marker} {item.get('title') or '(untitled)'}	{item.get('id') or ''}	{item.get('conversation_url') or ''}")
    source_counts = payload.get('source_counts') if isinstance(payload.get('source_counts'), dict) else {}
    if source_counts:
        source_summary = ', '.join(f"{name}={source_counts.get(name) or 0}" for name in ('snorlax', 'project_endpoint', 'dom', 'history', 'history_detail', 'current_page', 'recent_state') if name in source_counts)
        visibility = payload.get('visibility_status') or 'unknown'
        routing = payload.get('read_routing') if isinstance(payload.get('read_routing'), dict) else {}
        route_summary = f" route={routing.get('selected_path')}" if routing else ''
        print(f"# count={payload.get('count', len(chats))} visibility={visibility}{route_summary} sources: {source_summary}")
        if payload.get('history_supplement_used') or history_fallback_used:
            print('# history_supplement_used=true')
    return 0


async def cmd_chat_use(backend: Any, args: argparse.Namespace) -> int:
    store = _state_store_from_args(args)
    try:
        selected = await _resolve_chat_target(backend, args, args.target, keep_open=args.keep_open)
    except ValueError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1
    conversation_url = str(selected.get('conversation_url') or '')
    project_home_url = project_home_url_from_url(conversation_url)
    if not project_home_url:
        print('error: could not determine project for the selected chat', file=sys.stderr)
        return 2
    store.remember(project_home_url, conversation_url)
    snapshot = store.snapshot(project_home_url)
    payload = {
        'ok': True,
        'action': 'chat_use',
        'project_home_url': snapshot.get('resolved_project_home_url'),
        'conversation_url': snapshot.get('conversation_url'),
        'conversation_id': snapshot.get('conversation_id'),
        'chat_title': selected.get('title'),
        'selected_from_task_list_cache': bool(selected.get('_selected_from_task_list_cache')),
    }
    print(json.dumps(payload, indent=2, ensure_ascii=False))
    return 0


async def cmd_chat_leave(backend: Any, args: argparse.Namespace) -> int:
    snapshot_before = backend.state_snapshot()
    backend.clear_conversation()
    snapshot_after = backend.state_snapshot()
    payload = {
        'ok': True,
        'action': 'chat_leave',
        'project_home_url': snapshot_after.get('resolved_project_home_url') or snapshot_before.get('resolved_project_home_url'),
        'conversation_url': snapshot_after.get('conversation_url'),
        'conversation_id': snapshot_after.get('conversation_id'),
    }
    print(json.dumps(payload, indent=2, ensure_ascii=False))
    return 0


def _render_chat_payload(payload: dict[str, Any]) -> str:
    lines = [
        f"title={payload.get('title') or '(untitled)'}",
        f"conversation_id={payload.get('conversation_id') or 'none'}",
        f"conversation_url={payload.get('conversation_url') or 'none'}",
        f"turn_count={payload.get('turn_count') or 0}",
        '',
    ]
    turns = payload.get('turns') if isinstance(payload.get('turns'), list) else []
    for turn in turns:
        role = str(turn.get('role') or 'unknown')
        index = turn.get('index')
        lines.append(f"[{index}] {role}")
        lines.append(str(turn.get('text') or ''))
        lines.append('')
    return '\n'.join(lines).rstrip() + '\n'


def _one_line_preview(value: Any, *, max_chars: int = 96) -> str:
    text = re.sub(r"\s+", " ", str(value or "")).strip()
    if len(text) <= max_chars:
        return text
    return text[: max_chars - 1].rstrip() + "…"


def _message_text_from_any_payload(raw: dict[str, Any]) -> str:
    """Extract text from either normalized turns or raw ChatGPT message payloads."""
    direct = raw.get("text")
    if direct is not None:
        return str(direct)

    content = raw.get("content") if isinstance(raw.get("content"), dict) else None
    if not content:
        return ""

    parts = content.get("parts")
    if isinstance(parts, list):
        rendered: list[str] = []
        for part in parts:
            if isinstance(part, str):
                rendered.append(part)
            elif isinstance(part, dict):
                if isinstance(part.get("text"), str):
                    rendered.append(part["text"])
                elif isinstance(part.get("content"), str):
                    rendered.append(part["content"])
        return "\n".join(item for item in rendered if item).strip()

    if isinstance(content.get("text"), str):
        return content["text"]
    return ""


def _role_from_any_payload(raw: dict[str, Any]) -> str:
    author = raw.get("author") if isinstance(raw.get("author"), dict) else {}
    return str(raw.get("role") or author.get("role") or "").strip().lower()


def _turns_from_raw_conversation_mapping(payload: dict[str, Any]) -> list[dict[str, Any]]:
    """Best-effort fallback for raw conversation payloads returned by live backends."""
    mapping = payload.get("mapping") if isinstance(payload.get("mapping"), dict) else {}
    current_node = payload.get("current_node") or payload.get("currentNode")
    if not mapping or not current_node:
        return []

    node_ids: list[str] = []
    seen: set[str] = set()
    cursor = str(current_node)
    while cursor and cursor not in seen:
        seen.add(cursor)
        node_ids.append(cursor)
        node = mapping.get(cursor)
        if not isinstance(node, dict):
            break
        parent = node.get("parent")
        cursor = str(parent) if parent is not None else ""

    turns: list[dict[str, Any]] = []
    for node_id in reversed(node_ids):
        node = mapping.get(node_id)
        if not isinstance(node, dict):
            continue
        message = node.get("message") if isinstance(node.get("message"), dict) else None
        if not message:
            continue
        role = _role_from_any_payload(message)
        if role in {"", "system", "tool"}:
            continue
        text = _message_text_from_any_payload(message)
        if not text:
            continue
        turns.append({
            "index": len(turns) + 1,
            "id": node_id,
            "role": role,
            "text": text,
            "create_time": message.get("create_time") or message.get("createTime") or node.get("create_time") or node.get("createTime"),
            "status": message.get("status") or node.get("status") or "complete",
        })
    return turns


def _normalized_chat_turns(payload: dict[str, Any]) -> list[dict[str, Any]]:
    raw_turns = payload.get("turns")
    if isinstance(raw_turns, list):
        turns: list[dict[str, Any]] = []
        for raw in raw_turns:
            if not isinstance(raw, dict):
                continue
            role = _role_from_any_payload(raw)
            text = _message_text_from_any_payload(raw)
            if not role or not text:
                continue
            turns.append({
                "index": raw.get("index") or len(turns) + 1,
                "id": raw.get("id"),
                "role": role,
                "text": text,
                "create_time": raw.get("create_time") or raw.get("createTime"),
                "status": raw.get("status") or "complete",
            })
        return turns

    raw_messages = payload.get("messages")
    if isinstance(raw_messages, list):
        return _normalized_chat_turns({"turns": raw_messages})

    return _turns_from_raw_conversation_mapping(payload)


def _messages_from_chat_payload(payload: dict[str, Any]) -> list[dict[str, Any]]:
    """Group a transcript into user messages with zero or more answers."""
    raw_turns = _normalized_chat_turns(payload)
    messages: list[dict[str, Any]] = []
    current_message: Optional[dict[str, Any]] = None

    for raw_turn in raw_turns:
        role = str(raw_turn.get("role") or "").strip().lower()
        text = str(raw_turn.get("text") or "")
        if role == "user":
            current_message = {
                "index": len(messages) + 1,
                "id": raw_turn.get("id"),
                "role": "user",
                "turn_index": raw_turn.get("index"),
                "text": text,
                "preview": _one_line_preview(text),
                "create_time": raw_turn.get("create_time"),
                "answers": [],
                "answer_count": 0,
                "answered": False,
            }
            messages.append(current_message)
            continue

        if role == "assistant" and current_message is not None:
            answers = current_message.setdefault("answers", [])
            answer = {
                "index": len(answers) + 1,
                "id": raw_turn.get("id"),
                "role": "assistant",
                "turn_index": raw_turn.get("index"),
                "text": text,
                "preview": _one_line_preview(text),
                "create_time": raw_turn.get("create_time"),
                "status": raw_turn.get("status") or "complete",
            }
            answers.append(answer)
            current_message["answer_count"] = len(answers)
            current_message["answered"] = bool(answers)

    return messages


def _task_messages_payload(chat_payload: dict[str, Any]) -> dict[str, Any]:
    messages = _messages_from_chat_payload(chat_payload)
    return {
        "ok": bool(chat_payload.get("ok", True)),
        "action": "task_messages_list",
        "project_url": chat_payload.get("project_url"),
        "conversation_url": chat_payload.get("conversation_url"),
        "conversation_id": chat_payload.get("conversation_id"),
        "title": chat_payload.get("title"),
        "message_count": len(messages),
        "messages": messages,
    }


def _resolve_task_message(messages: list[dict[str, Any]], id_or_index: str) -> dict[str, Any]:
    target = str(id_or_index).strip()
    if not target:
        raise ValueError("message id or index is required")

    if target.lower() in {"last", "latest"}:
        if messages:
            return messages[-1]
        raise ValueError("message index out of range: last")

    if target.isdigit():
        index = int(target)
        if 1 <= index <= len(messages):
            return messages[index - 1]
        raise ValueError(f"message index out of range: {target}")

    exact = [item for item in messages if str(item.get("id") or "") == target]
    if len(exact) == 1:
        return exact[0]

    prefix = [item for item in messages if str(item.get("id") or "").startswith(target)]
    if len(prefix) == 1:
        return prefix[0]
    if len(prefix) > 1:
        raise ValueError(f"multiple messages matched id prefix: {target}")

    raise ValueError(f"message not found: {target}")


def _render_task_messages_list(payload: dict[str, Any]) -> str:
    lines = [
        f"title={payload.get('title') or '(untitled)'}",
        f"conversation_id={payload.get('conversation_id') or 'none'}",
        f"message_count={payload.get('message_count') or 0}",
        "",
    ]
    messages = payload.get("messages") if isinstance(payload.get("messages"), list) else []
    for item in messages:
        lines.append(
            f"{item.get('index'):>3}. answers={item.get('answer_count') or 0}\t"
            f"{item.get('id') or ''}\t{item.get('preview') or ''}"
        )
    return "\n".join(lines).rstrip() + "\n"


def _render_task_message_show(message: dict[str, Any]) -> str:
    lines = [
        f"message_index={message.get('index')}",
        f"message_id={message.get('id') or 'none'}",
        f"answer_count={message.get('answer_count') or 0}",
        "",
        str(message.get("text") or ""),
    ]
    return "\n".join(lines).rstrip() + "\n"


def _render_task_message_answers(message: dict[str, Any]) -> str:
    answers = message.get("answers") if isinstance(message.get("answers"), list) else []
    if not answers:
        return "(no answer)\n"
    lines: list[str] = []
    for answer in answers:
        if len(answers) > 1:
            lines.append(f"[answer {answer.get('index')}]")
        lines.append(str(answer.get("text") or ""))
        lines.append("")
    return "\n".join(lines).rstrip() + "\n"


async def cmd_chat_show(backend: Any, args: argparse.Namespace) -> int:
    try:
        selected = await _resolve_chat_target(backend, args, args.target, keep_open=args.keep_open)
    except ValueError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1
    result = await backend.get_chat(str(selected.get('conversation_url') or ''), keep_open=args.keep_open)
    store = _state_store_from_args(args)
    store.remember(project_home_url_from_url(str(selected.get('conversation_url') or '')), str(selected.get('conversation_url') or ''), project_name=None)
    if args.json:
        print(json.dumps(result, indent=2, ensure_ascii=False))
        return 0
    print(_render_chat_payload(result), end='')
    return 0


async def _fetch_task_messages_payload(
    backend: Any,
    args: argparse.Namespace,
    target: Optional[str] = None,
) -> dict[str, Any]:
    selected = await _resolve_chat_target(backend, args, target, keep_open=getattr(args, "keep_open", False))
    conversation_url = str(selected.get("conversation_url") or "")
    result = await backend.get_chat(conversation_url, keep_open=getattr(args, "keep_open", False))
    store = _state_store_from_args(args)
    store.remember(project_home_url_from_url(conversation_url), conversation_url, project_name=None)
    return _task_messages_payload(result)


async def cmd_task_messages_list(backend: Any, args: argparse.Namespace) -> int:
    try:
        payload = await _fetch_task_messages_payload(backend, args, getattr(args, "target", None))
    except ValueError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1
    if args.json:
        print(json.dumps(payload, indent=2, ensure_ascii=False))
        return 0
    print(_render_task_messages_list(payload), end="")
    return 0


async def cmd_task_message_show(backend: Any, args: argparse.Namespace) -> int:
    try:
        payload = await _fetch_task_messages_payload(backend, args, getattr(args, "target", None))
        message = _resolve_task_message(payload["messages"], args.id_or_index)
    except ValueError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1
    result = {**payload, "action": "task_message_show", "message": message}
    if args.json:
        print(json.dumps(result, indent=2, ensure_ascii=False))
        return 0
    print(_render_task_message_show(message), end="")
    return 0


async def cmd_task_message_answer(backend: Any, args: argparse.Namespace) -> int:
    try:
        payload = await _fetch_task_messages_payload(backend, args, getattr(args, "target", None))
        message = _resolve_task_message(payload["messages"], args.id_or_index)
    except ValueError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1
    answers = message.get("answers") if isinstance(message.get("answers"), list) else []
    result = {
        **payload,
        "action": "task_message_answer",
        "message": {key: value for key, value in message.items() if key != "answers"},
        "answer_count": len(answers),
        "answers": answers,
    }
    if args.json:
        print(json.dumps(result, indent=2, ensure_ascii=False))
        return 0
    print(_render_task_message_answers(message), end="")
    return 0



def _resolve_task_answer(message: dict[str, Any], *, answer_index: str | None = None, answer_id: str | None = None) -> dict[str, Any]:
    answers = message.get("answers") if isinstance(message.get("answers"), list) else []
    if not answers:
        raise ValueError("selected message has no assistant answers")

    if answer_id:
        target = str(answer_id).strip()
        exact = [item for item in answers if str(item.get("id") or "") == target]
        if len(exact) == 1:
            return exact[0]
        prefix = [item for item in answers if str(item.get("id") or "").startswith(target)]
        if len(prefix) == 1:
            return prefix[0]
        if len(prefix) > 1:
            raise ValueError(f"multiple answers matched id prefix: {target}")
        raise ValueError(f"answer not found: {target}")

    target = str(answer_index or "latest").strip().lower()
    if target in {"last", "latest"}:
        return answers[-1]
    if target.isdigit():
        index = int(target)
        if 1 <= index <= len(answers):
            return answers[index - 1]
        raise ValueError(f"answer index out of range: {target}")
    raise ValueError(f"invalid answer index: {answer_index}")


def _resolve_task_answer_globally(messages: list[dict[str, Any]], answer_id: str) -> tuple[dict[str, Any], dict[str, Any]]:
    """Resolve an assistant answer id across all user messages.

    `pb task answer parse --answer-id <id>` was initially scoped to the
    selected user message. In practice operators often discover the assistant
    answer id from `pb task messages list --json` and expect that id to be
    sufficient.  Global resolution keeps the old scoped behavior when a message
    selector is present, but removes the fragile two-id requirement for the
    common unique-answer case.
    """

    target = str(answer_id or "").strip()
    if not target:
        raise ValueError("answer id is required")

    exact: list[tuple[dict[str, Any], dict[str, Any]]] = []
    prefix: list[tuple[dict[str, Any], dict[str, Any]]] = []
    for message in messages:
        answers = message.get("answers") if isinstance(message.get("answers"), list) else []
        for answer in answers:
            candidate_id = str(answer.get("id") or "")
            if candidate_id == target:
                exact.append((message, answer))
            elif candidate_id.startswith(target):
                prefix.append((message, answer))

    if len(exact) == 1:
        return exact[0]
    if len(exact) > 1:
        raise ValueError(f"multiple answers matched id: {target}")
    if len(prefix) == 1:
        return prefix[0]
    if len(prefix) > 1:
        raise ValueError(f"multiple answers matched id prefix: {target}")
    raise ValueError(f"answer not found: {target}")


def _resolve_task_answer_parse_selection(messages: list[dict[str, Any]], args: argparse.Namespace) -> tuple[dict[str, Any], dict[str, Any], dict[str, Any]]:
    explicit_message_selector = (
        getattr(args, "message_id", None)
        or getattr(args, "message_index", None)
        or getattr(args, "id_or_index", None)
    )

    if explicit_message_selector:
        message = _resolve_task_message(messages, str(explicit_message_selector))
        answer = _resolve_task_answer(
            message,
            answer_index=getattr(args, "answer_index", None),
            answer_id=getattr(args, "answer_id", None),
        )
        return message, answer, {
            "policy": "explicit_message_selector",
            "message_selector": str(explicit_message_selector),
            "answer_selector": str(getattr(args, "answer_id", None) or getattr(args, "answer_index", None) or "latest"),
            "global_answer_id_resolution": False,
        }

    if getattr(args, "latest", False):
        message = _resolve_task_message(messages, "latest")
        answer = _resolve_task_answer(
            message,
            answer_index=getattr(args, "answer_index", None),
            answer_id=getattr(args, "answer_id", None),
        )
        return message, answer, {
            "policy": "latest_message",
            "message_selector": "latest",
            "answer_selector": str(getattr(args, "answer_id", None) or getattr(args, "answer_index", None) or "latest"),
            "global_answer_id_resolution": False,
        }

    if getattr(args, "answer_id", None):
        message, answer = _resolve_task_answer_globally(messages, str(getattr(args, "answer_id")))
        return message, answer, {
            "policy": "global_answer_id",
            "message_selector": None,
            "answer_selector": str(getattr(args, "answer_id", None)),
            "global_answer_id_resolution": True,
        }

    message = _resolve_task_message(messages, "latest")
    answer = _resolve_task_answer(message, answer_index=getattr(args, "answer_index", None), answer_id=None)
    return message, answer, {
        "policy": "latest_message_default",
        "message_selector": "latest",
        "answer_selector": str(getattr(args, "answer_index", None) or "latest"),
        "global_answer_id_resolution": False,
    }


def _render_task_answer_parse_result(result: dict[str, Any]) -> str:
    lines = [
        f"status={result.get('status')}",
        f"ok={str(bool(result.get('ok'))).lower()}",
        f"message_id={((result.get('message') or {}) if isinstance(result.get('message'), dict) else {}).get('id') or 'none'}",
        f"answer_id={((result.get('answer') or {}) if isinstance(result.get('answer'), dict) else {}).get('id') or 'none'}",
        f"artifact_candidate_count={result.get('artifact_candidate_count') or 0}",
    ]
    candidates = result.get("artifact_candidates") if isinstance(result.get("artifact_candidates"), list) else []
    for candidate in candidates:
        lines.append(
            f"- {candidate.get('filename') or '(missing filename)'}\t"
            f"version={candidate.get('version') or 'unknown'}\t"
            f"role={candidate.get('role') or 'unknown'}\t"
            f"status={candidate.get('status') or 'unknown'}"
        )
    detail = result.get("detail")
    if detail:
        lines.append(f"detail={detail}")
    errors = result.get("validation_errors")
    if errors:
        lines.append("validation_errors=" + ",".join(str(item) for item in errors))
    return "\n".join(lines).rstrip() + "\n"


async def cmd_task_answer_parse(backend: Any, args: argparse.Namespace) -> int:
    try:
        payload = await _fetch_task_messages_payload(backend, args, getattr(args, "target", None))
        message, answer, selection_policy = _resolve_task_answer_parse_selection(payload["messages"], args)
    except ValueError as exc:
        result = {
            "ok": False,
            "action": "task_answer_parse",
            "status": "answer_selection_failed",
            "error": str(exc),
        }
        if args.json:
            print(json.dumps(result, indent=2, ensure_ascii=False))
        else:
            print(f"error: {exc}", file=sys.stderr)
        return 1

    parsed = parse_promptbranch_reply(str(answer.get("text") or ""))
    selected = _protocol_answer_metadata(message, answer)
    parsed = _with_protocol_selection_on_artifact_candidates(parsed, selected=selected)
    promotion = _promote_task_answer_protocol_run(args, payload=payload, message=message, answer=answer, parsed=parsed)
    result = {
        **parsed,
        "action": "task_answer_parse",
        "project_url": payload.get("project_url"),
        "conversation_url": payload.get("conversation_url"),
        "conversation_id": payload.get("conversation_id"),
        "title": payload.get("title"),
        "message": {key: value for key, value in message.items() if key != "answers"},
        "answer": {key: value for key, value in answer.items() if key != "text"},
        "selected_answer": selected,
        "answer_selection": selection_policy,
        "selected_request_id": parsed.get("request_id"),
        "selected_message_id": selected.get("message_id"),
        "selected_answer_id": selected.get("answer_id"),
        "selected_protocol_reply": _protocol_selection_summary(
            request_id=parsed.get("request_id"),
            correlation_id=parsed.get("correlation_id"),
            message=message,
            answer=answer,
            conversation_id=payload.get("conversation_id"),
            conversation_url=payload.get("conversation_url"),
        ),
        "answer_text_length": len(str(answer.get("text") or "")),
        "protocol_run_promotion": promotion,
        "protocol_run_promoted": bool(promotion.get("performed")),
        "promoted_protocol_run_record_path": promotion.get("path"),
        "automation_performed": False,
        "download_performed": False,
        "migration_performed": False,
        "adoption_performed": False,
    }
    if args.json:
        print(json.dumps(result, indent=2, ensure_ascii=False))
    else:
        print(_render_task_answer_parse_result(result), end="")
    return 0 if result.get("ok") else 1




def _protocol_run_records_dir(profile_dir: str | Path) -> Path:
    return Path(profile_dir).expanduser().resolve() / "ask_protocol_runs"


def _protocol_run_is_validated(payload: dict[str, Any]) -> bool:
    return bool(
        payload.get("ok") is True
        and payload.get("status") in {"reply_validated", "recovered_after_service_timeout", "reply_validated_from_task_answer"}
        and payload.get("reply_validation_ok") is True
        and isinstance(payload.get("reply"), dict)
    )


def _load_latest_validated_protocol_run(profile_dir: str | Path) -> tuple[Path | None, dict[str, Any] | None, dict[str, Any]]:
    """Return the newest validated protocol run persisted by pb ask --parse-reply.

    Artifact intake must not scrape arbitrary assistant prose when a structured
    protocol record is available. The persisted run is the host-validated source
    of truth for the MVP inspection path.
    """

    root = _protocol_run_records_dir(profile_dir)
    if not root.is_dir():
        return None, None, {"status": "protocol_run_not_found", "record_count": 0, "records_dir": str(root)}
    records = sorted((item for item in root.glob("*.json") if item.is_file()), key=lambda item: item.stat().st_mtime, reverse=True)
    scanned = 0
    latest_invalid: dict[str, Any] | None = None
    latest_invalid_path: Path | None = None
    for path in records:
        scanned += 1
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError) as exc:
            latest_invalid = {"status": "protocol_run_unreadable", "error": str(exc), "path": str(path)}
            latest_invalid_path = path
            continue
        if not isinstance(payload, dict):
            latest_invalid = {"status": "protocol_run_invalid_payload", "path": str(path)}
            latest_invalid_path = path
            continue
        if _protocol_run_is_validated(payload):
            return path, payload, {"status": "latest_validated_protocol_run", "record_count": len(records), "scanned_count": scanned, "records_dir": str(root)}
        latest_invalid = {
            "status": "latest_protocol_run_not_validated",
            "path": str(path),
            "run_status": payload.get("status"),
            "ok": payload.get("ok"),
            "reply_validation_ok": payload.get("reply_validation_ok"),
        }
        latest_invalid_path = path
    diagnostic = {"status": "validated_protocol_run_not_found", "record_count": len(records), "scanned_count": scanned, "records_dir": str(root)}
    if latest_invalid is not None:
        diagnostic["latest_invalid"] = latest_invalid
        diagnostic["latest_invalid_path"] = str(latest_invalid_path) if latest_invalid_path else None
    return None, None, diagnostic


def _load_validated_protocol_run_by_request_id(
    profile_dir: str | Path,
    request_id: Any,
    *,
    allow_replay_unvalidated_artifact_run: bool = False,
    allow_finalize_materialized_protocol_run: bool = False,
) -> tuple[Path | None, dict[str, Any] | None, dict[str, Any]]:
    """Load one exact persisted protocol run by request ID.

    Normal selection accepts only validated records. An operator may explicitly
    opt into replay of one narrowly allowlisted pre-materialization failure. The
    replay path is exact-ID-only and remains fail-closed for all other invalid,
    ambiguous, mutated, or non-artifact records.
    """

    selected_request_id = str(request_id or "").strip()
    root = _protocol_run_records_dir(profile_dir)
    safe_request_id = re.sub(r"[^A-Za-z0-9_.-]+", "_", selected_request_id).strip("._")
    if not selected_request_id or safe_request_id != selected_request_id:
        return None, None, {
            "status": "protocol_run_request_id_invalid",
            "selected_request_id": selected_request_id or None,
            "records_dir": str(root),
        }

    path, payload, loaded = _load_protocol_run_record_for_request_id(profile_dir, selected_request_id)
    diagnostic = {
        **loaded,
        "selected_request_id": selected_request_id,
        "records_dir": str(root),
        "scanned_count": 1,
    }
    if payload is None:
        diagnostic["status"] = loaded.get("status") or "protocol_run_record_missing"
        return path, None, diagnostic

    payload_request_id = str(payload.get("request_id") or "")
    if payload_request_id != selected_request_id:
        diagnostic.update({
            "status": "protocol_run_request_id_mismatch",
            "payload_request_id": payload_request_id or None,
        })
        return path, None, diagnostic

    if not _protocol_run_is_validated(payload):
        finalization_eligibility = _protocol_run_materialized_finalization_eligibility(
            payload,
            selected_request_id=selected_request_id,
            profile_dir=profile_dir,
        )
        diagnostic["materialized_finalization_eligibility"] = finalization_eligibility
        if allow_finalize_materialized_protocol_run and finalization_eligibility.get("ok") is True:
            diagnostic.update({
                "available": True,
                "status": "selected_materialized_protocol_run",
                "record_count": len(list(root.glob("*.json"))) if root.is_dir() else 0,
                "run_status": payload.get("status"),
                "ok": payload.get("ok"),
                "reply_validation_ok": payload.get("reply_validation_ok"),
                "finalization_requested": True,
                "finalization_used": True,
                "previous_status": payload.get("status"),
            })
            return path, payload, diagnostic

        replay_eligibility = _protocol_run_unvalidated_artifact_replay_eligibility(
            payload,
            selected_request_id=selected_request_id,
        )
        diagnostic["replay_eligibility"] = replay_eligibility
        if allow_replay_unvalidated_artifact_run and replay_eligibility.get("ok") is True:
            diagnostic.update({
                "available": True,
                "status": "selected_replayable_protocol_run",
                "record_count": len(list(root.glob("*.json"))) if root.is_dir() else 0,
                "run_status": payload.get("status"),
                "ok": payload.get("ok"),
                "reply_validation_ok": payload.get("reply_validation_ok"),
                "replay_requested": True,
                "replay_used": True,
                "previous_status": payload.get("status"),
            })
            return path, payload, diagnostic
        diagnostic.update({
            "status": (
                "selected_protocol_run_not_finalizable"
                if allow_finalize_materialized_protocol_run and payload.get("status") in _MATERIALIZED_FINALIZATION_PROTOCOL_RUN_STATUSES
                else ("selected_protocol_run_not_replayable" if allow_replay_unvalidated_artifact_run else "selected_protocol_run_not_validated")
            ),
            "run_status": payload.get("status"),
            "ok": payload.get("ok"),
            "reply_validation_ok": payload.get("reply_validation_ok"),
            "replay_requested": bool(allow_replay_unvalidated_artifact_run),
            "replay_used": False,
            "finalization_requested": bool(allow_finalize_materialized_protocol_run),
            "finalization_used": False,
        })
        return path, None, diagnostic

    diagnostic.update({
        "available": True,
        "status": "selected_validated_protocol_run",
        "record_count": len(list(root.glob("*.json"))) if root.is_dir() else 0,
        "replay_requested": bool(allow_replay_unvalidated_artifact_run),
        "replay_used": False,
    })
    return path, payload, diagnostic


def _candidate_expected_filename(repo: str | None, version: str | None) -> str | None:
    if not repo or not version:
        return None
    return f"{repo}_{version}.zip"


def _protocol_run_expectations(run: dict[str, Any]) -> dict[str, Any]:
    request = run.get("request") if isinstance(run.get("request"), dict) else {}
    artifact = request.get("artifact") if isinstance(request.get("artifact"), dict) else {}
    repo = artifact.get("repo")
    target_version = artifact.get("target_version") or (run.get("baseline") or {}).get("target_version")
    if isinstance(run.get("baseline"), dict):
        target_version = target_version or run["baseline"].get("output_version")
    return {
        "expected_repo": str(repo) if repo else None,
        "expected_version": str(target_version) if target_version else None,
        "expected_filename": _candidate_expected_filename(str(repo), str(target_version)) if repo and target_version else None,
        "expected_input_artifact": artifact.get("current_baseline"),
        "expected_input_version": artifact.get("current_version"),
        "expected_source_ref": artifact.get("source_ref"),
        "expected_source_version": artifact.get("source_version"),
        "expected_release_type": artifact.get("release_type"),
    }


def _protocol_run_is_no_artifact_no_change(run: dict[str, Any]) -> bool:
    reply = run.get("reply") if isinstance(run.get("reply"), dict) else {}
    artifacts = reply.get("artifacts") if isinstance(reply.get("artifacts"), list) else []
    return (
        reply.get("status") == "no_artifact"
        and reply.get("result_type") == "no_change"
        and not artifacts
    )


_REPLAYABLE_UNVALIDATED_PROTOCOL_RUN_STATUSES = {"artifact_declared_but_not_attached"}
_REPLAYABLE_UNVALIDATED_CANONICAL_FAILURES = {
    "reply_validated",
    "download_proof",
    "artifact_declared_but_not_attached",
}
_REPLAYABLE_UNVALIDATED_REPLY_ERRORS = {
    "ask_release:reply_validated",
    "ask_release:download_proof",
    "ask_release:artifact_declared_but_not_attached",
    "reply_validated",
    "download_proof",
    "artifact_declared_but_not_attached",
}
_REPLAYABLE_UNVALIDATED_ASK_RELEASE_FAILURES = set(_REPLAYABLE_UNVALIDATED_CANONICAL_FAILURES)
_REPLAYABLE_ZIP_MEDIA_TYPES = {
    "application/zip",
    "application/x-zip-compressed",
}


def _normalized_replay_identity(*values: Any, fallback: Any = None) -> dict[str, Any]:
    """Resolve one replay identity while rejecting contradictory legacy copies."""

    normalized = [str(value).strip() for value in values if str(value or "").strip()]
    distinct = list(dict.fromkeys(normalized))
    if len(distinct) > 1:
        return {
            "ok": False,
            "value": None,
            "source": "conflicting_explicit_values",
            "explicit_values": distinct,
        }
    if distinct:
        return {
            "ok": True,
            "value": distinct[0],
            "source": "explicit_or_legacy_selection",
            "explicit_values": distinct,
        }
    fallback_text = str(fallback or "").strip()
    return {
        "ok": bool(fallback_text),
        "value": fallback_text or None,
        "source": "exact_run_identity_fallback" if fallback_text else "missing",
        "explicit_values": [],
    }


def _protocol_run_candidate_zip_evidence(candidate: dict[str, Any]) -> dict[str, Any]:
    """Classify one persisted protocol artifact as ZIP without trusting one field.

    New records may declare ``kind=zip``. Historical release replies frequently
    omitted ``kind`` while declaring both a ``.zip`` basename and a ZIP media
    type. Those two independent legacy signals are accepted together; a MIME or
    filename contradiction remains fail-closed. This classifier is shared by
    replay, finalization, ordinary validated intake, and migration.
    """

    raw = candidate.get("raw") if isinstance(candidate.get("raw"), dict) else {}
    raw_kind = str(raw.get("kind") or "").strip().lower()
    normalized_kind = str(candidate.get("kind") or "").strip().lower()
    filename = Path(str(candidate.get("filename") or "")).name
    media_type = str(candidate.get("media_type") or raw.get("media_type") or "").strip().lower()

    if raw_kind:
        ok = raw_kind == "zip"
        mode = "explicit_kind"
    elif normalized_kind and normalized_kind not in {"unknown", "none"}:
        ok = normalized_kind == "zip"
        mode = "normalized_kind"
    else:
        ok = filename.endswith(".zip") and media_type in _REPLAYABLE_ZIP_MEDIA_TYPES
        mode = "legacy_media_type"

    return {
        "ok": ok,
        "mode": mode,
        "filename": filename,
        "raw_kind": raw_kind or None,
        "normalized_kind": normalized_kind or None,
        "media_type": media_type or None,
        "allowed_media_types": sorted(_REPLAYABLE_ZIP_MEDIA_TYPES),
    }


def _protocol_run_replay_candidate_zip_evidence(candidate: dict[str, Any]) -> dict[str, Any]:
    """Backward-compatible name for the shared persisted-run ZIP classifier."""

    return _protocol_run_candidate_zip_evidence(candidate)


def _protocol_run_intake_baseline_errors(run: dict[str, Any]) -> list[str]:
    """Normalize persisted reply baseline aliases for every intake path.

    ``input_artifact`` and ``input_baseline`` are equivalent only when all
    present values agree with the request. Source and registry fields are
    optional reply metadata: absence is not a mismatch, but a present
    contradiction is rejected. Target version may be carried by the candidate,
    so baseline target fields are checked when present rather than required.
    """

    reply = run.get("reply") if isinstance(run.get("reply"), dict) else {}
    baseline = reply.get("baseline") if isinstance(reply.get("baseline"), dict) else {}
    request = run.get("request") if isinstance(run.get("request"), dict) else {}
    request_artifact = request.get("artifact") if isinstance(request.get("artifact"), dict) else {}
    expectations = _protocol_run_expectations(run)
    errors: list[str] = []

    expected_input = expectations.get("expected_input_artifact")
    input_values = [
        str(value)
        for value in (baseline.get("input_artifact"), baseline.get("input_baseline"))
        if value not in {None, ""}
    ]
    if expected_input is not None and (not input_values or any(value != str(expected_input) for value in input_values)):
        errors.append("baseline_artifact_mismatch")
    if expectations.get("expected_input_version") is not None and baseline.get("input_version") != expectations.get("expected_input_version"):
        errors.append("baseline_version_mismatch")
    if expectations.get("expected_release_type") is not None and baseline.get("release_type") != expectations.get("expected_release_type"):
        errors.append("baseline_release_type_mismatch")

    expected_version = _normalize_version_token(expectations.get("expected_version"))
    observed_targets = [
        _normalize_version_token(value)
        for value in (baseline.get("output_version"), baseline.get("target_version"))
        if value not in {None, ""}
    ]
    if expected_version and any(value != expected_version for value in observed_targets):
        errors.append("baseline_target_version_mismatch")

    output_artifact = baseline.get("output_artifact")
    if output_artifact is not None and output_artifact != expectations.get("expected_filename"):
        errors.append("baseline_output_artifact_mismatch")

    optional_pairs = [
        ("source_ref", expectations.get("expected_source_ref"), "baseline_source_ref_mismatch"),
        ("source_version", expectations.get("expected_source_version"), "baseline_source_version_mismatch"),
        ("registry_current", request_artifact.get("registry_current"), "baseline_registry_current_mismatch"),
        ("registry_current_version", request_artifact.get("registry_current_version"), "baseline_registry_current_version_mismatch"),
    ]
    for field, expected, error in optional_pairs:
        actual = baseline.get(field)
        if actual is not None and expected is not None and actual != expected:
            errors.append(error)
    return list(dict.fromkeys(errors))


def _protocol_run_replay_baseline_errors(run: dict[str, Any]) -> list[str]:
    """Backward-compatible replay name for shared baseline normalization."""

    return _protocol_run_intake_baseline_errors(run)


def _canonical_replay_failure(value: Any) -> str:
    text = str(value or "").strip()
    if text.startswith("ask_release:"):
        text = text.split(":", 1)[1]
    return text


def _protocol_run_replay_failure_evidence(run: dict[str, Any]) -> dict[str, Any]:
    """Normalize old/new attachment-proof failure labels and positive checks."""

    reply_errors_raw = [str(item) for item in (run.get("reply_validation_errors") or [])]
    ask_validation = run.get("ask_release_validation") if isinstance(run.get("ask_release_validation"), dict) else {}
    ask_failures_raw = [str(item) for item in (ask_validation.get("failures") or [])]
    reply_failures = {_canonical_replay_failure(item) for item in reply_errors_raw if _canonical_replay_failure(item)}
    ask_failures = {_canonical_replay_failure(item) for item in ask_failures_raw if _canonical_replay_failure(item)}
    combined = reply_failures | ask_failures

    checks = ask_validation.get("checks") if isinstance(ask_validation.get("checks"), dict) else {}
    required_true_checks = [
        "exact_artifact_count",
        "filename_matches",
        "version_matches",
        "role_matches",
        "status_release_candidate",
    ]
    positive_identity_checks = all(checks.get(name) is True for name in required_true_checks)
    artifact_count_exact = int(checks.get("artifact_count") or 0) == 1
    no_successful_download_claim = not any(
        checks.get(name) is True
        for name in (
            "download_claimed",
            "download_available",
            "download_proof",
            "download_direct_supported",
            "download_attachment_proven",
        )
    )
    canonical_failure_set_ok = (
        bool(combined)
        and "artifact_declared_but_not_attached" in combined
        and combined.issubset(_REPLAYABLE_UNVALIDATED_CANONICAL_FAILURES)
    )

    return {
        "ok": canonical_failure_set_ok and positive_identity_checks and artifact_count_exact and no_successful_download_claim,
        "reply_errors_raw": reply_errors_raw,
        "ask_failures_raw": ask_failures_raw,
        "reply_failures": sorted(reply_failures),
        "ask_failures": sorted(ask_failures),
        "canonical_failures": sorted(combined),
        "canonical_failure_set_ok": canonical_failure_set_ok,
        "positive_identity_checks": positive_identity_checks,
        "artifact_count_exact": artifact_count_exact,
        "no_successful_download_claim": no_successful_download_claim,
        "required_true_checks": required_true_checks,
        "checks": checks,
    }


_MATERIALIZED_FINALIZATION_PROTOCOL_RUN_STATUSES = {"release_candidate_validation_failed"}
_MATERIALIZED_FINALIZATION_STALE_REPLY_ERRORS = {
    "baseline_artifact_mismatch",
    "target_version_mismatch",
    "ask_release:reply_validated",
}
_MATERIALIZED_FINALIZATION_ASK_FAILURES = {"reply_validated"}
_MATERIALIZED_FINALIZATION_STATUS = "chatgpt_rendered_attachment_downloaded_verified"


def _protocol_run_materialized_finalization_eligibility(
    run: dict[str, Any],
    *,
    selected_request_id: str,
    profile_dir: str | Path,
) -> dict[str, Any]:
    """Validate an already downloaded ask-release run for idempotent finalization.

    This path is exact-request-only. It never redownloads, migrates, publishes,
    adopts, or trusts stale validation errors. The persisted inbox ZIP is opened
    again and compared with the request, reply envelope, selected answer, and
    recorded materialization metadata before the run may be finalized.
    """

    checks: dict[str, bool] = {}
    failures: list[str] = []

    def require(name: str, condition: Any) -> None:
        ok = bool(condition)
        checks[name] = ok
        if not ok:
            failures.append(name)

    request = run.get("request") if isinstance(run.get("request"), dict) else {}
    reply = run.get("reply") if isinstance(run.get("reply"), dict) else {}
    message = run.get("message") if isinstance(run.get("message"), dict) else {}
    answer = run.get("answer") if isinstance(run.get("answer"), dict) else {}
    selected = run.get("selected_answer") if isinstance(run.get("selected_answer"), dict) else {}
    selection = run.get("selected_protocol_reply") if isinstance(run.get("selected_protocol_reply"), dict) else {}
    request_id = str(run.get("request_id") or "")
    correlation_id = str(run.get("correlation_id") or "")
    message_id = str(message.get("id") or "")
    answer_id = str(answer.get("id") or "")
    conversation_id = str(run.get("conversation_id") or (request.get("task") or {}).get("conversation_id") or "")

    selection_request = _normalized_replay_identity(selection.get("request_id"), run.get("selected_request_id"), fallback=request_id)
    selection_correlation = _normalized_replay_identity(selection.get("correlation_id"), run.get("selected_correlation_id"), fallback=correlation_id)
    selection_message = _normalized_replay_identity(selection.get("message_id"), run.get("selected_message_id"), selected.get("message_id"), fallback=message_id)
    selection_answer = _normalized_replay_identity(selection.get("answer_id"), run.get("selected_answer_id"), selected.get("answer_id"), fallback=answer_id)

    require("action_is_ask_release", run.get("action") == "ask_release")
    require("run_status_allowlisted", run.get("status") in _MATERIALIZED_FINALIZATION_PROTOCOL_RUN_STATUSES)
    require("run_not_ok", run.get("ok") is False)
    require("reply_validation_failed", run.get("reply_validation_ok") is False)
    require("request_id_exact", request_id == selected_request_id)
    require("correlation_id_exact", correlation_id == selected_request_id)
    require("request_envelope_request_id_exact", str(request.get("request_id") or "") == selected_request_id)
    require("request_envelope_correlation_id_exact", str(request.get("correlation_id") or "") == selected_request_id)
    require("reply_request_id_exact", str(reply.get("request_id") or "") == selected_request_id)
    require("reply_correlation_id_exact", str(reply.get("correlation_id") or "") == selected_request_id)
    require("reply_declares_release_candidate", reply.get("status") == "completed" and reply.get("result_type") == "release_candidate")
    require("message_id_present", bool(message_id))
    require("answer_id_present", bool(answer_id))
    require("selection_request_identity_matches", selection_request.get("ok") and selection_request.get("value") == selected_request_id)
    require("selection_correlation_identity_matches", selection_correlation.get("ok") and selection_correlation.get("value") == selected_request_id)
    require("selection_message_identity_matches", selection_message.get("ok") and selection_message.get("value") == message_id)
    require("selection_answer_identity_matches", selection_answer.get("ok") and selection_answer.get("value") == answer_id)

    reply_text = "BEGIN_PROMPTBRANCH_REPLY_JSON\n" + json.dumps(reply, ensure_ascii=False) + "\nEND_PROMPTBRANCH_REPLY_JSON"
    reparsed = parse_promptbranch_reply(reply_text)
    require("reply_reparse_valid", reparsed.get("ok") is True and reparsed.get("status") == "valid")
    normalized_validation_ok, normalized_validation_errors = _validate_protocol_reply_against_request(reparsed, request)
    require("normalized_reply_matches_request", normalized_validation_ok and not normalized_validation_errors)

    candidates = reparsed.get("artifact_candidates") if isinstance(reparsed.get("artifact_candidates"), list) else []
    require("exactly_one_artifact_candidate", len(candidates) == 1)
    candidate = candidates[0] if len(candidates) == 1 and isinstance(candidates[0], dict) else {}
    expectations = _protocol_run_expectations(run)
    filename = Path(str(candidate.get("filename") or "")).name
    require("candidate_kind_zip", _protocol_run_replay_candidate_zip_evidence(candidate).get("ok"))
    require("candidate_role_release", candidate.get("role") == "candidate_release")
    require("candidate_filename_exact", bool(filename) and filename == expectations.get("expected_filename"))
    require("candidate_version_exact", _normalize_version_token(candidate.get("version")) == _normalize_version_token(expectations.get("expected_version")))

    ask_validation = run.get("ask_release_validation") if isinstance(run.get("ask_release_validation"), dict) else {}
    ask_checks = ask_validation.get("checks") if isinstance(ask_validation.get("checks"), dict) else {}
    required_positive_checks = [
        "exact_artifact_count", "filename_matches", "version_matches", "role_matches",
        "download_proof", "status_release_candidate", "artifact_materialization_proven",
        "browser_download_performed", "verification_performed", "envelope_metadata_verified",
    ]
    require("materialization_checks_positive", all(ask_checks.get(name) is True for name in required_positive_checks))
    require("run_materialization_proven", run.get("download_performed") is True and run.get("browser_download_performed") is True and run.get("verification_performed") is True and run.get("artifact_materialization_proven") is True and run.get("envelope_metadata_verified") is True)
    require("materialization_status_exact", run.get("materialization_status") == _MATERIALIZED_FINALIZATION_STATUS)

    reply_errors = {str(item) for item in (run.get("reply_validation_errors") or [])}
    ask_failures = {str(item) for item in (ask_validation.get("failures") or [])}
    require("stale_reply_errors_only", bool(reply_errors) and reply_errors.issubset(_MATERIALIZED_FINALIZATION_STALE_REPLY_ERRORS))
    require("stale_ask_failures_only", ask_failures.issubset(_MATERIALIZED_FINALIZATION_ASK_FAILURES))

    forbidden_true_flags = [
        "migration_performed", "adoption_performed", "project_source_mutated",
        "artifact_registry_updated", "state_artifact_updated", "state_source_updated",
    ]
    require("no_release_state_mutation", not any(run.get(name) is True for name in forbidden_true_flags))

    download = run.get("download") if isinstance(run.get("download"), dict) else {}
    expected_inbox = _artifact_inbox_dir(
        profile_dir=profile_dir,
        conversation_id=conversation_id,
        answer_id=answer_id,
        request_id=selected_request_id,
    )
    expected_path = (expected_inbox / filename).resolve() if filename else expected_inbox.resolve()
    actual_path = Path(str(download.get("path") or "")).expanduser().resolve() if download.get("path") else None
    require("artifact_path_exact", actual_path is not None and actual_path == expected_path)
    require("artifact_file_present", actual_path is not None and actual_path.is_file())

    file_metadata: dict[str, Any] = {}
    zip_verification: dict[str, Any] = {}
    zip_version: str | None = None
    if actual_path is not None and actual_path.is_file():
        file_metadata = _artifact_file_metadata(actual_path)
        zip_verification = verify_zip_artifact(actual_path)
        zip_version = _read_zip_version_file(actual_path)
    raw = candidate.get("raw") if isinstance(candidate.get("raw"), dict) else {}
    expected_sha = str(raw.get("sha256") or candidate.get("sha256") or "").lower()
    expected_size = raw.get("size_bytes") or candidate.get("size_bytes")
    expected_entries = raw.get("entry_count") or candidate.get("entry_count")
    require("artifact_sha256_exact", bool(expected_sha) and str(file_metadata.get("sha256") or "").lower() == expected_sha)
    try:
        size_exact = int(file_metadata.get("size_bytes")) == int(expected_size)
    except (TypeError, ValueError):
        size_exact = False
    require("artifact_size_exact", size_exact)
    try:
        entries_exact = int(zip_verification.get("entry_count")) == int(expected_entries)
    except (TypeError, ValueError):
        entries_exact = False
    require("artifact_entry_count_exact", entries_exact)
    require("artifact_zip_valid", zip_verification.get("ok") is True)
    require("artifact_version_exact", _normalize_version_token(zip_version) == _normalize_version_token(expectations.get("expected_version")))

    return {
        "ok": not failures,
        "status": "materialized_protocol_run_finalizable" if not failures else "materialized_protocol_run_not_finalizable",
        "checks": checks,
        "failures": failures,
        "normalized_validation_errors": normalized_validation_errors,
        "artifact_path": str(actual_path) if actual_path else None,
        "artifact_inbox_dir": str(expected_inbox),
        "artifact_metadata": file_metadata,
        "zip_verification": zip_verification,
        "allowed_run_statuses": sorted(_MATERIALIZED_FINALIZATION_PROTOCOL_RUN_STATUSES),
        "allowed_stale_reply_errors": sorted(_MATERIALIZED_FINALIZATION_STALE_REPLY_ERRORS),
        "allowed_stale_ask_failures": sorted(_MATERIALIZED_FINALIZATION_ASK_FAILURES),
    }


def _protocol_run_unvalidated_artifact_replay_eligibility(
    run: dict[str, Any],
    *,
    selected_request_id: str,
) -> dict[str, Any]:
    """Classify one failed ask-release record for explicit browser replay.

    This is deliberately not a generic validation bypass. It admits only the
    historical state where a structurally valid, exactly correlated release
    envelope declared one sandbox ZIP but no rendered attachment had yet been
    proven. Legacy field aliases are normalized only inside this explicit replay
    path, and contradictory copies still fail before browser access.
    """

    checks: dict[str, bool] = {}
    failures: list[str] = []

    def require(name: str, condition: Any) -> None:
        ok = bool(condition)
        checks[name] = ok
        if not ok:
            failures.append(name)

    request = run.get("request") if isinstance(run.get("request"), dict) else {}
    reply = run.get("reply") if isinstance(run.get("reply"), dict) else {}
    message = run.get("message") if isinstance(run.get("message"), dict) else {}
    answer = run.get("answer") if isinstance(run.get("answer"), dict) else {}
    selected = run.get("selected_answer") if isinstance(run.get("selected_answer"), dict) else {}
    selection = run.get("selected_protocol_reply") if isinstance(run.get("selected_protocol_reply"), dict) else {}

    request_id = str(run.get("request_id") or "")
    correlation_id = str(run.get("correlation_id") or "")
    request_request_id = str(request.get("request_id") or "")
    request_correlation_id = str(request.get("correlation_id") or "")
    reply_request_id = str(reply.get("request_id") or "")
    reply_correlation_id = str(reply.get("correlation_id") or "")
    message_id = str(message.get("id") or "")
    answer_id = str(answer.get("id") or "")

    selection_request = _normalized_replay_identity(
        selection.get("request_id"),
        run.get("selected_request_id"),
        fallback=request_id,
    )
    selection_correlation = _normalized_replay_identity(
        selection.get("correlation_id"),
        run.get("selected_correlation_id"),
        fallback=correlation_id,
    )
    selection_message = _normalized_replay_identity(
        selection.get("message_id"),
        run.get("selected_message_id"),
        selected.get("message_id"),
        fallback=message_id,
    )
    selection_answer = _normalized_replay_identity(
        selection.get("answer_id"),
        run.get("selected_answer_id"),
        selected.get("answer_id"),
        fallback=answer_id,
    )
    selection_evidence = {
        "request_id": selection_request,
        "correlation_id": selection_correlation,
        "message_id": selection_message,
        "answer_id": selection_answer,
    }

    require("action_is_ask_release", run.get("action") == "ask_release")
    require("run_status_allowlisted", run.get("status") in _REPLAYABLE_UNVALIDATED_PROTOCOL_RUN_STATUSES)
    require("run_not_ok", run.get("ok") is False)
    require("reply_validation_failed", run.get("reply_validation_ok") is False)
    require("request_id_exact", request_id == selected_request_id)
    require("correlation_id_exact", correlation_id == selected_request_id)
    require("request_envelope_request_id_exact", request_request_id == selected_request_id)
    require("request_envelope_correlation_id_exact", request_correlation_id == selected_request_id)
    require("reply_request_id_exact", reply_request_id == selected_request_id)
    require("reply_correlation_id_exact", reply_correlation_id == selected_request_id)
    require("reply_schema_exact", reply.get("schema") == "promptbranch.ask.reply")
    require("reply_schema_version_exact", str(reply.get("schema_version") or "") == "1.0")
    require("reply_declares_release_candidate", reply.get("status") == "completed" and reply.get("result_type") == "release_candidate")
    require("message_id_present", bool(message_id))
    require("answer_id_present", bool(answer_id))
    require("selected_message_identity_matches", str(selected.get("message_id") or "") == message_id)
    require("selected_answer_identity_matches", str(selected.get("answer_id") or "") == answer_id)
    require("selection_request_identity_matches", selection_request.get("ok") and selection_request.get("value") == selected_request_id)
    require("selection_correlation_identity_matches", selection_correlation.get("ok") and selection_correlation.get("value") == selected_request_id)
    require("selection_message_identity_matches", selection_message.get("ok") and selection_message.get("value") == message_id)
    require("selection_answer_identity_matches", selection_answer.get("ok") and selection_answer.get("value") == answer_id)
    require("conversation_url_present", bool(str(run.get("conversation_url") or (request.get("task") or {}).get("conversation_url") or "").strip()))
    require("conversation_id_present", bool(str(run.get("conversation_id") or (request.get("task") or {}).get("conversation_id") or "").strip()))
    require("answer_text_recorded", int(run.get("answer_text_length") or 0) > 0)

    reply_text = "BEGIN_PROMPTBRANCH_REPLY_JSON\n" + json.dumps(reply, ensure_ascii=False) + "\nEND_PROMPTBRANCH_REPLY_JSON"
    reparsed = parse_promptbranch_reply(reply_text)
    require("reply_reparse_valid", reparsed.get("ok") is True and reparsed.get("status") == "valid")
    candidates = reparsed.get("artifact_candidates") if isinstance(reparsed.get("artifact_candidates"), list) else []
    require("exactly_one_artifact_candidate", len(candidates) == 1)
    candidate = candidates[0] if len(candidates) == 1 and isinstance(candidates[0], dict) else {}
    expectations = _protocol_run_expectations(run)
    candidate_filename = Path(str(candidate.get("filename") or "")).name
    candidate_version = _normalize_version_token(candidate.get("version"))
    expected_version = _normalize_version_token(expectations.get("expected_version"))
    zip_evidence = _protocol_run_replay_candidate_zip_evidence(candidate)
    require("candidate_kind_zip", zip_evidence.get("ok"))
    require("candidate_role_release", candidate.get("role") == "candidate_release")
    require("candidate_filename_exact", bool(candidate_filename) and candidate_filename == expectations.get("expected_filename"))
    require("candidate_version_exact", bool(candidate_version) and candidate_version == expected_version)
    transport = _artifact_download_transport(_selected_candidate_download_url(candidate))
    require("candidate_is_unproven_sandbox", transport.get("scheme") == "sandbox" and not transport.get("direct_download_supported"))
    baseline_errors = _protocol_run_replay_baseline_errors(run)
    require("baseline_matches_request", not baseline_errors)

    failure_evidence = _protocol_run_replay_failure_evidence(run)
    require("attachment_failure_identity_checks_passed", failure_evidence.get("positive_identity_checks") and failure_evidence.get("artifact_count_exact"))
    require("reply_errors_are_attachment_only", failure_evidence.get("canonical_failure_set_ok") and failure_evidence.get("no_successful_download_claim"))
    require("ask_release_failures_are_attachment_only", failure_evidence.get("canonical_failure_set_ok") and failure_evidence.get("no_successful_download_claim"))

    forbidden_true_flags = [
        "download_performed",
        "browser_download_performed",
        "verification_performed",
        "migration_performed",
        "adoption_performed",
        "artifact_materialization_proven",
        "project_source_mutated",
        "artifact_registry_updated",
        "state_artifact_updated",
        "state_source_updated",
    ]
    require("no_prior_mutation_or_materialization", not any(run.get(name) is True for name in forbidden_true_flags))

    return {
        "ok": not failures,
        "status": "replayable_artifact_intake_failure" if not failures else "unvalidated_artifact_run_not_replayable",
        "allowlisted_previous_status": run.get("status"),
        "compatibility_profile": "legacy_attachment_only_protocol_run_v1",
        "checks": checks,
        "failures": failures,
        "selection_identity_evidence": selection_evidence,
        "candidate_zip_evidence": zip_evidence,
        "baseline_errors": baseline_errors,
        "failure_evidence": failure_evidence,
        "allowed_run_statuses": sorted(_REPLAYABLE_UNVALIDATED_PROTOCOL_RUN_STATUSES),
        "allowed_reply_validation_errors": sorted(_REPLAYABLE_UNVALIDATED_REPLY_ERRORS),
        "allowed_ask_release_failures": sorted(_REPLAYABLE_UNVALIDATED_ASK_RELEASE_FAILURES),
    }


def _protocol_run_baseline_errors(run: dict[str, Any]) -> list[str]:
    """Backward-compatible name for shared persisted-run baseline checks."""

    return _protocol_run_intake_baseline_errors(run)


def _normalize_protocol_run_reply_for_intake(
    run: dict[str, Any],
    *,
    allow_legacy_unvalidated_replay: bool = False,
) -> dict[str, Any]:
    reply = run.get("reply") if isinstance(run.get("reply"), dict) else {}
    artifacts = reply.get("artifacts") if isinstance(reply.get("artifacts"), list) else []
    text = "BEGIN_PROMPTBRANCH_REPLY_JSON\n" + json.dumps(reply, ensure_ascii=False) + "\nEND_PROMPTBRANCH_REPLY_JSON"
    parsed = parse_promptbranch_reply(text)
    baseline_errors = _protocol_run_intake_baseline_errors(run)
    normalized_candidates = parsed.get("artifact_candidates") if isinstance(parsed.get("artifact_candidates"), list) else []
    normalized_legacy_zip_count = 0
    for candidate in normalized_candidates:
        if not isinstance(candidate, dict):
            continue
        zip_evidence = _protocol_run_candidate_zip_evidence(candidate)
        raw = candidate.get("raw") if isinstance(candidate.get("raw"), dict) else {}
        if zip_evidence.get("ok") and not str(raw.get("kind") or "").strip():
            candidate["kind"] = "zip"
            candidate["legacy_kind_normalized"] = True
            candidate["legacy_kind_evidence"] = zip_evidence
            normalized_legacy_zip_count += 1
    parsed["protocol_run_intake_compatibility"] = {
        "profile": "persisted_protocol_run_v1",
        "baseline_errors": baseline_errors,
        "normalized_legacy_zip_count": normalized_legacy_zip_count,
    }
    if allow_legacy_unvalidated_replay:
        parsed["protocol_run_replay_compatibility"] = {
            "profile": "legacy_attachment_only_protocol_run_v1",
            "baseline_errors": baseline_errors,
            "normalized_legacy_zip_count": normalized_legacy_zip_count,
        }
    if baseline_errors:
        parsed = {
            **parsed,
            "ok": False,
            "status": "baseline_mismatch",
            "validation_errors": list(parsed.get("validation_errors") or []) + baseline_errors,
        }
    # Preserve the already-validated run identity even if parse revalidation fails.
    parsed.setdefault("request_id", run.get("request_id"))
    parsed.setdefault("correlation_id", run.get("correlation_id"))
    selected = run.get("selected_answer") if isinstance(run.get("selected_answer"), dict) else None
    if selected is None:
        answer = run.get("answer") if isinstance(run.get("answer"), dict) else {}
        message = run.get("message") if isinstance(run.get("message"), dict) else {}
        selected = _protocol_answer_metadata(message, answer)
    parsed = _with_protocol_selection_on_artifact_candidates(
        parsed,
        selected=selected,
        request_id=run.get("request_id"),
        correlation_id=run.get("correlation_id"),
    )
    parsed["protocol_run_status"] = run.get("status")
    parsed["protocol_run_reply_validation_ok"] = run.get("reply_validation_ok")
    parsed["protocol_run_artifact_candidate_count"] = len(artifacts)
    return parsed


def _protocol_run_reusable_materialization_evidence(
    run: dict[str, Any],
    *,
    selected_request_id: str,
    profile_dir: str | Path,
) -> dict[str, Any]:
    """Prove that a validated exact run can reuse its verified inbox ZIP.

    This does not migrate or trust the previous verification blindly. It only
    authorizes reuse of the exact inbox path; the ordinary verification step
    reopens the ZIP and compares all envelope metadata before migration.
    """

    checks: dict[str, bool] = {}
    failures: list[str] = []

    def require(name: str, condition: Any) -> None:
        ok = bool(condition)
        checks[name] = ok
        if not ok:
            failures.append(name)

    request = run.get("request") if isinstance(run.get("request"), dict) else {}
    task = request.get("task") if isinstance(request.get("task"), dict) else {}
    reply = run.get("reply") if isinstance(run.get("reply"), dict) else {}
    message = run.get("message") if isinstance(run.get("message"), dict) else {}
    answer = run.get("answer") if isinstance(run.get("answer"), dict) else {}
    request_id = str(run.get("request_id") or "")
    conversation_id = str(run.get("conversation_id") or task.get("conversation_id") or "")
    answer_id = str(answer.get("id") or "")

    parsed = _normalize_protocol_run_reply_for_intake(run)
    candidates = parsed.get("artifact_candidates") if isinstance(parsed.get("artifact_candidates"), list) else []
    candidate = candidates[0] if len(candidates) == 1 and isinstance(candidates[0], dict) else {}
    filename = _safe_artifact_filename(candidate.get("filename"))
    expected_inbox = _artifact_inbox_dir(
        profile_dir=profile_dir,
        conversation_id=conversation_id,
        answer_id=answer_id,
        request_id=request_id,
    )
    download = run.get("download") if isinstance(run.get("download"), dict) else {}
    recorded_path = Path(str(download.get("path") or expected_inbox / str(filename or ""))).expanduser().resolve()
    expected_path = (expected_inbox / str(filename or "")).resolve()

    require("run_validated", _protocol_run_is_validated(run))
    require("request_id_exact", request_id == selected_request_id)
    require("conversation_id_present", bool(conversation_id))
    require("message_id_present", bool(message.get("id")))
    require("answer_id_present", bool(answer_id))
    require("reply_normalized", parsed.get("ok") is True and not parsed.get("validation_errors"))
    require("exactly_one_candidate", len(candidates) == 1)
    require("candidate_kind_zip", _protocol_run_candidate_zip_evidence(candidate).get("ok"))
    require("candidate_filename_safe", bool(filename))
    require("materialization_proven", run.get("artifact_materialization_proven") is True)
    require("browser_download_recorded", run.get("browser_download_performed") is True)
    require("verification_recorded", run.get("verification_performed") is True)
    require("envelope_metadata_verified", run.get("envelope_metadata_verified") is True)
    require("materialization_status_exact", run.get("materialization_status") == _MATERIALIZED_FINALIZATION_STATUS)
    require("no_prior_migration", run.get("migration_performed") is not True)
    require("no_adoption", run.get("adoption_performed") is not True)
    require("no_project_source_mutation", run.get("project_source_mutated") is not True)
    require("no_registry_or_state_mutation", not any(run.get(name) is True for name in ("artifact_registry_updated", "state_artifact_updated", "state_source_updated")))
    require("artifact_path_exact", bool(filename) and recorded_path == expected_path)
    require("artifact_file_present", recorded_path.is_file())

    return {
        "ok": not failures,
        "status": "validated_materialized_protocol_run_reusable" if not failures else "validated_materialized_protocol_run_not_reusable",
        "checks": checks,
        "failures": failures,
        "artifact_path": str(recorded_path),
        "artifact_inbox_dir": str(expected_inbox),
        "candidate": candidate,
    }


def _artifact_intake_from_protocol_run_record(
    run: dict[str, Any],
    *,
    run_path: Path | None = None,
    expected_filename: str | None = None,
    expected_version: str | None = None,
    expected_repo: str | None = None,
    source: str = "last_validated_protocol_reply",
    allow_legacy_unvalidated_replay: bool = False,
    reuse_materialized_protocol_run: bool = False,
) -> dict[str, Any]:
    expectations = _protocol_run_expectations(run)
    parsed = _normalize_protocol_run_reply_for_intake(
        run,
        allow_legacy_unvalidated_replay=allow_legacy_unvalidated_replay,
    )
    result = _artifact_intake_from_parsed_answer(
        parsed,
        expected_filename=expected_filename or expectations.get("expected_filename"),
        expected_version=expected_version or expectations.get("expected_version"),
        expected_repo=expected_repo or expectations.get("expected_repo"),
    )
    result.update({
        "source": source,
        "protocol_run_record_path": str(run_path) if run_path else None,
        "protocol_run_request_id": run.get("request_id"),
        "protocol_run_correlation_id": run.get("correlation_id"),
        "request": run.get("request"),
        "expectations": expectations,
        "reply_validation_ok": run.get("reply_validation_ok"),
        "artifact_candidates_source": "protocol_run.reply.artifacts",
    })
    if reuse_materialized_protocol_run:
        result.update({
            "download": copy.deepcopy(run.get("download")) if isinstance(run.get("download"), dict) else {},
            "download_performed": run.get("download_performed") is True,
            "browser_download_performed": run.get("browser_download_performed") is True,
            "verification_performed": run.get("verification_performed") is True,
            "artifact_materialization_proven": run.get("artifact_materialization_proven") is True,
            "envelope_metadata_verified": run.get("envelope_metadata_verified") is True,
            "materialization_status": run.get("materialization_status"),
            "artifact_inbox_dir": run.get("artifact_inbox_dir"),
            "manual_import_required": False,
            "materialized_protocol_run_reused": True,
        })
    return result

def _artifact_intake_from_parsed_answer(
    parsed: dict[str, Any],
    *,
    expected_filename: str | None = None,
    expected_version: str | None = None,
    expected_repo: str | None = None,
) -> dict[str, Any]:
    candidates = parsed.get("artifact_candidates") if isinstance(parsed.get("artifact_candidates"), list) else []
    reply_status = parsed.get("reply_status")
    result_type = parsed.get("result_type")
    parse_ok = bool(parsed.get("ok"))
    if parse_ok and reply_status == "no_artifact" and not candidates:
        return {
            "ok": True,
            "action": "artifact_intake",
            "mode": "dry_run",
            "status": "no_artifact",
            "source": "parsed_protocol_reply",
            "reply_parse_status": parsed.get("status"),
            "reply_parse_ok": True,
            "reply_request_id": parsed.get("request_id"),
            "reply_correlation_id": parsed.get("correlation_id"),
            "reply_status": reply_status,
            "result_type": result_type,
            "protocol_run_status": parsed.get("protocol_run_status"),
            "protocol_run_reply_validation_ok": parsed.get("protocol_run_reply_validation_ok"),
            "baseline": parsed.get("baseline"),
            "validation": parsed.get("validation"),
            "next_step": parsed.get("next_step"),
            "artifact_candidate_count": 0,
            "zip_candidate_count": 0,
            "valid_zip_candidate_count": 0,
            "selected_candidate": None,
            "artifact_candidates": [],
            "candidates": [],
            "next_action": "none",
            "intake_stage": "candidate_extraction",
            "automation_performed": False,
            "download_performed": False,
            "migration_performed": False,
            "adoption_performed": False,
            "operator_instruction": "Validated protocol reply declared no_artifact. No artifact download, migration, adoption, or state change is required.",
        }
    classification = classify_artifact_candidates(
        candidates,
        expected_filename=expected_filename,
        expected_version=expected_version,
        expected_repo=expected_repo,
    )
    if not parse_ok:
        status = parsed.get("status") or "invalid_reply"
        if status == "reply_schema_missing":
            status = "missing_reply"
        elif status in {"reply_schema_invalid", "reply_schema_ambiguous"}:
            status = "invalid_reply"
        ok = False
        next_action = "none"
    elif classification.get("ok"):
        status = "artifact_candidates_found"
        ok = True
        next_action = "download_verify"
    else:
        status = classification.get("status") or "artifact_candidate_invalid"
        ok = False
        next_action = "none"
    return {
        **classification,
        "candidates": classification.get("artifact_candidates") if isinstance(classification.get("artifact_candidates"), list) else [],
        "ok": bool(ok),
        "action": "artifact_intake",
        "mode": "dry_run",
        "status": status,
        "source": "parsed_protocol_reply",
        "reply_parse_status": parsed.get("status"),
        "reply_parse_ok": parse_ok,
        "validation_errors": parsed.get("validation_errors") if isinstance(parsed.get("validation_errors"), list) else [],
        "reply_request_id": parsed.get("request_id"),
        "reply_correlation_id": parsed.get("correlation_id"),
        "reply_status": reply_status,
        "result_type": result_type,
        "baseline": parsed.get("baseline"),
        "validation": parsed.get("validation"),
        "next_step": parsed.get("next_step"),
        "next_action": next_action,
        "intake_stage": "candidate_extraction",
        "operator_instruction": "No artifact was downloaded or migrated. Use a later explicit download/verify/migrate intake step after candidate selection is valid.",
    }




def _safe_artifact_inbox_component(value: Any, *, fallback: str) -> str:
    text = str(value or "").strip()
    if not text:
        return fallback
    text = re.sub(r"[^A-Za-z0-9_.-]+", "_", text).strip("._-")
    return text[:96] or fallback


def _selected_candidate_download_url(candidate: dict[str, Any]) -> str | None:
    download = candidate.get("download") if isinstance(candidate.get("download"), dict) else {}
    url = download.get("url") or candidate.get("url") or candidate.get("download_url")
    if not url:
        link_text = download.get("link_text")
        if isinstance(link_text, str) and urllib.parse.urlparse(link_text.strip()).scheme in {"file", "http", "https"}:
            url = link_text.strip()
    if isinstance(url, str) and url.strip():
        return url.strip()
    return None


def _safe_artifact_filename(filename: Any) -> str | None:
    name = Path(str(filename or "")).name
    if not name or name in {".", ".."}:
        return None
    if name != str(filename or ""):
        return None
    if not name.endswith(".zip"):
        return None
    return name


def _artifact_inbox_dir(*, profile_dir: str | Path, conversation_id: Any, answer_id: Any, request_id: Any) -> Path:
    root = Path(profile_dir).expanduser().resolve() / "artifact_inbox"
    conversation_component = _safe_artifact_inbox_component(conversation_id, fallback="conversation_unknown")
    answer_component = _safe_artifact_inbox_component(answer_id, fallback="answer_unknown")
    request_component = _safe_artifact_inbox_component(request_id, fallback="request_unknown")
    return root / conversation_component / answer_component / request_component



def _artifact_download_transport(url: str | None) -> dict[str, Any]:
    """Classify whether an artifact reference is directly downloadable.

    ChatGPT session-local artifact links may appear as sandbox:/mnt/data/...
    references. Those are valid inside the assistant sandbox, but they are not
    directly fetchable by the operator's local Promptbranch runtime. They must
    fail closed with an explicit handoff instead of being reported as a generic
    download failure.
    """

    text = str(url or "").strip()
    if not text:
        return {
            "ok": False,
            "status": "artifact_download_url_missing",
            "scheme": None,
            "direct_download_supported": False,
            "requires_browser_context": False,
            "manual_import_supported": True,
            "reason": "selected candidate has no download.url",
        }
    parsed = urllib.parse.urlparse(text)
    scheme = (parsed.scheme or "file").lower()
    direct_supported = scheme in {"file", "http", "https"}
    requires_browser_context = scheme == "sandbox"
    if direct_supported:
        return {
            "ok": True,
            "status": "artifact_download_url_supported",
            "scheme": scheme,
            "direct_download_supported": True,
            "requires_browser_context": False,
            "manual_import_supported": True,
            "url": text,
        }
    reason = (
        "sandbox artifact references are ChatGPT-session-local and require browser/session-context download before local import"
        if requires_browser_context
        else f"unsupported artifact download URL scheme: {scheme}"
    )
    return {
        "ok": False,
        "status": "artifact_download_url_unsupported",
        "scheme": scheme,
        "direct_download_supported": False,
        "requires_browser_context": requires_browser_context,
        "manual_import_supported": True,
        "url": text,
        "reason": reason,
    }




def _release_candidate_download_proof(candidate: dict[str, Any] | None) -> dict[str, Any]:
    """Classify whether a release-candidate artifact has host-verifiable download proof.

    LLM-provided ``download.available=true`` is only a claim.  For strict
    ``ask-release`` validation, a JSON-only ``sandbox:/mnt/data/...`` reference
    must not count as real artifact materialization because the local runtime
    cannot fetch it and the ChatGPT UI may render it as plain JSON text rather
    than a file attachment.
    """

    if not isinstance(candidate, dict):
        return {
            "ok": False,
            "status": "artifact_candidate_missing",
            "failure": "artifact_candidate_missing",
            "claim_available": False,
            "direct_download_supported": False,
            "attachment_proven": False,
            "json_only_declared": False,
        }
    download = candidate.get("download") if isinstance(candidate.get("download"), dict) else {}
    url = _selected_candidate_download_url(candidate)
    transport = _artifact_download_transport(url)
    claim_available = bool(download.get("available") or download.get("url") or download.get("link_text") or download.get("markdown_link"))
    attachment_proven = bool(
        download.get("attachment_id")
        or download.get("file_id")
        or download.get("ui_attachment") is True
        or download.get("attachment_detected") is True
        or download.get("attachment_proven") is True
    )
    if transport.get("direct_download_supported"):
        return {
            "ok": True,
            "status": "direct_download_url",
            "failure": None,
            "claim_available": claim_available,
            "url": url,
            "transport": transport,
            "direct_download_supported": True,
            "attachment_proven": attachment_proven,
            "json_only_declared": False,
        }
    if attachment_proven:
        return {
            "ok": True,
            "status": "chatgpt_attachment_proven",
            "failure": None,
            "claim_available": claim_available,
            "url": url,
            "transport": transport,
            "direct_download_supported": False,
            "attachment_proven": True,
            "json_only_declared": False,
        }
    if url and transport.get("scheme") == "sandbox":
        return {
            "ok": False,
            "status": "artifact_declared_but_not_attached",
            "failure": "artifact_declared_but_not_attached",
            "claim_available": claim_available,
            "url": url,
            "transport": transport,
            "direct_download_supported": False,
            "attachment_proven": False,
            "json_only_declared": True,
            "operator_instruction": "The protocol reply declared a sandbox artifact URL, but no real direct-download URL or verified ChatGPT attachment was detected. Treat this as manual-import-required, not as a created downloadable candidate.",
        }
    return {
        "ok": False,
        "status": "artifact_download_proof_missing",
        "failure": "artifact_download_proof_missing",
        "claim_available": claim_available,
        "url": url,
        "transport": transport,
        "direct_download_supported": False,
        "attachment_proven": False,
        "json_only_declared": bool(claim_available),
    }

def _artifact_manual_import_command(filename: str) -> str:
    safe_filename = Path(filename).name or "artifact.zip"
    return (
        "pb artifact intake --from-last-answer "
        f"--local-file /path/to/{safe_filename} "
        "--verify --migrate --json"
    )

def _copy_or_download_to_path(url: str, target_path: Path, *, timeout_seconds: float) -> None:
    parsed = urllib.parse.urlparse(url)
    target_path.parent.mkdir(parents=True, exist_ok=True)
    tmp_path = target_path.with_suffix(target_path.suffix + ".tmp")
    if parsed.scheme in {"", "file"}:
        source = Path(urllib.request.url2pathname(parsed.path if parsed.scheme == "file" else url)).expanduser()
        if not source.is_file():
            raise FileNotFoundError(str(source))
        with source.open("rb") as src, tmp_path.open("wb") as dst:
            while True:
                chunk = src.read(1024 * 1024)
                if not chunk:
                    break
                dst.write(chunk)
    elif parsed.scheme in {"http", "https"}:
        request = urllib.request.Request(url, headers={"User-Agent": "promptbranch-artifact-intake/0.0.245.5"})
        with urllib.request.urlopen(request, timeout=max(1.0, float(timeout_seconds))) as response, tmp_path.open("wb") as dst:  # noqa: S310 - operator-supplied artifact URL, explicit command
            while True:
                chunk = response.read(1024 * 1024)
                if not chunk:
                    break
                dst.write(chunk)
    else:
        raise ValueError(f"unsupported download URL scheme: {parsed.scheme}")
    tmp_path.replace(target_path)


def _artifact_file_metadata(path: Path) -> dict[str, Any]:
    digest = hashlib.sha256()
    size = 0
    with path.open("rb") as fh:
        while True:
            chunk = fh.read(1024 * 1024)
            if not chunk:
                break
            size += len(chunk)
            digest.update(chunk)
    return {
        "path": str(path),
        "filename": path.name,
        "size_bytes": size,
        "sha256": digest.hexdigest(),
    }


def _artifact_candidates_registry_path(profile_dir: str | Path) -> Path:
    return Path(profile_dir).expanduser().resolve() / "artifact_candidates.json"


def _load_artifact_candidate_registry(profile_dir: str | Path) -> dict[str, Any]:
    path = _artifact_candidates_registry_path(profile_dir)
    if not path.exists():
        return {"schema_version": 1, "candidates": []}
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return {"schema_version": 1, "candidates": []}
    if not isinstance(payload, dict):
        return {"schema_version": 1, "candidates": []}
    if not isinstance(payload.get("candidates"), list):
        payload["candidates"] = []
    payload.setdefault("schema_version", 1)
    return payload


def _record_artifact_candidate(profile_dir: str | Path, record: dict[str, Any]) -> tuple[Path, dict[str, Any]]:
    path = _artifact_candidates_registry_path(profile_dir)
    payload = _load_artifact_candidate_registry(profile_dir)
    candidates = [item for item in payload.get("candidates", []) if isinstance(item, dict)]
    record_path = str(record.get("path") or "")
    record_filename = str(record.get("filename") or "")
    candidates = [item for item in candidates if not (str(item.get("path") or "") == record_path or (record_filename and str(item.get("filename") or "") == record_filename))]
    candidates.append(record)
    candidates.sort(key=lambda item: str(item.get("migrated_at") or item.get("created_at") or ""), reverse=True)
    payload["schema_version"] = 1
    payload["updated_at"] = utc_now()
    payload["candidates"] = candidates
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(payload, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    return path, record


def _candidate_version_normalized(value: Any) -> str | None:
    if value is None:
        return None
    text = str(value).strip()
    if not text:
        return None
    if not text.startswith("v"):
        text = "v" + text
    return text if valid_version_text(text) else None


def _candidate_protocol_selection(candidate: dict[str, Any] | None) -> dict[str, Any] | None:
    if not isinstance(candidate, dict):
        return None
    selected = candidate.get("selected_protocol_reply") if isinstance(candidate.get("selected_protocol_reply"), dict) else {}
    request_id = selected.get("request_id") or candidate.get("reply_request_id")
    message_id = selected.get("message_id") or candidate.get("message_id")
    answer_id = selected.get("answer_id") or candidate.get("answer_id")
    conversation_id = selected.get("conversation_id") or candidate.get("conversation_id")
    if not any([request_id, message_id, answer_id, conversation_id]):
        return None
    return {
        "request_id": request_id,
        "correlation_id": selected.get("correlation_id") or candidate.get("reply_correlation_id"),
        "conversation_id": conversation_id,
        "conversation_url": selected.get("conversation_url"),
        "message_id": message_id,
        "message_index": selected.get("message_index"),
        "answer_id": answer_id,
        "answer_index": selected.get("answer_index"),
    }


def _artifact_origin_provenance(record: dict[str, Any] | None) -> dict[str, Any]:
    item = record if isinstance(record, dict) else {}
    return {
        "conversation_url": str(item.get("origin_conversation_url") or "").strip() or None,
        "conversation_id": str(item.get("origin_conversation_id") or "").strip() or None,
        "request_id": str(item.get("origin_request_id") or "").strip() or None,
        "correlation_id": str(item.get("origin_correlation_id") or "").strip() or None,
        "message_id": str(item.get("origin_message_id") or "").strip() or None,
        "answer_id": str(item.get("origin_answer_id") or "").strip() or None,
    }


def _artifact_origin_provenance_valid(record: dict[str, Any] | None) -> bool:
    origin = _artifact_origin_provenance(record)
    return _looks_like_chatgpt_project_conversation(
        str(origin.get("conversation_url") or ""),
        str(origin.get("conversation_id") or ""),
    )


def _select_artifact_candidate_record(
    profile_dir: str | Path,
    *,
    artifact: str | None = None,
    version: str | None = None,
) -> tuple[Path, dict[str, Any] | None, dict[str, Any]]:
    registry_path = _artifact_candidates_registry_path(profile_dir)
    payload = _load_artifact_candidate_registry(profile_dir)
    candidates = [item for item in payload.get("candidates", []) if isinstance(item, dict)]
    requested_artifact = Path(str(artifact or "")).name if artifact else None
    requested_version = _candidate_version_normalized(version)

    matches: list[dict[str, Any]] = []
    for item in candidates:
        filename = str(item.get("filename") or Path(str(item.get("path") or "")).name)
        item_version = _candidate_version_normalized(item.get("version") or item.get("zip_version") or item.get("filename_version") or _artifact_version_from_filename(filename))
        if requested_artifact and filename != requested_artifact:
            continue
        if requested_version and item_version != requested_version:
            continue
        matches.append(item)

    if not requested_artifact and not requested_version:
        matches = candidates[:1] if candidates else []

    if len(matches) == 1:
        return registry_path, matches[0], {"status": "candidate_selected", "candidate_count": len(candidates), "match_count": 1}
    if not matches:
        return registry_path, None, {"status": "candidate_not_found", "candidate_count": len(candidates), "match_count": 0}
    return registry_path, None, {"status": "candidate_ambiguous", "candidate_count": len(candidates), "match_count": len(matches), "matches": matches[:5]}


def _mark_artifact_candidate_accepted(profile_dir: str | Path, *, candidate: dict[str, Any], current_payload: dict[str, Any]) -> tuple[Path, dict[str, Any] | None]:
    path = _artifact_candidates_registry_path(profile_dir)
    payload = _load_artifact_candidate_registry(profile_dir)
    candidates = [item for item in payload.get("candidates", []) if isinstance(item, dict)]
    target_path = str(candidate.get("path") or "")
    target_filename = str(candidate.get("filename") or "")
    accepted_at = utc_now()
    updated: dict[str, Any] | None = None
    next_candidates: list[dict[str, Any]] = []
    for item in candidates:
        item_path = str(item.get("path") or "")
        item_filename = str(item.get("filename") or "")
        if (target_path and item_path == target_path) or (target_filename and item_filename == target_filename):
            item = {
                **item,
                "status": "accepted_candidate",
                "accepted": True,
                "accepted_at": accepted_at,
                "adoption_performed": True,
                "artifact_current": current_payload,
            }
            updated = item
        next_candidates.append(item)
    payload["schema_version"] = 1
    payload["updated_at"] = accepted_at
    payload["candidates"] = next_candidates
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(payload, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    return path, updated


def _report_artifact_current_matches_candidate(
    current_payload: dict[str, Any],
    *,
    filename: str,
    version: str,
    require_runtime_code_match: bool = True,
) -> tuple[bool, dict[str, bool]]:
    """Check candidate acceptance against normalized repo-loop current state."""

    entries = _artifact_current_repo_entries(current_payload)
    best_checks: dict[str, bool] = {
        "state_artifact_ref_matches_candidate": False,
        "state_source_ref_matches_candidate": False,
        "state_artifact_version_matches_candidate": False,
        "state_source_version_matches_candidate": False,
        "registry_current_matches_candidate": False,
        "registry_current_matches_state_artifact": False,
        "state_source_matches_state_artifact": False,
        "code_version_matches_state_source": False,
        "repo_loop_entry_present": bool(entries),
    }
    expected_filename = Path(str(filename)).name
    for repo_id, entry in entries:
        state = entry.get("state") if isinstance(entry.get("state"), dict) else {}
        registry_current = entry.get("registry_current") if isinstance(entry.get("registry_current"), dict) else {}
        consistency = entry.get("consistency") if isinstance(entry.get("consistency"), dict) else {}
        checks = {
            "state_artifact_ref_matches_candidate": Path(str(state.get("artifact_ref") or "")).name == expected_filename,
            "state_source_ref_matches_candidate": _source_filename_match_details({"filename": Path(str(state.get("source_ref") or "")).name}, expected_filename).get("matched") is True,
            "state_artifact_version_matches_candidate": state.get("artifact_version") == version,
            "state_source_version_matches_candidate": state.get("source_version") == version,
            "registry_current_matches_candidate": Path(str(registry_current.get("filename") or "")).name == expected_filename and registry_current.get("version") == version,
            "registry_current_matches_state_artifact": consistency.get("registry_current_matches_state_artifact") is True,
            "state_source_matches_state_artifact": consistency.get("state_source_matches_state_artifact") is True,
            "code_version_matches_state_source": consistency.get("code_version_matches_state_source") is True,
            "repo_loop_entry_present": True,
        }
        required = {key: value for key, value in checks.items() if require_runtime_code_match or key != "code_version_matches_state_source"}
        if sum(bool(value) for value in checks.values()) > sum(bool(value) for value in best_checks.values()):
            best_checks = checks
            best_checks["matched_repo_id"] = bool(repo_id)
        if all(required.values()):
            checks["matched_repo_id"] = bool(repo_id)
            return True, checks
    return False, best_checks


def _release_control_command_for_candidate(
    repo_root: Path,
    *,
    version: str,
    release_log_keep: int,
    skip_docker_logs: bool = True,
    prune_release_logs: bool = True,
) -> list[str]:
    script = repo_root / "chatgpt_claudecode_workflow_release_control.sh"
    command = [str(script), "--version", version, "--tests-only", "--adopt-if-green"]
    if skip_docker_logs:
        command.append("--skip-docker-logs")
    if prune_release_logs:
        command.append("--prune-release-logs")
    command.extend(["--release-log-keep", str(int(release_log_keep))])
    return command


def _run_release_control_candidate_acceptance(command: list[str], *, repo_root: Path, timeout_seconds: float) -> dict[str, Any]:
    started_at = utc_now()
    try:
        completed = subprocess.run(
            command,
            cwd=str(repo_root),
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            timeout=max(1.0, float(timeout_seconds)),
            check=False,
        )
    except subprocess.TimeoutExpired as exc:
        return {
            "ok": False,
            "status": "candidate_acceptance_timeout",
            "command": command,
            "started_at": started_at,
            "timeout_seconds": timeout_seconds,
            "stdout_tail": (exc.stdout or "")[-4000:] if isinstance(exc.stdout, str) else "",
            "stderr_tail": (exc.stderr or "")[-4000:] if isinstance(exc.stderr, str) else "",
        }
    return {
        "ok": completed.returncode == 0,
        "status": "candidate_acceptance_command_ok" if completed.returncode == 0 else "candidate_acceptance_command_failed",
        "command": command,
        "returncode": completed.returncode,
        "started_at": started_at,
        "finished_at": utc_now(),
        "stdout_tail": (completed.stdout or "")[-4000:],
        "stderr_tail": (completed.stderr or "")[-4000:],
    }


def _promptbranch_command_path() -> str:
    """Return the current Promptbranch executable for delegated local test profiles."""

    argv0 = Path(sys.argv[0]).expanduser()
    if argv0.exists():
        return str(argv0.resolve())
    resolved = shutil.which("pb") or shutil.which("promptbranch")
    if resolved:
        return str(Path(resolved).resolve())
    return sys.argv[0]


def _candidate_test_command_for_profile(
    repo_root: Path,
    *,
    version: str,
    profile: str,
    release_log_keep: int,
    skip_docker_logs: bool = True,
    prune_release_logs: bool = True,
) -> list[str]:
    """Build a bounded candidate-test command for a migrated candidate.

    The smoke profile is the MVP loop default and deliberately avoids the
    historically expensive release-control/full-suite path.  The full profile
    remains available as the explicit adoption-grade gate and intentionally
    omits --adopt-if-green so candidate-test never advances current state.
    """

    normalized_profile = (profile or "smoke").strip().lower()
    if normalized_profile == "smoke":
        return [sys.executable, _promptbranch_command_path(), "test", "smoke", "--json", "--path", str(repo_root), "--substep-timeout-seconds", "120"]
    if normalized_profile != "full":
        raise ValueError(f"unsupported candidate-test profile: {profile}")

    script = repo_root / "chatgpt_claudecode_workflow_release_control.sh"
    command = [str(script), "--version", version, "--tests-only"]
    if skip_docker_logs:
        command.append("--skip-docker-logs")
    if prune_release_logs:
        command.append("--prune-release-logs")
    command.extend(["--release-log-keep", str(int(release_log_keep))])
    return command


def _release_control_test_command_for_candidate(
    repo_root: Path,
    *,
    version: str,
    release_log_keep: int,
    skip_docker_logs: bool = True,
    prune_release_logs: bool = True,
) -> list[str]:
    """Backward-compatible full-profile command builder."""

    return _candidate_test_command_for_profile(
        repo_root,
        version=version,
        profile="full",
        release_log_keep=release_log_keep,
        skip_docker_logs=skip_docker_logs,
        prune_release_logs=prune_release_logs,
    )


def _candidate_test_logs_dir(profile_dir: str | Path) -> Path:
    return Path(profile_dir).expanduser().resolve() / "artifact_candidate_test_logs"


def _tail_text_file(path: Path, limit: int = 4000) -> str:
    try:
        data = path.read_text(errors="replace")
    except Exception:
        return ""
    return data[-max(0, int(limit)) :]


def _run_release_control_candidate_test(
    command: list[str],
    *,
    repo_root: Path,
    timeout_seconds: float,
    stdout_log_path: Path | None = None,
    stderr_log_path: Path | None = None,
) -> dict[str, Any]:
    """Run candidate tests with an internal timeout and durable log files.

    This intentionally avoids subprocess.run(..., timeout=...) because an outer
    shell timeout can kill the parent before any JSON is emitted and because
    captured output is invisible while the child is running.  The child is placed
    in a new process group so timeout cleanup can terminate the whole delegated
    tree, including pytest children.
    """

    started_at = utc_now()
    timeout = max(1.0, float(timeout_seconds))
    stdout_log_path = stdout_log_path.resolve() if stdout_log_path else None
    stderr_log_path = stderr_log_path.resolve() if stderr_log_path else None
    if stdout_log_path:
        stdout_log_path.parent.mkdir(parents=True, exist_ok=True)
    if stderr_log_path:
        stderr_log_path.parent.mkdir(parents=True, exist_ok=True)

    stdout_handle = open(stdout_log_path, "w", encoding="utf-8", errors="replace") if stdout_log_path else subprocess.DEVNULL
    stderr_handle = open(stderr_log_path, "w", encoding="utf-8", errors="replace") if stderr_log_path else subprocess.DEVNULL
    proc: subprocess.Popen[str] | None = None
    try:
        proc = subprocess.Popen(
            command,
            cwd=str(repo_root),
            stdout=stdout_handle,
            stderr=stderr_handle,
            text=True,
            start_new_session=True,
        )
        try:
            returncode = proc.wait(timeout=timeout)
        except subprocess.TimeoutExpired:
            timed_out_at = utc_now()
            try:
                os.killpg(proc.pid, signal.SIGTERM)
            except Exception:
                try:
                    proc.terminate()
                except Exception:
                    pass
            try:
                proc.wait(timeout=10)
                killed_with = "SIGTERM"
            except subprocess.TimeoutExpired:
                try:
                    os.killpg(proc.pid, signal.SIGKILL)
                except Exception:
                    try:
                        proc.kill()
                    except Exception:
                        pass
                proc.wait(timeout=10)
                killed_with = "SIGKILL"
            return {
                "ok": False,
                "status": "candidate_test_timeout",
                "command": command,
                "repo_path": str(repo_root),
                "pid": proc.pid,
                "process_group_pid": proc.pid,
                "started_at": started_at,
                "finished_at": utc_now(),
                "timed_out_at": timed_out_at,
                "timeout_seconds": timeout,
                "killed_with": killed_with,
                "stdout_log_path": str(stdout_log_path) if stdout_log_path else None,
                "stderr_log_path": str(stderr_log_path) if stderr_log_path else None,
                "stdout_tail": _tail_text_file(stdout_log_path) if stdout_log_path else "",
                "stderr_tail": _tail_text_file(stderr_log_path) if stderr_log_path else "",
                "adoption_performed": False,
            }
        return {
            "ok": returncode == 0,
            "status": "candidate_test_passed" if returncode == 0 else "candidate_test_failed",
            "command": command,
            "repo_path": str(repo_root),
            "pid": proc.pid,
            "process_group_pid": proc.pid,
            "returncode": returncode,
            "started_at": started_at,
            "finished_at": utc_now(),
            "timeout_seconds": timeout,
            "stdout_log_path": str(stdout_log_path) if stdout_log_path else None,
            "stderr_log_path": str(stderr_log_path) if stderr_log_path else None,
            "stdout_tail": _tail_text_file(stdout_log_path) if stdout_log_path else "",
            "stderr_tail": _tail_text_file(stderr_log_path) if stderr_log_path else "",
            "adoption_performed": False,
        }
    except Exception as exc:
        return {
            "ok": False,
            "status": "candidate_test_runner_failed",
            "command": command,
            "repo_path": str(repo_root),
            "started_at": started_at,
            "finished_at": utc_now(),
            "timeout_seconds": timeout,
            "stdout_log_path": str(stdout_log_path) if stdout_log_path else None,
            "stderr_log_path": str(stderr_log_path) if stderr_log_path else None,
            "stdout_tail": _tail_text_file(stdout_log_path) if stdout_log_path else "",
            "stderr_tail": _tail_text_file(stderr_log_path) if stderr_log_path else "",
            "error": str(exc),
            "adoption_performed": False,
        }
    finally:
        if stdout_handle not in (None, subprocess.DEVNULL):
            try:
                stdout_handle.close()
            except Exception:
                pass
        if stderr_handle not in (None, subprocess.DEVNULL):
            try:
                stderr_handle.close()
            except Exception:
                pass


def _artifact_candidate_test_records_dir(profile_dir: str | Path) -> Path:
    return Path(profile_dir).expanduser().resolve() / "artifact_candidate_tests"


def _record_artifact_candidate_test(profile_dir: str | Path, *, candidate: dict[str, Any], test_result: dict[str, Any]) -> tuple[Path, dict[str, Any] | None]:
    profile_root = Path(profile_dir).expanduser().resolve()
    version = _candidate_version_normalized(candidate.get("version") or candidate.get("zip_version") or candidate.get("filename_version") or _artifact_version_from_filename(str(candidate.get("filename") or ""))) or "unknown"
    record_dir = _artifact_candidate_test_records_dir(profile_root) / version
    record_dir.mkdir(parents=True, exist_ok=True)
    timestamp = re.sub(r"[^0-9A-Za-z_.-]+", "_", utc_now())
    record_path = record_dir / f"candidate_test.{timestamp}.json"
    record = {
        "schema": "promptbranch.artifact.candidate_test",
        "schema_version": "1.0",
        "candidate": candidate,
        "result": test_result,
        "adoption_performed": False,
        "project_source_mutated": False,
        "project_source_mutation": "not_requested",
        "source_upload_verification": None,
        "artifact_registry_updated": False,
        "state_artifact_updated": False,
        "state_source_updated": False,
    }
    record_path.write_text(json.dumps(record, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")

    registry_path = _artifact_candidates_registry_path(profile_root)
    payload = _load_artifact_candidate_registry(profile_root)
    candidates = [item for item in payload.get("candidates", []) if isinstance(item, dict)]
    target_path = str(candidate.get("path") or "")
    target_filename = str(candidate.get("filename") or "")
    updated: dict[str, Any] | None = None
    next_candidates: list[dict[str, Any]] = []
    for item in candidates:
        item_path = str(item.get("path") or "")
        item_filename = str(item.get("filename") or "")
        if (target_path and item_path == target_path) or (target_filename and item_filename == target_filename):
            item = {
                **item,
                "latest_test": {
                    "ok": bool(test_result.get("ok")),
                    "status": test_result.get("status"),
                    "record_path": str(record_path),
                    "tested_at": test_result.get("finished_at") or test_result.get("started_at") or utc_now(),
                    "adoption_performed": False,
                },
                "tested": bool(test_result.get("ok")),
                "test_status": test_result.get("status"),
            }
            updated = item
        next_candidates.append(item)
    payload["schema_version"] = 1
    payload["updated_at"] = utc_now()
    payload["candidates"] = next_candidates
    registry_path.parent.mkdir(parents=True, exist_ok=True)
    registry_path.write_text(json.dumps(payload, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    return record_path, updated


def _path_is_relative_to(path: Path, root: Path) -> bool:
    try:
        path.resolve().relative_to(root.resolve())
    except ValueError:
        return False
    return True


def _migrate_verified_intake_artifact_candidate(result: dict[str, Any], *, profile_dir: str | Path, repo_path: str | Path, conversation_id: Any, answer_id: Any, message_id: Any = None) -> dict[str, Any]:
    if result.get("status") not in {"verified_candidate", "download_verified", "manual_import_verified"} or not result.get("verification_performed") or not result.get("ok"):
        return {**result, "ok": False, "status": "candidate_not_verified", "migration_performed": False, "migration_error": "candidate must be successfully verified before migration; run artifact intake with --verify --migrate", "intake_stage": result.get("intake_stage") or "migration_requested", "adoption_performed": False}

    candidate = result.get("selected_candidate") if isinstance(result.get("selected_candidate"), dict) else None
    filename = _safe_artifact_filename((candidate or {}).get("filename"))
    if not candidate or not filename:
        return {**result, "ok": False, "status": "artifact_wrong_filename", "migration_performed": False, "migration_error": "verified candidate filename must be a basename ending in .zip", "intake_stage": "migration_requested", "adoption_performed": False}

    profile_root = Path(profile_dir).expanduser().resolve()
    inbox_root = profile_root / "artifact_inbox"
    download = result.get("download") if isinstance(result.get("download"), dict) else {}
    source_value = str(download.get("path") or "")
    if source_value:
        source_path = Path(source_value).expanduser().resolve()
    else:
        source_path = (_artifact_inbox_dir(profile_dir=profile_root, conversation_id=conversation_id, answer_id=answer_id, request_id=result.get("reply_request_id")) / filename).resolve()
    if not source_path.is_file():
        return {**result, "ok": False, "status": "artifact_inbox_candidate_missing", "migration_performed": False, "migration_error": "verified candidate ZIP is missing from artifact_inbox", "artifact_inbox_path": str(source_path), "intake_stage": "migration_requested", "adoption_performed": False}
    if not _path_is_relative_to(source_path, inbox_root):
        return {**result, "ok": False, "status": "artifact_inbox_boundary_violation", "migration_performed": False, "migration_error": "migration source must be inside .pb_profile/artifact_inbox", "artifact_inbox_path": str(source_path), "intake_stage": "migration_requested", "adoption_performed": False}

    verification = verify_zip_artifact(source_path)
    if not verification.get("ok"):
        return {**result, "ok": False, "status": "artifact_zip_invalid", "migration_performed": False, "migration_error": str(verification.get("error") or "artifact_zip_invalid"), "verification": verification, "intake_stage": "migration_requested", "adoption_performed": False}

    repo_root = Path(repo_path).expanduser().resolve()
    if not repo_root.is_dir():
        return {**result, "ok": False, "status": "repo_path_invalid", "migration_performed": False, "migration_error": f"repo path is not a directory: {repo_root}", "repo_path": str(repo_root), "intake_stage": "migration_requested", "adoption_performed": False}
    target_path = (repo_root / filename).resolve()
    if target_path.parent != repo_root:
        return {**result, "ok": False, "status": "artifact_wrong_filename", "migration_performed": False, "migration_error": "migration target must stay directly under repo root", "target_path": str(target_path), "intake_stage": "migration_requested", "adoption_performed": False}

    source_metadata = _artifact_file_metadata(source_path)
    target_existed = target_path.exists()
    copy_performed = False
    if target_existed:
        target_metadata_before = _artifact_file_metadata(target_path)
        if target_metadata_before.get("sha256") != source_metadata.get("sha256"):
            return {**result, "ok": False, "status": "artifact_migration_target_exists", "migration_performed": False, "migration_error": "repo-root artifact already exists with different content", "source": source_metadata, "target": target_metadata_before, "target_path": str(target_path), "intake_stage": "migration_requested", "adoption_performed": False}
    else:
        shutil.copy2(source_path, target_path)
        copy_performed = True

    target_metadata = _artifact_file_metadata(target_path)
    zip_version = _read_zip_version_file(target_path) or result.get("zip_version")
    filename_version = _artifact_version_from_filename(filename) or result.get("filename_version")
    migrated_at = utc_now()
    candidate_record = {
        "schema": "promptbranch.artifact.candidate",
        "schema_version": "1.0",
        "kind": "candidate_release",
        "status": "candidate_release",
        "accepted": False,
        "verified": True,
        "filename": filename,
        "version": zip_version or filename_version or candidate.get("version"),
        "repo_id": result.get("expected_repo") or candidate.get("expected_repo") or candidate.get("repo_prefix"),
        "path": str(target_path),
        "sha256": target_metadata.get("sha256"),
        "size_bytes": target_metadata.get("size_bytes"),
        "source_inbox_path": str(source_path),
        "source_inbox_sha256": source_metadata.get("sha256"),
        "reply_request_id": result.get("reply_request_id"),
        "reply_correlation_id": result.get("reply_correlation_id"),
        "conversation_id": conversation_id,
        "message_id": message_id or result.get("selected_message_id"),
        "answer_id": answer_id,
        "selected_protocol_reply": result.get("selected_protocol_reply"),
        "verification": verification,
        "zip_version": zip_version,
        "filename_version": filename_version,
        "migrated_at": migrated_at,
        "migration_performed": True,
        "adoption_performed": False,
    }
    registry_path, registry_record = _record_artifact_candidate(profile_root, candidate_record)

    inbox_dir = _artifact_inbox_dir(profile_dir=profile_root, conversation_id=conversation_id, answer_id=answer_id, request_id=result.get("reply_request_id"))
    intake_record_path = inbox_dir / "intake.json"
    try:
        existing: dict[str, Any] = {}
        if intake_record_path.is_file():
            loaded = json.loads(intake_record_path.read_text(encoding="utf-8"))
            if isinstance(loaded, dict):
                existing = loaded
        existing.update({
            "status": "migrated_candidate",
            "migration_performed": True,
            "migration": {"source_path": str(source_path), "target_path": str(target_path), "target_existed": target_existed, "copy_performed": copy_performed, "migrated_at": migrated_at},
            "candidate_registry_updated": True,
            "candidate_registry_path": str(registry_path),
            "candidate_registry_entry": registry_record,
            "adoption_performed": False,
        })
        intake_record_path.parent.mkdir(parents=True, exist_ok=True)
        intake_record_path.write_text(json.dumps(existing, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    except (OSError, json.JSONDecodeError) as exc:
        return {**result, "ok": False, "status": "artifact_migration_metadata_failed", "migration_performed": True, "migration_error": str(exc), "migration": {"source_path": str(source_path), "target_path": str(target_path), "target_existed": target_existed, "copy_performed": copy_performed}, "candidate_registry_updated": True, "candidate_registry_path": str(registry_path), "candidate_registry_entry": registry_record, "intake_stage": "migrated", "adoption_performed": False}

    return {
        **result,
        "ok": True,
        "status": "migrated_candidate",
        "intake_stage": "migrated",
        "migration_performed": True,
        "migration": {"source_path": str(source_path), "target_path": str(target_path), "target_existed": target_existed, "copy_performed": copy_performed, "migrated_at": migrated_at},
        "candidate_registry_updated": True,
        "candidate_registry_path": str(registry_path),
        "candidate_registry_entry": registry_record,
        "intake_record_path": str(intake_record_path),
        "adoption_performed": False,
        "operator_instruction": "Verified candidate ZIP was migrated to the repo root and registered as candidate_release only. Adoption and Project Source mutation were not performed.",
    }



def _manual_import_selected_artifact_candidate(
    result: dict[str, Any],
    *,
    profile_dir: str | Path,
    conversation_id: Any,
    answer_id: Any,
    local_file: str | Path,
) -> dict[str, Any]:
    """Copy a browser/session-downloaded artifact into artifact_inbox.

    This is the explicit handoff path for sandbox:/ artifacts. It preserves the
    normal candidate validation, verification and migration flow while avoiding
    any claim that the local process directly downloaded the ChatGPT sandbox URL.
    """

    if result.get("status") not in {"candidate_selected", "artifact_candidates_found"} or not isinstance(result.get("selected_candidate"), dict):
        return {
            **result,
            "ok": False,
            "status": "artifact_candidate_not_selected",
            "manual_import_performed": False,
            "manual_import_error": "a single valid candidate must be selected before manual import",
            "download_performed": False,
            "intake_stage": "candidate_extraction",
        }
    candidate = dict(result["selected_candidate"])
    filename = _safe_artifact_filename(candidate.get("filename"))
    if not filename:
        return {
            **result,
            "ok": False,
            "status": "artifact_wrong_filename",
            "manual_import_performed": False,
            "manual_import_error": "selected candidate filename must be a basename ending in .zip",
            "download_performed": False,
            "intake_stage": "candidate_extraction",
        }
    kind = str(candidate.get("kind") or "").strip().lower()
    if kind and kind != "zip":
        return {
            **result,
            "ok": False,
            "status": "unsupported_artifact_type",
            "manual_import_performed": False,
            "manual_import_error": "selected candidate kind must be zip",
            "download_performed": False,
            "intake_stage": "manual_import_requested",
            "migration_performed": False,
            "adoption_performed": False,
        }
    role = str(candidate.get("role") or "").strip()
    if role and role not in {"candidate_release", "repair_candidate", "visual_artifact_roundtrip_output", "smoke_test_artifact"}:
        return {
            **result,
            "ok": False,
            "status": "unsupported_artifact_role",
            "manual_import_performed": False,
            "manual_import_error": "selected candidate role must be candidate_release, repair_candidate, visual_artifact_roundtrip_output, or smoke_test_artifact",
            "download_performed": False,
            "intake_stage": "manual_import_requested",
            "migration_performed": False,
            "adoption_performed": False,
        }

    source_path = Path(local_file).expanduser().resolve()
    if not source_path.is_file():
        return {
            **result,
            "ok": False,
            "status": "artifact_manual_import_source_missing",
            "manual_import_performed": False,
            "manual_import_error": f"manual import file does not exist: {source_path}",
            "manual_import_source_path": str(source_path),
            "download_performed": False,
            "intake_stage": "manual_import_requested",
            "migration_performed": False,
            "adoption_performed": False,
        }
    if source_path.suffix.lower() != ".zip":
        return {
            **result,
            "ok": False,
            "status": "artifact_manual_import_not_zip",
            "manual_import_performed": False,
            "manual_import_error": "manual import file must be a ZIP artifact",
            "manual_import_source_path": str(source_path),
            "download_performed": False,
            "intake_stage": "manual_import_requested",
            "migration_performed": False,
            "adoption_performed": False,
        }

    inbox_dir = _artifact_inbox_dir(
        profile_dir=profile_dir,
        conversation_id=conversation_id,
        answer_id=answer_id,
        request_id=result.get("reply_request_id"),
    )
    inbox_dir.mkdir(parents=True, exist_ok=True)
    target_path = inbox_dir / filename
    overwritten = target_path.exists()
    try:
        tmp_path = target_path.with_suffix(target_path.suffix + ".tmp")
        shutil.copy2(source_path, tmp_path)
        tmp_path.replace(target_path)
        metadata = _artifact_file_metadata(target_path)
    except OSError as exc:
        return {
            **result,
            "ok": False,
            "status": "artifact_manual_import_failed",
            "manual_import_performed": False,
            "manual_import_error": str(exc),
            "manual_import_source_path": str(source_path),
            "artifact_inbox_dir": str(inbox_dir),
            "download_performed": False,
            "intake_stage": "manual_import_requested",
            "migration_performed": False,
            "adoption_performed": False,
        }
    if metadata["size_bytes"] <= 0:
        return {
            **result,
            "ok": False,
            "status": "artifact_manual_import_empty",
            "manual_import_performed": True,
            "manual_import": metadata,
            "manual_import_source_path": str(source_path),
            "download": metadata,
            "download_performed": False,
            "artifact_inbox_dir": str(inbox_dir),
            "intake_stage": "manual_imported",
            "migration_performed": False,
            "adoption_performed": False,
        }

    transport = {
        "ok": True,
        "status": "artifact_manual_imported",
        "scheme": "file",
        "direct_download_supported": False,
        "requires_browser_context": False,
        "manual_import_supported": True,
        "mode": "manual_import",
        "source_path": str(source_path),
    }
    intake_record = {
        "schema": "promptbranch.artifact.intake.manual_import",
        "schema_version": "1.0",
        "status": "manual_imported",
        "candidate": candidate,
        "manual_import": metadata,
        "manual_import_source_path": str(source_path),
        "download": metadata,
        "download_url": _selected_candidate_download_url(candidate),
        "download_transport": transport,
        "reply_request_id": result.get("reply_request_id"),
        "reply_correlation_id": result.get("reply_correlation_id"),
        "conversation_id": conversation_id,
        "answer_id": answer_id,
        "created_at": utc_now(),
        "verification_performed": False,
        "migration_performed": False,
        "adoption_performed": False,
    }
    try:
        (inbox_dir / "intake.json").write_text(json.dumps(intake_record, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    except OSError as exc:
        return {
            **result,
            "ok": False,
            "status": "artifact_manual_import_metadata_failed",
            "manual_import_performed": True,
            "manual_import": metadata,
            "manual_import_error": str(exc),
            "manual_import_source_path": str(source_path),
            "download": metadata,
            "download_performed": False,
            "artifact_inbox_dir": str(inbox_dir),
            "intake_stage": "manual_imported",
        }

    return {
        **result,
        "ok": True,
        "status": "manual_imported",
        "intake_stage": "manual_imported",
        "manual_import_performed": True,
        "manual_import": metadata,
        "manual_import_source_path": str(source_path),
        "manual_import_source_filename": source_path.name,
        "manual_import_filename_matches_candidate": source_path.name == filename,
        "download_performed": False,
        "download": metadata,
        "download_url": _selected_candidate_download_url(candidate),
        "download_transport": transport,
        "download_overwrote_existing": overwritten,
        "artifact_inbox_dir": str(inbox_dir),
        "intake_record_path": str(inbox_dir / "intake.json"),
        "verification_performed": False,
        "migration_performed": False,
        "adoption_performed": False,
        "operator_instruction": "Artifact was manually imported into .pb_profile/artifact_inbox. Run/continue with --verify --migrate to validate and register it as a candidate_release.",
    }

async def _download_selected_artifact_candidate_via_browser(
    backend: Any,
    result: dict[str, Any],
    *,
    profile_dir: str | Path,
    conversation_id: Any,
    answer_id: Any,
    timeout_seconds: float,
    keep_open: bool = False,
) -> dict[str, Any]:
    if result.get("status") not in {"candidate_selected", "artifact_candidates_found"} or not isinstance(result.get("selected_candidate"), dict):
        return _download_selected_artifact_candidate(
            result,
            profile_dir=profile_dir,
            conversation_id=conversation_id,
            answer_id=answer_id,
            timeout_seconds=timeout_seconds,
        )
    candidate = dict(result["selected_candidate"])
    filename = _safe_artifact_filename(candidate.get("filename"))
    url = _selected_candidate_download_url(candidate)
    transport = _artifact_download_transport(url)
    if not filename or transport.get("scheme") != "sandbox":
        return _download_selected_artifact_candidate(
            result,
            profile_dir=profile_dir,
            conversation_id=conversation_id,
            answer_id=answer_id,
            timeout_seconds=timeout_seconds,
        )
    conversation_url = str(result.get("conversation_url") or "").strip()
    if not conversation_url:
        return {
            **result,
            "ok": False,
            "status": "artifact_browser_download_conversation_missing",
            "download_performed": False,
            "download_error": "browser-assisted sandbox download requires selected conversation_url",
            "download_url": url,
            "download_transport": transport,
            "requires_browser_context": True,
            "manual_import_supported": True,
            "intake_stage": "download_requested",
        }
    inbox_dir = _artifact_inbox_dir(
        profile_dir=profile_dir,
        conversation_id=conversation_id,
        answer_id=answer_id,
        request_id=result.get("reply_request_id"),
    )
    target_path = inbox_dir / filename
    overwritten = target_path.exists()
    if not hasattr(backend, "download_chat_artifact"):
        return {
            **result,
            "ok": False,
            "status": "artifact_browser_download_unsupported_backend",
            "download_performed": False,
            "download_error": "backend does not support browser-assisted artifact download",
            "download_url": url,
            "download_transport": transport,
            "requires_browser_context": True,
            "manual_import_supported": True,
            "browser_download_handoff": {
                "required": True,
                "reason": "backend does not support browser-assisted artifact download",
                "artifact_ref": url,
                "filename": filename,
                "manual_import_command": _artifact_manual_import_command(filename),
            },
            "manual_import_command": _artifact_manual_import_command(filename),
            "intake_stage": "download_requested",
        }
    # When the backend is the Dockerized ChatGPT service, the local repo path
    # is usually not writable from inside the container. Ask the service to save
    # into a container-writable staging path and return the bytes, then import
    # them into the CLI-owned artifact inbox below.
    service_staging_path = f"/tmp/promptbranch-artifact-downloads/{conversation_id or 'unknown'}/{answer_id or 'unknown'}/{result.get('reply_request_id') or 'unknown'}/{filename}"
    browser_target_path = service_staging_path if backend.__class__.__name__ == "ServiceBackend" else str(target_path)
    selection = result.get("selected_protocol_reply") if isinstance(result.get("selected_protocol_reply"), dict) else {}
    request_id = result.get("reply_request_id") or selection.get("request_id")
    correlated_answer_id = answer_id or selection.get("answer_id")
    correlated_turn_index = selection.get("answer_turn_index")
    try:
        try:
            browser_result = await backend.download_chat_artifact(
                conversation_url=conversation_url,
                artifact_url=url,
                filename=filename,
                target_path=browser_target_path,
                timeout_seconds=timeout_seconds,
                keep_open=keep_open,
                request_id=str(request_id) if request_id else None,
                answer_id=str(correlated_answer_id) if correlated_answer_id else None,
                answer_turn_index=int(correlated_turn_index) if correlated_turn_index is not None else None,
            )
        except TypeError as type_exc:
            # Compatibility fallback for older test doubles and third-party
            # backends. Production DirectBackend/ServiceBackend support the
            # correlated answer identity fields.
            if not any(token in str(type_exc) for token in ("request_id", "answer_id", "answer_turn_index")):
                raise
            browser_result = await backend.download_chat_artifact(
                conversation_url=conversation_url,
                artifact_url=url,
                filename=filename,
                target_path=browser_target_path,
                timeout_seconds=timeout_seconds,
                keep_open=keep_open,
            )
            if isinstance(browser_result, dict):
                browser_result = {**browser_result, "correlation_arguments_supported": False}
    except Exception as exc:  # noqa: BLE001
        return {
            **result,
            "ok": False,
            "status": "artifact_browser_download_failed",
            "download_performed": False,
            "download_error": str(exc),
            "download_url": url,
            "download_transport": {**transport, "browser_attempted": True},
            "artifact_inbox_dir": str(inbox_dir),
            "intake_stage": "download_requested",
        }
    if not isinstance(browser_result, dict) or not browser_result.get("ok"):
        return {
            **result,
            "ok": False,
            "status": (browser_result or {}).get("status") if isinstance(browser_result, dict) else "artifact_browser_download_failed",
            "download_performed": False,
            "download_error": (browser_result or {}).get("download_error") if isinstance(browser_result, dict) else "browser-assisted download returned invalid result",
            "download_url": url,
            "download_transport": {**transport, "browser_attempted": True, "browser_result": browser_result},
            "artifact_inbox_dir": str(inbox_dir),
            "intake_stage": "download_requested",
        }
    if not target_path.is_file():
        content_b64 = browser_result.get("content_base64") if isinstance(browser_result, dict) else None
        if content_b64:
            try:
                inbox_dir.mkdir(parents=True, exist_ok=True)
                target_path.write_bytes(base64.b64decode(content_b64.encode("ascii")))
            except Exception as exc:  # noqa: BLE001
                return {
                    **result,
                    "ok": False,
                    "status": "artifact_browser_download_import_failed",
                    "download_performed": False,
                    "download_error": str(exc),
                    "download_url": url,
                    "download_transport": {**transport, "browser_attempted": True, "browser_result": browser_result, "cli_import_attempted": True},
                    "artifact_inbox_dir": str(inbox_dir),
                    "intake_stage": "download_requested",
                }
    if not target_path.is_file():
        browser_target = Path(str(browser_result.get("target_path") or "")).expanduser() if isinstance(browser_result, dict) else None
        if browser_target and browser_target.is_file():
            try:
                inbox_dir.mkdir(parents=True, exist_ok=True)
                shutil.copy2(browser_target, target_path)
            except Exception as exc:  # noqa: BLE001
                return {
                    **result,
                    "ok": False,
                    "status": "artifact_browser_download_import_failed",
                    "download_performed": False,
                    "download_error": str(exc),
                    "download_url": url,
                    "download_transport": {**transport, "browser_attempted": True, "browser_result": browser_result, "cli_import_attempted": True, "browser_target_copy_attempted": True},
                    "artifact_inbox_dir": str(inbox_dir),
                    "intake_stage": "download_requested",
                }
    if not target_path.is_file():
        return {
            **result,
            "ok": False,
            "status": "artifact_browser_download_missing_file",
            "download_performed": False,
            "download_error": "browser reported success but no local artifact was imported",
            "download_url": url,
            "download_transport": {**transport, "browser_attempted": True, "browser_result": browser_result, "cli_import_attempted": True},
            "artifact_inbox_dir": str(inbox_dir),
            "intake_stage": "download_requested",
        }
    metadata = _artifact_file_metadata(target_path)
    intake_record = {
        "schema": "promptbranch.artifact.intake.download",
        "schema_version": "1.0",
        "status": "downloaded",
        "candidate": candidate,
        "download": metadata,
        "download_url": url,
        "download_transport": {**transport, "status": "artifact_browser_downloaded", "browser_result": browser_result},
        "reply_request_id": result.get("reply_request_id"),
        "reply_correlation_id": result.get("reply_correlation_id"),
        "conversation_id": conversation_id,
        "answer_id": answer_id,
        "created_at": utc_now(),
        "verification_performed": False,
        "migration_performed": False,
        "adoption_performed": False,
    }
    try:
        (inbox_dir / "intake.json").write_text(json.dumps(intake_record, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    except OSError as exc:
        return {
            **result,
            "ok": False,
            "status": "artifact_download_metadata_failed",
            "download_performed": True,
            "download": metadata,
            "download_error": str(exc),
            "download_url": url,
            "artifact_inbox_dir": str(inbox_dir),
            "intake_stage": "downloaded",
        }
    return {
        **result,
        "ok": True,
        "status": "downloaded",
        "intake_stage": "downloaded",
        "download_performed": True,
        "browser_download_performed": True,
        "manual_import_performed": False,
        "download": metadata,
        "download_url": url,
        "download_transport": {**transport, "status": "artifact_browser_downloaded", "browser_result": browser_result, "service_staging_path": browser_target_path},
        "download_overwrote_existing": overwritten,
        "artifact_inbox_dir": str(inbox_dir),
        "intake_record_path": str(inbox_dir / "intake.json"),
        "verification_performed": False,
        "migration_performed": False,
        "adoption_performed": False,
        "operator_instruction": "Artifact was downloaded through the browser/session context into .pb_profile/artifact_inbox. ZIP verification, migration, and adoption were not performed.",
    }


def _download_selected_artifact_candidate(
    result: dict[str, Any],
    *,
    profile_dir: str | Path,
    conversation_id: Any,
    answer_id: Any,
    timeout_seconds: float,
) -> dict[str, Any]:
    if result.get("status") not in {"candidate_selected", "artifact_candidates_found"} or not isinstance(result.get("selected_candidate"), dict):
        return {
            **result,
            "ok": False,
            "status": "artifact_candidate_not_selected",
            "download_performed": False,
            "download_error": "a single valid candidate must be selected before download",
            "intake_stage": "candidate_extraction",
        }
    candidate = dict(result["selected_candidate"])
    filename = _safe_artifact_filename(candidate.get("filename"))
    if not filename:
        return {
            **result,
            "ok": False,
            "status": "artifact_wrong_filename",
            "download_performed": False,
            "download_error": "selected candidate filename must be a basename ending in .zip",
            "intake_stage": "candidate_extraction",
        }
    kind = str(candidate.get("kind") or "").strip().lower()
    if kind and kind != "zip":
        return {
            **result,
            "ok": False,
            "status": "unsupported_artifact_type",
            "download_performed": False,
            "download_error": "selected candidate kind must be zip",
            "intake_stage": "download_requested",
            "migration_performed": False,
            "adoption_performed": False,
        }
    role = str(candidate.get("role") or "").strip()
    if role and role not in {"candidate_release", "repair_candidate", "visual_artifact_roundtrip_output", "smoke_test_artifact"}:
        return {
            **result,
            "ok": False,
            "status": "unsupported_artifact_role",
            "download_performed": False,
            "download_error": "selected candidate role must be candidate_release, repair_candidate, visual_artifact_roundtrip_output, or smoke_test_artifact",
            "intake_stage": "download_requested",
            "migration_performed": False,
            "adoption_performed": False,
        }
    download_payload = candidate.get("download") if isinstance(candidate.get("download"), dict) else {}
    if download_payload.get("available") is not True:
        return {
            **result,
            "ok": False,
            "status": "artifact_download_unavailable",
            "download_performed": False,
            "download_error": "selected candidate does not declare download.available=true",
            "intake_stage": "download_requested",
            "migration_performed": False,
            "adoption_performed": False,
        }
    url = _selected_candidate_download_url(candidate)
    if not url:
        return {
            **result,
            "ok": False,
            "status": "artifact_download_url_missing",
            "download_performed": False,
            "manual_import_performed": False,
            "download_error": "selected candidate has no download.url",
            "intake_stage": "download_requested",
        }
    transport = _artifact_download_transport(url)
    if not transport.get("direct_download_supported"):
        handoff = {
            "required": True,
            "reason": transport.get("reason"),
            "artifact_ref": url,
            "filename": filename,
            "manual_import_command": _artifact_manual_import_command(filename),
        }
        return {
            **result,
            "ok": False,
            "status": "artifact_download_url_unsupported",
            "download_performed": False,
            "manual_import_performed": False,
            "download_error": transport.get("reason") or f"unsupported artifact download URL scheme: {transport.get('scheme')}",
            "download_url": url,
            "download_url_scheme": transport.get("scheme"),
            "download_transport": transport,
            "requires_browser_context": bool(transport.get("requires_browser_context")),
            "manual_import_supported": True,
            "browser_download_handoff": handoff,
            "manual_import_command": handoff["manual_import_command"],
            "intake_stage": "download_requested",
            "migration_performed": False,
            "adoption_performed": False,
            "operator_instruction": "Artifact URL is not directly downloadable by the local runtime. Download it through the browser/session context, then rerun artifact intake with --local-file.",
        }
    inbox_dir = _artifact_inbox_dir(
        profile_dir=profile_dir,
        conversation_id=conversation_id,
        answer_id=answer_id,
        request_id=result.get("reply_request_id"),
    )
    target_path = inbox_dir / filename
    overwritten = target_path.exists()
    try:
        _copy_or_download_to_path(url, target_path, timeout_seconds=timeout_seconds)
        metadata = _artifact_file_metadata(target_path)
    except Exception as exc:  # noqa: BLE001 - report explicit operator-facing download failure
        return {
            **result,
            "ok": False,
            "status": "artifact_download_failed",
            "download_performed": False,
            "download_error": str(exc),
            "download_url": url,
            "artifact_inbox_dir": str(inbox_dir),
            "intake_stage": "download_requested",
        }
    if metadata["size_bytes"] <= 0:
        return {
            **result,
            "ok": False,
            "status": "artifact_download_empty",
            "download_performed": True,
            "download": metadata,
            "download_url": url,
            "artifact_inbox_dir": str(inbox_dir),
            "intake_stage": "downloaded",
            "migration_performed": False,
            "adoption_performed": False,
        }
    intake_record = {
        "schema": "promptbranch.artifact.intake.download",
        "schema_version": "1.0",
        "status": "downloaded",
        "candidate": candidate,
        "download": metadata,
        "download_url": url,
        "download_transport": transport,
        "reply_request_id": result.get("reply_request_id"),
        "reply_correlation_id": result.get("reply_correlation_id"),
        "conversation_id": conversation_id,
        "answer_id": answer_id,
        "created_at": utc_now(),
        "verification_performed": False,
        "migration_performed": False,
        "adoption_performed": False,
    }
    try:
        (inbox_dir / "intake.json").write_text(json.dumps(intake_record, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    except OSError as exc:
        return {
            **result,
            "ok": False,
            "status": "artifact_download_metadata_failed",
            "download_performed": True,
            "download": metadata,
            "download_error": str(exc),
            "download_url": url,
            "artifact_inbox_dir": str(inbox_dir),
            "intake_stage": "downloaded",
        }
    return {
        **result,
        "ok": True,
        "status": "downloaded",
        "intake_stage": "downloaded",
        "download_performed": True,
        "download": metadata,
        "download_url": url,
        "download_transport": transport,
        "download_overwrote_existing": overwritten,
        "artifact_inbox_dir": str(inbox_dir),
        "intake_record_path": str(inbox_dir / "intake.json"),
        "verification_performed": False,
        "migration_performed": False,
        "adoption_performed": False,
        "operator_instruction": "Artifact was downloaded to .pb_profile/artifact_inbox only. ZIP verification, migration, and adoption were not performed.",
    }


def _verify_intake_artifact_candidate(
    result: dict[str, Any],
    *,
    profile_dir: str | Path,
    conversation_id: Any,
    answer_id: Any,
) -> dict[str, Any]:
    """Verify a selected artifact candidate already present in artifact_inbox.

    This is intentionally an inbox-only verification step. It never migrates the
    ZIP to the repo root, never adopts it, and never mutates Project Sources.
    """

    candidate = result.get("selected_candidate") if isinstance(result.get("selected_candidate"), dict) else None
    if result.get("status") not in {"candidate_selected", "artifact_candidates_found", "downloaded", "manual_imported"} or candidate is None:
        return {
            **result,
            "ok": False,
            "status": "artifact_candidate_not_selected",
            "verification_performed": False,
            "verification_error": "a single valid candidate must be selected before verification",
            "intake_stage": result.get("intake_stage") or "candidate_extraction",
            "migration_performed": False,
            "adoption_performed": False,
        }

    filename = _safe_artifact_filename(candidate.get("filename"))
    if not filename:
        return {
            **result,
            "ok": False,
            "status": "artifact_wrong_filename",
            "verification_performed": False,
            "verification_error": "selected candidate filename must be a basename ending in .zip",
            "intake_stage": result.get("intake_stage") or "candidate_extraction",
            "migration_performed": False,
            "adoption_performed": False,
        }

    inbox_dir = _artifact_inbox_dir(
        profile_dir=profile_dir,
        conversation_id=conversation_id,
        answer_id=answer_id,
        request_id=result.get("reply_request_id"),
    )
    download = result.get("download") if isinstance(result.get("download"), dict) else {}
    candidate_path = Path(str(download.get("path") or inbox_dir / filename)).expanduser().resolve()
    if not candidate_path.is_file():
        return {
            **result,
            "ok": False,
            "status": "artifact_inbox_candidate_missing",
            "verification_performed": False,
            "verification_error": "candidate ZIP is not present in artifact_inbox; run with --download first or provide a persisted intake artifact",
            "artifact_inbox_dir": str(inbox_dir),
            "expected_artifact_path": str(candidate_path),
            "intake_stage": "verification_requested",
            "migration_performed": False,
            "adoption_performed": False,
        }

    verification = verify_zip_artifact(candidate_path)
    zip_version = _read_zip_version_file(candidate_path)
    filename_version = _artifact_version_from_filename(filename) or candidate.get("filename_version")
    expected_version = result.get("expected_version") or candidate.get("expected_version") or candidate.get("version") or filename_version
    expected_version = _artifact_version_from_filename(f"artifact_{expected_version}.zip") if expected_version and valid_version_text(str(expected_version)) else expected_version
    verification_errors: list[str] = []

    if not verification.get("ok"):
        if verification.get("wrapper_folder"):
            verification_errors.append("artifact_wrapper_folder")
        if verification.get("unsafe_entries"):
            verification_errors.append("artifact_zip_unsafe_entries")
        if verification.get("bad_entry"):
            verification_errors.append("artifact_zip_bad_entry")
        if verification.get("hygiene_violation_count"):
            verification_errors.append("artifact_zip_hygiene_failed")
        if not verification_errors:
            verification_errors.append(str(verification.get("error") or "artifact_zip_invalid"))
    if not verification.get("has_version_file"):
        verification_errors.append("artifact_version_file_missing")
    if zip_version and filename_version and str(zip_version) != str(filename_version):
        verification_errors.append("artifact_version_mismatch")
    if zip_version and expected_version and str(zip_version) != str(expected_version):
        verification_errors.append("artifact_wrong_version")
    if not zip_version and verification.get("has_version_file"):
        verification_errors.append("artifact_version_invalid")

    observed_metadata = _artifact_file_metadata(candidate_path)
    envelope_metadata = {
        "sha256": candidate.get("sha256") or candidate.get("expected_sha256"),
        "size_bytes": candidate.get("size_bytes") or candidate.get("expected_size_bytes"),
        "entry_count": candidate.get("entry_count") or candidate.get("expected_entry_count"),
    }
    envelope_metadata_checks: dict[str, bool | None] = {}
    for metadata_key, expected_value in envelope_metadata.items():
        if expected_value in {None, ""}:
            envelope_metadata_checks[metadata_key] = None
            continue
        actual_value = verification.get("entry_count") if metadata_key == "entry_count" else observed_metadata.get(metadata_key)
        try:
            if metadata_key in {"size_bytes", "entry_count"}:
                metadata_match = int(expected_value) == int(actual_value)
            else:
                metadata_match = str(expected_value).strip().lower() == str(actual_value or "").strip().lower()
        except (TypeError, ValueError):
            metadata_match = False
        envelope_metadata_checks[metadata_key] = metadata_match
        if not metadata_match:
            verification_errors.append(f"artifact_envelope_{metadata_key}_mismatch")

    # Prefer specific semantic errors over the generic artifact_zip_invalid when possible.
    if not verification_errors:
        if result.get("manual_import_performed"):
            status = "manual_import_verified"
            intake_stage = "manual_imported_verified"
        else:
            status = "download_verified" if result.get("download_performed") else "verified_candidate"
            intake_stage = "downloaded_verified" if result.get("download_performed") else "verified"
        ok = True
    else:
        status = next((item for item in verification_errors if item != "artifact_zip_invalid"), verification_errors[0])
        ok = False
        intake_stage = "verification_failed"

    verification_record = {
        "schema": "promptbranch.artifact.intake.verification",
        "schema_version": "1.0",
        "status": status,
        "ok": ok,
        "candidate": candidate,
        "download": observed_metadata,
        "verification": verification,
        "envelope_metadata": envelope_metadata,
        "envelope_metadata_checks": envelope_metadata_checks,
        "envelope_metadata_verified": all(value is not False for value in envelope_metadata_checks.values()),
        "zip_version": zip_version,
        "filename_version": filename_version,
        "expected_version": expected_version,
        "verification_errors": verification_errors,
        "reply_request_id": result.get("reply_request_id"),
        "reply_correlation_id": result.get("reply_correlation_id"),
        "conversation_id": conversation_id,
        "answer_id": answer_id,
        "verified_at": utc_now(),
        "verification_performed": True,
        "migration_performed": False,
        "accepted": False,
        "adoption_performed": False,
    }
    intake_record_path = inbox_dir / "intake.json"
    persisted_record = dict(verification_record)
    try:
        if intake_record_path.is_file():
            existing = json.loads(intake_record_path.read_text(encoding="utf-8"))
            if isinstance(existing, dict):
                persisted_record = {**existing, **verification_record}
        intake_record_path.parent.mkdir(parents=True, exist_ok=True)
        intake_record_path.write_text(json.dumps(persisted_record, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    except (OSError, json.JSONDecodeError) as exc:
        return {
            **result,
            "ok": False,
            "status": "artifact_verification_metadata_failed",
            "verification_performed": True,
            "verification": verification,
            "verification_error": str(exc),
            "artifact_inbox_dir": str(inbox_dir),
            "intake_stage": intake_stage,
            "migration_performed": False,
            "adoption_performed": False,
        }

    envelope_metadata_verified = all(value is not False for value in envelope_metadata_checks.values())
    browser_materialization_proven = bool(
        ok
        and result.get("download_performed") is True
        and result.get("browser_download_performed") is True
        and envelope_metadata_verified
    )
    return {
        **result,
        "ok": ok,
        "status": status,
        "intake_stage": intake_stage,
        "artifact_inbox_dir": str(inbox_dir),
        "intake_record_path": str(intake_record_path),
        "download": observed_metadata,
        "verification": verification,
        "envelope_metadata": envelope_metadata,
        "envelope_metadata_checks": envelope_metadata_checks,
        "envelope_metadata_verified": envelope_metadata_verified,
        "artifact_materialization_proven": browser_materialization_proven,
        "download_proof_status": (
            "chatgpt_rendered_attachment_downloaded_verified"
            if browser_materialization_proven
            else result.get("download_proof_status")
        ),
        "manual_import_required": False if browser_materialization_proven else result.get("manual_import_required"),
        "zip_version": zip_version,
        "filename_version": filename_version,
        "expected_version": expected_version,
        "verification_errors": verification_errors,
        "verification_performed": True,
        "migration_performed": False,
        "adoption_performed": False,
        "operator_instruction": "Artifact ZIP was verified inside .pb_profile/artifact_inbox only. Migration and adoption remain separate, explicit guarded steps.",
    }



def _verify_intake_smoke_zip_candidate(
    result: dict[str, Any],
    *,
    profile_dir: str | Path,
    conversation_id: Any,
    answer_id: Any,
    expected_entries: list[str] | None = None,
    expected_content: str | None = None,
) -> dict[str, Any]:
    """Verify a downloaded ChatGPT UI attachment smoke ZIP.

    This mode is intentionally separate from release verification. It proves the
    artifact transport path (ChatGPT rendered attachment/button -> browser
    download -> local artifact_inbox import) without requiring release ZIP
    semantics such as VERSION at ZIP root. It never migrates, adopts, or mutates
    Project Sources.
    """

    candidate = result.get("selected_candidate") if isinstance(result.get("selected_candidate"), dict) else None
    if result.get("status") not in {"candidate_selected", "artifact_candidates_found", "downloaded", "manual_imported"} or candidate is None:
        return {
            **result,
            "ok": False,
            "status": "artifact_candidate_not_selected",
            "smoke_verification_performed": False,
            "verification_performed": False,
            "verification_error": "a single valid candidate must be selected before smoke ZIP verification",
            "intake_stage": result.get("intake_stage") or "candidate_extraction",
            "migration_performed": False,
            "adoption_performed": False,
        }

    filename = _safe_artifact_filename(candidate.get("filename"))
    if not filename:
        return {
            **result,
            "ok": False,
            "status": "artifact_wrong_filename",
            "smoke_verification_performed": False,
            "verification_performed": False,
            "verification_error": "selected candidate filename must be a basename ending in .zip",
            "intake_stage": result.get("intake_stage") or "candidate_extraction",
            "migration_performed": False,
            "adoption_performed": False,
        }

    inbox_dir = _artifact_inbox_dir(
        profile_dir=profile_dir,
        conversation_id=conversation_id,
        answer_id=answer_id,
        request_id=result.get("reply_request_id"),
    )
    download = result.get("download") if isinstance(result.get("download"), dict) else {}
    candidate_path = Path(str(download.get("path") or inbox_dir / filename)).expanduser().resolve()
    if not candidate_path.is_file():
        return {
            **result,
            "ok": False,
            "status": "artifact_inbox_candidate_missing",
            "smoke_verification_performed": False,
            "verification_performed": False,
            "verification_error": "candidate ZIP is not present in artifact_inbox; run with --download first or provide a persisted intake artifact",
            "artifact_inbox_dir": str(inbox_dir),
            "expected_artifact_path": str(candidate_path),
            "intake_stage": "smoke_verification_requested",
            "migration_performed": False,
            "adoption_performed": False,
        }

    normalized_expected_entries = [str(item).strip().lstrip("/") for item in (expected_entries or []) if str(item).strip()]
    smoke_errors: list[str] = []
    zip_entries: list[str] = []
    content_checks: dict[str, Any] = {}
    testzip_result: str | None = None
    unsafe_entries: list[str] = []

    try:
        with zipfile.ZipFile(candidate_path) as zf:
            testzip_result = zf.testzip()
            zip_entries = [info.filename for info in zf.infolist()]
            for entry in zip_entries:
                if entry.startswith("/") or ".." in Path(entry).parts:
                    unsafe_entries.append(entry)
            if testzip_result:
                smoke_errors.append("smoke_zip_bad_entry")
            if unsafe_entries:
                smoke_errors.append("smoke_zip_unsafe_entries")
            for expected_entry in normalized_expected_entries:
                if expected_entry not in zip_entries:
                    smoke_errors.append("smoke_zip_expected_entry_missing")
                    content_checks[expected_entry] = {"ok": False, "status": "missing"}
                    continue
                if expected_content is not None:
                    try:
                        data = zf.read(expected_entry)
                        actual_text = data.decode("utf-8")
                    except (KeyError, UnicodeDecodeError) as exc:
                        smoke_errors.append("smoke_zip_expected_content_unreadable")
                        content_checks[expected_entry] = {"ok": False, "status": "unreadable", "error": str(exc)}
                        continue
                    content_ok = actual_text == expected_content
                    if not content_ok:
                        smoke_errors.append("smoke_zip_expected_content_mismatch")
                    content_checks[expected_entry] = {
                        "ok": content_ok,
                        "status": "matched" if content_ok else "mismatch",
                        "expected_size": len(expected_content.encode("utf-8")),
                        "actual_size": len(data),
                    }
    except zipfile.BadZipFile as exc:
        smoke_errors.append("smoke_zip_invalid")
        content_checks["error"] = str(exc)
    except OSError as exc:
        smoke_errors.append("smoke_zip_read_failed")
        content_checks["error"] = str(exc)

    # When no explicit entry expectation is supplied, the smoke verifier still
    # proves that the downloaded file is a readable ZIP with safe entries.
    ok = not smoke_errors
    status = "smoke_zip_verified" if ok else smoke_errors[0]
    intake_stage = "smoke_verified" if ok else "smoke_verification_failed"
    smoke_verification = {
        "schema": "promptbranch.artifact.intake.smoke_zip_verification",
        "schema_version": "1.0",
        "ok": ok,
        "status": status,
        "path": str(candidate_path),
        "entries": zip_entries,
        "entry_count": len(zip_entries),
        "expected_entries": normalized_expected_entries,
        "expected_content_provided": expected_content is not None,
        "content_checks": content_checks,
        "testzip": testzip_result,
        "unsafe_entries": unsafe_entries,
        "errors": smoke_errors,
    }

    verification_record = {
        "schema": "promptbranch.artifact.intake.verification",
        "schema_version": "1.0",
        "status": status,
        "ok": ok,
        "candidate": candidate,
        "download": _artifact_file_metadata(candidate_path),
        "smoke_verification": smoke_verification,
        "verification_errors": smoke_errors,
        "reply_request_id": result.get("reply_request_id"),
        "reply_correlation_id": result.get("reply_correlation_id"),
        "conversation_id": conversation_id,
        "answer_id": answer_id,
        "verified_at": utc_now(),
        "verification_performed": True,
        "smoke_verification_performed": True,
        "release_verification_performed": False,
        "migration_performed": False,
        "accepted": False,
        "adoption_performed": False,
    }
    intake_record_path = inbox_dir / "intake.json"
    persisted_record = dict(verification_record)
    try:
        if intake_record_path.is_file():
            existing = json.loads(intake_record_path.read_text(encoding="utf-8"))
            if isinstance(existing, dict):
                persisted_record = {**existing, **verification_record}
        intake_record_path.parent.mkdir(parents=True, exist_ok=True)
        intake_record_path.write_text(json.dumps(persisted_record, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    except (OSError, json.JSONDecodeError) as exc:
        return {
            **result,
            "ok": False,
            "status": "artifact_smoke_verification_metadata_failed",
            "smoke_verification_performed": True,
            "verification_performed": True,
            "smoke_verification": smoke_verification,
            "verification_error": str(exc),
            "artifact_inbox_dir": str(inbox_dir),
            "intake_stage": intake_stage,
            "migration_performed": False,
            "adoption_performed": False,
        }

    return {
        **result,
        "ok": ok,
        "status": status,
        "intake_stage": intake_stage,
        "artifact_inbox_dir": str(inbox_dir),
        "intake_record_path": str(intake_record_path),
        "download": _artifact_file_metadata(candidate_path),
        "smoke_verification": smoke_verification,
        "verification_errors": smoke_errors,
        "verification_performed": True,
        "smoke_verification_performed": True,
        "release_verification_performed": False,
        "migration_performed": False,
        "adoption_performed": False,
        "operator_instruction": "Smoke ZIP was verified inside .pb_profile/artifact_inbox only. This proves attachment/download mechanics; it is not release verification and cannot be migrated/adopted as a release artifact.",
    }



def _artifact_intake_no_state_mutation_flags(result: dict[str, Any]) -> dict[str, Any]:
    """Make the artifact-intake no-state-mutation boundary explicit.

    Download/verification may create files under .pb_profile/artifact_inbox and
    migration may copy a verified candidate ZIP to the repo root plus update the
    candidate registry. It must not adopt, upload to Project Sources, or advance
    artifact/source state.
    """

    return {
        **result,
        "project_source_mutated": False,
        "project_source_mutation": "not_requested",
        "source_upload_verification": None,
        "artifact_registry_updated": False,
        "state_artifact_updated": False,
        "state_source_updated": False,
        "adoption_performed": False,
    }


def _artifact_intake_migration_not_supported(result: dict[str, Any]) -> dict[str, Any]:
    """Compatibility helper retained for older tests/callers; CLI uses the verified migration path."""

    return _artifact_intake_no_state_mutation_flags({
        **result,
        "ok": False,
        "status": "artifact_migration_not_supported_in_previous_mvp",
        "intake_stage": result.get("intake_stage") or "migration_requested",
        "migration_performed": False,
        "migration_error": "Artifact intake supports verified candidate migration; run with --verify --migrate and a valid repo path.",
        "adoption_performed": False,
        "operator_instruction": "Use --download --verify --migrate to copy a verified candidate to the repo root. Adoption remains a later explicit step.",
    })

def _render_artifact_intake_result(result: dict[str, Any]) -> str:
    lines = [
        f"status={result.get('status')}",
        f"ok={str(bool(result.get('ok'))).lower()}",
        f"reply_parse_status={result.get('reply_parse_status')}",
        f"artifact_candidate_count={result.get('artifact_candidate_count') or 0}",
        f"zip_candidate_count={result.get('zip_candidate_count') or 0}",
        f"valid_zip_candidate_count={result.get('valid_zip_candidate_count') or 0}",
    ]
    selected = result.get("selected_candidate") if isinstance(result.get("selected_candidate"), dict) else None
    if selected:
        lines.append(f"selected={selected.get('filename')} version={selected.get('filename_version') or selected.get('version')}")
    if result.get("download_performed"):
        download = result.get("download") if isinstance(result.get("download"), dict) else {}
        lines.append(f"downloaded={download.get('path')} size={download.get('size_bytes')} sha256={download.get('sha256')}")
    if result.get("download_error"):
        lines.append(f"download_error={result.get('download_error')}")
    if result.get("requires_browser_context"):
        lines.append("requires_browser_context=true")
    if result.get("manual_import_command"):
        lines.append(f"manual_import_command={result.get('manual_import_command')}")
    if result.get("manual_import_performed"):
        manual_import = result.get("manual_import") if isinstance(result.get("manual_import"), dict) else {}
        lines.append(f"manual_imported={manual_import.get('path')} size={manual_import.get('size_bytes')} sha256={manual_import.get('sha256')}")
    if result.get("manual_import_error"):
        lines.append(f"manual_import_error={result.get('manual_import_error')}")
    if result.get("verification_performed"):
        lines.append(f"verification={result.get('status')} zip_version={result.get('zip_version')} filename_version={result.get('filename_version')}")
    if result.get("verification_error"):
        lines.append(f"verification_error={result.get('verification_error')}")
    if result.get("migration_performed"):
        migration = result.get("migration") if isinstance(result.get("migration"), dict) else {}
        lines.append(f"migrated={migration.get('target_path')} copy_performed={migration.get('copy_performed')}")
    if result.get("migration_error"):
        lines.append(f"migration_error={result.get('migration_error')}")
    candidates = result.get("artifact_candidates") if isinstance(result.get("artifact_candidates"), list) else []
    for candidate in candidates:
        errors = candidate.get("classification_errors") if isinstance(candidate.get("classification_errors"), list) else []
        lines.append(
            f"- {candidate.get('filename') or '(missing filename)'}\t"
            f"version={candidate.get('filename_version') or candidate.get('version') or 'unknown'}\t"
            f"repo={candidate.get('repo_prefix') or 'unknown'}\t"
            f"status={candidate.get('status') or 'unknown'}\t"
            f"errors={','.join(str(item) for item in errors) if errors else 'none'}"
        )
    return "\n".join(lines).rstrip() + "\n"


def _finalize_materialized_protocol_run_record(
    run: dict[str, Any],
    intake_result: dict[str, Any],
    *,
    run_path: Path,
    expected_filename: str | None,
    expected_version: str | None,
    expected_repo: str | None,
) -> dict[str, Any]:
    """Recompute and persist one already materialized ask-release result."""

    if not (
        intake_result.get("ok") is True
        and intake_result.get("verification_performed") is True
        and intake_result.get("artifact_materialization_proven") is True
        and intake_result.get("envelope_metadata_verified") is True
    ):
        return {
            **intake_result,
            "ok": False,
            "status": "materialized_protocol_run_finalization_failed",
            "protocol_run_finalization": {
                "performed": False,
                "reason": "persisted inbox artifact did not pass idempotent verification",
                "path": str(run_path),
            },
        }

    request = run.get("request") if isinstance(run.get("request"), dict) else {}
    reply = run.get("reply") if isinstance(run.get("reply"), dict) else {}
    reply_text = "BEGIN_PROMPTBRANCH_REPLY_JSON\n" + json.dumps(reply, ensure_ascii=False) + "\nEND_PROMPTBRANCH_REPLY_JSON"
    reparsed = parse_promptbranch_reply(reply_text)
    validation_ok, validation_errors = _validate_protocol_reply_against_request(reparsed, request)
    finalized = copy.deepcopy(run)
    finalized.update({
        "ok": bool(validation_ok),
        "status": "reply_validated" if validation_ok else "release_candidate_validation_failed",
        "reply_validation_ok": bool(validation_ok),
        "reply_validation_errors": list(validation_errors),
        "download": copy.deepcopy(intake_result.get("download")) if isinstance(intake_result.get("download"), dict) else {},
        "download_performed": True,
        "browser_download_performed": True,
        "verification_performed": True,
        "artifact_materialization_proven": True,
        "envelope_metadata_verified": True,
        "materialization_status": _MATERIALIZED_FINALIZATION_STATUS,
        "artifact_inbox_dir": intake_result.get("artifact_inbox_dir"),
        "migration_performed": False,
        "adoption_performed": False,
    })
    expectations = _protocol_run_expectations(finalized)
    expected = {
        "expected_repo": expected_repo or expectations.get("expected_repo"),
        "expected_version": _normalize_version_token(expected_version or expectations.get("expected_version")),
        "expected_artifact": expected_filename or expectations.get("expected_filename"),
        "expected_role": "candidate_release",
        "exact_artifact_count": 1,
    }
    finalized = _validate_ask_release_candidate_result(finalized, expected)
    if finalized.get("ok") is not True or finalized.get("reply_validation_ok") is not True:
        return {
            **intake_result,
            "ok": False,
            "status": "materialized_protocol_run_finalization_failed",
            "reply_validation_errors": finalized.get("reply_validation_errors"),
            "ask_release_validation": finalized.get("ask_release_validation"),
            "protocol_run_finalization": {
                "performed": False,
                "reason": "post-materialization release-candidate validation remained non-green",
                "path": str(run_path),
            },
        }

    finalized["post_materialization_finalization"] = {
        "performed": True,
        "finalized_at": utc_now(),
        "previous_status": run.get("status"),
        "source": "persisted_verified_artifact_inbox",
        "artifact_path": (intake_result.get("download") or {}).get("path") if isinstance(intake_result.get("download"), dict) else None,
        "no_redownload": True,
        "migration_performed": False,
        "adoption_performed": False,
    }
    try:
        run_path.write_text(json.dumps(finalized, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    except OSError as exc:
        return {
            **intake_result,
            "ok": False,
            "status": "materialized_protocol_run_finalization_persist_failed",
            "error": str(exc),
            "protocol_run_finalization": {
                "performed": False,
                "reason": "protocol run record write failed",
                "path": str(run_path),
            },
        }

    return {
        **intake_result,
        "ok": True,
        "action": "artifact_intake",
        "mode": "idempotent_finalize",
        "status": "reply_validated",
        "source": "selected_materialized_protocol_reply",
        "reply_validation_ok": True,
        "reply_validation_errors": [],
        "ask_release_validation": finalized.get("ask_release_validation"),
        "artifact_materialization_proven": True,
        "download_performed": True,
        "browser_download_performed": True,
        "verification_performed": True,
        "envelope_metadata_verified": True,
        "download_proof_status": _MATERIALIZED_FINALIZATION_STATUS,
        "migration_performed": False,
        "adoption_performed": False,
        "protocol_run_finalization": {
            "performed": True,
            "path": str(run_path),
            "previous_status": run.get("status"),
            "persisted_status": "reply_validated",
            "no_redownload": True,
        },
        "operator_instruction": "The exact already materialized protocol run was reverified and finalized idempotently. No download, migration, publication, adoption, commit, or push was performed during finalization.",
    }


async def cmd_artifact_intake(backend: Any, args: argparse.Namespace) -> int:
    use_protocol_record = bool(getattr(args, "from_last_protocol_run", False) or getattr(args, "from_last_answer", False))
    if not use_protocol_record:
        payload = {
            "ok": False,
            "action": "artifact_intake",
            "status": "intake_source_required",
            "error": "artifact intake supports --from-last-answer/--from-last-protocol-run only",
            "automation_performed": False,
            "download_performed": False,
            "migration_performed": False,
            "adoption_performed": False,
        }
        if args.json:
            print(json.dumps(payload, indent=2, ensure_ascii=False))
        else:
            print("error: artifact intake supports --from-last-answer/--from-last-protocol-run only", file=sys.stderr)
        return 1

    profile_dir = getattr(args, "profile_dir", None) or PROFILE_DIR_NAME
    conversation_id_for_artifact: Any = None
    answer_id_for_artifact: Any = None
    message_id_for_artifact: Any = None
    explicit_answer_selection = bool(
        getattr(args, "message_id", None)
        or getattr(args, "message_index", None)
        or getattr(args, "answer_id", None)
        or getattr(args, "answer_index", None)
    )
    protocol_run_request_id = getattr(args, "protocol_run_request_id", None)
    replay_unvalidated_artifact_run = bool(getattr(args, "replay_unvalidated_artifact_run", False))
    if replay_unvalidated_artifact_run and not protocol_run_request_id:
        result = {
            "ok": False,
            "action": "artifact_intake",
            "status": "unvalidated_artifact_replay_requires_exact_request_id",
            "error": "--replay-unvalidated-artifact-run requires --from-last-protocol-run and --protocol-run-request-id",
            "automation_performed": False,
            "download_performed": False,
            "verification_performed": False,
            "migration_performed": False,
            "adoption_performed": False,
        }
        if args.json:
            print(json.dumps(result, indent=2, ensure_ascii=False))
        else:
            print(f"error: {result['error']}", file=sys.stderr)
        return 1
    if replay_unvalidated_artifact_run and (
        not getattr(args, "download", False)
        or not getattr(args, "verify", False)
        or bool(getattr(args, "local_file", None))
        or bool(getattr(args, "verify_smoke_zip", False))
        or bool(getattr(args, "migrate", False))
    ):
        result = {
            "ok": False,
            "action": "artifact_intake",
            "status": "unvalidated_artifact_replay_mode_invalid",
            "error": "explicit unvalidated artifact replay requires --download --verify and forbids --local-file, --verify-smoke-zip, and --migrate",
            "automation_performed": False,
            "download_performed": False,
            "verification_performed": False,
            "migration_performed": False,
            "adoption_performed": False,
        }
        if args.json:
            print(json.dumps(result, indent=2, ensure_ascii=False))
        else:
            print(f"error: {result['error']}", file=sys.stderr)
        return 1
    if protocol_run_request_id and not getattr(args, "from_last_protocol_run", False):
        result = {
            "ok": False,
            "action": "artifact_intake",
            "status": "protocol_run_selector_requires_protocol_source",
            "error": "--protocol-run-request-id requires --from-last-protocol-run",
            "automation_performed": False,
            "download_performed": False,
            "migration_performed": False,
            "adoption_performed": False,
        }
        if args.json:
            print(json.dumps(result, indent=2, ensure_ascii=False))
        else:
            print(f"error: {result['error']}", file=sys.stderr)
        return 1
    if protocol_run_request_id and explicit_answer_selection:
        result = {
            "ok": False,
            "action": "artifact_intake",
            "status": "artifact_intake_selector_conflict",
            "error": "--protocol-run-request-id cannot be combined with message/answer selectors",
            "automation_performed": False,
            "download_performed": False,
            "migration_performed": False,
            "adoption_performed": False,
        }
        if args.json:
            print(json.dumps(result, indent=2, ensure_ascii=False))
        else:
            print(f"error: {result['error']}", file=sys.stderr)
        return 1
    reusable_materialized_protocol_run = False
    materialized_reuse_evidence: dict[str, Any] | None = None
    if protocol_run_request_id:
        run_path, run_record, lookup = _load_validated_protocol_run_by_request_id(
            profile_dir,
            protocol_run_request_id,
            allow_replay_unvalidated_artifact_run=replay_unvalidated_artifact_run,
            allow_finalize_materialized_protocol_run=bool(
                not replay_unvalidated_artifact_run
                and getattr(args, "download", False)
                and getattr(args, "verify", False)
                and not getattr(args, "local_file", None)
                and not getattr(args, "verify_smoke_zip", False)
                and not getattr(args, "migrate", False)
            ),
        )
    else:
        run_path, run_record, lookup = _load_latest_validated_protocol_run(profile_dir)

    if (
        protocol_run_request_id
        and run_record is not None
        and _protocol_run_is_validated(run_record)
        and run_record.get("artifact_materialization_proven") is True
        and (getattr(args, "download", False) or getattr(args, "verify", False) or getattr(args, "migrate", False))
    ):
        materialized_reuse_evidence = _protocol_run_reusable_materialization_evidence(
            run_record,
            selected_request_id=str(protocol_run_request_id),
            profile_dir=profile_dir,
        )
        if materialized_reuse_evidence.get("ok") is not True:
            result = {
                "ok": False,
                "action": "artifact_intake",
                "status": "selected_materialized_protocol_run_not_reusable",
                "source": "selected_validated_protocol_reply",
                "lookup": {**lookup, "materialized_reuse_evidence": materialized_reuse_evidence},
                "artifact_candidate_count": 0,
                "candidates": [],
                "artifact_candidates": [],
                "automation_performed": False,
                "download_performed": False,
                "verification_performed": False,
                "migration_performed": False,
                "adoption_performed": False,
                "error": f"validated materialized protocol run was not reusable for request_id={protocol_run_request_id}",
            }
            if args.json:
                print(json.dumps(result, indent=2, ensure_ascii=False))
            else:
                print(_render_artifact_intake_result(result), end="")
            return 1
        reusable_materialized_protocol_run = True
        lookup = {**lookup, "materialized_reuse_evidence": materialized_reuse_evidence, "materialized_reuse_used": True}

    if explicit_answer_selection and getattr(args, "from_last_answer", False):
        try:
            task_target = getattr(args, "target", None)
            payload = await _fetch_task_messages_payload(backend, args, task_target)
            message = _resolve_task_message_for_artifact_intake(payload["messages"], args)
            answer = _resolve_task_answer(
                message,
                answer_index=getattr(args, "answer_index", None),
                answer_id=getattr(args, "answer_id", None),
            )
        except ValueError as exc:
            result = {
                "ok": False,
                "action": "artifact_intake",
                "status": "answer_selection_failed",
                "error": str(exc),
                "automation_performed": False,
                "download_performed": False,
                "migration_performed": False,
                "adoption_performed": False,
            }
            if args.json:
                print(json.dumps(result, indent=2, ensure_ascii=False))
            else:
                print(f"error: {exc}", file=sys.stderr)
            return 1
        parsed = parse_promptbranch_reply(str(answer.get("text") or ""))
        promotion = _promote_task_answer_protocol_run(args, payload=payload, message=message, answer=answer, parsed=parsed, source="artifact_intake_explicit_answer")
        result = _artifact_intake_from_parsed_answer(
            parsed,
            expected_filename=getattr(args, "expect_artifact", None),
            expected_version=getattr(args, "expect_version", None),
            expected_repo=getattr(args, "expect_repo", None),
        )
        conversation_id_for_artifact = payload.get("conversation_id")
        answer_id_for_artifact = answer.get("id")
        message_id_for_artifact = message.get("id")
        selected = _protocol_answer_metadata(message, answer)
        result.update({
            "source": "explicit_task_answer",
            "lookup": lookup,
            "project_url": payload.get("project_url"),
            "conversation_url": payload.get("conversation_url"),
            "conversation_id": payload.get("conversation_id"),
            "title": payload.get("title"),
            "message": {key: value for key, value in message.items() if key != "answers"},
            "answer": {key: value for key, value in answer.items() if key != "text"},
            "selected_answer": selected,
            "selected_request_id": parsed.get("request_id"),
            "selected_message_id": selected.get("message_id"),
            "selected_answer_id": selected.get("answer_id"),
            "selected_protocol_reply": _protocol_selection_summary(
                request_id=parsed.get("request_id"),
                correlation_id=parsed.get("correlation_id"),
                message=message,
                answer=answer,
                conversation_id=payload.get("conversation_id"),
                conversation_url=payload.get("conversation_url"),
            ),
            "answer_text_length": len(str(answer.get("text") or "")),
            "protocol_run_promotion": promotion,
            "protocol_run_promoted": bool(promotion.get("performed")),
            "promoted_protocol_run_record_path": promotion.get("path"),
        })
    elif run_record is not None:
        result = _artifact_intake_from_protocol_run_record(
            run_record,
            run_path=run_path,
            expected_filename=getattr(args, "expect_artifact", None),
            expected_version=getattr(args, "expect_version", None),
            expected_repo=getattr(args, "expect_repo", None),
            source=(
                "selected_replayable_protocol_reply"
                if lookup.get("status") == "selected_replayable_protocol_run"
                else (
                    "selected_materialized_protocol_reply"
                    if lookup.get("status") == "selected_materialized_protocol_run"
                    else (
                        "selected_materialized_validated_protocol_reply"
                        if reusable_materialized_protocol_run
                        else ("selected_validated_protocol_reply" if protocol_run_request_id else "last_validated_protocol_reply")
                    )
                )
            ),
            allow_legacy_unvalidated_replay=lookup.get("status") in {"selected_replayable_protocol_run", "selected_materialized_protocol_run"},
            reuse_materialized_protocol_run=(lookup.get("status") == "selected_materialized_protocol_run" or reusable_materialized_protocol_run),
        )
        result["lookup"] = lookup
        request = run_record.get("request") if isinstance(run_record.get("request"), dict) else {}
        workspace = request.get("workspace") if isinstance(request.get("workspace"), dict) else {}
        task = request.get("task") if isinstance(request.get("task"), dict) else {}
        message = run_record.get("message") if isinstance(run_record.get("message"), dict) else {}
        answer = run_record.get("answer") if isinstance(run_record.get("answer"), dict) else {}
        conversation_id_for_artifact = run_record.get("conversation_id") or task.get("conversation_id")
        answer_id_for_artifact = answer.get("id")
        message_id_for_artifact = message.get("id")
        selection = _protocol_selection_summary(
            request_id=result.get("reply_request_id") or run_record.get("request_id"),
            correlation_id=result.get("reply_correlation_id") or run_record.get("correlation_id"),
            message=message,
            answer=answer,
            conversation_id=conversation_id_for_artifact,
            conversation_url=run_record.get("conversation_url") or task.get("conversation_url"),
        )
        result.update({
            "project_url": workspace.get("project_home_url"),
            "conversation_url": run_record.get("conversation_url") or task.get("conversation_url"),
            "conversation_id": run_record.get("conversation_id") or task.get("conversation_id"),
            "title": run_record.get("title"),
            "message": {key: value for key, value in message.items() if key != "text"},
            "answer": {key: value for key, value in answer.items() if key != "text"},
            "selected_request_id": selection.get("request_id"),
            "selected_message_id": selection.get("message_id"),
            "selected_answer_id": selection.get("answer_id"),
            "selected_protocol_reply": selection,
            "answer_text_length": int(run_record.get("answer_text_length") or 0),
            "protocol_run_selector": {
                "mode": "request_id" if protocol_run_request_id else "latest_validated",
                "request_id": protocol_run_request_id,
            },
        })
        if replay_unvalidated_artifact_run:
            result["protocol_run_selector"].update({
                "replay_unvalidated_artifact_run": True,
                "replay_used": lookup.get("status") == "selected_replayable_protocol_run",
                "previous_status": lookup.get("previous_status"),
            })
            result["protocol_run_replay"] = {
                "requested": True,
                "used": lookup.get("status") == "selected_replayable_protocol_run",
                "previous_status": lookup.get("previous_status"),
                "eligibility": lookup.get("replay_eligibility"),
            }
        if reusable_materialized_protocol_run:
            result["protocol_run_selector"].update({
                "materialized_reuse": True,
                "materialized_reuse_used": True,
            })
            result["protocol_run_materialized_reuse"] = {
                "used": True,
                "evidence": materialized_reuse_evidence,
            }
        if lookup.get("status") == "selected_materialized_protocol_run":
            result["protocol_run_selector"].update({
                "materialized_finalization": True,
                "finalization_used": True,
                "previous_status": lookup.get("previous_status"),
            })
            result["protocol_run_finalization"] = {
                "requested": True,
                "used": True,
                "previous_status": lookup.get("previous_status"),
                "eligibility": lookup.get("materialized_finalization_eligibility"),
            }
    elif getattr(args, "from_last_protocol_run", False):
        result = {
            "ok": False,
            "action": "artifact_intake",
            "mode": "dry_run",
            "status": lookup.get("status") or "protocol_run_not_found",
            "source": "selected_protocol_reply" if protocol_run_request_id else "last_validated_protocol_reply",
            "lookup": lookup,
            "artifact_candidate_count": 0,
            "candidates": [],
            "artifact_candidates": [],
            "next_action": "none",
            "automation_performed": False,
            "download_performed": False,
            "verification_performed": False,
            "migration_performed": False,
            "adoption_performed": False,
            "error": (
                f"selected protocol run was not eligible for intake for request_id={protocol_run_request_id}"
                if protocol_run_request_id
                else "no validated protocol run was found; run pb ask --protocol --parse-reply first"
            ),
        }
        if args.json:
            print(json.dumps(result, indent=2, ensure_ascii=False))
        else:
            print(_render_artifact_intake_result(result), end="")
        return 1
    else:
        # Backward-compatible fallback for old --from-last-answer callers: read the
        # live latest task answer only when no validated protocol run exists.
        try:
            task_target = getattr(args, "target", None)
            payload = await _fetch_task_messages_payload(backend, args, task_target)
            message = _resolve_task_message(payload["messages"], "latest")
            answer = _resolve_task_answer(message, answer_index="latest")
        except ValueError as exc:
            result = {
                "ok": False,
                "action": "artifact_intake",
                "status": "answer_selection_failed",
                "error": str(exc),
                "automation_performed": False,
                "download_performed": False,
                "migration_performed": False,
                "adoption_performed": False,
            }
            if args.json:
                print(json.dumps(result, indent=2, ensure_ascii=False))
            else:
                print(f"error: {exc}", file=sys.stderr)
            return 1
        parsed = parse_promptbranch_reply(str(answer.get("text") or ""))
        result = _artifact_intake_from_parsed_answer(
            parsed,
            expected_filename=getattr(args, "expect_artifact", None),
            expected_version=getattr(args, "expect_version", None),
            expected_repo=getattr(args, "expect_repo", None),
        )
        conversation_id_for_artifact = payload.get("conversation_id")
        answer_id_for_artifact = answer.get("id")
        message_id_for_artifact = message.get("id")
        selected = _protocol_answer_metadata(message, answer)
        result.update(
            {
                "source": "live_latest_task_answer_fallback",
                "lookup": lookup,
                "project_url": payload.get("project_url"),
                "conversation_url": payload.get("conversation_url"),
                "conversation_id": payload.get("conversation_id"),
                "title": payload.get("title"),
                "message": {key: value for key, value in message.items() if key != "answers"},
                "answer": {key: value for key, value in answer.items() if key != "text"},
                "selected_answer": selected,
                "selected_request_id": parsed.get("request_id"),
                "selected_message_id": selected.get("message_id"),
                "selected_answer_id": selected.get("answer_id"),
                "selected_protocol_reply": _protocol_selection_summary(
                    request_id=parsed.get("request_id"),
                    correlation_id=parsed.get("correlation_id"),
                    message=message,
                    answer=answer,
                    conversation_id=payload.get("conversation_id"),
                    conversation_url=payload.get("conversation_url"),
                ),
                "answer_text_length": len(str(answer.get("text") or "")),
            }
        )
    local_file = getattr(args, "local_file", None)
    if local_file and getattr(args, "download", False):
        result = {
            **result,
            "ok": False,
            "status": "artifact_intake_mode_conflict",
            "error": "--local-file is a manual import path and cannot be combined with --download",
            "download_performed": False,
            "manual_import_performed": False,
            "migration_performed": False,
            "adoption_performed": False,
            "intake_stage": result.get("intake_stage") or "candidate_extraction",
        }
    elif local_file:
        result = _manual_import_selected_artifact_candidate(
            result,
            profile_dir=getattr(args, "profile_dir", None) or PROFILE_DIR_NAME,
            conversation_id=conversation_id_for_artifact,
            answer_id=answer_id_for_artifact,
            local_file=local_file,
        )
    elif getattr(args, "download", False):
        if lookup.get("status") == "selected_materialized_protocol_run" or reusable_materialized_protocol_run:
            result = {
                **result,
                "ok": True,
                "status": "downloaded",
                "intake_stage": "download_reused",
                "download_reused": True,
                "download_performed": True,
                "browser_download_performed": True,
                "artifact_materialization_proven": True,
                "manual_import_required": False,
            }
        else:
            result = await _download_selected_artifact_candidate_via_browser(
                backend,
                result,
                profile_dir=getattr(args, "profile_dir", None) or PROFILE_DIR_NAME,
                conversation_id=conversation_id_for_artifact,
                answer_id=answer_id_for_artifact,
                timeout_seconds=float(getattr(args, "download_timeout", 120.0) or 120.0),
                keep_open=bool(getattr(args, "keep_open", False)),
            )
    if getattr(args, "verify", False) and getattr(args, "verify_smoke_zip", False):
        result = {
            **result,
            "ok": False,
            "status": "artifact_intake_verify_mode_conflict",
            "intake_stage": result.get("intake_stage") or "verification_requested",
            "verification_performed": False,
            "verification_error": "use either --verify for strict release artifacts or --verify-smoke-zip for attachment smoke ZIPs, not both",
            "migration_performed": False,
            "adoption_performed": False,
        }
    elif getattr(args, "verify_smoke_zip", False):
        result = _verify_intake_smoke_zip_candidate(
            result,
            profile_dir=getattr(args, "profile_dir", None) or PROFILE_DIR_NAME,
            conversation_id=conversation_id_for_artifact,
            answer_id=answer_id_for_artifact,
            expected_entries=list(getattr(args, "expect_entry", []) or []),
            expected_content=getattr(args, "expect_content", None),
        )
    elif getattr(args, "verify", False):
        result = _verify_intake_artifact_candidate(
            result,
            profile_dir=getattr(args, "profile_dir", None) or PROFILE_DIR_NAME,
            conversation_id=conversation_id_for_artifact,
            answer_id=answer_id_for_artifact,
        )
    if getattr(args, "migrate", False):
        result = _migrate_verified_intake_artifact_candidate(
            result,
            profile_dir=getattr(args, "profile_dir", None) or PROFILE_DIR_NAME,
            repo_path=getattr(args, "repo_path", ".") or ".",
            conversation_id=conversation_id_for_artifact,
            answer_id=answer_id_for_artifact,
            message_id=message_id_for_artifact,
        )
    if lookup.get("status") == "selected_materialized_protocol_run" and run_record is not None and run_path is not None:
        result = _finalize_materialized_protocol_run_record(
            run_record,
            result,
            run_path=run_path,
            expected_filename=getattr(args, "expect_artifact", None),
            expected_version=getattr(args, "expect_version", None),
            expected_repo=getattr(args, "expect_repo", None),
        )
    result = _artifact_intake_no_state_mutation_flags(result)
    if args.json:
        print(json.dumps(result, indent=2, ensure_ascii=False))
    else:
        print(_render_artifact_intake_result(result), end="")
    return 0 if result.get("ok") else 1


async def cmd_chat_summarize(backend: Any, args: argparse.Namespace) -> int:
    try:
        selected = await _resolve_chat_target(backend, args, args.target, keep_open=args.keep_open)
    except ValueError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1
    summary_prompt = (
        'Summarize this chat so far as JSON with keys topic, key_points, decisions, unresolved_questions, next_steps.'
        if args.json
        else 'Summarize this chat so far. Include the main topic, key points, decisions, unresolved questions, and next steps. Keep it concise.'
    )
    response = await backend.ask(
        prompt=summary_prompt,
        conversation_url=str(selected.get('conversation_url') or ''),
        expect_json=args.json,
        keep_open=args.keep_open,
        retries=args.retries,
    )
    answer, conversation_url = _split_ask_response(response)
    payload = {
        'ok': True,
        'action': 'chat_summarize',
        'conversation_url': conversation_url or selected.get('conversation_url'),
        'conversation_id': conversation_id_from_url(conversation_url or str(selected.get('conversation_url') or '')),
        'chat_title': selected.get('title'),
        'answer': answer,
    }
    if args.json:
        print(json.dumps(payload, indent=2, ensure_ascii=False))
        return 0
    if isinstance(answer, (dict, list)):
        print(json.dumps(answer, indent=2, ensure_ascii=False))
    else:
        print(answer)
    return 0

