def _browser_status_is_idle(payload: Any) -> bool:
    if not isinstance(payload, dict):
        return False
    return (
        payload.get("status") == "available"
        and not bool(payload.get("owner_active"))
        and not payload.get("active_operation")
        and not bool(payload.get("external_lock_held"))
    )


async def _wait_for_browser_idle(
    backend: Any,
    *,
    timeout_seconds: float = DEFAULT_BROWSER_WAIT_IDLE_TIMEOUT_SECONDS,
    poll_seconds: float = DEFAULT_BROWSER_WAIT_IDLE_POLL_SECONDS,
    action: str = "browser_wait_idle",
) -> dict[str, Any]:
    timeout_seconds = max(0.001, float(timeout_seconds))
    poll_seconds = max(0.001, float(poll_seconds))
    deadline = time.monotonic() + timeout_seconds
    attempts = 0
    last_status: dict[str, Any] | None = None
    while True:
        attempts += 1
        status_payload = await backend.browser_status()
        if isinstance(status_payload, dict):
            last_status = dict(status_payload)
        else:
            last_status = {"ok": False, "status": "invalid_browser_status_payload", "payload": status_payload}
        if _browser_status_is_idle(last_status):
            return {
                "ok": True,
                "action": action,
                "status": "available",
                "idle": True,
                "attempts": attempts,
                "timeout_seconds": timeout_seconds,
                "poll_seconds": poll_seconds,
                "browser_status": last_status,
            }
        remaining = deadline - time.monotonic()
        if remaining <= 0:
            return {
                "ok": False,
                "action": action,
                "status": "browser_profile_busy_timeout",
                "idle": False,
                "attempts": attempts,
                "timeout_seconds": timeout_seconds,
                "poll_seconds": poll_seconds,
                "browser_status": last_status,
                "operator_action": "retry_after_active_browser_operation_or_use_async_job_status",
                "next_safe_commands": [
                    "pb browser status --json",
                    f"pb browser wait-idle --timeout {timeout_seconds:g} --json",
                ],
            }
        await asyncio.sleep(min(poll_seconds, max(0.001, remaining)))


def _browser_profile_busy_next_safe_commands(command: str) -> list[str]:
    return [
        "pb browser status --json",
        f"pb browser wait-idle --timeout {DEFAULT_BROWSER_WAIT_IDLE_TIMEOUT_SECONDS:g} --json",
        command,
    ]


async def cmd_project_source_list(backend: Any, args: argparse.Namespace) -> int:
    try:
        result = await backend.list_project_sources(keep_open=args.keep_open)
    except Exception as exc:
        service_payload = _service_exception_payload(exc, args)
        if service_payload and service_payload.get("status") == "browser_profile_busy":
            payload = dict(service_payload)
            payload.update({
                "ok": False,
                "action": "source_list",
                "status": "browser_profile_busy",
                "project_source_mutated": False,
                "source_count": None,
                "next_safe_commands": _browser_profile_busy_next_safe_commands("pb src list --json"),
            })
            if args.json:
                print(json.dumps(payload, indent=2, ensure_ascii=False))
            else:
                print(f"status={payload.get('status')}", file=sys.stderr)
                if payload.get("active_operation"):
                    print(f"active_operation={payload.get('active_operation')}", file=sys.stderr)
                print("retry after the active browser operation completes", file=sys.stderr)
            return 75
        raise
    sources, payload = _project_source_list_payload(result)
    if args.json:
        print(json.dumps(payload, indent=2, ensure_ascii=False))
        return 0
    if not sources:
        print('(no project sources found)')
        return 0
    for idx, item in enumerate(sources, start=1):
        title = str(item.get('title') or item.get('name') or item.get('identity') or '(untitled)')
        subtitle = str(item.get('subtitle') or '')
        identity = str(item.get('identity') or '')
        columns = [f"{idx:>3}. {title}"]
        if subtitle:
            columns.append(subtitle)
        if identity and identity != title and identity != subtitle:
            columns.append(identity)
        print("	".join(columns))
    return 0


def _profile_wait_timeout_from_args(args: argparse.Namespace) -> float | None:
    if getattr(args, "no_queue", False):
        return None
    value = getattr(args, "profile_wait_timeout_seconds", None)
    if value is not None:
        return max(0.001, float(value))
    if getattr(args, "wait_for_profile", False):
        return DEFAULT_PROFILE_WAIT_TIMEOUT_SECONDS
    command = getattr(args, "command", None)
    src_command = getattr(args, "src_command", None)
    if command in {"src", "project-source-add"} and (src_command in {None, "add"}):
        return SERVICE_BROWSER_QUEUE_DEFAULT_WAIT_SECONDS
    return None


def _source_add_busy_payload(
    service_payload: dict[str, Any],
    *,
    source_kind: str,
    file_path: Optional[str],
    display_name: Optional[str],
    overwrite_existing: bool,
    args: argparse.Namespace,
    profile_lock_wait_seconds: float | None = None,
) -> dict[str, Any]:
    payload = dict(service_payload)
    payload.update({
        "ok": False,
        "action": "source_add",
        "status": "browser_profile_busy",
        "classification": "expected_contention",
        "source_kind": source_kind,
        "file_path": file_path,
        "display_name": display_name,
        "overwrite_existing": overwrite_existing,
        "project_source_mutated": False,
        "persistence_verified": False,
        "operator_review_required": False,
        "queue_enabled": profile_lock_wait_seconds is not None,
        "queue_mode": "bounded_wait_for_single_service_profile" if profile_lock_wait_seconds is not None else "fail_fast",
        "queue_wait_timeout_seconds": profile_lock_wait_seconds,
    })
    command_parts = ["pb", "src", "add"]
    if source_kind != "file":
        command_parts.extend(["--type", source_kind])
        value = getattr(args, "value", None)
        if value:
            command_parts.extend(["--value", shlex.quote(str(value))])
    elif file_path:
        command_parts.extend(["--file", shlex.quote(str(file_path))])
    if display_name:
        command_parts.extend(["--name", shlex.quote(str(display_name))])
    command_parts.append("--wait-for-profile")
    wait_timeout = getattr(args, "profile_wait_timeout_seconds", None) or DEFAULT_PROFILE_WAIT_TIMEOUT_SECONDS
    command_parts.extend(["--profile-wait-timeout-seconds", str(float(wait_timeout))])
    payload.setdefault(
        "recovery_hint",
        "The browser profile is currently owned by another browser-backed operation. The service-profile queue waited until its timeout; retry after the active operation finishes or increase --profile-wait-timeout-seconds.",
    )
    payload["next_safe_commands"] = [
        "pb browser status --json",
        " ".join(command_parts),
    ]
    return payload


def _candidate_validation_command_from_file(file_path: Optional[str]) -> str | None:
    if not file_path:
        return None
    path = Path(file_path)
    match = re.search(r"_v(\d+(?:\.\d+){2,})\.zip$", path.name)
    if not match:
        return None
    version = f"v{match.group(1)}"
    return (
        "./scripts/pb-browser-cloudflare-validation.sh "
        f"--install-artifact {shlex.quote(str(path))} "
        f"--install-version {shlex.quote(version)}"
    )


def _project_source_add_exception_payload(
    exc: Exception,
    *,
    source_kind: str,
    file_path: Optional[str],
    display_name: Optional[str],
    overwrite_existing: bool,
    service_payload: Optional[dict[str, Any]] = None,
) -> dict[str, Any]:
    error_text = str(exc)
    service_status = service_payload.get("status") if service_payload else None
    status = "source_add_failed"
    if service_status == "project_source_mutation_gate_closed":
        status = "project_source_mutation_gate_closed"
    elif "remove/delete action" in error_text:
        status = "overwrite_remove_failed"
    elif "already exists" in error_text.lower():
        status = "source_already_exists"

    payload: dict[str, Any] = {
        "ok": False,
        "action": "source_add",
        "status": status,
        "source_kind": source_kind,
        "file_path": file_path,
        "display_name": display_name,
        "overwrite_existing": overwrite_existing,
        "project_source_mutated": False,
        "persistence_verified": False,
        "operator_review_required": status == "overwrite_remove_failed",
        "error": error_text,
    }
    if service_payload:
        payload["service_status"] = service_status
        for field in (
            "runtime",
            "release_blocking",
            "timeout_layer",
            "service_timeout_seconds",
            "configured_timeout_seconds",
            "active_operation",
            "operator_action",
            "recovery_hint",
        ):
            if service_payload.get(field) is not None:
                payload[field] = service_payload.get(field)

    if status == "project_source_mutation_gate_closed":
        recommended = _candidate_validation_command_from_file(file_path)
        payload.update({
            "classification": "expected_safety_gate",
            "operator_action": "use_auth_only_validation_or_explicitly_enable_the_mutation_gate_for_a_guarded_diagnostic",
            "recovery_hint": (
                "This release slice intentionally keeps ChatGPT Project Source mutation disabled. "
                "Do not use pbsa/pb src add for standard-browser Cloudflare validation."
            ),
            "project_source_required_for_standard_browser_validation": False,
            "mutation_gate_env": "PROMPTBRANCH_ALLOW_PROJECT_SOURCE_MUTATION=1",
            "next_safe_commands": [cmd for cmd in [
                recommended,
                "./scripts/pb-browser-cloudflare-validation.sh --skip-bootstrap",
                "./scripts/docker-browser-parity-guarded-project-source-test.sh  # diagnostic only; enables the explicit mutation gate",
            ] if cmd],
        })
    return payload


async def cmd_project_source_add(backend: CommandBackend, args: argparse.Namespace) -> int:
    source_kind = args.type or "file"
    value = args.value
    positional_file_path = getattr(args, "file_path", None)
    file_path = args.file or positional_file_path
    display_name = args.name
    if args.file and positional_file_path and args.file != positional_file_path:
        print("error: pass the file path either positionally or with --file, not both", file=sys.stderr)
        return 2
    if source_kind != "file" and positional_file_path:
        print("error: positional source path is only supported when --type=file", file=sys.stderr)
        return 2
    if source_kind == "file" and not file_path:
        print("error: file path is required when --type=file", file=sys.stderr)
        return 2
    if source_kind in {"link", "text"} and not value:
        print(f"error: --value is required when --type={source_kind}", file=sys.stderr)
        return 2
    if source_kind == "file" and display_name:
        display_name = Path(display_name).name
    elif source_kind == "file" and file_path and not display_name:
        display_name = Path(file_path).name

    overwrite_existing = not getattr(args, "no_overwrite", False)
    profile_lock_wait_seconds = _profile_wait_timeout_from_args(args)
    protected_release_version: Optional[str] = None
    protected_release_filename: Optional[str] = None
    if source_kind == "file":
        try:
            registry = _artifact_registry_from_args(args)
            repo_id = normalize_repo_id(getattr(registry, "repo_id", None))
            current = registry.current(repo_id=repo_id) if repo_id else registry.current()
            if isinstance(current, dict):
                protected_release_version = str(current.get("version") or "").strip() or None
                protected_release_filename = Path(str(current.get("filename") or "")).name or None
        except Exception:
            protected_release_version = None
            protected_release_filename = None
        if not protected_release_version or not protected_release_filename:
            repo_context_raw = getattr(args, "repo_path", None)
            repo_context = Path(str(repo_context_raw)).expanduser().resolve() if repo_context_raw else Path.cwd().resolve()
            control_version, control_filename = _accepted_current_release_identity_from_project_control(repo_context)
            protected_release_version = protected_release_version or control_version
            protected_release_filename = protected_release_filename or control_filename
    source_add_kwargs: dict[str, Any] = {
        "source_kind": source_kind,
        "value": value,
        "file_path": file_path,
        "display_name": display_name,
        "keep_open": args.keep_open,
        "overwrite_existing": overwrite_existing,
        "profile_lock_wait_seconds": profile_lock_wait_seconds,
    }
    if protected_release_version:
        source_add_kwargs["protected_release_version"] = protected_release_version
    if protected_release_filename:
        source_add_kwargs["protected_release_filename"] = protected_release_filename

    try:
        result = await backend.add_project_source(**source_add_kwargs)
    except Exception as exc:
        service_payload = _service_exception_payload(exc, args)
        if service_payload and service_payload.get("status") == "browser_profile_busy":
            result = _source_add_busy_payload(
                service_payload,
                source_kind=source_kind,
                file_path=file_path,
                display_name=display_name,
                overwrite_existing=overwrite_existing,
                args=args,
                profile_lock_wait_seconds=profile_lock_wait_seconds,
            )
        else:
            result = _project_source_add_exception_payload(
                exc,
                source_kind=source_kind,
                file_path=file_path,
                display_name=display_name,
                overwrite_existing=overwrite_existing,
                service_payload=service_payload,
            )
    if result.get("ok") and not getattr(args, "no_post_mutation_wait_idle", False):
        idle_result = await _wait_for_browser_idle(
            backend,
            timeout_seconds=getattr(args, "post_mutation_idle_timeout_seconds", DEFAULT_BROWSER_WAIT_IDLE_TIMEOUT_SECONDS) or DEFAULT_BROWSER_WAIT_IDLE_TIMEOUT_SECONDS,
            poll_seconds=getattr(args, "post_mutation_idle_poll_seconds", DEFAULT_BROWSER_WAIT_IDLE_POLL_SECONDS) or DEFAULT_BROWSER_WAIT_IDLE_POLL_SECONDS,
            action="source_add_post_mutation_wait_idle",
        )
        result = dict(result)
        result["post_mutation_browser_idle"] = idle_result
        result["browser_profile_released"] = bool(idle_result.get("ok"))
        if not idle_result.get("ok"):
            result["ok"] = False
            result["status"] = "source_add_browser_profile_not_idle_after_mutation"
            result.setdefault("operator_action", "retry_after_active_browser_operation_or_use_async_job_status")
            result.setdefault("next_safe_commands", _browser_profile_busy_next_safe_commands("pb src list --json"))
    print(json.dumps(result, indent=2, ensure_ascii=False))
    if result.get("ok"):
        return 0
    return 75 if result.get("status") in {"browser_profile_busy", "source_add_browser_profile_not_idle_after_mutation"} else 1


