def _protocol_request_from_current_baseline(backend: Any, args: argparse.Namespace, *, prompt: str) -> dict[str, Any]:
    registry = _artifact_registry_from_args(args)
    current_payload = _artifact_current_payload(backend, registry)
    selected_repo_id, selected_current = _artifact_current_select_entry(current_payload)
    state = selected_current.get("state") if isinstance(selected_current.get("state"), dict) else {}
    registry_current = selected_current.get("registry_current") if isinstance(selected_current.get("registry_current"), dict) else {}
    snapshot = backend.state_snapshot()
    current_artifact = state.get("artifact_ref") or registry_current.get("filename")
    current_version = state.get("artifact_version") or registry_current.get("version")
    current_source = state.get("source_ref") or current_artifact
    source_version = state.get("source_version") or current_version
    repo_name = selected_repo_id or _repo_name_from_artifact_name(str(current_artifact or registry_current.get("filename") or ""))
    selected_origin_record = dict(registry_current)
    baseline_artifact_override = str(getattr(args, "baseline_artifact", None) or "").strip()
    baseline_version_override = _normalize_version_token(getattr(args, "baseline_version", None))
    baseline_override_applied = False
    if baseline_artifact_override:
        current_artifact = Path(baseline_artifact_override).name; current_source = current_artifact
        inferred_version = _normalize_version_token(_artifact_version_from_filename(current_artifact))
        current_version = baseline_version_override or inferred_version or current_version
        source_version = current_version; repo_name = _repo_name_from_artifact_name(str(current_artifact)) or repo_name; baseline_override_applied = True
    elif baseline_version_override:
        current_version = baseline_version_override; source_version = baseline_version_override; baseline_override_applied = True
    if baseline_override_applied:
        matches=[item for item in registry.list() if item.get("kind")=="adopted_release" and (not repo_name or item.get("repo_id")==repo_name) and _candidate_version_normalized(item.get("version"))==_candidate_version_normalized(current_version) and (not current_artifact or Path(str(item.get("filename") or "")).name==Path(str(current_artifact)).name)]
        selected_origin_record=dict(matches[0]) if len(matches)==1 else {}
    explicit = str(getattr(args,"conversation_url",None) or "").strip() or None
    if explicit:
        routed=explicit; source="explicit_cli"
    elif _artifact_origin_provenance_valid(selected_origin_record):
        routed=str(selected_origin_record.get("origin_conversation_url")); source="baseline_artifact_provenance"; args.conversation_url=routed
    else:
        return {"ok":False,"action":"ask_protocol_request","status":"baseline_artifact_conversation_provenance_missing","error":"successor protocol ask requires an explicit conversation or immutable origin conversation provenance on the selected baseline artifact","baseline_artifact":current_artifact,"baseline_version":current_version,"repo_id":repo_name,"routing_source":"none","required_command":f"pb artifact bind-conversation --repo {repo_name} --version {current_version} --conversation-url <chat-url> --json","artifact_current":current_payload,"automation_performed":False,"download_performed":False,"migration_performed":False,"adoption_performed":False}
    cid=conversation_id_from_url(routed or "")
    if not cid:
        return {"ok":False,"action":"ask_protocol_request","status":"invalid_successor_conversation_url","error":"successor conversation must be an exact ChatGPT conversation URL","conversation_url":routed,"routing_source":source,"automation_performed":False,"download_performed":False,"migration_performed":False,"adoption_performed":False}
    request_id=getattr(args,"request_id",None) or f"req_{utc_now().replace('-', '').replace(':', '').replace('.', '').replace('+', 'Z')}"
    artifact={"repo":repo_name,"current_baseline":current_artifact,"current_version":current_version,"source_ref":current_source,"source_version":source_version,"registry_current":current_artifact if baseline_override_applied else registry_current.get("filename"),"registry_current_version":current_version if baseline_override_applied else registry_current.get("version")}
    if baseline_override_applied:
        artifact.update({"baseline_override":True,"baseline_override_reason":"explicit_protocol_request_baseline","observed_registry_current":registry_current.get("filename"),"observed_registry_current_version":registry_current.get("version")})
    envelope=build_ask_request_envelope(prompt=prompt,request_id=request_id,correlation_id=getattr(args,"correlation_id",None),workspace={"project_name":snapshot.get("project_name") or project_name_from_url(snapshot.get("resolved_project_home_url") or ""),"project_home_url":snapshot.get("resolved_project_home_url")},task={"conversation_url":routed,"conversation_id":cid,"turn_policy":"assistant_may_return_one_protocol_reply"},artifact=artifact,target_version=getattr(args,"target_version",None),release_type=getattr(args,"release_type","normal"),intent_kind=getattr(args,"intent_kind","software_release_request"),infer_target_version=not bool(getattr(args,"no_target_version_inference",False)))
    return {"ok":True,"action":"ask_protocol_request","status":"request_built","request":envelope,"artifact_current":current_payload,"conversation_routing":{"source":source,"conversation_url":routed,"conversation_id":cid,"baseline_artifact":current_artifact,"baseline_version":current_version},"automation_performed":False,"download_performed":False,"migration_performed":False,"adoption_performed":False}



def _baseline_from_protocol_request(envelope: dict[str, Any]) -> dict[str, Any]:
    artifact = envelope.get("artifact") if isinstance(envelope.get("artifact"), dict) else {}
    return {
        "input_artifact": artifact.get("current_baseline"),
        "input_version": artifact.get("current_version"),
        "source_ref": artifact.get("source_ref"),
        "source_version": artifact.get("source_version"),
        "target_version": artifact.get("target_version"),
        "release_type": artifact.get("release_type"),
    }


def _validate_protocol_reply_against_request(parsed: dict[str, Any], envelope: dict[str, Any]) -> tuple[bool, list[str]]:
    """Validate one parsed reply against its exact request envelope.

    Release replies historically used ``baseline.input_baseline`` while older
    protocol code expected ``baseline.input_artifact``.  A normal release may
    likewise express the target version through ``baseline.target_version`` or
    the single candidate artifact instead of ``baseline.output_version``.  The
    aliases are equivalent only when every present value agrees; contradictory
    values remain fail-closed.
    """

    errors: list[str] = []
    if not parsed.get("ok"):
        errors.append(str(parsed.get("status") or "reply_parse_failed"))
        return False, errors

    expected_request_id = envelope.get("request_id")
    expected_correlation_id = envelope.get("correlation_id")
    if expected_request_id and parsed.get("request_id") != expected_request_id:
        errors.append("request_id_mismatch")
    if expected_correlation_id and parsed.get("correlation_id") != expected_correlation_id:
        errors.append("correlation_id_mismatch")

    artifact = envelope.get("artifact") if isinstance(envelope.get("artifact"), dict) else {}
    baseline = parsed.get("baseline") if isinstance(parsed.get("baseline"), dict) else {}
    reply = parsed.get("reply") if isinstance(parsed.get("reply"), dict) else {}
    artifacts = parsed.get("artifacts") if isinstance(parsed.get("artifacts"), list) else []
    if "artifacts" not in parsed and isinstance(reply.get("artifacts"), list):
        artifacts = reply.get("artifacts") or []

    expected_baseline = artifact.get("current_baseline")
    baseline_values = [
        str(value)
        for value in (baseline.get("input_artifact"), baseline.get("input_baseline"))
        if value not in {None, ""}
    ]
    if expected_baseline:
        if not baseline_values or any(value != str(expected_baseline) for value in baseline_values):
            errors.append("baseline_artifact_mismatch")
    if artifact.get("current_version") and baseline.get("input_version") != artifact.get("current_version"):
        errors.append("baseline_version_mismatch")

    expected_target_version = _normalize_version_token(artifact.get("target_version"))
    reply_status = parsed.get("reply_status") or reply.get("status") or parsed.get("status")
    result_type = parsed.get("result_type") or reply.get("result_type")
    no_artifact_no_change = reply_status == "no_artifact" and result_type == "no_change" and not artifacts
    if expected_target_version:
        observed_target_versions: list[str] = []
        for value in (baseline.get("output_version"), baseline.get("target_version")):
            normalized = _normalize_version_token(value)
            if normalized:
                observed_target_versions.append(normalized)
        if not no_artifact_no_change:
            for candidate in artifacts:
                if isinstance(candidate, dict):
                    normalized = _normalize_version_token(candidate.get("version"))
                    if normalized:
                        observed_target_versions.append(normalized)
        observed_target_versions = list(dict.fromkeys(observed_target_versions))
        if no_artifact_no_change:
            if any(value != expected_target_version for value in observed_target_versions):
                errors.append("target_version_mismatch")
        elif not observed_target_versions or any(value != expected_target_version for value in observed_target_versions):
            errors.append("target_version_mismatch")

    if artifact.get("release_type") and baseline.get("release_type") != artifact.get("release_type"):
        errors.append("release_type_mismatch")
    return not errors, list(dict.fromkeys(errors))



def _protocol_run_record_path(args: argparse.Namespace, request_id: Any) -> Path:
    safe = re.sub(r"[^A-Za-z0-9_.-]+", "_", str(request_id or "unknown")).strip("._") or "unknown"
    return Path(args.profile_dir).expanduser().resolve() / "ask_protocol_runs" / f"{safe}.json"


def _persist_protocol_run_record(args: argparse.Namespace, result: dict[str, Any]) -> str | None:
    request = result.get("request") if isinstance(result.get("request"), dict) else {}
    request_id = request.get("request_id") or result.get("request_id")
    try:
        path = _protocol_run_record_path(args, request_id)
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(json.dumps(result, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
        return str(path)
    except OSError:
        return None


def _protocol_ask_record_dir(args: argparse.Namespace, request_id: Any) -> Path:
    safe = re.sub(r"[^A-Za-z0-9_.-]+", "_", str(request_id or "unknown")).strip("._") or "unknown"
    return Path(args.profile_dir).expanduser().resolve() / "ask_records" / safe


def _write_protocol_record_json(path: Path, value: Any) -> bool:
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(json.dumps(value, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
        return True
    except OSError:
        return False


def _persist_protocol_ask_debug_record(args: argparse.Namespace, result: dict[str, Any]) -> dict[str, str]:
    request = result.get("request") if isinstance(result.get("request"), dict) else {}
    request_id = request.get("request_id") or result.get("request_id")
    record_dir = _protocol_ask_record_dir(args, request_id)
    written: dict[str, str] = {}

    def write_json(name: str, value: Any) -> None:
        if value is None:
            return
        path = record_dir / name
        if _write_protocol_record_json(path, value):
            written[name] = str(path)

    write_json("request.json", request or None)
    write_json("submit_evidence.json", result.get("ask_submit_evidence"))
    pre_marker = result.get("pre_ask_marker") if isinstance(result.get("pre_ask_marker"), dict) else {}
    write_json("before_backend_snapshot.json", pre_marker.get("transcript_snapshot") if isinstance(pre_marker, dict) else None)
    fresh_turn = result.get("fresh_turn_evidence") if isinstance(result.get("fresh_turn_evidence"), dict) else {}
    attempts = fresh_turn.get("attempts") if isinstance(fresh_turn.get("attempts"), list) else []
    if attempts:
        path = record_dir / "after_backend_snapshots.jsonl"
        try:
            path.parent.mkdir(parents=True, exist_ok=True)
            with path.open("w", encoding="utf-8") as handle:
                for attempt in attempts:
                    snapshot = attempt.get("snapshot") if isinstance(attempt, dict) else None
                    if isinstance(snapshot, dict):
                        handle.write(json.dumps(snapshot, ensure_ascii=False, sort_keys=True) + "\n")
            written["after_backend_snapshots.jsonl"] = str(path)
        except OSError:
            pass
    write_json("classification.json", {
        "ok": result.get("ok"),
        "status": result.get("status"),
        "error": result.get("error"),
        "error_type": result.get("error_type"),
        "request_id": result.get("request_id") or request.get("request_id"),
        "conversation_id": result.get("conversation_id"),
        "fresh_turn_evidence": fresh_turn or None,
        "answer_selection": result.get("answer_selection"),
    })
    parsed_reply = {key: result.get(key) for key in ("schema", "schema_version", "request_id", "correlation_id", "result_type", "summary", "baseline", "changes", "artifacts", "validation", "next_step", "confidence") if key in result}
    write_json("reply.parsed.json", parsed_reply or None)
    return written


def _recent_debug_artifacts(limit: int = 12) -> list[str]:
    root = Path.cwd() / "debug_artifacts"
    if not root.is_dir():
        return []
    artifacts: list[Path] = []
    try:
        artifacts = [item for item in root.iterdir() if item.is_file()]
    except OSError:
        return []
    artifacts.sort(key=lambda path: path.stat().st_mtime if path.exists() else 0.0, reverse=True)
    return [str(path) for path in artifacts[: max(0, int(limit))]]


def _protocol_failure_result(
    args: argparse.Namespace,
    *,
    envelope: dict[str, Any],
    status: str,
    error: str,
    error_type: str | None = None,
    ask_response: dict[str, Any] | None = None,
    pre_ask_marker: dict[str, Any] | None = None,
) -> dict[str, Any]:
    artifact = envelope.get("artifact") if isinstance(envelope.get("artifact"), dict) else {}
    return {
        "ok": False,
        "action": "ask_protocol_run",
        "status": status,
        "error": error,
        "error_type": error_type or status,
        "request_id": envelope.get("request_id"),
        "correlation_id": envelope.get("correlation_id"),
        "request": envelope,
        "request_baseline": _baseline_from_protocol_request(envelope),
        "current_baseline": artifact.get("current_baseline"),
        "current_version": artifact.get("current_version"),
        "target_version": artifact.get("target_version"),
        "release_type": artifact.get("release_type"),
        "protocol_timeout_seconds": float(getattr(args, "protocol_timeout_seconds", DEFAULT_PROTOCOL_ASK_TIMEOUT_SECONDS) or DEFAULT_PROTOCOL_ASK_TIMEOUT_SECONDS),
        "service_timeout_seconds": float(getattr(args, "service_timeout_seconds", DEFAULT_SERVICE_TIMEOUT_SECONDS) or DEFAULT_SERVICE_TIMEOUT_SECONDS),
        "ask_response": ask_response,
        "ask_submit_evidence": _protocol_ask_submit_evidence(ask_response),
        "pre_ask_marker": pre_ask_marker,
        "debug_artifacts": _recent_debug_artifacts(),
        "automation_performed": True,
        "download_performed": False,
        "migration_performed": False,
        "adoption_performed": False,
        "operator_instruction": "Protocol ask failed before a validated reply was available. No artifact download, migration, adoption, or Project Source mutation was performed.",
    }




def _protocol_expected_conversation_id(envelope: dict[str, Any]) -> str:
    task = envelope.get("task") if isinstance(envelope.get("task"), dict) else {}
    value = str(task.get("conversation_id") or "").strip()
    if value and value != "current":
        return value
    from_url = conversation_id_from_url(task.get("conversation_url"))
    return str(from_url or "").strip()


def _protocol_expected_conversation_url(envelope: dict[str, Any]) -> str:
    task = envelope.get("task") if isinstance(envelope.get("task"), dict) else {}
    return str(task.get("conversation_url") or "").strip()


def _protocol_conversation_id_from_response(ask_response: dict[str, Any] | None) -> str:
    if not isinstance(ask_response, dict):
        return ""
    value = str(ask_response.get("conversation_id") or "").strip()
    if value:
        return value
    return str(conversation_id_from_url(ask_response.get("conversation_url")) or "").strip()


def _protocol_conversation_lock_mismatch(envelope: dict[str, Any], ask_response: dict[str, Any] | None) -> dict[str, Any] | None:
    """Return mismatch metadata when the service response points to another task.

    Protocol ask parsing is conversation-locked. A response from another
    conversation may contain a valid-looking stale assistant answer, but it is
    not operationally admissible for the current protocol request.
    """

    expected_id = _protocol_expected_conversation_id(envelope)
    if not expected_id:
        return None
    actual_id = _protocol_conversation_id_from_response(ask_response)
    if not actual_id or actual_id == expected_id:
        return None
    return {
        "expected_conversation_id": expected_id,
        "expected_conversation_url": _protocol_expected_conversation_url(envelope) or None,
        "actual_conversation_id": actual_id,
        "actual_conversation_url": ask_response.get("conversation_url") if isinstance(ask_response, dict) else None,
        "status": "submit_clicked_target_conversation_lost",
        "diagnostic": "ask_response conversation_url/conversation_id differs from the protocol request target; parser refused to use the returned assistant text",
    }


def _protocol_ask_submit_evidence(ask_response: dict[str, Any] | None) -> dict[str, Any] | None:
    if not isinstance(ask_response, dict):
        return None
    evidence = ask_response.get("submit_evidence")
    return evidence if isinstance(evidence, dict) else None


def _classify_protocol_submit_visibility_failure(
    ask_response: dict[str, Any],
    fresh_turn_evidence: dict[str, Any],
) -> tuple[str, str, str]:
    """Classify failure between browser submit and transcript visibility.

    v0.0.221 keeps submit/click evidence separate from backend transcript
    evidence so the operator can distinguish a failed submit from a stale
    transcript reader or wrong conversation context.
    """

    submit = _protocol_ask_submit_evidence(ask_response)
    source_agreement = fresh_turn_evidence.get("source_agreement") if isinstance(fresh_turn_evidence.get("source_agreement"), dict) else {}
    backend_refresh = fresh_turn_evidence.get("backend_refresh") if isinstance(fresh_turn_evidence.get("backend_refresh"), dict) else {}
    if source_agreement and source_agreement.get("same_conversation_id") is False:
        return (
            "submit_clicked_target_conversation_lost",
            "submit_clicked_target_conversation_lost: post-submit transcript refresh read a different conversation than the protocol request expected",
            "Protocol ask submit evidence was collected, but the task transcript source or ask response points at a different conversation. The parser remained locked to the requested conversation and refused the returned assistant text. No artifact download, migration, adoption, or Project Source mutation was performed.",
        )
    if not submit:
        return (
            "ask_submission_not_visible",
            "ask_submission_not_visible: no newer user message or request_id-matched user turn was visible after the protocol ask submit; browser submit evidence was unavailable",
            "Protocol ask submit evidence was unavailable and no fresh user turn was visible after post-submit refresh/poll. No artifact download, migration, adoption, or Project Source mutation was performed.",
        )
    clicked = bool(submit.get("clicked"))
    enter_fallback = bool(submit.get("enter_fallback_used"))
    dom = submit.get("dom_user_turn_evidence") if isinstance(submit.get("dom_user_turn_evidence"), dict) else {}
    dom_visible = bool(dom.get("visible"))
    if not clicked and not enter_fallback:
        return (
            "ask_submit_not_triggered",
            "ask_submit_not_triggered: browser submit evidence does not show a clicked send button or Enter fallback",
            "Protocol ask was not proven submitted in the browser. No artifact download, migration, adoption, or Project Source mutation was performed.",
        )
    if dom_visible and not fresh_turn_evidence.get("fresh_user_turn_visible"):
        if fresh_turn_evidence.get("request_message_found") is False and int(fresh_turn_evidence.get("newer_user_message_count") or 0) == 0:
            return (
                "submit_clicked_old_turns_only",
                "submit_clicked_old_turns_only: browser DOM became visible but backend/task transcript contains no request-id match and no user message newer than the pre-submit marker",
                "Protocol ask submit returned old or already-loaded conversation turns, not a materialized fresh request. The parser refused stale assistant text. No artifact download, migration, adoption, or Project Source mutation was performed.",
            )
        return (
            "submit_visible_but_task_reader_stale",
            "submit_visible_but_task_reader_stale: browser DOM shows the submitted user turn but backend/task transcript did not expose it after polling",
            "Protocol ask was visible in the browser DOM, but not in the backend/task transcript. No artifact download, migration, adoption, or Project Source mutation was performed.",
        )
    composer_cleared = bool(submit.get("composer_cleared"))
    if composer_cleared and backend_refresh and not backend_refresh.get("snapshot_changed"):
        return (
            "submit_visible_but_backend_snapshot_stale",
            "submit_visible_but_backend_snapshot_stale: browser submit cleared the composer, but backend transcript snapshots did not change across refresh attempts",
            "Protocol ask appears submitted because the composer cleared, but backend transcript snapshots stayed stale. No artifact download, migration, adoption, or Project Source mutation was performed.",
        )
    before_user_turns = submit.get("before_user_turns") if isinstance(submit.get("before_user_turns"), dict) else {}
    before_generic = before_user_turns.get("generic_turns") if isinstance(before_user_turns.get("generic_turns"), dict) else {}
    if composer_cleared and not dom_visible and int(before_user_turns.get("count") or 0) == 0 and int(before_generic.get("count") or 0) > 0:
        return (
            "ask_clicked_composer_cleared_dom_selector_missed",
            "ask_clicked_composer_cleared_dom_selector_missed: browser click cleared the composer, but role-specific user-turn selectors did not see existing or new user turns",
            "Protocol ask appears submitted because the composer cleared, but DOM role selectors missed user turns and backend/task transcript stayed stale. No artifact download, migration, adoption, or Project Source mutation was performed.",
        )
    if composer_cleared and not fresh_turn_evidence.get("fresh_user_turn_visible"):
        return (
            "ask_clicked_composer_cleared_backend_stale",
            "ask_clicked_composer_cleared_backend_stale: browser submit cleared the composer, but no newer user turn was exposed by DOM/backend transcript refresh",
            "Protocol ask appears submitted because the composer cleared, but the task transcript did not expose the new turn after polling. No artifact download, migration, adoption, or Project Source mutation was performed.",
        )
    return (
        "ask_clicked_but_no_turn_materialized",
        "ask_clicked_but_no_turn_materialized: browser submit was attempted, but no DOM or backend evidence of a fresh user turn materialized",
        "Protocol ask was submitted or attempted, but no fresh user turn was visible after post-submit refresh/poll. No artifact download, migration, adoption, or Project Source mutation was performed.",
    )




def _protocol_recovery_conversation_url(args: argparse.Namespace, envelope: dict[str, Any]) -> str:
    expected = _protocol_expected_conversation_url(envelope)
    if expected:
        return expected
    arg_value = str(getattr(args, "conversation_url", None) or "").strip()
    if arg_value:
        return arg_value
    try:
        state_snapshot = _state_store_from_args(args).snapshot(getattr(args, "project_url", None))
    except Exception:
        state_snapshot = {}
    if isinstance(state_snapshot, dict):
        value = state_snapshot.get("conversation_url") or (state_snapshot.get("task") or {}).get("conversation_url")
        if value:
            return str(value)
    task = envelope.get("task") if isinstance(envelope.get("task"), dict) else {}
    return str(task.get("conversation_url") or "").strip()


def _validated_protocol_recovery_record(payload: dict[str, Any], envelope: dict[str, Any]) -> tuple[dict[str, Any] | None, str | None]:
    if not isinstance(payload, dict):
        return None, "protocol_recovery_record_not_object"
    if not _protocol_run_is_validated(payload):
        return None, "protocol_recovery_record_not_validated"
    if str(payload.get("request_id") or "") != str(envelope.get("request_id") or ""):
        return None, "protocol_recovery_request_id_mismatch"
    if str(payload.get("correlation_id") or "") != str(envelope.get("correlation_id") or ""):
        return None, "protocol_recovery_correlation_id_mismatch"
    validation_ok, validation_errors = _validate_protocol_reply_against_request(payload, envelope)
    if not validation_ok:
        return None, "protocol_recovery_validation_failed:" + ",".join(validation_errors)
    recovered = copy.deepcopy(payload)
    recovered["ok"] = True
    recovered["status"] = "recovered_after_service_timeout"
    recovered["reply_validation_ok"] = True
    recovered["reply_validation_errors"] = []
    recovered.setdefault("request", envelope)
    recovered.setdefault("request_baseline", _baseline_from_protocol_request(envelope))
    recovered["service_timeout_recovery"] = {
        "attempted": True,
        "source": "persisted_protocol_run_record",
        "previous_status": payload.get("status"),
        "record_had_validated_reply": True,
    }
    recovered["timeout_layer"] = "service_client"
    recovered["operator_instruction"] = "Protocol ask service call timed out, but a persisted validated protocol reply for the same request was found and recovered. No artifact download, migration, adoption, or Project Source mutation was performed."
    return recovered, None


def _load_protocol_run_record_for_request(args: argparse.Namespace, envelope: dict[str, Any]) -> tuple[Path | None, dict[str, Any] | None, dict[str, Any]]:
    path = _protocol_run_record_path(args, envelope.get("request_id"))
    if not path.is_file():
        return path, None, {"available": False, "status": "protocol_run_record_missing", "path": str(path)}
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        return path, None, {"available": False, "status": "protocol_run_record_unreadable", "path": str(path), "error": str(exc)}
    if not isinstance(payload, dict):
        return path, None, {"available": False, "status": "protocol_run_record_invalid_payload", "path": str(path)}
    return path, payload, {"available": True, "status": "protocol_run_record_loaded", "path": str(path)}


async def _recover_protocol_reply_after_service_timeout(
    backend: CommandBackend,
    args: argparse.Namespace,
    *,
    envelope: dict[str, Any],
    error: str,
    error_type: str,
    pre_ask_marker: dict[str, Any] | None,
) -> tuple[dict[str, Any] | None, dict[str, Any]]:
    """Recover a protocol reply after the HTTP service response times out.

    The browser service can complete the ChatGPT ask and persist/serve the
    resulting conversation after the CLI HTTP client has timed out waiting for
    /v1/ask. Recovery is deliberately bounded and fail-closed: only a reply
    matching the original request envelope may become a successful protocol run.
    """

    diagnostic: dict[str, Any] = {
        "attempted": True,
        "timeout_layer": "service_client",
        "error": error,
        "error_type": error_type,
        "request_id": envelope.get("request_id"),
        "correlation_id": envelope.get("correlation_id"),
        "persisted_record_checked": False,
        "transcript_recovery_attempted": False,
        "recovered": False,
    }

    record_path, record_payload, record_diag = _load_protocol_run_record_for_request(args, envelope)
    diagnostic["persisted_record_checked"] = True
    diagnostic["persisted_record"] = record_diag
    if isinstance(record_payload, dict):
        recovered, reason = _validated_protocol_recovery_record(record_payload, envelope)
        if recovered is not None:
            diagnostic["recovered"] = True
            diagnostic["source"] = "persisted_protocol_run_record"
            diagnostic["record_path"] = str(record_path) if record_path else None
            recovered["service_timeout_recovery"] = {**diagnostic, **recovered.get("service_timeout_recovery", {})}
            return recovered, diagnostic
        diagnostic["persisted_record_rejected_reason"] = reason

    conversation_url = _protocol_recovery_conversation_url(args, envelope)
    diagnostic["conversation_url"] = conversation_url or None
    if not conversation_url:
        diagnostic["transcript_recovery_status"] = "conversation_url_missing"
        return None, diagnostic

    diagnostic["transcript_recovery_attempted"] = True
    synthetic_ask_response = {
        "ok": True,
        "answer": None,
        "conversation_url": conversation_url,
        "status": "service_read_timeout_recovery_probe",
        "error": error,
        "error_type": error_type,
        "timeout_layer": "service_client",
        "partial_result": True,
    }
    try:
        result = await _parse_protocol_reply_after_ask(
            backend,
            args,
            envelope=envelope,
            ask_response=synthetic_ask_response,
            pre_ask_marker=pre_ask_marker,
        )
    except Exception as exc:
        diagnostic["transcript_recovery_status"] = "exception"
        diagnostic["transcript_recovery_error_type"] = exc.__class__.__name__
        diagnostic["transcript_recovery_error"] = str(exc)
        return None, diagnostic

    diagnostic["transcript_recovery_status"] = result.get("status")
    diagnostic["transcript_recovery_ok"] = bool(result.get("ok"))
    diagnostic["transcript_reply_validation_ok"] = bool(result.get("reply_validation_ok"))
    if result.get("ok") is True and result.get("reply_validation_ok") is True:
        recovered = dict(result)
        recovered["status"] = "recovered_after_service_timeout"
        recovered["timeout_layer"] = "service_client"
        recovered["service_timeout_recovery"] = {**diagnostic, "recovered": True, "source": "task_transcript_reparse"}
        recovered["operator_instruction"] = "Protocol ask service call timed out, but the same request was recovered from the task transcript and validated. No artifact download, migration, adoption, or Project Source mutation was performed."
        diagnostic["recovered"] = True
        diagnostic["source"] = "task_transcript_reparse"
        return recovered, diagnostic

    diagnostic["transcript_recovery_result_status"] = result.get("status")
    diagnostic["transcript_recovery_result_error"] = result.get("error")
    return None, diagnostic

def _emit_protocol_result(args: argparse.Namespace, result: dict[str, Any]) -> int:
    record_path = _persist_protocol_run_record(args, result)
    if record_path:
        result["protocol_run_record_path"] = record_path
        result["request_persisted"] = True
    else:
        result["request_persisted"] = False
    debug_files = _persist_protocol_ask_debug_record(args, result)
    if debug_files:
        result["ask_debug_record_files"] = debug_files
        result["ask_debug_record_dir"] = str(Path(next(iter(debug_files.values()))).parent)
    if getattr(args, "json", False):
        print(json.dumps(result, indent=2, ensure_ascii=False))
    else:
        print(_render_task_answer_parse_result(result), end="")
    return 0 if result.get("ok") else 1


def _protocol_turn_number(value: Any) -> int | None:
    if value is None:
        return None
    try:
        return int(value)
    except (TypeError, ValueError):
        return None


def _latest_protocol_task_marker(payload: dict[str, Any]) -> dict[str, Any]:
    messages = payload.get("messages") if isinstance(payload.get("messages"), list) else []
    latest_message = messages[-1] if messages else None
    latest_answer: dict[str, Any] | None = None
    latest_answer_message: dict[str, Any] | None = None
    for message in reversed(messages):
        answers = message.get("answers") if isinstance(message.get("answers"), list) else []
        if answers:
            latest_answer = answers[-1]
            latest_answer_message = message
            break
    return {
        "available": True,
        "conversation_url": payload.get("conversation_url"),
        "conversation_id": payload.get("conversation_id"),
        "message_count": len(messages),
        "latest_user_message_id": latest_message.get("id") if isinstance(latest_message, dict) else None,
        "latest_user_message_index": latest_message.get("index") if isinstance(latest_message, dict) else None,
        "latest_user_turn_index": latest_message.get("turn_index") if isinstance(latest_message, dict) else None,
        "latest_answer_id": latest_answer.get("id") if isinstance(latest_answer, dict) else None,
        "latest_answer_index": latest_answer.get("index") if isinstance(latest_answer, dict) else None,
        "latest_answer_turn_index": latest_answer.get("turn_index") if isinstance(latest_answer, dict) else None,
        "latest_answer_message_id": latest_answer_message.get("id") if isinstance(latest_answer_message, dict) else None,
        "latest_answer_message_index": latest_answer_message.get("index") if isinstance(latest_answer_message, dict) else None,
    }


def _protocol_prompt_prefix(envelope: dict[str, Any], *, max_length: int = 96) -> str:
    intent = envelope.get("intent") if isinstance(envelope.get("intent"), dict) else {}
    summary = str(intent.get("summary") or "").strip()
    summary = re.sub(r"\s+", " ", summary)
    return summary[:max_length]


def _protocol_flat_turns(messages: list[dict[str, Any]]) -> list[dict[str, Any]]:
    turns: list[dict[str, Any]] = []
    for message in messages:
        if not isinstance(message, dict):
            continue
        turns.append({
            "role": "user",
            "id": message.get("id"),
            "index": message.get("index"),
            "turn_index": message.get("turn_index"),
            "create_time": message.get("create_time"),
            "preview": message.get("preview"),
            "text": message.get("text"),
        })
        answers = message.get("answers") if isinstance(message.get("answers"), list) else []
        for answer in answers:
            if not isinstance(answer, dict):
                continue
            turns.append({
                "role": "assistant",
                "id": answer.get("id"),
                "index": answer.get("index"),
                "turn_index": answer.get("turn_index"),
                "create_time": answer.get("create_time"),
                "status": answer.get("status"),
                "preview": answer.get("preview"),
                "text": answer.get("text"),
            })
    return turns


def _protocol_transcript_fingerprint(turns: list[dict[str, Any]]) -> str:
    stable: list[dict[str, Any]] = []
    for turn in turns:
        stable.append({
            "role": turn.get("role"),
            "id": turn.get("id"),
            "index": turn.get("index"),
            "turn_index": turn.get("turn_index"),
            "create_time": turn.get("create_time"),
            "status": turn.get("status"),
            "text_hash": hashlib.sha256(str(turn.get("text") or turn.get("preview") or "").encode("utf-8", errors="replace")).hexdigest(),
        })
    blob = json.dumps(stable, sort_keys=True, ensure_ascii=False, separators=(",", ":"))
    return "sha256:" + hashlib.sha256(blob.encode("utf-8", errors="replace")).hexdigest()


def _protocol_transcript_snapshot(
    payload: dict[str, Any],
    *,
    source: str,
    envelope: dict[str, Any] | None = None,
    fetched_at: str | None = None,
) -> dict[str, Any]:
    messages = payload.get("messages") if isinstance(payload.get("messages"), list) else []
    turns = _protocol_flat_turns(messages)
    user_turns = [turn for turn in turns if turn.get("role") == "user"]
    assistant_turns = [turn for turn in turns if turn.get("role") == "assistant"]
    latest_turn = turns[-1] if turns else None
    latest_user = user_turns[-1] if user_turns else None
    latest_assistant = assistant_turns[-1] if assistant_turns else None
    request_id = str((envelope or {}).get("request_id") or "")
    prompt_prefix = _protocol_prompt_prefix(envelope or {})
    text_blob = "\n".join(str(message.get("text") or "") for message in messages if isinstance(message, dict))
    return {
        "available": True,
        "source": source,
        "fetched_at": fetched_at or utc_now(),
        "conversation_url": payload.get("conversation_url"),
        "conversation_id": payload.get("conversation_id"),
        "title": payload.get("title"),
        "message_count": len(messages),
        "user_message_count": len(user_turns),
        "assistant_message_count": len(assistant_turns),
        "latest_message_id": latest_turn.get("id") if isinstance(latest_turn, dict) else None,
        "latest_message_role": latest_turn.get("role") if isinstance(latest_turn, dict) else None,
        "latest_create_time": latest_turn.get("create_time") if isinstance(latest_turn, dict) else None,
        "latest_user_message_id": latest_user.get("id") if isinstance(latest_user, dict) else None,
        "latest_user_message_index": latest_user.get("index") if isinstance(latest_user, dict) else None,
        "latest_user_turn_index": latest_user.get("turn_index") if isinstance(latest_user, dict) else None,
        "latest_user_create_time": latest_user.get("create_time") if isinstance(latest_user, dict) else None,
        "latest_assistant_message_id": latest_assistant.get("id") if isinstance(latest_assistant, dict) else None,
        "latest_assistant_message_index": latest_assistant.get("index") if isinstance(latest_assistant, dict) else None,
        "latest_assistant_turn_index": latest_assistant.get("turn_index") if isinstance(latest_assistant, dict) else None,
        "latest_assistant_create_time": latest_assistant.get("create_time") if isinstance(latest_assistant, dict) else None,
        "message_ids_tail": [turn.get("id") for turn in turns[-8:]],
        "roles_tail": [turn.get("role") for turn in turns[-8:]],
        "turn_indexes_tail": [turn.get("turn_index") for turn in turns[-8:]],
        "request_id_found": bool(request_id and request_id in text_blob),
        "prompt_prefix": prompt_prefix,
        "prompt_prefix_found": bool(prompt_prefix and prompt_prefix in text_blob),
        "raw_fingerprint": _protocol_transcript_fingerprint(turns),
    }


def _compare_protocol_transcript_snapshots(before: dict[str, Any] | None, after: dict[str, Any] | None) -> dict[str, Any]:
    if not isinstance(before, dict) or not before.get("available"):
        return {"available": False, "reason": "before_snapshot_missing"}
    if not isinstance(after, dict) or not after.get("available"):
        return {"available": False, "reason": "after_snapshot_missing"}
    message_count_before = _protocol_turn_number(before.get("message_count")) or 0
    message_count_after = _protocol_turn_number(after.get("message_count")) or 0
    return {
        "available": True,
        "same_conversation_id": before.get("conversation_id") == after.get("conversation_id"),
        "message_count_before": message_count_before,
        "message_count_after": message_count_after,
        "message_count_delta": message_count_after - message_count_before,
        "latest_message_id_changed": before.get("latest_message_id") != after.get("latest_message_id"),
        "latest_user_message_id_changed": before.get("latest_user_message_id") != after.get("latest_user_message_id"),
        "latest_assistant_message_id_changed": before.get("latest_assistant_message_id") != after.get("latest_assistant_message_id"),
        "fingerprint_changed": before.get("raw_fingerprint") != after.get("raw_fingerprint"),
    }


def _protocol_backend_refresh_summary(attempts: list[dict[str, Any]], before_snapshot: dict[str, Any] | None) -> dict[str, Any]:
    comparisons = [attempt.get("snapshot_comparison") for attempt in attempts if isinstance(attempt.get("snapshot_comparison"), dict)]
    available = [item for item in comparisons if item.get("available")]
    last = available[-1] if available else {}
    return {
        "attempt_count": len(attempts),
        "before_snapshot_available": bool(isinstance(before_snapshot, dict) and before_snapshot.get("available")),
        "snapshot_changed": any(bool(item.get("fingerprint_changed")) for item in available),
        "message_count_delta": last.get("message_count_delta"),
        "latest_message_id_changed": any(bool(item.get("latest_message_id_changed")) for item in available),
        "latest_user_message_id_changed": any(bool(item.get("latest_user_message_id_changed")) for item in available),
        "latest_assistant_message_id_changed": any(bool(item.get("latest_assistant_message_id_changed")) for item in available),
        "fingerprint_changed": any(bool(item.get("fingerprint_changed")) for item in available),
        "latest_comparison": last or None,
    }


def _message_after_protocol_marker(message: dict[str, Any], marker: dict[str, Any] | None) -> bool:
    if not isinstance(marker, dict) or not marker.get("available"):
        return True
    msg_index = _protocol_turn_number(message.get("index"))
    marker_msg_index = _protocol_turn_number(marker.get("message_count") or marker.get("latest_user_message_index"))
    if msg_index is not None and marker_msg_index is not None and msg_index > marker_msg_index:
        return True
    msg_turn = _protocol_turn_number(message.get("turn_index"))
    marker_turn = _protocol_turn_number(marker.get("latest_user_turn_index"))
    if msg_turn is not None and marker_turn is not None and msg_turn > marker_turn:
        return True
    return False


def _answer_after_protocol_marker(answer: dict[str, Any], marker: dict[str, Any] | None) -> bool:
    if not isinstance(marker, dict) or not marker.get("available"):
        return True
    answer_turn = _protocol_turn_number(answer.get("turn_index"))
    marker_turn = _protocol_turn_number(marker.get("latest_answer_turn_index"))
    if answer_turn is not None and marker_turn is not None:
        return answer_turn > marker_turn
    answer_id = str(answer.get("id") or "")
    marker_id = str(marker.get("latest_answer_id") or "")
    return bool(answer_id and marker_id and answer_id != marker_id)


def _protocol_answer_metadata(message: dict[str, Any] | None, answer: dict[str, Any] | None) -> dict[str, Any]:
    return {
        "message_id": message.get("id") if isinstance(message, dict) else None,
        "message_index": message.get("index") if isinstance(message, dict) else None,
        "message_turn_index": message.get("turn_index") if isinstance(message, dict) else None,
        "answer_id": answer.get("id") if isinstance(answer, dict) else None,
        "answer_index": answer.get("index") if isinstance(answer, dict) else None,
        "answer_turn_index": answer.get("turn_index") if isinstance(answer, dict) else None,
    }


def _protocol_selection_summary(*, request_id: Any = None, correlation_id: Any = None, message: dict[str, Any] | None = None, answer: dict[str, Any] | None = None, conversation_id: Any = None, conversation_url: Any = None) -> dict[str, Any]:
    """Compact identity block for candidate-intake/candidate-run reporting."""

    selected = _protocol_answer_metadata(message, answer)
    return {
        "request_id": request_id,
        "correlation_id": correlation_id,
        "conversation_id": conversation_id,
        "conversation_url": conversation_url,
        "message_id": selected.get("message_id"),
        "message_index": selected.get("message_index"),
        "message_turn_index": selected.get("message_turn_index"),
        "answer_id": selected.get("answer_id"),
        "answer_index": selected.get("answer_index"),
        "answer_turn_index": selected.get("answer_turn_index"),
    }


def _protocol_run_record_path_for_profile(profile_dir: str | Path, request_id: Any) -> Path:
    safe = re.sub(r"[^A-Za-z0-9_.-]+", "_", str(request_id or "unknown")).strip("._") or "unknown"
    return Path(profile_dir).expanduser().resolve() / "ask_protocol_runs" / f"{safe}.json"


def _load_protocol_run_record_for_request_id(profile_dir: str | Path, request_id: Any) -> tuple[Path, dict[str, Any] | None, dict[str, Any]]:
    path = _protocol_run_record_path_for_profile(profile_dir, request_id)
    if not path.is_file():
        return path, None, {"available": False, "status": "protocol_run_record_missing", "path": str(path)}
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        return path, None, {"available": False, "status": "protocol_run_record_unreadable", "path": str(path), "error": str(exc)}
    if not isinstance(payload, dict):
        return path, None, {"available": False, "status": "protocol_run_record_invalid_payload", "path": str(path)}
    return path, payload, {"available": True, "status": "protocol_run_record_loaded", "path": str(path)}


def _promote_task_answer_protocol_run(args: argparse.Namespace, *, payload: dict[str, Any], message: dict[str, Any], answer: dict[str, Any], parsed: dict[str, Any], source: str = "task_answer_parse") -> dict[str, Any]:
    """Persist a valid parsed task answer as the selected validated protocol run.

    This closes the service-timeout/operator-recovery gap: once an operator has
    selected the exact message/answer pair, later artifact-intake commands can
    read the same validated protocol run from .pb_profile/ask_protocol_runs
    instead of accidentally falling back to newer diagnostic prose.
    """

    request_id = parsed.get("request_id")
    correlation_id = parsed.get("correlation_id")
    diagnostic: dict[str, Any] = {
        "attempted": bool(request_id),
        "performed": False,
        "source": source,
        "reason": None,
        "request_id": request_id,
        "correlation_id": correlation_id,
    }
    if not request_id:
        diagnostic["reason"] = "request_id_missing"
        return diagnostic
    if parsed.get("ok") is not True or not isinstance(parsed.get("reply"), dict):
        diagnostic["reason"] = "parsed_reply_not_valid"
        return diagnostic

    profile_dir = getattr(args, "profile_dir", None) or PROFILE_DIR_NAME
    record_path, existing, existing_diag = _load_protocol_run_record_for_request_id(profile_dir, request_id)
    diagnostic["existing_record"] = existing_diag
    request = existing.get("request") if isinstance(existing, dict) and isinstance(existing.get("request"), dict) else {}
    validation_ok = True
    validation_errors: list[str] = []
    if request:
        validation_ok, validation_errors = _validate_protocol_reply_against_request(parsed, request)
    if not validation_ok:
        diagnostic["reason"] = "reply_validation_failed:" + ",".join(validation_errors)
        diagnostic["reply_validation_errors"] = validation_errors
        return diagnostic

    selected = _protocol_answer_metadata(message, answer)
    record = dict(existing) if isinstance(existing, dict) else {}
    record.update({
        "ok": True,
        "action": "ask_protocol_run",
        "status": "reply_validated_from_task_answer",
        "request_id": request_id,
        "correlation_id": correlation_id,
        "request": request,
        "reply": parsed.get("reply"),
        "reply_validation_ok": True,
        "reply_validation_errors": [],
        "reply_status": parsed.get("reply_status"),
        "result_type": parsed.get("result_type"),
        "artifact_candidate_count": int(parsed.get("artifact_candidate_count") or 0),
        "conversation_url": payload.get("conversation_url"),
        "conversation_id": payload.get("conversation_id"),
        "title": payload.get("title"),
        "message": {key: value for key, value in message.items() if key != "answers"},
        "answer": {key: value for key, value in answer.items() if key != "text"},
        "selected_answer": selected,
        "answer_text_length": len(str(answer.get("text") or "")),
        "task_answer_parse_promotion": {
            "performed": True,
            "source": source,
            "promoted_at": utc_now(),
            "message_id": selected.get("message_id"),
            "answer_id": selected.get("answer_id"),
        },
        "automation_performed": False,
        "download_performed": False,
        "migration_performed": False,
        "adoption_performed": False,
    })
    if not record.get("request_baseline") and request:
        record["request_baseline"] = _baseline_from_protocol_request(request)
    try:
        record_path.parent.mkdir(parents=True, exist_ok=True)
        record_path.write_text(json.dumps(record, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    except OSError as exc:
        diagnostic["reason"] = "protocol_run_record_write_failed"
        diagnostic["error"] = str(exc)
        diagnostic["path"] = str(record_path)
        return diagnostic

    diagnostic.update({
        "performed": True,
        "reason": None,
        "path": str(record_path),
        "status": "reply_validated_from_task_answer",
        "message_id": selected.get("message_id"),
        "answer_id": selected.get("answer_id"),
    })
    return diagnostic


def _resolve_task_message_for_artifact_intake(messages: list[dict[str, Any]], args: argparse.Namespace) -> dict[str, Any]:
    message_selector = getattr(args, "message_id", None) or getattr(args, "message_index", None)
    if not message_selector:
        message_selector = "latest"
    return _resolve_task_message(messages, str(message_selector))


def _select_protocol_reply_message_answer(
    messages: list[dict[str, Any]],
    *,
    args: argparse.Namespace,
    envelope: dict[str, Any],
    pre_ask_marker: dict[str, Any] | None,
) -> tuple[dict[str, Any], dict[str, Any], dict[str, Any]]:
    request_id = str(envelope.get("request_id") or "")

    if getattr(args, "answer_id", None):
        for message in messages:
            answers = message.get("answers") if isinstance(message.get("answers"), list) else []
            try:
                answer = _resolve_task_answer(message, answer_id=getattr(args, "answer_id", None))
            except ValueError:
                continue
            is_after = _message_after_protocol_marker(message, pre_ask_marker) or _answer_after_protocol_marker(answer, pre_ask_marker)
            if not is_after and request_id and request_id not in str(answer.get("text") or ""):
                raise ValueError("stale_answer_detected: explicit answer id selected an answer older than the protocol ask")
            return message, answer, {
                "policy": "explicit_answer_id",
                "fresh_request_message_matched": request_id in str(message.get("text") or "") if request_id else False,
                "selected_answer_is_after_pre_ask_marker": is_after,
            }
        raise ValueError(f"answer not found: {getattr(args, 'answer_id', None)}")

    request_messages = [message for message in messages if request_id and request_id in str(message.get("text") or "")]
    if request_messages:
        candidate_messages = request_messages
        policy = "request_id_message_match"
        fresh_match = True
    elif isinstance(pre_ask_marker, dict) and pre_ask_marker.get("available"):
        candidate_messages = [message for message in messages if _message_after_protocol_marker(message, pre_ask_marker)]
        policy = "newer_than_pre_ask_marker"
        fresh_match = False
        if not candidate_messages:
            raise ValueError("stale_answer_detected: no user message newer than the protocol ask pre-marker was found")
    else:
        candidate_messages = messages[-1:] if messages else []
        policy = "latest_without_pre_ask_marker"
        fresh_match = False

    if not candidate_messages:
        raise ValueError("assistant_not_detected: no candidate user message is available for protocol reply parsing")

    for message in reversed(candidate_messages):
        answers = message.get("answers") if isinstance(message.get("answers"), list) else []
        if not answers:
            continue
        answer = _resolve_task_answer(message, answer_index=getattr(args, "answer_index", None), answer_id=None)
        is_after = _message_after_protocol_marker(message, pre_ask_marker) or _answer_after_protocol_marker(answer, pre_ask_marker)
        if isinstance(pre_ask_marker, dict) and pre_ask_marker.get("available") and not is_after and not fresh_match:
            raise ValueError("stale_answer_detected: selected assistant answer is not newer than the protocol ask pre-marker")
        return message, answer, {
            "policy": policy,
            "fresh_request_message_matched": fresh_match,
            "selected_answer_is_after_pre_ask_marker": is_after,
        }

    if policy == "request_id_message_match":
        raise ValueError("assistant_not_detected: protocol request message was found but it has no assistant answer yet")
    raise ValueError("stale_answer_detected: no newer assistant answer was found after the protocol ask")


async def _capture_pre_ask_protocol_marker(backend: Any, args: argparse.Namespace) -> dict[str, Any] | None:
    conversation_url = str(
        getattr(args, "conversation_url", None)
        or _state_store_from_args(args).snapshot(getattr(args, "project_url", None)).get("conversation_url")
        or ""
    )
    if not conversation_url:
        return None
    try:
        chat = await backend.get_chat(conversation_url, keep_open=getattr(args, "keep_open", False))
        payload = _task_messages_payload(chat)
        marker = _latest_protocol_task_marker(payload)
        marker["capture_status"] = "captured"
        marker["transcript_snapshot"] = _protocol_transcript_snapshot(payload, source="pre_ask_task_messages", envelope=None)
        return marker
    except Exception as exc:
        return {
            "available": False,
            "capture_status": "failed",
            "conversation_url": conversation_url,
            "error_type": exc.__class__.__name__,
            "error": str(exc),
        }


def _is_protocol_parse_ask(args: argparse.Namespace) -> bool:
    if getattr(args, "command", None) == "ask-release":
        return not bool(getattr(args, "no_parse_reply", False))
    return bool(getattr(args, "command", None) == "ask" and getattr(args, "protocol", False) and getattr(args, "parse_reply", False))


def _browser_response_timeout_seconds() -> float:
    """Return the browser-service assistant-response wait budget in seconds.

    The Docker service can legitimately keep the HTTP request open while the
    ChatGPT UI is still showing the assistant as running.  A lower client read
    timeout causes a premature `ReadTimeout`, even though the answer may finish
    correctly later in the UI.  Keep this default aligned with
    docker-compose.chatgpt-service.yml and allow operators to override it with
    the same environment variable used by the browser service.
    """

    raw_value = os.getenv("CHATGPT_RESPONSE_TIMEOUT_MS")
    if raw_value is None or not str(raw_value).strip():
        return DEFAULT_BROWSER_RESPONSE_TIMEOUT_SECONDS
    try:
        return max(1.0, float(raw_value) / 1000.0)
    except (TypeError, ValueError):
        return DEFAULT_BROWSER_RESPONSE_TIMEOUT_SECONDS


def _protocol_service_timeout_floor(args: argparse.Namespace) -> float:
    """Minimum HTTP read timeout for a protocol ask transaction.

    The browser service has to submit the ask, wait for the assistant response
    or service-side timeout, and return submit evidence. The client read
    timeout must therefore be larger than both the protocol response budget and
    the browser service response wait budget.  Otherwise `pb ask --protocol` /
    `pb ask-release` can fail with `service_read_timeout` while ChatGPT is still
    generating a valid answer in the UI.
    """

    protocol_timeout = max(1.0, float(getattr(args, "protocol_timeout_seconds", DEFAULT_PROTOCOL_ASK_TIMEOUT_SECONDS) or DEFAULT_PROTOCOL_ASK_TIMEOUT_SECONDS))
    fresh_turn_timeout = max(0.0, float(getattr(args, "protocol_fresh_turn_timeout_seconds", DEFAULT_PROTOCOL_FRESH_TURN_TIMEOUT_SECONDS) or 0.0))
    browser_response_timeout = _browser_response_timeout_seconds()
    buffer_seconds = max(30.0, float(DEFAULT_PROTOCOL_SERVICE_TIMEOUT_BUFFER_SECONDS))
    return max(protocol_timeout, browser_response_timeout) + fresh_turn_timeout + buffer_seconds


def _mvp_proof_timeout_budget(args: argparse.Namespace) -> dict[str, float]:
    """Return nested timeout budgets for one integrated release-candidate Ask.

    The outer lifecycle subprocess must outlive the browser response wait,
    fresh-turn correlation, attachment materialization, and a final safety
    margin. Operators keep the one-command interface; a smaller hidden/manual
    step timeout cannot truncate an otherwise valid ChatGPT generation.
    """

    browser_response_timeout = max(
        float(DEFAULT_MVP_PROOF_PROTOCOL_TIMEOUT_SECONDS),
        float(_browser_response_timeout_seconds()),
    )
    fresh_turn_timeout = float(DEFAULT_MVP_PROOF_FRESH_TURN_TIMEOUT_SECONDS)
    artifact_materialization_timeout = float(DEFAULT_MVP_PROOF_ARTIFACT_MATERIALIZATION_TIMEOUT_SECONDS)
    safety_buffer = float(DEFAULT_MVP_PROOF_STEP_TIMEOUT_BUFFER_SECONDS)
    requested_outer_timeout = max(
        0.0,
        float(getattr(args, "mvp_proof_step_timeout_seconds", 0.0) or 0.0),
    )
    required_outer_timeout = (
        browser_response_timeout
        + fresh_turn_timeout
        + artifact_materialization_timeout
        + safety_buffer
    )
    return {
        "protocol_timeout_seconds": browser_response_timeout,
        "fresh_turn_timeout_seconds": fresh_turn_timeout,
        "artifact_materialization_timeout_seconds": artifact_materialization_timeout,
        "safety_buffer_seconds": safety_buffer,
        "required_outer_timeout_seconds": required_outer_timeout,
        "requested_outer_timeout_seconds": requested_outer_timeout,
        "outer_step_timeout_seconds": max(requested_outer_timeout, required_outer_timeout),
    }


def _apply_protocol_timeout(args: argparse.Namespace) -> None:
    if not _is_protocol_parse_ask(args):
        return
    timeout = max(1.0, float(getattr(args, "protocol_timeout_seconds", DEFAULT_PROTOCOL_ASK_TIMEOUT_SECONDS) or DEFAULT_PROTOCOL_ASK_TIMEOUT_SECONDS))
    args.protocol_timeout_seconds = timeout
    if getattr(args, "service_base_url", None):
        current = float(getattr(args, "service_timeout_seconds", DEFAULT_SERVICE_TIMEOUT_SECONDS) or DEFAULT_SERVICE_TIMEOUT_SECONDS)
        args.service_timeout_seconds = max(current, _protocol_service_timeout_floor(args))



def _protocol_request_message_matches(messages: list[dict[str, Any]], envelope: dict[str, Any]) -> list[dict[str, Any]]:
    request_id = str(envelope.get("request_id") or "")
    if not request_id:
        return []
    return [message for message in messages if request_id in str(message.get("text") or "")]


def _protocol_new_user_messages(messages: list[dict[str, Any]], pre_ask_marker: dict[str, Any] | None) -> list[dict[str, Any]]:
    if not isinstance(pre_ask_marker, dict) or not pre_ask_marker.get("available"):
        return messages[-1:] if messages else []
    return [message for message in messages if _message_after_protocol_marker(message, pre_ask_marker)]


def _protocol_fresh_turn_evidence(
    payload: dict[str, Any],
    *,
    pre_ask_marker: dict[str, Any] | None,
    envelope: dict[str, Any],
    attempts: list[dict[str, Any]] | None = None,
    snapshot: dict[str, Any] | None = None,
) -> dict[str, Any]:
    messages = payload.get("messages") if isinstance(payload.get("messages"), list) else []
    request_matches = _protocol_request_message_matches(messages, envelope)
    newer_messages = _protocol_new_user_messages(messages, pre_ask_marker)
    marker_count = _protocol_turn_number(pre_ask_marker.get("message_count") if isinstance(pre_ask_marker, dict) else None) if isinstance(pre_ask_marker, dict) else None
    message_count = len(messages)
    latest_marker = _latest_protocol_task_marker(payload)
    transcript_snapshot = snapshot or _protocol_transcript_snapshot(payload, source="task_messages", envelope=envelope)
    before_snapshot = pre_ask_marker.get("transcript_snapshot") if isinstance(pre_ask_marker, dict) and isinstance(pre_ask_marker.get("transcript_snapshot"), dict) else None
    backend_refresh = _protocol_backend_refresh_summary(attempts or [], before_snapshot)
    task = envelope.get("task") if isinstance(envelope.get("task"), dict) else {}
    expected_conversation_id = _protocol_expected_conversation_id(envelope)
    actual_conversation_id = str(payload.get("conversation_id") or "")
    same_conversation_id = (not expected_conversation_id) or expected_conversation_id == actual_conversation_id
    prompt_prefix = _protocol_prompt_prefix(envelope)
    prompt_prefix_matches = [message for message in messages if prompt_prefix and prompt_prefix in str(message.get("text") or "")]
    prompt_prefix_newer_matches = [message for message in newer_messages if prompt_prefix and prompt_prefix in str(message.get("text") or "")]
    marker_available = bool(isinstance(pre_ask_marker, dict) and pre_ask_marker.get("available"))
    fresh_user_turn_visible = bool(
        same_conversation_id
        and (
            request_matches
            or newer_messages
            or prompt_prefix_newer_matches
            or ((not marker_available) and prompt_prefix_matches)
        )
    )
    return {
        "fresh_user_turn_visible": fresh_user_turn_visible,
        "request_message_found": bool(request_matches),
        "prompt_prefix_found": bool(prompt_prefix_matches),
        "prompt_prefix_fresh_message_count": len(prompt_prefix_newer_matches),
        "newer_user_message_count": len(newer_messages),
        "request_message_count": len(request_matches),
        "prompt_prefix_message_count": len(prompt_prefix_matches),
        "message_count_before": marker_count,
        "message_count_after": message_count,
        "message_count_delta": (message_count - marker_count) if marker_count is not None else None,
        "expected_conversation_id": expected_conversation_id or None,
        "actual_conversation_id": actual_conversation_id or None,
        "source_agreement": {
            "same_conversation_id": same_conversation_id,
            "expected_conversation_id": expected_conversation_id or None,
            "actual_conversation_id": actual_conversation_id or None,
        },
        "latest_marker": latest_marker,
        "backend_refresh": backend_refresh,
        "transcript_snapshot": transcript_snapshot,
        "attempt_count": len(attempts or []),
        "attempts": attempts or [],
    }

async def _wait_for_protocol_fresh_turn(
    backend: Any,
    args: argparse.Namespace,
    *,
    conversation_url: str,
    envelope: dict[str, Any],
    pre_ask_marker: dict[str, Any] | None,
) -> tuple[dict[str, Any], dict[str, Any]]:
    """Fetch/poll chat state until the protocol ask is visible as a fresh user turn."""

    timeout = max(0.0, float(getattr(args, "protocol_fresh_turn_timeout_seconds", DEFAULT_PROTOCOL_FRESH_TURN_TIMEOUT_SECONDS) or 0.0))
    poll_seconds = max(0.1, float(getattr(args, "protocol_fresh_turn_poll_seconds", DEFAULT_PROTOCOL_FRESH_TURN_POLL_SECONDS) or DEFAULT_PROTOCOL_FRESH_TURN_POLL_SECONDS))
    deadline = time.monotonic() + timeout
    attempts: list[dict[str, Any]] = []
    last_payload: dict[str, Any] | None = None
    attempt = 0
    while True:
        attempt += 1
        chat = await backend.get_chat(conversation_url, keep_open=getattr(args, "keep_open", False))
        payload = _task_messages_payload(chat)
        last_payload = payload
        before_snapshot = pre_ask_marker.get("transcript_snapshot") if isinstance(pre_ask_marker, dict) and isinstance(pre_ask_marker.get("transcript_snapshot"), dict) else None
        snapshot = _protocol_transcript_snapshot(payload, source="post_ask_task_messages", envelope=envelope)
        comparison = _compare_protocol_transcript_snapshots(before_snapshot, snapshot)
        evidence = _protocol_fresh_turn_evidence(payload, pre_ask_marker=pre_ask_marker, envelope=envelope, attempts=attempts, snapshot=snapshot)
        attempts.append({
            "attempt": attempt,
            "message_count_after": evidence.get("message_count_after"),
            "message_count_delta": evidence.get("message_count_delta"),
            "request_message_found": evidence.get("request_message_found"),
            "prompt_prefix_found": evidence.get("prompt_prefix_found"),
            "newer_user_message_count": evidence.get("newer_user_message_count"),
            "fresh_user_turn_visible": evidence.get("fresh_user_turn_visible"),
            "snapshot": snapshot,
            "snapshot_comparison": comparison,
            "latest_user_message_id": (evidence.get("latest_marker") or {}).get("latest_user_message_id") if isinstance(evidence.get("latest_marker"), dict) else None,
            "latest_user_message_index": (evidence.get("latest_marker") or {}).get("latest_user_message_index") if isinstance(evidence.get("latest_marker"), dict) else None,
            "latest_answer_id": (evidence.get("latest_marker") or {}).get("latest_answer_id") if isinstance(evidence.get("latest_marker"), dict) else None,
        })
        evidence = _protocol_fresh_turn_evidence(payload, pre_ask_marker=pre_ask_marker, envelope=envelope, attempts=attempts, snapshot=snapshot)
        if evidence["fresh_user_turn_visible"]:
            evidence["status"] = "fresh_turn_visible"
            evidence["timeout_seconds"] = timeout
            evidence["poll_seconds"] = poll_seconds
            return payload, evidence
        remaining = deadline - time.monotonic()
        if timeout <= 0.0 or remaining <= 0.0:
            evidence["status"] = "ask_submission_not_visible"
            evidence["timeout_seconds"] = timeout
            evidence["poll_seconds"] = poll_seconds
            return payload, evidence
        await asyncio.sleep(min(poll_seconds, max(0.0, remaining)))


def _protocol_ask_response_failure_result(
    args: argparse.Namespace,
    *,
    envelope: dict[str, Any],
    ask_response: dict[str, Any],
    pre_ask_marker: dict[str, Any] | None,
) -> dict[str, Any] | None:
    """Convert a service-returned ask failure into protocol-run JSON.

    v0.0.221 relies on the browser service returning partial submit evidence
    when assistant response waiting times out. Such a response is a terminal
    protocol failure, not a reply to parse.
    """

    if not isinstance(ask_response, dict) or ask_response.get("ok", True):
        return None
    status = str(ask_response.get("status") or "ask_failed")
    error = str(ask_response.get("error") or status)
    result = _protocol_failure_result(
        args,
        envelope=envelope,
        status=status,
        error=error,
        error_type=str(ask_response.get("error_type") or status),
        ask_response=ask_response,
        pre_ask_marker=pre_ask_marker,
    )
    result["partial_submit_evidence_returned"] = _protocol_ask_submit_evidence(ask_response) is not None
    result["timeout_layer"] = ask_response.get("timeout_layer") or ("assistant_response" if "timeout" in status else "service")
    if "debug_artifacts" in ask_response and isinstance(ask_response.get("debug_artifacts"), list):
        result["debug_artifacts"] = ask_response.get("debug_artifacts")
    result["operator_instruction"] = "Protocol ask reached the browser service but failed before a validated reply was available. Partial submit evidence is included when available. No artifact download, migration, adoption, or Project Source mutation was performed."
    return result


async def _parse_protocol_reply_after_ask(
    backend: Any,
    args: argparse.Namespace,
    *,
    envelope: dict[str, Any],
    ask_response: dict[str, Any],
    pre_ask_marker: dict[str, Any] | None = None,
) -> dict[str, Any]:
    expected_conversation_url = _protocol_expected_conversation_url(envelope)
    expected_conversation_id = _protocol_expected_conversation_id(envelope)
    response_conversation_id = _protocol_conversation_id_from_response(ask_response)
    lock_mismatch = _protocol_conversation_lock_mismatch(envelope, ask_response)
    state_snapshot = _state_store_from_args(args).snapshot(getattr(args, "project_url", None))
    state_conversation_url = (
        state_snapshot.get("conversation_url")
        or (state_snapshot.get("task") or {}).get("conversation_url")
        if isinstance(state_snapshot, dict)
        else None
    )
    conversation_url = str(
        expected_conversation_url
        or getattr(args, "conversation_url", None)
        or state_conversation_url
        or ask_response.get("conversation_url")
        or ""
    )
    if lock_mismatch is not None:
        result = {
            "ok": False,
            "action": "ask_protocol_run",
            "status": "submit_clicked_target_conversation_lost",
            "error": "submit_clicked_target_conversation_lost: browser/service returned a different conversation than the protocol request target; refusing to parse stale or wrong-conversation assistant text",
            "error_type": "conversation_lock_mismatch",
            "request": envelope,
            "request_baseline": _baseline_from_protocol_request(envelope),
            "ask_response": ask_response,
            "ask_submit_evidence": _protocol_ask_submit_evidence(ask_response),
            "conversation_url": conversation_url,
            "conversation_id": expected_conversation_id or None,
            "response_conversation_id": response_conversation_id or None,
            "conversation_lock": lock_mismatch,
            "answer_selection": {"policy": "conversation_locked_protocol_reply_required", "selected": None},
            "debug_artifacts": _recent_debug_artifacts(),
            "automation_performed": True,
            "download_performed": False,
            "migration_performed": False,
            "adoption_performed": False,
            "operator_instruction": "Protocol ask submit returned or followed a different conversation. The parser stayed locked to the requested conversation and refused to use returned assistant text. No artifact download, migration, adoption, or Project Source mutation was performed.",
        }
        return result
    if not conversation_url:
        return {
            "ok": False,
            "action": "ask_protocol_run",
            "status": "conversation_url_missing",
            "error": "ask response did not include a conversation_url and no current task is selected",
            "request": envelope,
            "ask_response": ask_response,
            "automation_performed": True,
            "download_performed": False,
            "migration_performed": False,
            "adoption_performed": False,
        }

    payload, fresh_turn_evidence = await _wait_for_protocol_fresh_turn(
        backend,
        args,
        conversation_url=conversation_url,
        envelope=envelope,
        pre_ask_marker=pre_ask_marker,
    )
    post_ask_marker = _latest_protocol_task_marker(payload)
    if not fresh_turn_evidence.get("fresh_user_turn_visible"):
        failure_status, failure_error, operator_instruction = _classify_protocol_submit_visibility_failure(ask_response, fresh_turn_evidence)
        return {
            "ok": False,
            "action": "ask_protocol_run",
            "status": failure_status,
            "error": failure_error,
            "request": envelope,
            "request_baseline": _baseline_from_protocol_request(envelope),
            "ask_response": ask_response,
            "ask_submit_evidence": _protocol_ask_submit_evidence(ask_response),
            "conversation_url": conversation_url,
            "conversation_id": payload.get("conversation_id"),
            "title": payload.get("title"),
            "pre_ask_marker": pre_ask_marker,
            "post_ask_marker": post_ask_marker,
            "fresh_turn_evidence": fresh_turn_evidence,
            "answer_selection": {"policy": "fresh_protocol_reply_required", "selected": None},
            "debug_artifacts": _recent_debug_artifacts(),
            "automation_performed": True,
            "download_performed": False,
            "migration_performed": False,
            "adoption_performed": False,
            "operator_instruction": operator_instruction,
        }
    try:
        message, answer, selection = _select_protocol_reply_message_answer(
            payload["messages"],
            args=args,
            envelope=envelope,
            pre_ask_marker=pre_ask_marker,
        )
    except ValueError as exc:
        status = "answer_selection_failed"
        error_text = str(exc)
        if error_text.startswith("stale_answer_detected"):
            status = "stale_answer_detected"
        elif error_text.startswith("assistant_not_detected"):
            status = "fresh_user_turn_visible_reply_timeout"
        return {
            "ok": False,
            "action": "ask_protocol_run",
            "status": status,
            "error": error_text,
            "request": envelope,
            "request_baseline": _baseline_from_protocol_request(envelope),
            "ask_response": ask_response,
            "ask_submit_evidence": _protocol_ask_submit_evidence(ask_response),
            "conversation_url": conversation_url,
            "conversation_id": payload.get("conversation_id"),
            "title": payload.get("title"),
            "pre_ask_marker": pre_ask_marker,
            "post_ask_marker": post_ask_marker,
            "fresh_turn_evidence": fresh_turn_evidence,
            "answer_selection": {"policy": "fresh_protocol_reply_required", "selected": None},
            "automation_performed": True,
            "download_performed": False,
            "migration_performed": False,
            "adoption_performed": False,
        }

    selected_answer_text = str(answer.get("text") or "")
    selected = _protocol_answer_metadata(message, answer)
    parsed = parse_promptbranch_reply(selected_answer_text)
    parsed = _with_protocol_selection_on_artifact_candidates(parsed, selected=selected)
    validation_ok, validation_errors = _validate_protocol_reply_against_request(parsed, envelope)
    status = "reply_validated" if validation_ok else "reply_validation_failed"
    normalized_ask_response = _normalize_protocol_ask_response_for_selected_reply(
        ask_response,
        selected_answer_text=selected_answer_text,
        selected_answer=answer,
        validation_ok=validation_ok,
    )
    result = {
        **parsed,
        "ok": bool(parsed.get("ok") and validation_ok),
        "action": "ask_protocol_run",
        "status": status,
        "request": envelope,
        "request_baseline": _baseline_from_protocol_request(envelope),
        "reply_validation_ok": validation_ok,
        "reply_validation_errors": validation_errors,
        "ask_response": normalized_ask_response,
        "ask_submit_evidence": _protocol_ask_submit_evidence(ask_response),
        "conversation_url": payload.get("conversation_url") or conversation_url,
        "conversation_id": payload.get("conversation_id"),
        "title": payload.get("title"),
        "message": {key: value for key, value in message.items() if key != "answers"},
        "answer": {key: value for key, value in answer.items() if key != "text"},
        "selected_answer": selected,
        "selected_request_id": parsed.get("request_id"),
        "selected_message_id": selected.get("message_id"),
        "selected_answer_id": selected.get("answer_id"),
        "selected_protocol_reply": _protocol_selection_summary(
            request_id=parsed.get("request_id"),
            correlation_id=parsed.get("correlation_id"),
            message=message,
            answer=answer,
            conversation_id=payload.get("conversation_id"),
            conversation_url=payload.get("conversation_url") or conversation_url,
        ),
        "answer_selection": {**selection, "selected": selected},
        "pre_ask_marker": pre_ask_marker,
        "post_ask_marker": post_ask_marker,
        "fresh_turn_evidence": fresh_turn_evidence,
        "answer_text_length": len(str(answer.get("text") or "")),
        "automation_performed": True,
        "download_performed": False,
        "migration_performed": False,
        "adoption_performed": False,
        "operator_instruction": "Protocol ask was sent and the latest reply was parsed/validated only. No artifact download, migration, adoption, or Project Source mutation was performed.",
    }
    return result



def _normalize_protocol_ask_response_for_selected_reply(
    ask_response: dict[str, Any] | None,
    *,
    selected_answer_text: str,
    selected_answer: dict[str, Any] | None,
    validation_ok: bool,
) -> dict[str, Any] | None:
    """Keep browser-stream text diagnostic and prevent stale answer misuse.

    The service/browser ``ask_response.answer`` field may contain an
    intermediate stream value such as "Thinking ... Streaming interrupted"
    even when protocol parsing succeeds from the authoritative task transcript.
    Protocol automation must not treat that browser stream value as the final
    answer source.
    """

    if not isinstance(ask_response, dict):
        return ask_response
    normalized = copy.deepcopy(ask_response)
    raw_answer = normalized.get("answer")
    raw_answer_text = raw_answer if isinstance(raw_answer, str) else (json.dumps(raw_answer, ensure_ascii=False) if raw_answer is not None else "")
    selected_text = str(selected_answer_text or "")
    normalized["answer"] = None
    normalized["answer_source"] = "protocol_reply_authoritative" if validation_ok else "protocol_reply_candidate"
    normalized["authoritative_reply_location"] = "reply" if validation_ok else "selected_answer"
    normalized["answer_suppressed_reason"] = "browser_stream_answer_may_be_intermediate; use top-level reply and reply_validation_ok for protocol automation"
    normalized["raw_browser_answer_preview"] = raw_answer_text[:500] if raw_answer_text else ""
    normalized["raw_browser_answer_length"] = len(raw_answer_text)
    normalized["raw_browser_answer_complete"] = bool(raw_answer_text and raw_answer_text.strip() == selected_text.strip())
    normalized["selected_answer_source"] = "task_messages"
    normalized["selected_answer_text_length"] = len(selected_text)
    if isinstance(selected_answer, dict):
        normalized["selected_answer_id"] = selected_answer.get("id")
        normalized["selected_answer_index"] = selected_answer.get("index")
        normalized["selected_answer_turn_index"] = selected_answer.get("turn_index")
    return normalized



def _with_protocol_selection_on_artifact_candidates(parsed: dict[str, Any], *, selected: dict[str, Any] | None, request_id: Any = None, correlation_id: Any = None) -> dict[str, Any]:
    """Attach deterministic request/message/answer identity to parsed candidates."""

    if not isinstance(parsed, dict):
        return parsed
    enriched = copy.deepcopy(parsed)
    selected = selected if isinstance(selected, dict) else {}
    request_id_value = request_id or enriched.get("request_id")
    correlation_id_value = correlation_id or enriched.get("correlation_id")
    if not enriched.get("answer_id") and selected.get("answer_id"):
        enriched["answer_id"] = selected.get("answer_id")
    candidates = enriched.get("artifact_candidates") if isinstance(enriched.get("artifact_candidates"), list) else []
    next_candidates: list[dict[str, Any]] = []
    for candidate in candidates:
        if not isinstance(candidate, dict):
            next_candidates.append(candidate)
            continue
        item = copy.deepcopy(candidate)
        source = item.get("source") if isinstance(item.get("source"), dict) else {}
        source = dict(source)
        if not source.get("request_id"):
            source["request_id"] = request_id_value
        if not source.get("correlation_id"):
            source["correlation_id"] = correlation_id_value
        if not source.get("message_id"):
            source["message_id"] = selected.get("message_id")
        if not source.get("message_index"):
            source["message_index"] = selected.get("message_index")
        if not source.get("message_turn_index"):
            source["message_turn_index"] = selected.get("message_turn_index")
        if not source.get("answer_id"):
            source["answer_id"] = selected.get("answer_id")
        if not source.get("answer_index"):
            source["answer_index"] = selected.get("answer_index")
        if not source.get("answer_turn_index"):
            source["answer_turn_index"] = selected.get("answer_turn_index")
        item["source"] = source
        next_candidates.append(item)
    enriched["artifact_candidates"] = next_candidates
    return enriched

def _repo_name_from_artifact_name(filename: str) -> str | None:
    name = Path(filename).name
    if name.endswith(".zip"):
        name = name[:-4]
    match = re.search(r"_?v?\d+\.\d+\.\d+(?:\.\d+)?$", name)
    if not match:
        return None
    return name[: match.start()].rstrip("_.-") or None




def _normalize_version_token(value: str | None) -> str | None:
    if value is None:
        return None
    text = str(value).strip()
    if not text:
        return None
    return text if text.startswith("v") else f"v{text}"


def _ask_release_expected_from_envelope(envelope: dict[str, Any], args: argparse.Namespace) -> dict[str, Any]:
    artifact = envelope.get("artifact") if isinstance(envelope.get("artifact"), dict) else {}
    expected_repo = str(getattr(args, "expect_repo", None) or artifact.get("repo") or "").strip() or None
    expected_version = _normalize_version_token(getattr(args, "expect_version", None) or artifact.get("target_version"))
    expected_artifact = str(getattr(args, "expect_artifact", None) or "").strip() or None
    if expected_artifact:
        expected_artifact = Path(expected_artifact).name
    elif expected_repo and expected_version:
        expected_artifact = _candidate_expected_filename(expected_repo, expected_version)
    return {
        "expected_repo": expected_repo,
        "expected_version": expected_version,
        "expected_artifact": expected_artifact,
        "expected_role": "candidate_release",
        "exact_artifact_count": 1,
    }


def _augment_release_candidate_request(envelope: dict[str, Any], expected: dict[str, Any]) -> dict[str, Any]:
    enriched = copy.deepcopy(envelope)
    task = enriched.setdefault("task", {})
    if isinstance(task, dict):
        task["turn_policy"] = "assistant_must_return_one_zip_attachment_and_one_protocol_reply"
    artifact = enriched.setdefault("artifact", {})
    if isinstance(artifact, dict):
        if expected.get("expected_repo") and not artifact.get("repo"):
            artifact["repo"] = expected.get("expected_repo")
        if expected.get("expected_version") and not artifact.get("target_version"):
            artifact["target_version"] = expected.get("expected_version")
        artifact["expected_output_artifact"] = expected.get("expected_artifact")
        artifact["expected_output_version"] = expected.get("expected_version")
        artifact["expected_artifact_role"] = expected.get("expected_role")
        artifact["artifact_count_policy"] = "exactly_one_expected_zip_candidate"
        artifact["no_artifact_reply_allowed"] = False
        artifact["download_policy"] = "rendered_chatgpt_attachment_or_clickable_download_link_required"
    constraints = enriched.setdefault("constraints", {})
    if isinstance(constraints, dict):
        constraints["exactly_one_zip_artifact_required"] = True
        constraints["expected_output_artifact_required"] = True
        constraints["fresh_artifact_for_request_required"] = True
        constraints["attachment_outside_envelope_required"] = True
        constraints["json_only_artifact_declaration_forbidden"] = True
        constraints["no_artifact_reply_allowed"] = False
        constraints["no_auto_adopt"] = True
    enriched["expected_output"] = {
        "success_component_count": 2,
        "success_components_in_order": [
            {
                "component": 1,
                "type": "rendered_chatgpt_downloadable_zip",
                "count": 1,
                "filename": expected.get("expected_artifact"),
                "rendered_outside_envelope": True,
                "required": True,
            },
            {
                "component": 2,
                "type": "promptbranch_reply_envelope",
                "count": 1,
                "begin_marker": BEGIN_REPLY_MARKER,
                "end_marker": END_REPLY_MARKER,
                "required": True,
            },
        ],
        "failure_component_count": 1,
        "failure_component": {
            "type": "failed_promptbranch_reply_envelope",
            "artifact_count": 0,
        },
        "other_output_allowed": False,
    }
    expected_reply = enriched.setdefault("expected_reply", {})
    if isinstance(expected_reply, dict):
        expected_reply["required_top_level_keys"] = [
            "schema", "schema_version", "request_id", "correlation_id",
            "status", "result_type", "summary", "baseline", "changes",
            "artifacts", "validation", "next_step", "confidence",
        ]
        expected_reply["result_type_required"] = "release_candidate"
        expected_reply["artifact_policy"] = {
            "exact_count": 1,
            "expected_filename": expected.get("expected_artifact"),
            "expected_version": expected.get("expected_version"),
            "expected_role": expected.get("expected_role"),
            "physical_creation_required": True,
            "rendered_attachment_required": True,
            "rendered_outside_envelope_required": True,
            "download_available_required": True,
            "json_only_declaration_forbidden": True,
        }
    decisions = enriched.setdefault("protocol_decisions", {})
    if isinstance(decisions, dict):
        decisions["reply_envelope_count"] = 1
        decisions["zip_attachment_required"] = True
        decisions["zip_attachment_count"] = 1
        decisions["zip_attachment_outside_envelope"] = True
        decisions["successful_response_component_count"] = 2
        decisions["failed_response_component_count"] = 1
        decisions["artifact_url_policy"] = "rendered_attachment_and_envelope_metadata_must_identify_same_file"
        decisions["download_policy"] = "rendered_chatgpt_attachment_or_clickable_download_link"
        decisions["no_artifact_reply_allowed"] = False
        decisions["release_candidate_artifact_required"] = True
        decisions["candidate_run_next_step_required"] = True
    return enriched


def _build_zip_artifact_user_prompt(
    *,
    request_label: str,
    expected_artifact: Any,
    baseline: Any,
    current_version: Any,
    target_version: Any,
    result_type: str,
    expected_role: str,
    prompt_text: str,
    artifact_version_required: bool = True,
    no_change_disallowed: bool = True,
    forbidden_claims: str | None = None,
    execution_requirements: str | None = None,
) -> str:
    """Build the canonical user prompt for requests that must create a ZIP.

    Release-candidate asks and live visual artifact tests both depend on the
    same prompt contract shape: state the expected ZIP, state the baseline or
    test context, then provide the concrete implementation scope.  Keeping this
    text generation in one helper prevents test fixtures from drifting away from
    production prompt wording.
    """

    role_clause = f"role {expected_role}"
    if artifact_version_required:
        artifact_rule = (
            "The reply envelope artifacts array MUST contain exactly one ZIP candidate "
            f"with the expected filename, version, {role_clause}, and a real downloadable ChatGPT attachment/link. "
        )
    else:
        artifact_rule = (
            "The reply envelope artifacts array MUST contain exactly one ZIP candidate "
            f"with the expected filename, {role_clause}, and a real downloadable ChatGPT attachment/link. "
        )

    status_rule = f"The reply envelope MUST use status completed and result_type {result_type}. "
    no_change_rule = (
        "Do not return status no_artifact or result_type no_change for this command. "
        if no_change_disallowed
        else ""
    )
    forbidden_claims_rule = f"{forbidden_claims.strip()} " if forbidden_claims else ""
    execution_requirements_block = str(execution_requirements or "").strip()
    prompt_body = str(prompt_text or "").strip()
    display_baseline = "none" if baseline is None else str(baseline)
    display_current_version = "none" if current_version is None else str(current_version)
    display_target_version = "none" if target_version is None else str(target_version)
    schema_contract = (
        "The reply envelope JSON MUST include all required top-level keys: "
        "schema, schema_version, request_id, correlation_id, status, result_type, summary, "
        "baseline, changes, artifacts, validation, next_step, confidence. "
        "schema MUST be exactly promptbranch.ask.reply. "
        "schema_version MUST be exactly 1.0. "
        "summary MUST be a non-empty string. "
        "next_step MUST be an object with operator_action and recommended_command. "
        "If you cannot create the real downloadable ZIP or cannot produce every required envelope field, "
        "return status failed with result_type "
        f"{result_type}, artifacts as an empty array, and a failure summary instead of a success claim. "
    )
    prompt_header = (
        f"{request_label}. Create exactly one ZIP artifact named {expected_artifact}.\n"
        f"Input baseline: {display_baseline}\n"
        f"Input version: {display_current_version}\n"
        f"Target version: {display_target_version}\n"
        f"{status_rule}"
        f"{artifact_rule}"
        f"{schema_contract}"
        f"{no_change_rule}"
        f"{forbidden_claims_rule}\n\n"
    )
    if execution_requirements_block:
        prompt_header += f"{execution_requirements_block}\n\n"
    return prompt_header + (
        "Requested implementation scope:\n"
        f"{prompt_body}"
    )


def _build_ask_release_user_prompt(base_prompt: str, expected: dict[str, Any], envelope: dict[str, Any]) -> str:
    artifact = envelope.get("artifact") if isinstance(envelope.get("artifact"), dict) else {}
    baseline = artifact.get("current_baseline")
    current_version = artifact.get("current_version")
    target_version = expected.get("expected_version") or artifact.get("target_version")
    expected_artifact = expected.get("expected_artifact")
    request_id = envelope.get("request_id")
    release_type = artifact.get("release_type") or "normal"
    prompt_text = str(base_prompt or "").strip() or (
        f"Create {expected_artifact} from accepted baseline {baseline} for target {target_version}."
    )
    return (
        f"Create exactly one new ZIP artifact named:\n\n{expected_artifact}\n\n"
        f"Input baseline:\n\n{baseline}\n\n"
        f"Input version:\n\n{current_version}\n\n"
        f"Target version:\n\n{target_version}\n\n"
        f"Release type:\n\n{release_type}\n\n"
        "Requested implementation scope:\n\n"
        f"1. Use the exact accepted/current release ZIP {baseline} as the actual source baseline.\n\n"
        "2. Extract or otherwise inspect that exact baseline ZIP.\n\n"
        "3. Create a fresh working copy derived from that baseline.\n\n"
        "4. Apply the requested target-version changes consistently across all authoritative version, package, "
        "release-contract, control-surface, documentation, and test locations required by the repository. The "
        f"requested scope is: {prompt_text}\n\n"
        "5. Preserve complete repository contents.\n\n"
        "6. Package repository contents directly at ZIP root.\n\n"
        "7. Do not include a wrapper directory.\n\n"
        "8. Do not include nested ZIP files.\n\n"
        "9. Do not include cache files, Python bytecode, temporary files, or unsafe paths.\n\n"
        f"10. Do not reuse, rename, copy, or reference a {target_version} ZIP created for an earlier answer, "
        "earlier request, Retry, or failed lifecycle attempt.\n\n"
        f"11. Create a brand-new physical ZIP specifically for request:\n\n{request_id}\n\n"
        "12. Create the physical ZIP before beginning the final response.\n\n"
        "13. Validate the actual created ZIP before replying:\n"
        "    - exact filename;\n"
        f"    - embedded version {target_version};\n"
        "    - ZIP CRC;\n"
        "    - repository-root layout;\n"
        "    - no wrapper directory;\n"
        "    - no nested ZIP files;\n"
        "    - no cache files;\n"
        "    - no unsafe paths;\n"
        "    - actual SHA-256;\n"
        "    - actual byte size;\n"
        "    - actual ZIP entry count.\n\n"
        "14. Expose the created ZIP as Component 1 of the final response using a real rendered ChatGPT attachment "
        "or clickable download link outside the JSON envelope.\n\n"
        "15. Only after Component 1 is present, construct Component 2 using metadata observed from that exact "
        "physical ZIP.\n\n"
        "16. The artifact object in the reply envelope must contain:\n"
        "    - filename;\n"
        "    - version;\n"
        "    - role;\n"
        "    - media_type;\n"
        "    - actual size_bytes;\n"
        "    - actual sha256;\n"
        "    - actual entry_count;\n"
        "    - download_available=true;\n"
        "    - download_url matching the rendered attachment or link.\n\n"
        "17. Do not set status=\"completed\" unless the physical ZIP has been created and exposed as "
        "Component 1 in the same assistant response.\n\n"
        "18. Do not claim adoption, accepted/current advancement, Project Source mutation, Git commit, or Git push.\n\n"
        "19. When the ZIP cannot be physically created or exposed, return the defined failed envelope with "
        "artifacts=[]."
    )



def _ask_release_candidate_for_browser_intake(
    result: dict[str, Any],
    expected: dict[str, Any],
) -> dict[str, Any] | None:
    """Build one deterministic intake candidate from the validated reply.

    This preserves the raw envelope metadata while attaching the exact
    request/message/answer identity selected by the protocol parser.  It does
    not treat the JSON sandbox URL as proof; the browser download step must
    provide that proof.
    """

    reply = result.get("reply") if isinstance(result.get("reply"), dict) else {}
    artifacts = reply.get("artifacts") if isinstance(reply.get("artifacts"), list) else []
    if len(artifacts) != 1 or not isinstance(artifacts[0], dict):
        return None
    raw = copy.deepcopy(artifacts[0])
    filename = Path(str(raw.get("filename") or raw.get("name") or "")).name
    if not filename or filename != str(raw.get("filename") or raw.get("name") or ""):
        return None
    download = raw.get("download") if isinstance(raw.get("download"), dict) else {}
    url = _selected_candidate_download_url(raw)
    selected = result.get("selected_answer") if isinstance(result.get("selected_answer"), dict) else {}
    selection = _protocol_selection_summary(
        request_id=result.get("request_id"),
        correlation_id=result.get("correlation_id"),
        message=result.get("message") if isinstance(result.get("message"), dict) else None,
        answer=result.get("answer") if isinstance(result.get("answer"), dict) else None,
        conversation_id=result.get("conversation_id"),
        conversation_url=result.get("conversation_url"),
    )
    if selected:
        selection.update({key: value for key, value in selected.items() if value is not None})
    return {
        "kind": raw.get("kind") or "zip",
        "filename": filename,
        "version": raw.get("version"),
        "role": raw.get("role"),
        "download": {
            "available": bool(download.get("available") or raw.get("download_available") or url),
            "url": url,
            "link_text": download.get("link_text") or raw.get("link_text") or filename,
            "requires_browser_context": bool(
                download.get("requires_browser_context")
                or (_artifact_download_transport(url).get("requires_browser_context"))
            ),
        },
        "source": {
            "request_id": result.get("request_id"),
            "correlation_id": result.get("correlation_id"),
            "message_id": selection.get("message_id"),
            "answer_id": selection.get("answer_id"),
            "answer_turn_index": selection.get("answer_turn_index"),
        },
        "expected_sha256": raw.get("sha256"),
        "expected_size_bytes": raw.get("size_bytes"),
        "expected_entry_count": raw.get("entry_count"),
        "expected_version": expected.get("expected_version"),
        "raw": raw,
        "selected_protocol_reply": selection,
    }


def _ask_release_envelope_metadata_check(
    candidate: dict[str, Any],
    verified: dict[str, Any],
) -> dict[str, Any]:
    actual_file = verified.get("download") if isinstance(verified.get("download"), dict) else {}
    verification = verified.get("verification") if isinstance(verified.get("verification"), dict) else {}
    expected_values = {
        "sha256": candidate.get("expected_sha256"),
        "size_bytes": candidate.get("expected_size_bytes"),
        "entry_count": candidate.get("expected_entry_count"),
    }
    actual_values = {
        "sha256": actual_file.get("sha256"),
        "size_bytes": actual_file.get("size_bytes"),
        "entry_count": verification.get("entry_count"),
    }
    missing = [key for key, value in expected_values.items() if value in {None, ""}]
    mismatches: list[str] = []
    for key in ("sha256", "size_bytes", "entry_count"):
        if key in missing:
            continue
        expected_value = expected_values[key]
        actual_value = actual_values[key]
        if key in {"size_bytes", "entry_count"}:
            try:
                expected_value = int(expected_value)
                actual_value = int(actual_value)
            except (TypeError, ValueError):
                mismatches.append(key)
                continue
        else:
            expected_value = str(expected_value).strip().lower()
            actual_value = str(actual_value or "").strip().lower()
        if expected_value != actual_value:
            mismatches.append(key)
    return {
        "ok": not missing and not mismatches,
        "status": "envelope_artifact_metadata_verified" if not missing and not mismatches else (
            "envelope_artifact_metadata_missing" if missing else "envelope_artifact_metadata_mismatch"
        ),
        "expected": expected_values,
        "actual": actual_values,
        "missing": missing,
        "mismatches": mismatches,
    }


async def _materialize_ask_release_rendered_candidate(
    backend: Any,
    args: argparse.Namespace,
    result: dict[str, Any],
    expected: dict[str, Any],
) -> dict[str, Any]:
    """Detect, download and verify the rendered candidate in the exact answer.

    The operation is intentionally inbox-only. It never migrates the candidate,
    adopts a release, mutates Project Sources, commits, or pushes.
    """

    candidate = _ask_release_candidate_for_browser_intake(result, expected)
    if candidate is None:
        return {
            **result,
            "artifact_materialization_attempted": False,
            "artifact_materialization_proven": False,
        }
    url = _selected_candidate_download_url(candidate)
    transport = _artifact_download_transport(url)
    if transport.get("scheme") != "sandbox":
        return {
            **result,
            "artifact_materialization_attempted": False,
            "artifact_materialization_proven": bool(transport.get("direct_download_supported")),
        }

    selection = candidate.get("selected_protocol_reply") if isinstance(candidate.get("selected_protocol_reply"), dict) else {}
    intake = {
        "ok": True,
        "status": "candidate_selected",
        "action": "artifact_intake",
        "selected_candidate": candidate,
        "artifact_candidate_count": 1,
        "reply_request_id": result.get("request_id"),
        "reply_correlation_id": result.get("correlation_id"),
        "conversation_url": result.get("conversation_url"),
        "conversation_id": result.get("conversation_id"),
        "selected_message_id": selection.get("message_id"),
        "selected_answer_id": selection.get("answer_id"),
        "selected_protocol_reply": selection,
        "expected_version": expected.get("expected_version"),
        "download_performed": False,
        "verification_performed": False,
        "migration_performed": False,
        "adoption_performed": False,
    }
    downloaded = await _download_selected_artifact_candidate_via_browser(
        backend,
        intake,
        profile_dir=getattr(args, "profile_dir", None) or PROFILE_DIR_NAME,
        conversation_id=result.get("conversation_id"),
        answer_id=selection.get("answer_id"),
        timeout_seconds=float(getattr(args, "artifact_materialization_timeout_seconds", 180.0) or 180.0),
        keep_open=bool(getattr(args, "keep_open", False)),
    )
    if not downloaded.get("ok") or downloaded.get("download_performed") is not True:
        return {
            **result,
            "artifact_materialization_attempted": True,
            "artifact_materialization_proven": False,
            "download_performed": False,
            "browser_download_performed": False,
            "verification_performed": False,
            "materialization": downloaded,
            "materialization_status": downloaded.get("status"),
            "manual_import_required": True,
        }

    verified = _verify_intake_artifact_candidate(
        downloaded,
        profile_dir=getattr(args, "profile_dir", None) or PROFILE_DIR_NAME,
        conversation_id=result.get("conversation_id"),
        answer_id=selection.get("answer_id"),
    )
    metadata_check = _ask_release_envelope_metadata_check(candidate, verified)
    if not verified.get("ok") or verified.get("verification_performed") is not True or not metadata_check.get("ok"):
        return {
            **result,
            "artifact_materialization_attempted": True,
            "artifact_materialization_proven": False,
            "download_performed": bool(downloaded.get("download_performed")),
            "browser_download_performed": bool(downloaded.get("browser_download_performed")),
            "verification_performed": bool(verified.get("verification_performed")),
            "materialization": verified,
            "materialization_status": verified.get("status"),
            "envelope_metadata_verification": metadata_check,
            "envelope_metadata_verified": False,
            "manual_import_required": False,
        }

    enriched = copy.deepcopy(result)
    reply = enriched.get("reply") if isinstance(enriched.get("reply"), dict) else {}
    artifacts = reply.get("artifacts") if isinstance(reply.get("artifacts"), list) else []
    if len(artifacts) == 1 and isinstance(artifacts[0], dict):
        raw = copy.deepcopy(artifacts[0])
        download = raw.get("download") if isinstance(raw.get("download"), dict) else {}
        browser_result = (
            downloaded.get("download_transport", {}).get("browser_result")
            if isinstance(downloaded.get("download_transport"), dict)
            else {}
        )
        download = {
            **download,
            "available": True,
            "url": _selected_candidate_download_url(raw) or url,
            "link_text": download.get("link_text") or raw.get("link_text") or candidate.get("filename"),
            "attachment_detected": True,
            "attachment_proven": True,
            "ui_attachment": True,
            "file_id": browser_result.get("file_id") if isinstance(browser_result, dict) else None,
            "rendered_control_kind": browser_result.get("control_kind") if isinstance(browser_result, dict) else None,
            "correlation_mode": browser_result.get("correlation_mode") if isinstance(browser_result, dict) else None,
            "correlated_answer_id": selection.get("answer_id"),
            "correlated_request_id": result.get("request_id"),
        }
        raw["download"] = download
        artifacts[0] = raw
        reply["artifacts"] = artifacts
        enriched["reply"] = reply

    return {
        **enriched,
        "artifact_materialization_attempted": True,
        "artifact_materialization_proven": True,
        "download_performed": True,
        "browser_download_performed": True,
        "verification_performed": True,
        "envelope_metadata_verification": metadata_check,
        "envelope_metadata_verified": True,
        "materialization": verified,
        "materialization_status": "chatgpt_rendered_attachment_downloaded_verified",
        "download": verified.get("download"),
        "download_transport": downloaded.get("download_transport"),
        "artifact_inbox_dir": verified.get("artifact_inbox_dir"),
        "manual_import_required": False,
        "migration_performed": False,
        "adoption_performed": False,
    }

def _validate_ask_release_candidate_result(result: dict[str, Any], expected: dict[str, Any]) -> dict[str, Any]:
    validated = copy.deepcopy(result)
    checks: dict[str, Any] = {
        "reply_validated": bool(validated.get("ok") is True and validated.get("reply_validation_ok") is True),
        "expected_artifact": expected.get("expected_artifact"),
        "expected_version": expected.get("expected_version"),
        "exact_artifact_count": False,
        "filename_matches": False,
        "version_matches": False,
        "role_matches": False,
        "download_claimed": False,
        "download_available": False,
        "download_proof": False,
        "download_proof_status": "artifact_candidate_missing",
        "status_release_candidate": False,
    }
    reply = validated.get("reply") if isinstance(validated.get("reply"), dict) else {}
    artifacts = reply.get("artifacts") if isinstance(reply.get("artifacts"), list) else []
    checks["artifact_count"] = len(artifacts)
    checks["exact_artifact_count"] = len(artifacts) == 1
    checks["status_release_candidate"] = reply.get("status") == "completed" and reply.get("result_type") == "release_candidate"
    download_proof: dict[str, Any] = _release_candidate_download_proof(None)
    if len(artifacts) == 1 and isinstance(artifacts[0], dict):
        candidate = artifacts[0]
        checks["filename_matches"] = Path(str(candidate.get("filename") or candidate.get("name") or "")).name == expected.get("expected_artifact")
        checks["version_matches"] = _normalize_version_token(candidate.get("version")) == expected.get("expected_version")
        checks["role_matches"] = candidate.get("role") == expected.get("expected_role")
        download_proof = _release_candidate_download_proof(candidate)
        checks["download_claimed"] = bool(download_proof.get("claim_available"))
        checks["download_available"] = bool(download_proof.get("ok"))
        checks["download_proof"] = bool(download_proof.get("ok"))
        checks["download_proof_status"] = download_proof.get("status")
        checks["download_direct_supported"] = bool(download_proof.get("direct_download_supported"))
        checks["download_attachment_proven"] = bool(download_proof.get("attachment_proven"))
        checks["download_json_only_declared"] = bool(download_proof.get("json_only_declared"))
        checks["download_url"] = download_proof.get("url")
    checks["artifact_materialization_attempted"] = bool(validated.get("artifact_materialization_attempted"))
    checks["artifact_materialization_proven"] = bool(validated.get("artifact_materialization_proven"))
    checks["browser_download_performed"] = bool(validated.get("browser_download_performed"))
    checks["verification_performed"] = bool(validated.get("verification_performed"))
    checks["envelope_metadata_verified"] = bool(validated.get("envelope_metadata_verified"))
    checks["materialization_status"] = validated.get("materialization_status")
    required = {"reply_validated", "exact_artifact_count", "filename_matches", "version_matches", "role_matches", "download_proof", "status_release_candidate"}
    failures = [name for name, ok in checks.items() if name in required and not ok]
    if "download_proof" in failures and download_proof.get("failure"):
        failures.append(str(download_proof.get("failure")))
    failures = list(dict.fromkeys(failures))
    validated["ask_release_validation"] = {
        "ok": not failures,
        "failures": failures,
        "checks": checks,
        "download_proof": download_proof,
        "operator_instruction": "Run `pb artifact candidate-run --execute-until-blocked --require-complete --require-real-candidate --json` only after ask-release validation is green.",
    }
    validated["expected_artifact"] = expected.get("expected_artifact")
    validated["expected_version"] = expected.get("expected_version")
    validated["candidate_producing_protocol_flow"] = True
    if failures:
        validated["ok"] = False
        metadata_check = validated.get("envelope_metadata_verification") if isinstance(validated.get("envelope_metadata_verification"), dict) else {}
        materialization_status = str(validated.get("materialization_status") or "")
        if metadata_check and metadata_check.get("ok") is False:
            validated["status"] = str(metadata_check.get("status") or "envelope_artifact_metadata_mismatch")
            validated["artifact_materialization_proven"] = False
            validated["manual_import_required"] = False
            validated["operator_instruction"] = "The rendered ZIP was downloaded, but its observed SHA-256, byte size, or ZIP entry count did not match the exact reply envelope. The candidate was rejected fail-closed."
        elif materialization_status and materialization_status not in {"chatgpt_rendered_attachment_downloaded_verified"}:
            validated["status"] = materialization_status
            validated["artifact_materialization_proven"] = False
            validated["manual_import_required"] = bool(validated.get("manual_import_required", True))
            validated["operator_instruction"] = "The exact correlated assistant turn did not yield one downloaded and verified rendered ZIP attachment. The candidate was rejected fail-closed."
        elif download_proof.get("status") == "artifact_declared_but_not_attached":
            validated["status"] = "artifact_declared_but_not_attached"
            validated["artifact_materialization_proven"] = False
            validated["manual_import_required"] = True
            validated["operator_instruction"] = "The protocol reply declared a ZIP in JSON only. No real direct-download URL or verified ChatGPT attachment was proven; create/download the ZIP through the UI or rerun after a real attachment is available."
        else:
            validated["status"] = "release_candidate_validation_failed"
        validated["reply_validation_ok"] = False
        errors = list(validated.get("reply_validation_errors") or [])
        errors.extend(f"ask_release:{failure}" for failure in failures)
        validated["reply_validation_errors"] = errors
        validated["error"] = "release-candidate protocol reply did not contain exactly one expected materialized downloadable ZIP candidate"
    else:
        validated["status"] = "reply_validated"
        validated["reply_validation_ok"] = True
        validated["artifact_materialization_proven"] = True
        if validated.get("browser_download_performed") and validated.get("verification_performed"):
            validated["download_proof_status"] = "chatgpt_rendered_attachment_downloaded_verified"
        validated["operator_instruction"] = "Validated exactly one expected release-candidate ZIP with host-verifiable download proof. Next run strict candidate-run with --require-real-candidate."
    return validated


async def cmd_ask_release(backend: CommandBackend, args: argparse.Namespace) -> int:
    attachment_paths = _collect_ask_attachment_paths(args)
    try:
        raw_prompt = _merge_prompt_text(getattr(args, "prompt", None), getattr(args, "prompt_file", None))
    except (OSError, UnicodeError) as exc:
        print(f"error: could not read prompt file: {exc}", file=sys.stderr)
        return 2

    args.protocol = True
    args.intent_kind = "software_release_candidate_request"
    protocol_payload = _protocol_request_from_current_baseline(backend, args, prompt=raw_prompt or "release candidate request")
    if protocol_payload.get("ok") is not True:
        print(json.dumps(protocol_payload, indent=2, ensure_ascii=False)); return 2
    expected = _ask_release_expected_from_envelope(protocol_payload["request"], args)
    if not expected.get("expected_artifact") or not expected.get("expected_version"):
        payload = {
            "ok": False,
            "action": "ask_release",
            "status": "expected_artifact_unresolved",
            "error": "ask-release requires a resolvable repo and target version; pass --target-version and ensure pb artifact current is set, or pass --expect-artifact/--expect-version/--expect-repo",
            "expected": expected,
            "request": protocol_payload.get("request"),
        }
        print(json.dumps(payload, indent=2, ensure_ascii=False))
        return 2

    envelope = _augment_release_candidate_request(protocol_payload["request"], expected)
    protocol_payload["request"] = envelope
    protocol_payload["action"] = "ask_release"
    protocol_payload["expected"] = expected
    protocol_payload["candidate_producing_protocol_flow"] = True
    protocol_payload["strict_real_candidate_required"] = True
    if getattr(args, "print_request_json", False):
        print(json.dumps(protocol_payload, indent=2, ensure_ascii=False))
        return 0

    release_prompt = _build_ask_release_user_prompt(raw_prompt, expected, envelope)
    prompt = render_release_candidate_artifact_prompt(envelope, user_prompt=release_prompt)
    for attachment_path in attachment_paths:
        if not Path(attachment_path).is_file():
            print(f"error: attachment file not found: {attachment_path}", file=sys.stderr)
            return 2
    legacy_single_file = args.file if args.file and not getattr(args, "attachments", None) else None
    repeatable_attachments = attachment_paths if not legacy_single_file else None
    parse_reply = not bool(getattr(args, "no_parse_reply", False))
    pre_ask_marker = await _capture_pre_ask_protocol_marker(backend, args) if parse_reply else None
    try:
        response = await backend.ask(
            prompt=prompt,
            file_path=legacy_single_file,
            attachment_paths=repeatable_attachments,
            conversation_url=args.conversation_url,
            expect_json=False,
            keep_open=args.keep_open,
            retries=args.retries,
            prefer_button_submit=bool(getattr(args, "prompt_file", None)),
        )
    except Exception as exc:
        if parse_reply:
            lowered = f"{exc.__class__.__name__}: {exc}".lower()
            status = "service_read_timeout" if exc.__class__.__name__ in {"ReadTimeout", "TimeoutException"} else ("response_timeout" if "timeout" in lowered or "timed out" in lowered else "ask_failed")
            recovery_diagnostic: dict[str, Any] | None = None
            if status == "service_read_timeout":
                recovered, recovery_diagnostic = await _recover_protocol_reply_after_service_timeout(
                    backend,
                    args,
                    envelope=envelope,
                    error=str(exc),
                    error_type=exc.__class__.__name__,
                    pre_ask_marker=pre_ask_marker,
                )
                if recovered is not None:
                    recovered = await _materialize_ask_release_rendered_candidate(backend, args, recovered, expected)
                    recovered = _validate_ask_release_candidate_result(recovered, expected)
                    return _emit_protocol_result(args, recovered)
            result = _protocol_failure_result(
                args,
                envelope=envelope,
                status=status,
                error=str(exc),
                error_type=exc.__class__.__name__,
                pre_ask_marker=pre_ask_marker,
            )
            result["action"] = "ask_release"
            result["expected"] = expected
            if status == "service_read_timeout":
                result["timeout_layer"] = "service_client"
                result["service_timeout_recovery"] = recovery_diagnostic or {"attempted": False}
            return _emit_protocol_result(args, result)
        raise

    if not parse_reply:
        payload = {
            **protocol_payload,
            "ok": True,
            "status": "submitted_without_parse",
            "ask_response": response,
            "automation_performed": True,
            "download_performed": False,
            "migration_performed": False,
            "adoption_performed": False,
            "operator_instruction": "ask-release submitted the candidate-producing protocol request without parsing. Rerun with default parsing before candidate-run.",
        }
        if args.json:
            print(json.dumps(payload, indent=2, ensure_ascii=False))
        else:
            print(f"status={payload['status']}")
        return 0

    if isinstance(response, dict):
        response_failure = _protocol_ask_response_failure_result(args, envelope=envelope, ask_response=response, pre_ask_marker=pre_ask_marker)
        if response_failure is not None:
            response_failure["action"] = "ask_release"
            response_failure["expected"] = expected
            return _emit_protocol_result(args, response_failure)
    try:
        result = await _parse_protocol_reply_after_ask(backend, args, envelope=envelope, ask_response=response, pre_ask_marker=pre_ask_marker)
    except Exception as exc:
        result = _protocol_failure_result(
            args,
            envelope=envelope,
            status="reply_parse_failed",
            error=str(exc),
            error_type=exc.__class__.__name__,
            ask_response=response if isinstance(response, dict) else {"answer": response},
            pre_ask_marker=pre_ask_marker,
        )
    result["action"] = "ask_release"
    result["expected"] = expected
    result = await _materialize_ask_release_rendered_candidate(backend, args, result, expected)
    result = _validate_ask_release_candidate_result(result, expected)
    return _emit_protocol_result(args, result)

def _integrated_mvp_ask_requested(args: argparse.Namespace, prompt: str) -> bool:
    """Return true only for the canonical one-command MVP proof spelling.

    The narrow trigger prevents ordinary prompts containing release options from
    unexpectedly mutating a repository.  The operator contract is deliberately
    exact: ``pb ask continue --target-version ... --release-type normal``.
    """

    return (
        str(prompt or "").strip().lower() == "continue"
        and bool(str(getattr(args, "target_version", "") or "").strip())
        and str(getattr(args, "release_type", "normal") or "normal") == "normal"
        and not bool(getattr(args, "protocol", False))
        and not bool(getattr(args, "parse_reply", False))
        and not bool(getattr(args, "print_request_json", False))
    )


def _mvp_json_from_output(text: str) -> dict[str, Any] | None:
    """Extract the largest complete JSON object from command output."""

    source = str(text or "")
    try:
        payload = json.loads(source)
        return payload if isinstance(payload, dict) else None
    except json.JSONDecodeError:
        pass
    decoder = json.JSONDecoder()
    objects: list[tuple[int, int, dict[str, Any]]] = []
    for index, char in enumerate(source):
        if char != "{":
            continue
        try:
            value, consumed = decoder.raw_decode(source[index:])
        except json.JSONDecodeError:
            continue
        if isinstance(value, dict):
            objects.append((consumed, index, value))
    if not objects:
        return None
    objects.sort(key=lambda item: (item[0], item[1]))
    return objects[-1][2]


def _run_mvp_lifecycle_command(
    command: list[str],
    *,
    cwd: Path,
    timeout_seconds: float,
    stdout_path: Path | None = None,
    stderr_path: Path | None = None,
) -> dict[str, Any]:
    """Run one bounded lifecycle subprocess and retain exact evidence.

    Full command output is written to the evidence paths.  The returned value
    deliberately contains only bounded tails plus a parsed JSON object for the
    in-process controller.  This prevents the final ``pb ask`` result from
    embedding an entire multi-megabyte release-control transcript.
    """

    started = time.monotonic()
    try:
        completed = subprocess.run(
            command,
            cwd=str(cwd),
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            timeout=max(1.0, float(timeout_seconds)),
            check=False,
        )
        stdout = completed.stdout or ""
        stderr = completed.stderr or ""
        returncode: int | None = completed.returncode
        status = "passed" if completed.returncode == 0 else "failed"
    except subprocess.TimeoutExpired as exc:
        stdout = exc.stdout.decode() if isinstance(exc.stdout, bytes) else (exc.stdout or "")
        stderr = exc.stderr.decode() if isinstance(exc.stderr, bytes) else (exc.stderr or "")
        returncode = None
        status = "timeout"
    if stdout_path is not None:
        stdout_path.parent.mkdir(parents=True, exist_ok=True)
        stdout_path.write_text(stdout, encoding="utf-8")
    if stderr_path is not None:
        stderr_path.parent.mkdir(parents=True, exist_ok=True)
        stderr_path.write_text(stderr, encoding="utf-8")
    tail_limit = 4000
    return {
        "ok": returncode == 0,
        "status": f"mvp_lifecycle_command_{status}",
        "command": command,
        "returncode": returncode,
        "duration_seconds": round(time.monotonic() - started, 3),
        "timeout_seconds": float(timeout_seconds),
        "stdout_bytes": len(stdout.encode("utf-8")),
        "stderr_bytes": len(stderr.encode("utf-8")),
        "stdout_tail": stdout[-tail_limit:],
        "stderr_tail": stderr[-tail_limit:],
        "output_tail_limit": tail_limit,
        "parsed_json": _mvp_json_from_output(stdout),
        "stdout_path": str(stdout_path) if stdout_path is not None else None,
        "stderr_path": str(stderr_path) if stderr_path is not None else None,
    }


def _mvp_stage_record(name: str, step: dict[str, Any]) -> dict[str, Any]:
    """Return bounded, operator-safe evidence for one lifecycle stage."""

    record = {
        "name": name,
        "ok": step.get("ok") is True,
        "status": step.get("status"),
        "command": step.get("command"),
        "returncode": step.get("returncode"),
        "duration_seconds": step.get("duration_seconds"),
        "timeout_seconds": step.get("timeout_seconds"),
        "stdout_bytes": step.get("stdout_bytes"),
        "stderr_bytes": step.get("stderr_bytes"),
        "stdout_tail": str(step.get("stdout_tail") or step.get("stdout") or "")[-4000:],
        "stderr_tail": str(step.get("stderr_tail") or step.get("stderr") or "")[-4000:],
        "stdout_path": step.get("stdout_path"),
        "stderr_path": step.get("stderr_path"),
    }
    parsed = step.get("parsed_json")
    if isinstance(parsed, dict):
        summary_keys = (
            "ok",
            "action",
            "status",
            "request_id",
            "correlation_id",
            "reply_status",
            "result_type",
            "download_performed",
            "verification_performed",
            "migration_performed",
            "adoption_performed",
            "release_exit_code",
            "all_tests_final_verdict",
            "error",
        )
        parsed_summary = {key: parsed.get(key) for key in summary_keys if key in parsed}
        ask_validation = parsed.get("ask_release_validation")
        if isinstance(ask_validation, dict):
            parsed_summary["ask_release_validation"] = {
                key: ask_validation.get(key)
                for key in ("ok", "status", "error")
                if key in ask_validation
            }
        selected = parsed.get("selected_protocol_reply")
        if isinstance(selected, dict):
            parsed_summary["selected_protocol_reply"] = {
                key: selected.get(key)
                for key in ("request_id", "correlation_id", "conversation_url", "message_id", "answer_id")
                if key in selected
            }
        download = parsed.get("download")
        if isinstance(download, dict):
            parsed_summary["download"] = {
                key: download.get(key)
                for key in ("filename", "version", "sha256", "size_bytes", "path")
                if key in download
            }
        record["parsed_result"] = parsed_summary
    return record


def _mvp_candidate_sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _mvp_current_baseline(
    backend: Any,
    args: argparse.Namespace,
    *,
    repo_root: Path,
) -> dict[str, Any]:
    registry = _artifact_registry_from_args(args)
    payload = _artifact_current_payload(backend, registry)
    identity = load_repo_identity(repo_root)
    repo_id = identity.repo_id if identity is not None else None
    selected = _artifact_current_selected_sections(payload, repo_id=repo_id)
    state = selected.get("state") if isinstance(selected.get("state"), dict) else {}
    current = selected.get("registry_current") if isinstance(selected.get("registry_current"), dict) else {}
    baseline_version = _candidate_version_normalized(current.get("version") or state.get("artifact_version"))
    baseline_artifact = Path(str(current.get("filename") or state.get("artifact_ref") or "")).name or None
    baseline_sha256 = str(current.get("sha256") or "").strip().lower() or None
    selected_repo_id = repo_id or state.get("repo_id") or current.get("repo_id")
    project_home_url = str(
        state.get("project_home_url")
        or current.get("project_url")
        or (payload.get("scope") or {}).get("project_home_url")
        or ""
    ).strip() or None
    return {
        "ok": bool(payload.get("ok") is True and selected_repo_id and baseline_version and baseline_artifact and baseline_sha256 and project_home_url),
        "repo_id": selected_repo_id,
        "version": baseline_version,
        "artifact": baseline_artifact,
        "sha256": baseline_sha256,
        "project_home_url": project_home_url,
        "project_id": _project_identity_from_url(project_home_url),
        "artifact_current": payload,
        "selected": selected,
    }


def _mvp_passed_proof_records(profile_root: Path) -> list[dict[str, Any]]:
    records: list[dict[str, Any]] = []
    release_root = profile_root / "release_logs"
    if not release_root.is_dir():
        return records
    for path in release_root.glob("*/mvp-proof-cycle-*.json"):
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            continue
        if not isinstance(payload, dict):
            continue
        if payload.get("status") != "mvp_proof_cycle_passed" or payload.get("ok") is not True:
            continue
        cycle = payload.get("cycle")
        version = _candidate_version_normalized(payload.get("version"))
        if not isinstance(cycle, int) or cycle not in {1, 2} or not version:
            continue
        records.append({"cycle": cycle, "version": version, "path": str(path), "payload": payload})
    records.sort(key=lambda item: (Path(item["path"]).stat().st_mtime, item["cycle"]))
    return records


def _mvp_next_cycle(profile_root: Path, *, baseline_version: str) -> dict[str, Any]:
    """Resolve strict consecutive proof position from persisted passed proof."""

    records = _mvp_passed_proof_records(profile_root)
    latest = records[-1] if records else None
    if latest and latest["version"] == baseline_version and latest["cycle"] == 2:
        return {"ok": False, "status": "mvp_already_verified", "cycle": None, "records": records, "latest": latest}
    if latest and latest["version"] == baseline_version and latest["cycle"] == 1:
        return {"ok": True, "status": "mvp_cycle_2_required", "cycle": 2, "records": records, "latest": latest}
    # Any repair/intervening baseline breaks consecutiveness and restarts at 1.
    return {"ok": True, "status": "mvp_cycle_1_required", "cycle": 1, "records": records, "latest": latest}


def _mvp_cli_prefix(args: argparse.Namespace, profile_root: Path) -> list[str]:
    prefix = [sys.executable, str(Path(__file__).resolve()), "--profile-dir", str(profile_root)]
    service_base_url = str(getattr(args, "service_base_url", "") or "").strip()
    if service_base_url:
        prefix.extend(["--service-base-url", service_base_url])
    service_token = str(getattr(args, "service_token", "") or "").strip()
    if service_token:
        prefix.extend(["--service-token", service_token])
    return prefix


def _mvp_emit_result(args: argparse.Namespace, payload: dict[str, Any], code: int) -> int:
    # ``pb ask`` uses structured JSON by default.  The integrated lifecycle does
    # not print a success token before every stage has completed.
    print(json.dumps(payload, indent=2, ensure_ascii=False))
    return code


async def cmd_ask_mvp_proof_lifecycle(backend: Any, args: argparse.Namespace) -> int:
    """Own one complete normal MVP proof cycle behind a single ``pb ask``."""

    repo_root = Path.cwd().resolve()
    profile_root = resolve_profile_dir(getattr(args, "profile_dir", None))
    target_version = _candidate_version_normalized(getattr(args, "target_version", None))
    release_type = str(getattr(args, "release_type", "normal") or "normal")
    baseline = _mvp_current_baseline(backend, args, repo_root=repo_root)
    explicit_conversation_url = str(getattr(args, "conversation_url", "") or "").strip()
    conversation_id = conversation_id_from_url(explicit_conversation_url)
    conversation_project_home_url = project_home_url_from_url(explicit_conversation_url)
    conversation_project_id = _project_identity_from_url(explicit_conversation_url)
    baseline_project_home_url = str(baseline.get("project_home_url") or "").strip() or None
    conversation_selection = {
        "selection": "explicit_cli_argument" if explicit_conversation_url else "missing",
        "conversation_url": explicit_conversation_url or None,
        "conversation_id": conversation_id,
        "project_home_url": conversation_project_home_url,
        "project_id": conversation_project_id,
        "baseline_project_home_url": baseline_project_home_url,
        "baseline_project_id": baseline.get("project_id"),
    }
    base: dict[str, Any] = {
        "ok": False,
        "action": "ask_mvp_proof_lifecycle",
        "status": "mvp_proof_lifecycle_preflight",
        "operator_command": "pb ask continue --conversation-url <project-conversation-url> --target-version <version> --release-type normal",
        "repo_path": str(repo_root),
        "profile_dir": str(profile_root),
        "target_version": target_version,
        "release_type": release_type,
        "baseline": baseline,
        "conversation_selection": conversation_selection,
        "stages": [],
        "download_performed": False,
        "verification_performed": False,
        "migration_performed": False,
        "release_control_performed": False,
        "adoption_performed": False,
        "continuation_ask_performed": False,
        "proof_written": False,
    }

    def fail(status: str, error: str, *, code: int = 1, stage: dict[str, Any] | None = None) -> int:
        payload = {**base, "ok": False, "status": status, "error": error}
        if stage is not None:
            payload["failed_stage"] = stage
        payload["operator_instruction"] = "Inspect the failed_stage evidence. Accepted/current is never claimed advanced by this command unless adoption and final proof both pass."
        return _mvp_emit_result(args, payload, code)

    if release_type != "normal" or not target_version or not re.fullmatch(r"v\d+\.\d+\.\d+", target_version):
        return fail("mvp_proof_invalid_target", "integrated MVP proof requires a normal three-component --target-version and --release-type normal", code=2)
    if not explicit_conversation_url:
        return fail("mvp_proof_conversation_required", "integrated MVP proof requires an explicit --conversation-url; implicit task state and browser context are forbidden", code=2)
    if not is_project_conversation_url(explicit_conversation_url) or not conversation_id or not conversation_project_home_url:
        return fail("mvp_proof_conversation_invalid", "--conversation-url must be a complete ChatGPT Project conversation URL containing /g/<project>/c/<conversation-id>", code=2)
    if not baseline.get("ok"):
        return fail("mvp_proof_baseline_unresolved", "accepted/current repository identity, artifact, version, and SHA-256 could not be resolved", code=2)
    if not baseline_project_home_url or not _same_project_url_identity(explicit_conversation_url, baseline_project_home_url):
        return fail("mvp_proof_conversation_project_mismatch", "explicit --conversation-url does not belong to the accepted/current release-authority project", code=2)
    baseline_version = str(baseline["version"])
    expected_target = _release_expected_next_normal_version(baseline_version)
    if target_version != expected_target:
        return fail("mvp_proof_target_not_next_normal", f"target must be the next normal version after accepted/current {baseline_version}: expected {expected_target}", code=2)

    cycle_state = _mvp_next_cycle(profile_root, baseline_version=baseline_version)
    if not cycle_state.get("ok"):
        return fail("mvp_already_verified", "two consecutive normal MVP proof cycles are already complete for the accepted baseline", code=2)
    cycle = int(cycle_state["cycle"])
    next_version = _release_expected_next_normal_version(target_version)
    repo_id = str(baseline["repo_id"])
    artifact_name = f"{repo_id}_{target_version}.zip"
    release_log_dir = profile_root / "release_logs" / target_version
    release_log_dir.mkdir(parents=True, exist_ok=True)
    summary_path = release_log_dir / f"mvp-ask-lifecycle.{target_version}.json"
    base.update({
        "cycle": cycle,
        "next_version": next_version,
        "repo_id": repo_id,
        "artifact": artifact_name,
        "release_log_dir": str(release_log_dir),
        "proof_sequence_before": f"{cycle - 1}/2",
    })

    cli_prefix = _mvp_cli_prefix(args, profile_root)
    timeout_budget = _mvp_proof_timeout_budget(args)
    step_timeout = float(timeout_budget["outer_step_timeout_seconds"])
    protocol_timeout = float(timeout_budget["protocol_timeout_seconds"])
    fresh_turn_timeout = float(timeout_budget["fresh_turn_timeout_seconds"])
    release_timeout = float(getattr(args, "mvp_proof_release_timeout_seconds", 14400.0) or 14400.0)
    base["release_candidate_timeout_budget"] = timeout_budget

    ask_command = cli_prefix + [
        "ask-release",
        f"Create normal release {target_version} from accepted/current {baseline_version}. Return exactly one real downloadable candidate ZIP and the strict Promptbranch reply envelope.",
        "--target-version", target_version,
        "--release-type", "normal",
        "--expect-artifact", artifact_name,
        "--expect-version", target_version,
        "--expect-repo", repo_id,
        "--conversation-url", explicit_conversation_url,
        "--protocol-timeout-seconds", str(protocol_timeout),
        "--protocol-fresh-turn-timeout-seconds", str(fresh_turn_timeout),
        "--json",
    ]
    ask_step = _run_mvp_lifecycle_command(
        ask_command,
        cwd=repo_root,
        timeout_seconds=step_timeout,
        stdout_path=release_log_dir / f"mvp-ask-release.{target_version}.json",
        stderr_path=release_log_dir / f"mvp-ask-release.{target_version}.stderr.log",
    )
    base["stages"].append(_mvp_stage_record("release_candidate_ask", ask_step))
    ask_payload = ask_step.get("parsed_json") if isinstance(ask_step.get("parsed_json"), dict) else {}
    ask_validation = ask_payload.get("ask_release_validation") if isinstance(ask_payload.get("ask_release_validation"), dict) else {}
    selection = ask_payload.get("selected_protocol_reply") if isinstance(ask_payload.get("selected_protocol_reply"), dict) else {}
    message_id = selection.get("message_id") or ask_payload.get("selected_message_id")
    answer_id = selection.get("answer_id") or ask_payload.get("selected_answer_id")
    conversation_url = selection.get("conversation_url") or ask_payload.get("conversation_url")
    returned_conversation_id = conversation_id_from_url(str(conversation_url or ""))
    if conversation_url and (
        returned_conversation_id != conversation_id
        or not _same_project_url_identity(str(conversation_url), explicit_conversation_url)
    ):
        return fail("mvp_release_candidate_conversation_mismatch", "release-candidate Ask returned a conversation different from the explicitly pinned --conversation-url", stage=base["stages"][-1])
    if not (
        ask_step.get("ok")
        and ask_payload.get("ok") is True
        and ask_validation.get("ok") is True
        and message_id
        and answer_id
        and conversation_url
    ):
        return fail("mvp_release_candidate_ask_failed", "release-candidate Ask did not yield one exactly correlated materialized ZIP", stage=base["stages"][-1])

    intake_path = release_log_dir / f"artifact-intake.{target_version}.json"
    intake_command = cli_prefix + [
        "artifact", "intake",
        "--from-last-answer",
        "--task", explicit_conversation_url,
        "--message-id", str(message_id),
        "--answer-id", str(answer_id),
        "--expect-artifact", artifact_name,
        "--expect-version", target_version,
        "--expect-repo", repo_id,
    ]
    if ask_payload.get("download_performed") is not True:
        intake_command.append("--download")
    intake_command.extend([
        "--verify", "--migrate",
        "--repo-path", str(repo_root),
        "--json",
    ])
    intake_step = _run_mvp_lifecycle_command(
        intake_command,
        cwd=repo_root,
        timeout_seconds=step_timeout,
        stdout_path=intake_path,
        stderr_path=release_log_dir / f"artifact-intake.{target_version}.stderr.log",
    )
    base["stages"].append(_mvp_stage_record("artifact_intake", intake_step))
    intake = intake_step.get("parsed_json") if isinstance(intake_step.get("parsed_json"), dict) else {}
    candidate_path = repo_root / artifact_name
    if not (
        intake_step.get("ok")
        and intake.get("ok") is True
        and intake.get("status") == "migrated_candidate"
        and intake.get("download_performed") is True
        and intake.get("verification_performed") is True
        and intake.get("migration_performed") is True
        and candidate_path.is_file()
    ):
        return fail("mvp_artifact_intake_failed", "exact correlated artifact download, verification, and migration did not complete", stage=base["stages"][-1])
    candidate_sha256 = _mvp_candidate_sha256(candidate_path)
    intake_download = intake.get("download") if isinstance(intake.get("download"), dict) else {}
    intake_sha256 = str(intake_download.get("sha256") or intake.get("sha256") or "").strip().lower()
    if intake_sha256 != candidate_sha256:
        return fail("mvp_artifact_intake_sha_mismatch", "download/intake SHA-256 differs from the migrated canonical candidate", stage=base["stages"][-1])
    base.update({
        "download_performed": True,
        "verification_performed": True,
        "migration_performed": True,
        "candidate_sha256": candidate_sha256,
        "selected_protocol_reply": selection,
        "artifact_intake": str(intake_path),
    })

    release_script = repo_root / "chatgpt_claudecode_workflow_release_control.sh"
    if not release_script.is_file():
        return fail("mvp_release_control_missing", f"release-control script not found: {release_script}", code=2)
    release_control_log = release_log_dir / f"release_control.{target_version}.full.all-all.adopt.log"
    release_command = [
        str(release_script),
        "--version", target_version,
        "--install-from-zip", str(candidate_path),
        "--run-all-tests",
        "--run-external-live-tests",
        "--require-chatgpt-live-validation",
        "--adopt-after-validation",
        "--skip-docker-logs",
        "--prune-release-logs",
        "--release-log-keep", "12",
    ]
    release_step = _run_mvp_lifecycle_command(
        release_command,
        cwd=repo_root,
        timeout_seconds=release_timeout,
        stdout_path=release_control_log,
        stderr_path=release_log_dir / f"release_control.{target_version}.stderr.log",
    )
    base["stages"].append(_mvp_stage_record("strict_release_control", release_step))
    base["release_control_performed"] = True
    if not release_step.get("ok"):
        return fail("mvp_release_control_failed", "strict release validation/adoption returned nonzero", stage=base["stages"][-1])

    required_release_evidence = [
        release_log_dir / f"pb_test.all.{target_version}.summary.json",
        release_log_dir / f"pb_test.visual_artifact_roundtrip.{target_version}.log",
        release_log_dir / f"pb_artifact_adopt.{target_version}.json",
        release_log_dir / f"pb_artifact_current.{target_version}.json",
    ]
    missing = [str(path) for path in required_release_evidence if not path.is_file()]
    if missing:
        return fail("mvp_release_evidence_missing", f"strict release returned zero but required proof evidence is missing: {missing}", stage=base["stages"][-1])
    base["adoption_performed"] = True

    finalizer = repo_root / "scripts" / "finalize-mvp-proof-cycle.sh"
    pipx_pb = Path.home() / ".local" / "share" / "pipx" / "venvs" / "promptbranch" / "bin" / "pb"
    pb_cmd = str(pipx_pb) if pipx_pb.is_file() else (shutil.which("pb") or "pb")
    finalizer_command = [
        str(finalizer),
        "--cycle", str(cycle),
        "--version", target_version,
        "--baseline-version", baseline_version,
        "--next-version", str(next_version),
        "--repo-id", repo_id,
        "--artifact-intake", str(intake_path),
        "--artifact-path", str(candidate_path),
        "--release-log-dir", str(release_log_dir),
        "--pb-cmd", pb_cmd,
        "--conversation-url", explicit_conversation_url,
    ]
    finalizer_step = _run_mvp_lifecycle_command(
        finalizer_command,
        cwd=repo_root,
        timeout_seconds=step_timeout,
        stdout_path=release_log_dir / f"mvp-proof-finalizer.{target_version}.log",
        stderr_path=release_log_dir / f"mvp-proof-finalizer.{target_version}.stderr.log",
    )
    base["stages"].append(_mvp_stage_record("proof_finalizer", finalizer_step))
    proof_path = release_log_dir / f"mvp-proof-cycle-{cycle}.{target_version}.json"
    proof: dict[str, Any] = {}
    if proof_path.is_file():
        try:
            loaded = json.loads(proof_path.read_text(encoding="utf-8"))
            proof = loaded if isinstance(loaded, dict) else {}
        except json.JSONDecodeError:
            proof = {}
    if not (finalizer_step.get("ok") and proof.get("ok") is True and proof.get("status") == "mvp_proof_cycle_passed"):
        return fail("mvp_proof_finalization_failed", "post-adoption continuation or final fail-closed proof verification did not pass", stage=base["stages"][-1])

    status = "mvp_verified" if cycle == 2 else "mvp_proof_cycle_passed"
    payload = {
        **base,
        "ok": True,
        "status": status,
        "accepted_current_version": target_version,
        "accepted_current_artifact": artifact_name,
        "consecutive_proof_count": f"{cycle}/2",
        "mvp_status": "complete" if cycle == 2 else "proof_cycle_1_complete",
        "continuation_ask_performed": True,
        "proof_written": True,
        "proof_path": str(proof_path),
        "proof": proof,
        "operator_instruction": "No additional operator command is required for this cycle. Run the same one-command form for the next normal target only when consecutive_proof_count is 1/2.",
    }
    summary_path.write_text(json.dumps(payload, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    payload["summary_path"] = str(summary_path)
    return _mvp_emit_result(args, payload, 0)

async def cmd_ask(backend: CommandBackend, args: argparse.Namespace) -> int:
    if getattr(args, "new_task", False) and getattr(args, "conversation_url", None):
        print(json.dumps(_new_task_conversation_url_conflict_payload(), indent=2, ensure_ascii=False))
        return 2
    attachment_paths = _collect_ask_attachment_paths(args)
    try:
        prompt, attachment_paths, prompt_file_transport = _prepare_prompt_file_transport(
            args.prompt,
            getattr(args, "prompt_file", None),
            args,
            attachment_paths=attachment_paths,
        )
    except (OSError, UnicodeError) as exc:
        print(f"error: could not read prompt file: {exc}", file=sys.stderr)
        return 2
    if not prompt:
        print("error: prompt is required", file=sys.stderr)
        return 2

    if _integrated_mvp_ask_requested(args, prompt):
        if attachment_paths or getattr(args, "new_task", False):
            payload = {
                "ok": False,
                "action": "ask_mvp_proof_lifecycle",
                "status": "mvp_proof_invalid_arguments",
                "error": "the integrated proof lifecycle forbids attachments and --new-task; an explicit --conversation-url is required",
            }
            print(json.dumps(payload, indent=2, ensure_ascii=False))
            return 2
        return await cmd_ask_mvp_proof_lifecycle(backend, args)

    protocol_payload: dict[str, Any] | None = None
    envelope: dict[str, Any] | None = None
    if getattr(args, "protocol", False):
        protocol_payload = _protocol_request_from_current_baseline(backend, args, prompt=prompt)
        if protocol_payload.get("ok") is not True:
            print(json.dumps(protocol_payload, indent=2, ensure_ascii=False)); return 2
        envelope = protocol_payload["request"]
        if getattr(args, "print_request_json", False):
            print(json.dumps(protocol_payload, indent=2, ensure_ascii=False))
            return 0
        prompt = render_protocol_ask_prompt(envelope, user_prompt=prompt)
    elif getattr(args, "parse_reply", False):
        print("error: --parse-reply requires --protocol", file=sys.stderr)
        return 2

    for attachment_path in attachment_paths:
        if not Path(attachment_path).is_file():
            print(f"error: attachment file not found: {attachment_path}", file=sys.stderr)
            return 2

    prompt_file_attachment_active = bool(
        isinstance(prompt_file_transport, dict) and prompt_file_transport.get("mode_effective") == "attachment"
    )
    legacy_single_file = args.file if args.file and not getattr(args, "attachments", None) and not prompt_file_attachment_active else None
    repeatable_attachments = attachment_paths if not legacy_single_file else None

    if getattr(args, "debug_browser", False):
        args.keep_open = True
        args.headless = False
        args.debug = True
    protocol_parse = bool(getattr(args, "parse_reply", False))
    pre_ask_marker = await _capture_pre_ask_protocol_marker(backend, args) if protocol_parse else None
    try:
        ask_kwargs = {
            "prompt": prompt,
            "file_path": legacy_single_file,
            "attachment_paths": repeatable_attachments,
            "conversation_url": args.conversation_url,
            # Protocol replies are envelope text, not raw JSON. Let the ask
            # operation return first, then parse/validate deterministically.
            "expect_json": False if protocol_parse else args.json,
            "keep_open": args.keep_open,
            "retries": args.retries,
            "prefer_button_submit": bool(getattr(args, "prompt_file", None)),
        }
        if getattr(args, "new_task", False):
            ask_kwargs["new_task"] = True
        response = await backend.ask(**ask_kwargs)
    except Exception as exc:
        if protocol_parse and envelope is not None:
            lowered = f"{exc.__class__.__name__}: {exc}".lower()
            if exc.__class__.__name__ in {"ReadTimeout", "TimeoutException"}:
                status = "service_read_timeout"
            else:
                status = "response_timeout" if "timeout" in lowered or "timed out" in lowered else "ask_failed"
            recovery_diagnostic: dict[str, Any] | None = None
            if status == "service_read_timeout":
                recovered, recovery_diagnostic = await _recover_protocol_reply_after_service_timeout(
                    backend,
                    args,
                    envelope=envelope,
                    error=str(exc),
                    error_type=exc.__class__.__name__,
                    pre_ask_marker=pre_ask_marker,
                )
                if recovered is not None:
                    return _emit_protocol_result(args, recovered)
            result = _protocol_failure_result(
                args,
                envelope=envelope,
                status=status,
                error=str(exc),
                error_type=exc.__class__.__name__,
                pre_ask_marker=pre_ask_marker,
            )
            if status == "service_read_timeout":
                result["timeout_layer"] = "service_client"
                result["service_timeout_recovery"] = recovery_diagnostic or {"attempted": False}
            elif status == "response_timeout":
                result["timeout_layer"] = "unknown_response_wait"
            return _emit_protocol_result(args, result)
        raise
    if protocol_parse:
        assert envelope is not None
        if isinstance(response, dict):
            response_failure = _protocol_ask_response_failure_result(args, envelope=envelope, ask_response=response, pre_ask_marker=pre_ask_marker)
            if response_failure is not None:
                return _emit_protocol_result(args, response_failure)
        try:
            result = await _parse_protocol_reply_after_ask(backend, args, envelope=envelope, ask_response=response, pre_ask_marker=pre_ask_marker)
        except Exception as exc:
            result = _protocol_failure_result(
                args,
                envelope=envelope,
                status="reply_parse_failed",
                error=str(exc),
                error_type=exc.__class__.__name__,
                ask_response=response if isinstance(response, dict) else {"answer": response},
                pre_ask_marker=pre_ask_marker,
            )
        return _emit_protocol_result(args, result)

    response = _enrich_ask_response_with_canonical_text(response)
    if isinstance(response, dict) and isinstance(prompt_file_transport, dict) and prompt_file_transport.get("prompt_file_present"):
        response.setdefault("prompt_file_transport", prompt_file_transport)
        response = _flatten_prompt_file_attachment_diagnostics(response, prompt_file_transport)
    ok = True
    if isinstance(response, dict) and response.get("ok") is False:
        ok = False

    if getattr(args, "text", False):
        if not ok:
            error = response.get("error") if isinstance(response, dict) else None
            status = response.get("status") if isinstance(response, dict) else None
            print(error or status or "ask failed", file=sys.stderr)
            return 1
        answer, _ = _split_ask_response(response)
        print(_canonical_answer_text(answer))
        return 0

    # v0.0.278.60: structured JSON result output is the default transport
    # contract for pb ask.  --json remains a request-mode flag for strict
    # assistant JSON, while --text opts into the legacy answer-only output.
    print(json.dumps(response, indent=2, ensure_ascii=False))
    return 0 if ok else 1


def _cli_command_name(argv0: Optional[str] = None) -> str:
    return "promptbranch"


def _completion_function_name(command_name: str) -> str:
    sanitized = re.sub(r"[^A-Za-z0-9_]", "_", command_name)
    return f"_{sanitized}_complete"


def _compact_prompt_text(snapshot: dict[str, Any], *, command_name: str = "promptbranch") -> str:
    project_name = snapshot.get("project_name") or snapshot.get("project_slug") or "no-project"
    conversation_id = snapshot.get("conversation_id")
    if conversation_id:
        return f"{command_name}:{project_name}#{str(conversation_id)[:8]}"
    return f"{command_name}:{project_name}"



def _looks_like_chatgpt_url(value: str) -> bool:
    return value.startswith("https://") or value.startswith("http://")


def _completion_command_names() -> list[str]:
    return sorted(COMMANDS)


def _global_option_names() -> list[str]:
    return sorted(GLOBAL_OPTION_HAS_VALUE.keys())


