def _run_bounded_smoke_subprocess(
    spec: dict[str, Any],
    *,
    repo_path: Path,
    timeout_seconds: float,
    log_dir: Path,
) -> dict[str, Any]:
    started_at = utc_now()
    name = str(spec.get("name") or "unknown")
    command = [str(item) for item in spec.get("command") or []]
    safe_name = re.sub(r"[^A-Za-z0-9_.-]+", "_", name)
    log_dir.mkdir(parents=True, exist_ok=True)
    stdout_log = log_dir / f"{safe_name}.stdout.log"
    stderr_log = log_dir / f"{safe_name}.stderr.log"
    timeout = max(1.0, float(timeout_seconds))
    stdout_handle = open(stdout_log, "w", encoding="utf-8", errors="replace")
    stderr_handle = open(stderr_log, "w", encoding="utf-8", errors="replace")
    proc: subprocess.Popen[str] | None = None
    try:
        proc = subprocess.Popen(
            command,
            cwd=str(repo_path),
            stdout=stdout_handle,
            stderr=stderr_handle,
            text=True,
            start_new_session=True,
        )
        try:
            returncode = proc.wait(timeout=timeout)
        except subprocess.TimeoutExpired:
            timed_out_at = utc_now()
            try:
                os.killpg(proc.pid, signal.SIGTERM)
            except Exception:
                try:
                    proc.terminate()
                except Exception:
                    pass
            try:
                proc.wait(timeout=5)
                killed_with = "SIGTERM"
            except subprocess.TimeoutExpired:
                try:
                    os.killpg(proc.pid, signal.SIGKILL)
                except Exception:
                    try:
                        proc.kill()
                    except Exception:
                        pass
                proc.wait(timeout=5)
                killed_with = "SIGKILL"
            return {
                "name": name,
                "ok": False,
                "status": "smoke_substep_timeout",
                "kind": spec.get("kind"),
                "description": spec.get("description"),
                "command": command,
                "pid": proc.pid,
                "process_group_pid": proc.pid,
                "started_at": started_at,
                "finished_at": utc_now(),
                "timed_out_at": timed_out_at,
                "timeout_seconds": timeout,
                "killed_with": killed_with,
                "stdout_log_path": str(stdout_log),
                "stderr_log_path": str(stderr_log),
                "stdout_tail": _tail_text_file(stdout_log),
                "stderr_tail": _tail_text_file(stderr_log),
            }
        stdout_text = stdout_log.read_text(encoding="utf-8", errors="replace") if stdout_log.is_file() else ""
        required_stdout = [str(item) for item in (spec.get("required_stdout_contains") or [])]
        missing_stdout = [item for item in required_stdout if item not in stdout_text]
        stdout_contract_ok = not missing_stdout
        accepted_readonly_statuses = {
            str(item) for item in (spec.get("accepted_readonly_json_statuses") or []) if str(item)
        }
        structured_payload = None
        structured_readonly_status_accepted = False
        if accepted_readonly_statuses and stdout_text.strip():
            try:
                candidate_payload = json.loads(stdout_text)
            except json.JSONDecodeError:
                candidate_payload = None
            if isinstance(candidate_payload, dict):
                structured_payload = candidate_payload
                candidate_status = str(candidate_payload.get("status") or "")
                mutation_flags = [
                    candidate_payload.get("mutating_actions_executed"),
                    candidate_payload.get("project_source_mutated"),
                    candidate_payload.get("artifact_registry_updated"),
                    candidate_payload.get("adoption_performed"),
                ]
                structured_readonly_status_accepted = bool(
                    candidate_status in accepted_readonly_statuses
                    and not any(value is True for value in mutation_flags)
                )
        step_ok = bool((returncode == 0 and stdout_contract_ok) or structured_readonly_status_accepted)
        return {
            "name": name,
            "ok": step_ok,
            "status": (
                "passed_structured_readonly_uninitialized"
                if structured_readonly_status_accepted
                else "passed" if step_ok
                else ("smoke_stdout_contract_failed" if returncode == 0 else "failed")
            ),
            "kind": spec.get("kind"),
            "description": spec.get("description"),
            "command": command,
            "pid": proc.pid,
            "process_group_pid": proc.pid,
            "returncode": returncode,
            "started_at": started_at,
            "finished_at": utc_now(),
            "timeout_seconds": timeout,
            "required_stdout_contains": required_stdout,
            "missing_stdout_contains": missing_stdout,
            "stdout_contract_ok": stdout_contract_ok,
            "accepted_readonly_json_statuses": sorted(accepted_readonly_statuses),
            "structured_readonly_status_accepted": structured_readonly_status_accepted,
            "structured_payload_status": structured_payload.get("status") if isinstance(structured_payload, dict) else None,
            "stdout_log_path": str(stdout_log),
            "stderr_log_path": str(stderr_log),
            "stdout_tail": _tail_text_file(stdout_log),
            "stderr_tail": _tail_text_file(stderr_log),
        }
    except Exception as exc:
        return {
            "name": name,
            "ok": False,
            "status": "smoke_substep_runner_failed",
            "kind": spec.get("kind"),
            "description": spec.get("description"),
            "command": command,
            "started_at": started_at,
            "finished_at": utc_now(),
            "timeout_seconds": timeout,
            "stdout_log_path": str(stdout_log),
            "stderr_log_path": str(stderr_log),
            "stdout_tail": _tail_text_file(stdout_log),
            "stderr_tail": _tail_text_file(stderr_log),
            "error": str(exc),
        }
    finally:
        try:
            stdout_handle.close()
        except Exception:
            pass
        try:
            stderr_handle.close()
        except Exception:
            pass


async def cmd_test_smoke(args: argparse.Namespace) -> int:
    repo_path = Path(getattr(args, "path", ".") or ".").expanduser().resolve()
    profile_root = resolve_profile_dir(getattr(args, "profile_dir", None))
    run_id = str(getattr(args, "run_id", "") or datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S.%fZ"))
    log_dir = profile_root / "test_smoke_logs" / run_id
    timeout_seconds = float(getattr(args, "substep_timeout_seconds", 60.0) or 60.0)
    steps: list[dict[str, Any]] = []
    started_at = utc_now()
    for spec in _promptbranch_smoke_step_specs(repo_path):
        result = _run_bounded_smoke_subprocess(
            spec,
            repo_path=repo_path,
            timeout_seconds=timeout_seconds,
            log_dir=log_dir,
        )
        steps.append(result)
        if not bool(result.get("ok")):
            break
    ok = bool(steps) and all(bool(step.get("ok")) for step in steps)
    failed_step = next((step for step in steps if not bool(step.get("ok"))), None)
    payload = {
        "ok": ok,
        "schema": TEST_SUITE_REPORT_SCHEMA,
        "schema_version": TEST_SUITE_REPORT_SCHEMA_VERSION,
        "action": "test_smoke",
        "profile": "smoke",
        "status": "passed" if ok else (failed_step.get("status") if failed_step else "smoke_no_steps_run"),
        "repo_path": str(repo_path),
        "version": (repo_path / "VERSION").read_text(encoding="utf-8").strip() if (repo_path / "VERSION").is_file() else None,
        "started_at": started_at,
        "finished_at": utc_now(),
        "substep_timeout_seconds": timeout_seconds,
        "log_dir": str(log_dir),
        "step_count": len(steps),
        "planned_steps": [
            {"name": spec.get("name"), "kind": spec.get("kind"), "command": spec.get("command"), "description": spec.get("description")}
            for spec in _promptbranch_smoke_step_specs(repo_path)
        ],
        "steps": steps,
        "failed_step": failed_step,
        "operator_instruction": "Smoke profile is bounded and local. Use `pb test browser` or `pb test full` for live browser/adoption-grade coverage.",
    }
    if getattr(args, "json_out", None):
        Path(args.json_out).expanduser().resolve().write_text(json.dumps(payload, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    if getattr(args, "json", False):
        print(json.dumps(payload, indent=2, ensure_ascii=False))
    else:
        print(f"status={payload.get('status')}")
        for step in steps:
            print(f"{step.get('name')}: {step.get('status')}")
    return 0 if ok else 1

