async def cmd_loop(backend: CommandBackend, args: argparse.Namespace) -> int:
    del backend
    target = getattr(args, "target", None)
    if not target:
        print("error: --target is required", file=sys.stderr)
        return 2
    loop_command = getattr(args, "loop_command", None)
    if loop_command == "validate":
        payload = validate_loop_target_file(target)
        if getattr(args, "json", False):
            print(json.dumps(payload, indent=2, ensure_ascii=False))
        else:
            print(render_loop_validation_text(payload), end="")
        return 0 if payload.get("ok") else 1
    if loop_command == "plan":
        payload = plan_loop_target_file(target, execute_stubbed=False)
        if getattr(args, "json", False):
            print(json.dumps(payload, indent=2, ensure_ascii=False))
        else:
            print(render_loop_plan_text(payload), end="")
        return 0 if payload.get("ok") else 1
    if loop_command == "promotion-readiness":
        payload = assess_loop_sandbox_correction_promotion_readiness(
            target,
            repo_root=getattr(args, "repo_root", None),
            required_runs=int(getattr(args, "runs", 3)),
        )
        if getattr(args, "json", False):
            print(json.dumps(payload, indent=2, ensure_ascii=False))
        else:
            print(render_loop_sandbox_correction_promotion_readiness_text(payload), end="")
        if payload.get("status") == "ready":
            return 0
        if payload.get("status") == "not_ready":
            return 1
        return 2
    if loop_command == "promotion-decision":
        payload = assess_loop_sandbox_correction_promotion_decision(
            target,
            repo_root=getattr(args, "repo_root", None),
            required_runs=int(getattr(args, "runs", 3)),
        )
        if getattr(args, "json", False):
            print(json.dumps(payload, indent=2, ensure_ascii=False))
        else:
            print(render_loop_sandbox_correction_promotion_decision_text(payload), end="")
        return 0 if payload.get("decision") == "go" else 1
    if loop_command == "execution-envelope-design":
        payload = design_loop_controlled_correction_execution_envelope(
            target,
            repo_root=getattr(args, "repo_root", None),
        )
        if getattr(args, "json", False):
            print(json.dumps(payload, indent=2, ensure_ascii=False))
        else:
            print(render_loop_controlled_correction_execution_envelope_design_text(payload), end="")
        return 0 if payload.get("status") == "execution_envelope_design_ready" else 2
    if loop_command == "execution-envelope-validation":
        payload = validate_loop_controlled_correction_execution_envelope(
            target,
            repo_root=getattr(args, "repo_root", None),
        )
        if getattr(args, "json", False):
            print(json.dumps(payload, indent=2, ensure_ascii=False))
        else:
            print(render_loop_controlled_correction_execution_envelope_validation_text(payload), end="")
        return 0 if payload.get("status") == "execution_envelope_validation_passed" else 2
    if loop_command == "run":
        # The loop runner remains gated. Presentation modes remain dry-run;
        # v0.1.100 adds exactly one explicit allowlisted read-only validation
        # command execution path behind --read-only-execution --evidence-gate
        # --execute-read-only-validation. v0.1.101 diagnoses the result, and
        # v0.1.102 may generate a proposal-only correction plan with no file mutation.
        # v0.1.104 may mutate, verify, roll back, and delete only a temporary sandbox fixture after that plan.
        payload = plan_loop_target_file(target, execute_stubbed=True)
        payload["dry_run"] = True
        selected_modes = [
            bool(getattr(args, "state_only", False)),
            bool(getattr(args, "planned_actions", False)),
            bool(getattr(args, "read_only_execution", False)),
        ]
        if sum(1 for item in selected_modes if item) > 1:
            print("error: --state-only, --planned-actions, and --read-only-execution are mutually exclusive", file=sys.stderr)
            return 2
        if getattr(args, "evidence_report", False) and not getattr(args, "read_only_execution", False):
            print("error: --evidence-report requires --read-only-execution", file=sys.stderr)
            return 2
        if getattr(args, "evidence_gate", False) and not getattr(args, "read_only_execution", False):
            print("error: --evidence-gate requires --read-only-execution", file=sys.stderr)
            return 2
        if getattr(args, "evidence_report", False) and getattr(args, "evidence_gate", False):
            print("error: --evidence-report and --evidence-gate are mutually exclusive", file=sys.stderr)
            return 2
        if getattr(args, "execute_read_only_validation", False) and not (getattr(args, "read_only_execution", False) and getattr(args, "evidence_gate", False)):
            print("error: --execute-read-only-validation requires --read-only-execution --evidence-gate", file=sys.stderr)
            return 2
        if getattr(args, "execute_read_only_validation", False) and getattr(args, "evidence_report", False):
            print("error: --execute-read-only-validation cannot be combined with --evidence-report", file=sys.stderr)
            return 2
        if getattr(args, "diagnose_read_only_result", False) and not getattr(args, "execute_read_only_validation", False):
            print("error: --diagnose-read-only-result requires --execute-read-only-validation", file=sys.stderr)
            return 2
        if getattr(args, "generate_correction_plan", False) and not getattr(args, "diagnose_read_only_result", False):
            print("error: --generate-correction-plan requires --diagnose-read-only-result", file=sys.stderr)
            return 2
        if getattr(args, "execute_sandbox_mutation", False) and not getattr(args, "generate_correction_plan", False):
            print("error: --execute-sandbox-mutation requires --generate-correction-plan", file=sys.stderr)
            return 2
        if getattr(args, "state_only", False):
            payload = build_loop_state_only_payload(payload)
        elif getattr(args, "planned_actions", False):
            payload = build_loop_action_walkthrough_payload(payload)
        elif getattr(args, "read_only_execution", False):
            payload = build_loop_read_only_execution_payload(payload, repo_root=Path.cwd())
            if getattr(args, "evidence_report", False):
                payload = build_loop_read_only_evidence_report(payload)
            elif getattr(args, "evidence_gate", False):
                gate = build_loop_read_only_evidence_gate(build_loop_read_only_evidence_report(payload))
                if getattr(args, "execute_read_only_validation", False):
                    payload = build_loop_read_only_command_execution_payload(payload, gate, repo_root=Path.cwd())
                    if getattr(args, "diagnose_read_only_result", False):
                        payload = build_loop_read_only_command_diagnosis_payload(payload)
                        if getattr(args, "generate_correction_plan", False):
                            payload = build_loop_read_only_correction_plan_payload(payload)
                            if getattr(args, "execute_sandbox_mutation", False):
                                payload = build_loop_sandbox_mutation_verification_payload(plan=plan_loop_target_file(target, execute_stubbed=True), correction_payload=payload, repo_root=Path.cwd())
                else:
                    payload = gate
        if getattr(args, "json", False):
            print(json.dumps(payload, indent=2, ensure_ascii=False))
        elif getattr(args, "state_only", False):
            print(render_loop_state_only_text(payload), end="")
        elif getattr(args, "planned_actions", False):
            print(render_loop_action_walkthrough_text(payload), end="")
        elif getattr(args, "read_only_execution", False):
            if getattr(args, "evidence_report", False):
                print(render_loop_read_only_evidence_report_text(payload), end="")
            elif getattr(args, "evidence_gate", False) and getattr(args, "execute_read_only_validation", False) and getattr(args, "diagnose_read_only_result", False) and getattr(args, "generate_correction_plan", False) and getattr(args, "execute_sandbox_mutation", False):
                print(render_loop_sandbox_mutation_verification_text(payload), end="")
            elif getattr(args, "evidence_gate", False) and getattr(args, "execute_read_only_validation", False) and getattr(args, "diagnose_read_only_result", False) and getattr(args, "generate_correction_plan", False):
                print(render_loop_read_only_correction_plan_text(payload), end="")
            elif getattr(args, "evidence_gate", False) and getattr(args, "execute_read_only_validation", False) and getattr(args, "diagnose_read_only_result", False):
                print(render_loop_read_only_command_diagnosis_text(payload), end="")
            elif getattr(args, "evidence_gate", False) and getattr(args, "execute_read_only_validation", False):
                print(render_loop_read_only_command_execution_text(payload), end="")
            elif getattr(args, "evidence_gate", False):
                print(render_loop_read_only_evidence_gate_text(payload), end="")
            else:
                print(render_loop_read_only_execution_text(payload), end="")
        else:
            print(render_loop_plan_text(payload), end="")
        return 0 if payload.get("ok") else 1
    raise RuntimeError(f"Unknown loop command: {loop_command}")


