async def cmd_task(backend: CommandBackend, args: argparse.Namespace) -> int:
    if args.task_command == "list":
        return await cmd_chat_list(backend, args)
    if args.task_command == "use":
        return await cmd_chat_use(backend, args)
    if args.task_command == "current":
        return await cmd_task_current(backend, args)
    if args.task_command == "leave":
        return await cmd_chat_leave(backend, args)
    if args.task_command == "show":
        return await cmd_chat_show(backend, args)
    if args.task_command == "messages":
        if args.task_messages_command == "list":
            return await cmd_task_messages_list(backend, args)
        raise RuntimeError(f"Unknown task messages command: {args.task_messages_command}")
    if args.task_command == "message":
        if args.task_message_command == "show":
            return await cmd_task_message_show(backend, args)
        if args.task_message_command == "answer":
            return await cmd_task_message_answer(backend, args)
        raise RuntimeError(f"Unknown task message command: {args.task_message_command}")
    if args.task_command == "answer":
        if args.task_answer_command == "parse":
            return await cmd_task_answer_parse(backend, args)
        raise RuntimeError(f"Unknown task answer command: {args.task_answer_command}")
    raise RuntimeError(f"Unknown task command: {args.task_command}")


def _accepted_current_release_identity_from_project_control(
    repo_context: Path | None = None,
) -> tuple[Optional[str], Optional[str]]:
    """Resolve the accepted/current release identity from the nearest control surface.

    Artifact registry state remains preferred.  This read-only fallback exists so
    release-control can protect the accepted baseline even when a freshly joined
    project registry has not yet adopted a record.
    """
    start = (repo_context or Path.cwd()).expanduser().resolve()
    search_roots = [start, *start.parents]
    for root in search_roots:
        plan_state = root / "docs" / "project" / "plan-state.json"
        if not plan_state.is_file():
            continue
        try:
            payload = json.loads(plan_state.read_text(encoding="utf-8"))
        except (OSError, ValueError, TypeError):
            continue
        if not isinstance(payload, dict):
            continue
        version = str(payload.get("accepted_current_version") or "").strip() or None
        artifact = Path(str(payload.get("accepted_current_artifact") or "")).name or None
        if version or artifact:
            return version, artifact
    return None, None


def _artifact_registry_from_args(args: argparse.Namespace) -> ArtifactRegistry:
    repo_context_raw = getattr(args, "repo_path", None)
    repo_context = Path(str(repo_context_raw)).expanduser().resolve() if repo_context_raw else Path.cwd().resolve()
    try:
        identity = load_repo_identity(repo_context)
    except ValueError as exc:
        raise _project_registry_failure(
            "project_identity_invalid",
            error=str(exc),
            resolution_method="identity_manifest",
        ) from exc
    if identity is None:
        raise _project_registry_failure(
            "project_scope_unresolved",
            error=f"{REPO_IDENTITY_FILE_NAME} is required under {repo_context}; initialize this repository with pb project join",
            resolution_method="identity_manifest",
        )

    repos = configured_repos(identity.project_id)
    configured = repos.get(identity.repo_id)
    if not isinstance(configured, dict):
        raise _project_registry_failure(
            "project_repo_not_configured",
            error=f"repo_id {identity.repo_id!r} is not registered in the project dataset; run pb project join",
            identity=identity,
        )
    configured_root_raw = configured.get("repo_root")
    try:
        configured_root = Path(str(configured_root_raw)).expanduser().resolve() if configured_root_raw else None
    except OSError as exc:
        raise _project_registry_failure(
            "project_repo_configuration_invalid",
            error=f"configured repo_root is invalid: {exc}",
            identity=identity,
        ) from exc
    if configured_root is None or configured_root != identity.repo_root.resolve():
        raise _project_registry_failure(
            "project_repo_root_mismatch",
            error=f"identity repo_root {identity.repo_root} does not match configured repo_root {configured_root_raw!r}",
            identity=identity,
        )

    repo_local_registry = identity.repo_root / PROFILE_DIR_NAME / "promptbranch_artifacts.json"
    if repo_local_registry.exists():
        raise _project_registry_failure(
            "legacy_repo_local_registry_detected",
            error=f"remove or archive the obsolete repo-local artifact registry before continuing: {repo_local_registry}",
            identity=identity,
        )

    registry = ArtifactRegistry(project_registry_dir(identity.project_id))
    state = registry.inspect()
    if not state.get("ok"):
        raise _project_registry_failure(
            str(state.get("status") or "artifact_registry_invalid"),
            error=str(state.get("error") or "artifact registry is unavailable"),
            identity=identity,
            registry=registry,
            registry_state=state,
        )

    registry.identity = identity  # type: ignore[attr-defined]
    registry.project_id = identity.project_id  # type: ignore[attr-defined]
    registry.repo_id = identity.repo_id  # type: ignore[attr-defined]
    registry.resolution_method = "identity_manifest"  # type: ignore[attr-defined]
    registry.registry_status = state.get("status")  # type: ignore[attr-defined]
    return registry


def _artifact_state_store(registry: ArtifactRegistry) -> ConversationStateStore:
    return ConversationStateStore(str(registry.profile_dir))


def _artifact_output_dir(args: argparse.Namespace, registry: ArtifactRegistry) -> Path:
    output_dir = getattr(args, "output_dir", None)
    return Path(output_dir).expanduser() if output_dir else registry.artifact_dir


def _artifact_state_project_url(backend: Any) -> Optional[str]:
    if backend is None:
        return None
    snapshot = backend.state_snapshot()
    candidate = snapshot.get("resolved_project_home_url") if isinstance(snapshot, dict) else None
    if not isinstance(candidate, str) or candidate == DEFAULT_PROJECT_URL:
        return None
    return candidate


def _artifact_registry_snapshot(registry: ArtifactRegistry, *, repo_id: str | None = None) -> dict[str, Any]:
    artifacts = registry.list()
    repo_ids = registry.repo_ids()
    current = registry.current(repo_id=repo_id) if repo_id else registry.current()
    return {
        "path": str(registry.path),
        "exists": registry.path.exists(),
        "current": current,
        "current_all": registry.current_all(),
        "repo_id": normalize_repo_id(repo_id),
        "repo_ids": repo_ids,
        "repo_count": len(repo_ids),
        "ambiguous_current": bool(not repo_id and registry.is_current_ambiguous()),
        "artifact_count": len(artifacts),
        "filenames": [str(item.get("filename")) for item in artifacts if item.get("filename")],
    }


def _state_artifact_summary(snapshot: dict[str, Any]) -> dict[str, Any]:
    if not isinstance(snapshot, dict):
        return {}
    return {
        "project_home_url": snapshot.get("resolved_project_home_url"),
        "repo_id": snapshot.get("artifact_repo_id"),
        "repo_count": snapshot.get("artifact_repo_count"),
        "artifact_ref": snapshot.get("artifact_ref"),
        "artifact_version": snapshot.get("artifact_version"),
        "source_ref": snapshot.get("source_ref"),
        "source_version": snapshot.get("source_version"),
    }




def _src_sync_upload_confirm_command(repo_path: Path, transaction_id: str, *, force_required: bool = False) -> str:
    parts = [
        "pb",
        "src",
        "sync",
        str(repo_path),
        "--upload",
        "--confirm-upload",
        "--confirm-transaction-id",
        transaction_id,
    ]
    if force_required:
        parts.append("--force")
    parts.append("--json")
    return shlex.join(parts)


def _artifact_release_upload_confirm_command(repo_path: Path, transaction_id: str, *, force_required: bool = False) -> str:
    parts = [
        "pb",
        "artifact",
        "release",
        str(repo_path),
        "--sync-source",
        "--upload",
        "--confirm-upload",
        "--confirm-transaction-id",
        transaction_id,
    ]
    if force_required:
        parts.append("--force")
    parts.append("--json")
    return shlex.join(parts)


def _artifact_release_status_from_source_sync(status: str | None) -> str:
    if status in {"planned", "upload_confirmation_required", "sync_mode_required"}:
        return "planned"
    if status == "verified_packaged":
        return "packaged"
    if status == "uploaded":
        return "uploaded"
    if status == "upload_ambiguous":
        return "upload_ambiguous"
    return "failed"


def _redact_source_sync_payload_for_artifact_release(payload: dict[str, Any]) -> dict[str, Any]:
    """Return diagnostic src_sync payload without executable delegated confirm commands.

    The artifact-release workflow intentionally exposes only one executable
    confirmation command at the top level: ``confirmation.confirm_command``.
    Nested src_sync details are retained for diagnostics, but their delegated
    confirmation commands are redacted to avoid operator confusion.
    """

    redacted = copy.deepcopy(payload)
    confirmation = redacted.get("confirmation")
    if isinstance(confirmation, dict):
        if confirmation.get("confirm_command"):
            confirmation.pop("confirm_command", None)
            confirmation["confirm_command_redacted"] = True
            confirmation["confirm_command_redacted_reason"] = "use top-level artifact_release confirmation.confirm_command exactly"
        confirmation.pop("source_sync_confirm_command", None)
    return redacted


def _rewrite_source_sync_payload_for_artifact_release(payload: dict[str, Any], *, repo_path: Path) -> dict[str, Any]:
    source_status = str(payload.get("status") or "")
    release_status = _artifact_release_status_from_source_sync(source_status)
    source_sync_diagnostics = _redact_source_sync_payload_for_artifact_release(payload)
    rewritten = {
        **payload,
        "action": "artifact_release",
        "status": release_status,
        "release_workflow": "artifact_release_source_sync_v1",
        "source_sync_status": source_status,
        "source_sync_action": payload.get("action"),
        "status_vocabulary": ["planned", "packaged", "uploaded", "upload_ambiguous", "failed"],
        "operator_instruction": "Run confirmation.confirm_command exactly; nested source_sync payload is diagnostic only.",
        "source_sync": source_sync_diagnostics,
    }
    confirmation = payload.get("confirmation")
    if isinstance(confirmation, dict) and payload.get("transaction_id"):
        force_required = bool((confirmation.get("force_required") is True) or ("--force" in str(confirmation.get("confirm_command") or "")))
        rewritten["confirmation"] = {
            **confirmation,
            "confirm_command": _artifact_release_upload_confirm_command(
                repo_path,
                str(payload.get("transaction_id")),
                force_required=force_required,
            ),
            "operator_instruction": "Run this top-level artifact release confirm command exactly.",
        }
        rewritten["confirmation"].pop("source_sync_confirm_command", None)
    next_commands = payload.get("next_commands")
    if isinstance(next_commands, dict):
        rewritten["next_commands"] = {
            **next_commands,
            "artifact_local_package": f"pb artifact release {shlex.quote(str(repo_path))} --sync-source --no-upload --json",
            "artifact_upload_preflight": f"pb artifact release {shlex.quote(str(repo_path))} --sync-source --upload --json",
        }
    return rewritten

def _registry_contains_artifact(registry: ArtifactRegistry, *, path: str, filename: str, sha256: str) -> bool:
    for item in registry.list():
        if not isinstance(item, dict):
            continue
        if str(item.get("path") or "") == path and str(item.get("filename") or "") == filename and str(item.get("sha256") or "") == sha256:
            return True
    return False


def _local_source_sync_verification(
    *,
    record: Any,
    registry: ArtifactRegistry,
    before_registry: dict[str, Any],
    before_state: dict[str, Any],
    after_state: dict[str, Any],
    project_url: Optional[str],
) -> dict[str, Any]:
    zip_check = verify_zip_artifact(record.path)
    after_registry = _artifact_registry_snapshot(registry)
    state_before = _state_artifact_summary(before_state)
    state_after = _state_artifact_summary(after_state)
    registry_contains = _registry_contains_artifact(
        registry,
        path=record.path,
        filename=record.filename,
        sha256=record.sha256,
    )
    state_artifact_updated = True
    if project_url:
        state_artifact_updated = (
            state_after.get("artifact_ref") == record.filename
            and state_after.get("artifact_version") == record.version
        )
    checks = {
        "zip_exists": Path(record.path).is_file(),
        "zip_crc_ok": bool(zip_check.get("ok")) and zip_check.get("testzip") is None,
        "zip_sha256_matches_record": bool(Path(record.path).is_file()) and verify_zip_artifact(record.path).get("sha256") == record.sha256,
        "registry_contains_artifact": registry_contains,
        "registry_current_matches_artifact": bool(after_registry.get("current")) and str((after_registry.get("current") or {}).get("filename") or "") == record.filename,
        "state_artifact_updated": state_artifact_updated,
        "project_source_not_mutated": True,
        "project_source_mutated": False,
    }
    required_checks = {key: value for key, value in checks.items() if key != "project_source_mutated"}
    ok = all(bool(value) for value in required_checks.values())
    return {
        "ok": ok,
        "status": "verified" if ok else "verification_failed",
        "scope": "local_artifact_only",
        "checks": checks,
        "zip": zip_check,
        "before_snapshot": {
            "artifact_registry": before_registry,
            "state": state_before,
        },
        "after_snapshot": {
            "artifact_registry": after_registry,
            "state": state_after,
        },
    }



def _source_identity_values(source: dict[str, Any]) -> set[str]:
    values: set[str] = set()
    if not isinstance(source, dict):
        return values
    for key in (
        "title",
        "name",
        "filename",
        "display_name",
        "source_ref",
        "id",
        "identity",
        "text",
        "label",
    ):
        value = source.get(key)
        if isinstance(value, str) and value.strip():
            values.add(value.strip())
    return values


def _source_stable_key(source: dict[str, Any]) -> str:
    if not isinstance(source, dict):
        return ""
    for key in ("id", "source_id", "source_ref", "title", "name", "filename", "display_name", "identity", "text"):
        value = source.get(key)
        if isinstance(value, str) and value.strip():
            return value.strip()
    return json.dumps(source, sort_keys=True, ensure_ascii=False)


def _source_filename_match_details(source: dict[str, Any], filename: str) -> dict[str, Any]:
    target = Path(str(filename or "").strip()).name
    if not target:
        return {"matched": False, "requested_filename": target, "assigned_filename": None, "match_kind": None}
    suffix = Path(target).suffix
    stem = target[:-len(suffix)] if suffix else target
    exact_pattern = re.compile(rf"(?<![A-Za-z0-9_.-])({re.escape(target)})(?![A-Za-z0-9_.-])", re.IGNORECASE)
    indexed_pattern = re.compile(
        rf"(?<![A-Za-z0-9_.-])({re.escape(stem)}\(\d+\){re.escape(suffix)})(?![A-Za-z0-9_.-])",
        re.IGNORECASE,
    )
    indexed_matches: list[str] = []
    for value in _source_identity_values(source):
        exact = exact_pattern.search(value)
        if exact:
            return {
                "matched": True,
                "requested_filename": target,
                "assigned_filename": exact.group(1),
                "match_kind": "exact_canonical",
            }
        indexed = indexed_pattern.search(value)
        if indexed and indexed.group(1).casefold() not in {item.casefold() for item in indexed_matches}:
            indexed_matches.append(indexed.group(1))
    if len(indexed_matches) == 1:
        return {
            "matched": True,
            "requested_filename": target,
            "assigned_filename": indexed_matches[0],
            "match_kind": "backend_assigned_indexed",
        }
    return {
        "matched": False,
        "requested_filename": target,
        "assigned_filename": None,
        "match_kind": "ambiguous_within_source" if len(indexed_matches) > 1 else None,
    }


def _source_matches_filename(source: dict[str, Any], filename: str) -> bool:
    return bool(_source_filename_match_details(source, filename).get("matched"))



def _operation_error_payload(operation: str, exc: Exception) -> dict[str, Any]:
    response = getattr(exc, "response", None)
    status_code = getattr(response, "status_code", None)
    response_text = None
    if response is not None:
        try:
            response_text = getattr(response, "text", None)
        except Exception:
            response_text = None
    payload: dict[str, Any] = {
        "ok": False,
        "action": operation,
        "status": "service_error",
        "exception_type": type(exc).__name__,
        "error": str(exc),
    }
    if status_code is not None:
        payload["http_status_code"] = status_code
    if response_text:
        payload["response_text"] = str(response_text)[:2000]
    return payload

def _project_sources_snapshot_from_result(result: Any) -> dict[str, Any]:
    sources, payload = _project_source_list_payload(result)
    return {
        "ok": bool(payload.get("ok")),
        "status": payload.get("status"),
        "count": len(sources),
        "sources": sources,
        "source_keys": [_source_stable_key(item) for item in sources],
        "raw": payload,
    }


def _verify_project_source_upload_change(
    *,
    before_result: Any,
    after_result: Any,
    upload_result: Any,
    expected_filename: str,
) -> dict[str, Any]:
    before = _project_sources_snapshot_from_result(before_result)
    after = _project_sources_snapshot_from_result(after_result)
    before_sources = before.get("sources") if isinstance(before.get("sources"), list) else []
    after_sources = after.get("sources") if isinstance(after.get("sources"), list) else []
    before_keys = {key for key in before.get("source_keys", []) if isinstance(key, str) and key}
    after_keys = {key for key in after.get("source_keys", []) if isinstance(key, str) and key}

    matched_before = [item for item in before_sources if isinstance(item, dict) and _source_matches_filename(item, expected_filename)]
    matched_after = [item for item in after_sources if isinstance(item, dict) and _source_matches_filename(item, expected_filename)]
    removed_keys = sorted(before_keys - after_keys)
    added_keys = sorted(after_keys - before_keys)
    expected_removed_keys = sorted({
        _source_stable_key(item)
        for item in matched_before
        if isinstance(item, dict) and _source_stable_key(item)
    } & set(removed_keys))
    collateral_removed_keys = sorted(set(removed_keys) - set(expected_removed_keys))

    upload_ok = bool(isinstance(upload_result, dict) and upload_result.get("ok"))
    checks = {
        "upload_result_ok": upload_ok,
        "before_source_list_ok": bool(before.get("ok")),
        "after_source_list_ok": bool(after.get("ok")),
        "expected_source_present_after": bool(matched_after),
        "expected_source_replaced": bool(expected_removed_keys and matched_after),
        "collateral_sources_removed": bool(collateral_removed_keys),
    }
    ok = (
        checks["upload_result_ok"]
        and checks["before_source_list_ok"]
        and checks["after_source_list_ok"]
        and checks["expected_source_present_after"]
        and not checks["collateral_sources_removed"]
    )
    ambiguous = (
        not checks["upload_result_ok"]
        and checks["before_source_list_ok"]
        and checks["after_source_list_ok"]
        and checks["expected_source_present_after"]
        and not checks["collateral_sources_removed"]
    )
    status = "verified" if ok else ("upload_ambiguous" if ambiguous else "source_upload_not_verified")
    ambiguity_reason = "upload_result_failed_but_expected_source_present_after" if ambiguous else None
    return {
        "ok": ok,
        "status": status,
        "expected_filename": expected_filename,
        "checks": checks,
        "operator_review_required": bool(ambiguous),
        "ambiguity_reason": ambiguity_reason,
        "before_snapshot": {
            "ok": before.get("ok"),
            "status": before.get("status"),
            "count": before.get("count"),
            "matching_expected_count": len(matched_before),
            "source_keys": before.get("source_keys"),
        },
        "after_snapshot": {
            "ok": after.get("ok"),
            "status": after.get("status"),
            "count": after.get("count"),
            "matching_expected_count": len(matched_after),
            "source_keys": after.get("source_keys"),
        },
        "matched_after": matched_after[:3],
        "added_source_keys": added_keys,
        "removed_source_keys": removed_keys,
        "expected_removed_source_keys": expected_removed_keys,
        "collateral_removed_source_keys": collateral_removed_keys,
        "collateral_change_detected": bool(collateral_removed_keys),
        "upload_result_status": upload_result.get("status") if isinstance(upload_result, dict) else None,
    }


async def cmd_src_sync(backend: Any, args: argparse.Namespace) -> int:
    """Package a repo snapshot and optionally upload it as a project source."""
    registry = _artifact_registry_from_args(args)
    repo_path = Path(args.path).expanduser().resolve()
    project_url = _artifact_state_project_url(backend)

    no_upload_requested = bool(getattr(args, "no_upload", False))
    upload_requested = bool(getattr(args, "upload", False) or getattr(args, "confirm_upload", False))
    confirm_upload = bool(getattr(args, "confirm_upload", False))
    confirm_transaction_id = str(getattr(args, "confirm_transaction_id", None) or "").strip()

    if no_upload_requested and upload_requested:
        payload = {
            "ok": False,
            "action": "src_sync",
            "status": "conflicting_sync_modes",
            "dry_run": bool(getattr(args, "dry_run", False)),
            "no_upload": no_upload_requested,
            "upload_requested": upload_requested,
            "confirm_upload": confirm_upload,
            "mutating_actions_executed": False,
            "project_source_mutated": False,
            "repo_path": str(repo_path),
            "error": "choose either --no-upload or --upload/--confirm-upload, not both",
        }
        print(json.dumps(payload, indent=2, ensure_ascii=False))
        return 2

    if getattr(args, "dry_run", False):
        output_dir = _artifact_output_dir(args, registry)
        try:
            plan, included = build_source_sync_preflight(
                repo_path,
                output_dir=output_dir,
                filename=getattr(args, "filename", None),
                profile_dir=registry.profile_dir,
                project_url=project_url,
                upload_requested=upload_requested,
            )
        except ValueError as exc:
            print(json.dumps({"ok": False, "action": "src_sync", "status": "plan_failed", "error": str(exc)}, indent=2, ensure_ascii=False))
            return 2
        prechecks = plan["preflight"]["preflight"]
        transaction_plan = {
            "transaction_id": plan["preflight"]["transaction_id"],
            "would_package_repo_snapshot": True,
            "would_update_artifact_registry": True,
            "would_upload_project_source": bool(upload_requested),
            "would_update_promptbranch_artifact_state": bool(project_url),
            "required_settle_conditions": plan["preflight"]["verification_plan"].get("commit_wait", []),
            "verification_plan": plan["preflight"]["verification_plan"],
            "collateral_checks": plan["preflight"]["collateral_checks"],
        }
        warnings: list[str] = []
        if upload_requested and not project_url:
            warnings.append("no current workspace is selected; live upload would fail unless you run `pb ws use <project>` first")
        artifact_plan = {**plan, "would_upload_source": bool(upload_requested)}
        payload = {
            "ok": True,
            "action": "src_sync",
            "status": "planned",
            "dry_run": True,
            "mutating_actions_executed": False,
            "repo_path": str(repo_path),
            "project_url": project_url,
            "artifact": artifact_plan,
            "included_count": len(included),
            "prechecks": prechecks,
            "before_snapshot": plan["preflight"]["before_snapshot"],
            "collateral_checks": plan["preflight"]["collateral_checks"],
            "transaction_id": plan["preflight"]["transaction_id"],
            "transaction_plan": transaction_plan,
            "warnings": warnings,
        }
        if args.json:
            print(json.dumps(payload, indent=2, ensure_ascii=False))
        else:
            print(f"status={payload['status']}")
            print(f"artifact={artifact_plan['path']}")
            print(f"file_count={artifact_plan['file_count']}")
            if warnings:
                print(f"warning={warnings[0]}")
        return 0

    output_dir = _artifact_output_dir(args, registry)
    try:
        preflight_plan, planned_included = build_source_sync_preflight(
            repo_path,
            output_dir=output_dir,
            filename=getattr(args, "filename", None),
            profile_dir=registry.profile_dir,
            project_url=project_url,
            upload_requested=upload_requested,
        )
    except ValueError as exc:
        print(json.dumps({"ok": False, "action": "src_sync", "status": "preflight_failed", "error": str(exc)}, indent=2, ensure_ascii=False))
        return 2

    collateral = preflight_plan["preflight"]["collateral_checks"]
    collision_keys = ("output_path_exists", "registry_path_collision", "registry_filename_collision")
    collisions = {key: collateral.get(key) for key in collision_keys if collateral.get(key)}
    upload_force_required = bool(upload_requested and collisions)

    if not no_upload_requested and not upload_requested:
        payload = {
            "ok": False,
            "action": "src_sync",
            "status": "sync_mode_required",
            "dry_run": False,
            "no_upload": False,
            "upload_requested": False,
            "confirm_upload": False,
            "mutating_actions_executed": False,
            "project_source_mutated": False,
            "repo_path": str(repo_path),
            "project_url": project_url,
            "artifact": {**preflight_plan, "would_upload_source": False},
            "included_count": len(planned_included),
            "preflight": preflight_plan["preflight"],
            "error": "explicit sync mode required; use --no-upload for local packaging or --upload for upload preflight",
            "next_commands": {
                "local_package": f"pb src sync {repo_path} --no-upload --json",
                "upload_preflight": f"pb src sync {repo_path} --upload --json",
            },
        }
        print(json.dumps(payload, indent=2, ensure_ascii=False))
        return 2

    if upload_requested and not confirm_upload:
        warnings: list[str] = []
        if not project_url:
            warnings.append("no current workspace is selected; confirmed upload would fail unless you run `pb ws use <project>` first")
        if upload_force_required:
            warnings.append("local artifact collision detected; confirmation command includes --force to overwrite/re-register the local package before upload")
        payload = {
            "ok": False,
            "action": "src_sync",
            "status": "upload_confirmation_required",
            "dry_run": False,
            "no_upload": False,
            "upload_requested": True,
            "confirm_upload": False,
            "mutating_actions_executed": False,
            "project_source_mutated": False,
            "repo_path": str(repo_path),
            "project_url": project_url,
            "artifact": {**preflight_plan, "would_upload_source": True},
            "included_count": len(planned_included),
            "preflight": preflight_plan["preflight"],
            "transaction_id": preflight_plan["preflight"]["transaction_id"],
            "confirmation": {
                "required": True,
                "reason": "live ChatGPT project source upload is mutating and requires explicit confirmation",
                "confirm_flag": "--confirm-upload",
                "confirm_transaction_id_flag": "--confirm-transaction-id",
                "transaction_id": preflight_plan["preflight"]["transaction_id"],
                "force_required": upload_force_required,
                "force_reason": "local artifact collision must be intentionally overwritten before upload" if upload_force_required else None,
                "confirm_command": _src_sync_upload_confirm_command(
                    repo_path,
                    preflight_plan["preflight"]["transaction_id"],
                    force_required=upload_force_required,
                ),
            },
            "warnings": warnings,
        }
        print(json.dumps(payload, indent=2, ensure_ascii=False))
        return 2

    if upload_requested and confirm_upload:
        expected_transaction_id = str(preflight_plan["preflight"].get("transaction_id") or "")
        if not confirm_transaction_id:
            payload = {
                "ok": False,
                "action": "src_sync",
                "status": "upload_transaction_id_required",
                "dry_run": False,
                "no_upload": False,
                "upload_requested": True,
                "confirm_upload": True,
                "mutating_actions_executed": False,
                "project_source_mutated": False,
                "repo_path": str(repo_path),
                "project_url": project_url,
                "artifact": {**preflight_plan, "would_upload_source": True},
                "included_count": len(planned_included),
                "preflight": preflight_plan["preflight"],
                "transaction_id": expected_transaction_id,
                "confirmation": {
                    "required": True,
                    "reason": "confirmed upload requires the transaction id from a reviewed upload preflight",
                    "confirm_flag": "--confirm-upload",
                    "confirm_transaction_id_flag": "--confirm-transaction-id",
                    "force_required": upload_force_required,
                    "force_reason": "local artifact collision must be intentionally overwritten before upload" if upload_force_required else None,
                    "confirm_command": _src_sync_upload_confirm_command(repo_path, expected_transaction_id, force_required=upload_force_required),
                },
                "error": "confirmed upload requires --confirm-transaction-id from the upload preflight",
            }
            print(json.dumps(payload, indent=2, ensure_ascii=False))
            return 2
        if confirm_transaction_id != expected_transaction_id:
            payload = {
                "ok": False,
                "action": "src_sync",
                "status": "upload_transaction_id_mismatch",
                "dry_run": False,
                "no_upload": False,
                "upload_requested": True,
                "confirm_upload": True,
                "mutating_actions_executed": False,
                "project_source_mutated": False,
                "repo_path": str(repo_path),
                "project_url": project_url,
                "artifact": {**preflight_plan, "would_upload_source": True},
                "included_count": len(planned_included),
                "preflight": preflight_plan["preflight"],
                "transaction_id": expected_transaction_id,
                "provided_transaction_id": confirm_transaction_id,
                "error": "confirmed upload transaction id does not match current preflight",
            }
            print(json.dumps(payload, indent=2, ensure_ascii=False))
            return 2

    if collisions and not getattr(args, "force", False):
        payload = {
            "ok": False,
            "action": "src_sync",
            "status": "local_artifact_collision",
            "dry_run": False,
            "no_upload": bool(getattr(args, "no_upload", False)),
            "mutating_actions_executed": False,
            "repo_path": str(repo_path),
            "project_url": project_url,
            "artifact": {**preflight_plan, "would_upload_source": bool(upload_requested)},
            "included_count": len(planned_included),
            "preflight": preflight_plan["preflight"],
            "collisions": collisions,
            "confirmation": ({
                "required": True,
                "reason": "confirmed upload also requires explicit --force because the local artifact path or registry entry already exists",
                "confirm_flag": "--confirm-upload",
                "confirm_transaction_id_flag": "--confirm-transaction-id",
                "transaction_id": preflight_plan["preflight"]["transaction_id"],
                "force_required": True,
                "force_flag": "--force",
                "confirm_command": _src_sync_upload_confirm_command(
                    repo_path,
                    preflight_plan["preflight"]["transaction_id"],
                    force_required=True,
                ),
            } if upload_requested else None),
            "error": "local artifact collision detected; rerun with --force to overwrite/register this artifact",
        }
        print(json.dumps(payload, indent=2, ensure_ascii=False))
        return 2

    if upload_requested and not project_url:
        payload = {
            "ok": False,
            "action": "src_sync",
            "status": "no_workspace_selected",
            "dry_run": False,
            "no_upload": False,
            "mutating_actions_executed": False,
            "repo_path": str(repo_path),
            "project_url": project_url,
            "artifact": {**preflight_plan, "would_upload_source": True},
            "included_count": len(planned_included),
            "preflight": preflight_plan["preflight"],
            "error": "no current workspace is selected; run `pb ws use <project>` or pass --no-upload",
        }
        print(json.dumps(payload, indent=2, ensure_ascii=False))
        return 2

    before_registry = _artifact_registry_snapshot(registry)
    before_state = backend.state_snapshot()

    try:
        record, included = create_repo_snapshot(
            repo_path,
            output_dir=output_dir,
            filename=getattr(args, "filename", None),
            kind=getattr(args, "artifact_kind", "source_snapshot"),
        )
    except ValueError as exc:
        print(json.dumps({"ok": False, "action": "src_sync", "status": "package_failed", "error": str(exc), "preflight": preflight_plan["preflight"]}, indent=2, ensure_ascii=False))
        return 2

    upload_result: dict[str, Any] | None = None
    upload_source_before_result: Any = None
    upload_source_after_result: Any = None
    source_upload_verification: dict[str, Any] | None = None
    uploaded = False
    if upload_requested:
        if not project_url:
            payload = {
                "ok": False,
                "action": "src_sync",
                "status": "no_workspace_selected",
                "artifact": record.to_dict(),
                "included_count": len(included),
                "preflight": preflight_plan["preflight"],
                "error": "no current workspace is selected; run `pb ws use <project>` or pass --no-upload",
            }
            print(json.dumps(payload, indent=2, ensure_ascii=False))
            return 2
        try:
            upload_source_before_result = await backend.list_project_sources(keep_open=args.keep_open)
        except Exception as exc:
            upload_source_before_result = _operation_error_payload("source_list_before_upload", exc)

        before_sources_snapshot = _project_sources_snapshot_from_result(upload_source_before_result)
        if not before_sources_snapshot.get("ok"):
            upload_result = {
                "ok": False,
                "action": "source_add",
                "status": "before_source_list_unavailable",
                "error": "project source list before upload was not readable; upload was not attempted",
            }
            upload_source_after_result = upload_source_before_result
        else:
            try:
                upload_result = await backend.add_project_source(
                    source_kind="file",
                    file_path=record.path,
                    display_name=record.filename,
                    keep_open=args.keep_open,
                )
            except Exception as exc:
                upload_result = _operation_error_payload("source_add", exc)
            try:
                upload_source_after_result = await backend.list_project_sources(keep_open=args.keep_open)
            except Exception as exc:
                upload_source_after_result = _operation_error_payload("source_list_after_upload", exc)

        source_upload_verification = _verify_project_source_upload_change(
            before_result=upload_source_before_result,
            after_result=upload_source_after_result,
            upload_result=upload_result,
            expected_filename=record.filename,
        )
        uploaded = bool(source_upload_verification.get("ok"))

    # Transaction rule: a live upload may write the local ZIP before the UI/API
    # trigger, but the artifact registry and Promptbranch artifact/source state
    # must not be advanced unless the project source upload verifies. Otherwise a
    # failed ChatGPT source mutation would leave local state falsely claiming the
    # new source is current. The no-upload path is intentionally local-only and
    # remains verified via _local_source_sync_verification below.
    artifact_payload: dict[str, Any] = record.to_dict()
    registry_updated = False
    state_artifact_updated = False
    state_source_updated = False
    store = _artifact_state_store(registry)
    if no_upload_requested or uploaded:
        artifact_payload = registry.add(record)
        registry_updated = True
        if project_url:
            if uploaded:
                store.remember_artifact(
                    project_url=project_url,
                    artifact_ref=record.filename,
                    artifact_version=record.version,
                    source_ref=record.filename,
                    source_version=record.version,
                )
                state_artifact_updated = True
                state_source_updated = True
            else:
                store.remember_artifact(
                    project_url=project_url,
                    artifact_ref=record.filename,
                    artifact_version=record.version,
                )
                state_artifact_updated = True
    after_state = backend.state_snapshot()
    local_verification = _local_source_sync_verification(
        record=record,
        registry=registry,
        before_registry=before_registry,
        before_state=before_state,
        after_state=after_state,
        project_url=project_url,
    )
    no_upload = no_upload_requested
    upload_ambiguous = bool(
        upload_requested
        and isinstance(source_upload_verification, dict)
        and source_upload_verification.get("status") == "upload_ambiguous"
    )
    upload_status = (
        "verified_packaged"
        if no_upload and local_verification.get("ok")
        else ("uploaded" if uploaded else ("packaged_unverified" if no_upload else ("upload_ambiguous" if upload_ambiguous else "upload_failed")))
    )
    project_source_mutation = "verified" if uploaded else ("ambiguous" if upload_ambiguous else ("not_requested" if not upload_requested else "not_verified"))
    payload = {
        "ok": bool((no_upload and local_verification.get("ok")) or uploaded),
        "action": "src_sync",
        "status": upload_status,
        "dry_run": False,
        "no_upload": no_upload,
        "upload_requested": upload_requested,
        "confirm_upload": confirm_upload,
        "mutating_actions_executed": True,
        "project_source_mutated": bool(uploaded),
        "project_source_mutation": project_source_mutation,
        "operator_review_required": bool(upload_ambiguous),
        "local_artifact_written": True,
        "artifact_registry_updated": registry_updated,
        "state_artifact_updated": state_artifact_updated,
        "state_source_updated": state_source_updated,
        "artifact": artifact_payload,
        "included_count": len(included),
        "preflight": preflight_plan["preflight"],
        "transaction_id": preflight_plan["preflight"]["transaction_id"],
        "local_verification": local_verification,
        "upload_verification": {
            "ok": bool(uploaded),
            "status": "verified" if uploaded else ("not_requested" if not upload_requested else ("upload_ambiguous" if upload_ambiguous else "upload_not_verified")),
            "project_source_mutated": bool(uploaded),
            "project_source_mutation": project_source_mutation,
            "operator_review_required": bool(upload_ambiguous),
            "artifact_registry_updated_after_upload": registry_updated if upload_requested else False,
            "state_source_updated_after_upload": state_source_updated if upload_requested else False,
            "registry_update_deferred_until_upload_verified": bool(upload_requested and not uploaded),
            "source_list_verification": source_upload_verification,
        },
        "upload_result": upload_result,
        "project_url": project_url,
    }
    if args.json:
        print(json.dumps(payload, indent=2, ensure_ascii=False))
    else:
        print(f"artifact={record.path}")
        print(f"file_count={record.file_count}")
        print(f"sha256={record.sha256}")
        print(f"status={payload['status']}")
    return 0 if payload["ok"] else 1


def _artifact_version_from_filename(filename: str) -> str | None:
    parsed = parse_canonical_artifact_filename(filename)
    return parsed["version"] if parsed else None


def _canonical_artifact_adopt_parse(filename: str, requested_repo_id: str | None = None) -> dict[str, Any]:
    parsed = parse_canonical_artifact_filename(filename)
    if parsed:
        return {
            "ok": True,
            "repo_id": parsed["repo_id"],
            "version": parsed["version"],
            "expected_canonical_filename": filename,
        }
    expected = canonical_artifact_filename(requested_repo_id or "repo", "v0.0.0")
    return {
        "ok": False,
        "status": "non_canonical_artifact_name",
        "version": None,
        "expected_canonical_filename": expected,
    }


def _artifact_prefix_from_filename(filename: str) -> str | None:
    """Return the artifact identity prefix before the final _VERSION.zip suffix.

    Worktree/transport artifact lines may intentionally use prefixes such as
    ``chatgpt_claudecode_workflow-2``. Release diagnostics must report that
    prefix explicitly instead of silently collapsing it to the canonical project
    slug.
    """

    value = Path(str(filename or "")).name
    match = re.match(r"^(?P<prefix>.+)_(?P<version>v?\d+(?:\.\d+){2,})\.zip$", value)
    if not match:
        return None
    version = match.group("version")
    if not valid_version_text(version):
        return None
    prefix = match.group("prefix").strip()
    return prefix or None


def _read_zip_version_file(path: str | Path) -> str | None:
    try:
        with zipfile.ZipFile(path) as archive:
            if "VERSION" not in archive.namelist():
                return None
            value = archive.read("VERSION").decode("utf-8", errors="replace").strip()
    except (OSError, zipfile.BadZipFile, KeyError):
        return None
    return value if valid_version_text(value) else None


def _resolve_adopt_local_zip(artifact_name: str, *, local_path: str | None, registry: ArtifactRegistry) -> Path | None:
    candidates: list[Path] = []
    if local_path:
        candidates.append(Path(local_path).expanduser())
    raw = Path(artifact_name).expanduser()
    candidates.append(raw)
    if not raw.is_absolute():
        candidates.append(Path.cwd() / raw)
        candidates.append(registry.artifact_dir / raw.name)
    seen: set[Path] = set()
    for candidate in candidates:
        try:
            resolved = candidate.resolve()
        except OSError:
            resolved = candidate.absolute()
        if resolved in seen:
            continue
        seen.add(resolved)
        if resolved.is_file():
            return resolved
    return None


def _json_objects_from_text(raw: str) -> list[dict[str, Any]]:
    decoder = json.JSONDecoder()
    objects: list[dict[str, Any]] = []
    for index, char in enumerate(raw):
        if char != "{":
            continue
        try:
            value, _end = decoder.raw_decode(raw[index:])
        except Exception:
            continue
        if isinstance(value, dict):
            objects.append(value)
    return objects


def _load_project_source_adoption_evidence(path_value: str | Path) -> dict[str, Any]:
    path = Path(path_value).expanduser()
    if not path.is_file():
        return {
            "ok": False,
            "status": "source_evidence_not_found",
            "source_evidence_path": str(path),
            "error": "Project Source adoption evidence file does not exist.",
        }
    raw = path.read_text(encoding="utf-8", errors="replace")
    candidates = [
        value for value in _json_objects_from_text(raw)
        if str(value.get("action") or "") == "add"
        and value.get("ok") is True
        and value.get("persistence_verified") is True
    ]
    if not candidates:
        return {
            "ok": False,
            "status": "source_evidence_invalid",
            "source_evidence_path": str(path),
            "error": "Evidence does not contain a successful persistent Project Source add result.",
        }
    value = candidates[-1]
    requested = Path(str(value.get("requested_filename") or value.get("source_match_requested") or "")).name
    assigned = Path(str(value.get("assigned_filename") or value.get("backend_assigned_name") or "")).name
    processed = str(value.get("processed_file_id") or "").strip()
    library_id = str(value.get("library_metadata_object_id") or "").strip()
    project_url = str(value.get("project_url") or "").strip()
    required_checks = {
        "requested_filename_present": bool(requested),
        "assigned_filename_present": bool(assigned),
        "processed_file_id_present": processed.startswith("file_"),
        "library_metadata_object_id_present": library_id.startswith("libfile_"),
        "project_url_present": project_url.startswith("https://chatgpt.com/g/"),
        "replacement_backing_identity_verified": value.get("replacement_backing_identity_verified") is True,
        "family_replacement_verified": value.get("family_replacement_verified") is True,
        "final_family_singleton": int(value.get("final_family_source_count") or 0) == 1,
    }
    ok = all(required_checks.values())
    return {
        "ok": ok,
        "status": "source_evidence_verified" if ok else "source_evidence_invalid",
        "source_evidence_path": str(path),
        "requested_filename": requested or None,
        "assigned_filename": assigned or None,
        "processed_file_id": processed or None,
        "library_metadata_object_id": library_id or None,
        "project_url": project_url or None,
        "checks": required_checks,
        "raw_evidence": value,
        "error": None if ok else "Project Source evidence is missing authoritative identity or singleton-correlation fields.",
    }


def _project_sources_matching_exact_assigned_filename(result: Any, assigned_filename: str) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    sources, payload = _project_source_list_payload(result)
    target = Path(str(assigned_filename or "")).name.casefold()
    matched: list[dict[str, Any]] = []
    for item in sources:
        if not isinstance(item, dict):
            continue
        candidates: set[str] = set()
        for value in _source_identity_values(item):
            for token in re.findall(r"[^\s]+(?:\.zip|\.txt|\.pdf|\.docx|\.xlsx|\.pptx)", value, flags=re.IGNORECASE):
                candidates.add(Path(token.rstrip(".,;:")).name.casefold())
        for key in ("assigned_filename", "filename", "name", "title"):
            value = item.get(key)
            if isinstance(value, str) and value.strip():
                candidates.add(Path(value.strip()).name.casefold())
        if target and target in candidates:
            matched.append({**item, "assigned_filename": assigned_filename, "filename_match_kind": "exact_assigned_filename"})
    payload["matching_expected_count"] = len(matched)
    payload["matching_expected"] = matched[:5]
    payload["matching_assigned_filenames"] = [assigned_filename for _ in matched]
    payload["matching_kinds"] = ["exact_assigned_filename" for _ in matched]
    return matched, payload


def _project_sources_matching_filename(result: Any, filename: str) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    sources, payload = _project_source_list_payload(result)
    matched: list[dict[str, Any]] = []
    for item in sources:
        if not isinstance(item, dict):
            continue
        details = _source_filename_match_details(item, filename)
        if not details.get("matched"):
            continue
        matched.append({
            **item,
            "requested_filename": details.get("requested_filename"),
            "assigned_filename": details.get("assigned_filename"),
            "filename_match_kind": details.get("match_kind"),
        })
    payload["matching_expected_count"] = len(matched)
    payload["matching_expected"] = matched[:5]
    payload["matching_assigned_filenames"] = [item.get("assigned_filename") for item in matched]
    payload["matching_kinds"] = [item.get("filename_match_kind") for item in matched]
    return matched, payload


def _artifact_current_repo_entries(
    current_payload: dict[str, Any],
    *,
    repo_id: str | None = None,
) -> list[tuple[str | None, dict[str, Any]]]:
    """Return entries from the mandatory project repo-loop payload."""

    if not isinstance(current_payload, dict):
        return []
    normalized_repo_id = normalize_repo_id(repo_id)
    repos = current_payload.get("repos")
    if not isinstance(repos, dict):
        return []
    entries: list[tuple[str | None, dict[str, Any]]] = []
    for key in sorted(repos):
        repo_payload = repos.get(key)
        if not isinstance(repo_payload, dict):
            continue
        entry_repo_id = normalize_repo_id(key) or key
        if normalized_repo_id and entry_repo_id != normalized_repo_id:
            continue
        entries.append((entry_repo_id, repo_payload))
    return entries


def _artifact_current_select_entry(
    current_payload: dict[str, Any],
    *,
    repo_id: str | None = None,
    filename: str | None = None,
    version: str | None = None,
) -> tuple[str | None, dict[str, Any]]:
    entries = _artifact_current_repo_entries(current_payload, repo_id=repo_id)
    expected_filename = Path(str(filename)).name if filename else None
    expected_version = _candidate_version_normalized(version) if version else None

    def score(entry: tuple[str | None, dict[str, Any]]) -> int:
        _, payload = entry
        state = payload.get("state") if isinstance(payload.get("state"), dict) else {}
        registry_current = payload.get("registry_current") if isinstance(payload.get("registry_current"), dict) else {}
        baseline_roles = payload.get("baseline_roles") if isinstance(payload.get("baseline_roles"), dict) else {}
        refs = {str(value) for value in [state.get("artifact_ref"), state.get("source_ref"), registry_current.get("filename"), baseline_roles.get("adopted_artifact_ref"), baseline_roles.get("adopted_source_ref"), baseline_roles.get("registry_current_ref")] if value}
        versions = {_candidate_version_normalized(value) for value in [state.get("artifact_version"), state.get("source_version"), registry_current.get("version"), baseline_roles.get("adopted_artifact_version"), baseline_roles.get("adopted_source_version"), baseline_roles.get("registry_current_version")] if value}
        value = 0
        if expected_filename and expected_filename in {Path(item).name for item in refs}:
            value += 2
        if expected_version and expected_version in versions:
            value += 2
        return value

    if not entries:
        return None, {}
    ranked = sorted(entries, key=score, reverse=True)
    return ranked[0]


def _artifact_current_selected_sections(
    current_payload: dict[str, Any],
    *,
    repo_id: str | None = None,
    filename: str | None = None,
    version: str | None = None,
    allow_legacy_single_payload: bool = True,
) -> dict[str, Any]:
    """Return common sections from the mandatory project repo-loop payload."""

    selected_repo_id, selected_current = _artifact_current_select_entry(
        current_payload,
        repo_id=repo_id,
        filename=filename,
        version=version,
    )
    repo_loop_entry_present = isinstance(selected_current, dict) and bool(selected_current)
    legacy_single_payload_used = False
    if not repo_loop_entry_present and allow_legacy_single_payload and any(
        isinstance(current_payload.get(key), dict)
        for key in ("state", "registry_current", "baseline_roles", "runtime", "consistency")
    ):
        selected_current = current_payload
        legacy_single_payload_used = True
    if not isinstance(selected_current, dict):
        selected_current = {}
    state = selected_current.get("state") if isinstance(selected_current.get("state"), dict) else {}
    registry_current = selected_current.get("registry_current") if isinstance(selected_current.get("registry_current"), dict) else {}
    baseline_roles = selected_current.get("baseline_roles") if isinstance(selected_current.get("baseline_roles"), dict) else {}
    runtime = selected_current.get("runtime") if isinstance(selected_current.get("runtime"), dict) else {}
    consistency = selected_current.get("consistency") if isinstance(selected_current.get("consistency"), dict) else {}
    return {
        "repo_id": selected_repo_id,
        "payload": selected_current,
        "state": state,
        "registry_current": registry_current,
        "baseline_roles": baseline_roles,
        "runtime": runtime,
        "consistency": consistency,
        "repo_loop_entry_present": repo_loop_entry_present,
        "legacy_single_payload_used": legacy_single_payload_used,
    }


def _artifact_current_payload(
    backend: Any,
    registry: ArtifactRegistry,
    *,
    repo_id: str | None = None,
    all_repos: bool = False,
    state_store: ConversationStateStore | None = None,
) -> dict[str, Any]:
    normalized_repo_id = normalize_repo_id(repo_id)
    project_url = _artifact_state_project_url(backend)
    store = state_store
    registry_state = registry.inspect()
    if not registry_state.get("ok"):
        return {
            "ok": False,
            "action": "artifact_current_all" if all_repos else "artifact_current",
            "status": registry_state.get("status"),
            "scope": {"kind": "unresolved"},
            "registry_source": "project_registry",
            "registry_file": str(registry.path),
            "registry_exists": bool(registry_state.get("registry_exists")),
            "registry_valid": bool(registry_state.get("registry_valid")),
            "registry_readable": bool(registry_state.get("registry_readable")),
            "project_id": None,
            "repo_id": normalized_repo_id or None,
            "resolution_method": "identity_manifest",
            "fallback_used": False,
            "repo_count": None,
            "repos": None,
            "missing_repo_count": None,
            "missing_repos": None,
            "error": registry_state.get("error"),
        }
    identity = getattr(registry, "identity", None)
    try:
        if identity is None:
            identity = load_repo_identity(Path.cwd())
    except ValueError as exc:
        return {
            "ok": False,
            "action": "artifact_current_all" if all_repos else "artifact_current",
            "status": "project_identity_invalid",
            "scope": {"kind": "unresolved"},
            "registry_source": "unresolved",
            "registry_file": str(registry.path),
            "registry_exists": True,
            "registry_valid": True,
            "registry_readable": True,
            "project_id": None,
            "repo_id": normalized_repo_id or None,
            "resolution_method": "identity_manifest",
            "fallback_used": False,
            "repo_count": None,
            "repos": None,
            "missing_repo_count": None,
            "missing_repos": None,
            "error": str(exc),
        }
    if identity is None:
        return {
            "ok": False,
            "action": "artifact_current_all" if all_repos else "artifact_current",
            "status": "project_scope_unresolved",
            "scope": {"kind": "unresolved"},
            "registry_source": "unresolved",
            "registry_file": str(registry.path),
            "registry_exists": True,
            "registry_valid": True,
            "registry_readable": True,
            "project_id": None,
            "repo_id": normalized_repo_id or None,
            "resolution_method": "identity_manifest",
            "fallback_used": False,
            "repo_count": None,
            "repos": None,
            "missing_repo_count": None,
            "missing_repos": None,
            "error": f"{REPO_IDENTITY_FILE_NAME} is required; run pb project join",
        }
    expected_registry = project_registry_dir(identity.project_id).resolve()
    resolver_verified = bool(getattr(registry, "resolution_method", None) == "identity_manifest")
    if not resolver_verified and registry.profile_dir.resolve() != expected_registry:
        return {
            "ok": False,
            "action": "artifact_current_all" if all_repos else "artifact_current",
            "status": "non_authoritative_artifact_registry",
            "scope": {"kind": "unresolved"},
            "registry_source": "unresolved",
            "registry_file": str(registry.path),
            "registry_exists": True,
            "registry_valid": True,
            "registry_readable": True,
            "project_id": identity.project_id,
            "repo_id": identity.repo_id,
            "resolution_method": "identity_manifest",
            "fallback_used": False,
            "repo_count": None,
            "repos": None,
            "missing_repo_count": None,
            "missing_repos": None,
            "error": f"artifact registry is not the authoritative project registry: {expected_registry}",
        }

    def snapshot_for(scope_repo_id: str | None) -> dict[str, Any]:
        if store is not None:
            return store.snapshot(project_url, repo_id=scope_repo_id)
        if backend is None:
            return {}
        snapshot = backend.state_snapshot()
        return snapshot if isinstance(snapshot, dict) else {}

    def available_repo_ids() -> list[str]:
        snapshot = snapshot_for(None)
        state_repos = (snapshot.get("artifacts_by_repo") or {}).keys() if isinstance(snapshot.get("artifacts_by_repo"), dict) else []
        configured = set(configured_repos(identity.project_id).keys())
        return sorted(set(registry.repo_ids()) | {str(item) for item in state_repos if item} | configured)

    def single_payload(scope_repo_id: str | None) -> dict[str, Any]:
        snapshot = snapshot_for(scope_repo_id)
        registry_current = registry.current(repo_id=scope_repo_id) if scope_repo_id else registry.current()
        state_has_artifact = bool(snapshot.get("artifact_ref") or snapshot.get("artifact_version") or snapshot.get("source_ref") or snapshot.get("source_version"))
        if scope_repo_id and not registry_current and not state_has_artifact:
            return {
                "ok": False,
                "action": "artifact_current",
                "status": "repo_current_not_found",
                "scope": {"kind": "repo", "repo_id": scope_repo_id},
                "state": None,
                "registry_current": None,
                "available_repos": available_repo_ids(),
                "registry_file": str(registry.path),
            }
        registry_filename = str((registry_current or {}).get("filename") or "") if registry_current else ""
        registry_version = str((registry_current or {}).get("version") or "") if registry_current else ""
        registry_source_ref = str((registry_current or {}).get("source_ref") or registry_filename or "") if registry_current else ""
        state = {
            "artifact_ref": snapshot.get("artifact_ref"),
            "artifact_version": snapshot.get("artifact_version"),
            "source_ref": snapshot.get("source_ref"),
            "source_version": snapshot.get("source_version"),
            "project_home_url": snapshot.get("resolved_project_home_url"),
            "repo_id": scope_repo_id or snapshot.get("artifact_repo_id"),
        }
        if scope_repo_id and registry_current and not state_has_artifact:
            state.update({
                "artifact_ref": registry_filename or None,
                "artifact_version": registry_version or None,
                "source_ref": registry_source_ref or None,
                "source_version": registry_version or None,
            })
        state_artifact_ref = str(state.get("artifact_ref") or "")
        state_artifact_version = str(state.get("artifact_version") or "")
        state_source_ref = str(state.get("source_ref") or "")
        state_source_version = str(state.get("source_version") or "")
        runtime_version = f"v{CLI_VERSION}" if not str(CLI_VERSION).startswith("v") else str(CLI_VERSION)
        registry_matches_state = bool(registry_current) and registry_filename == state_artifact_ref and registry_version == state_artifact_version
        state_source_matches_artifact = bool(state_artifact_ref or state_source_ref) and _source_filename_match_details({"filename": state_source_ref}, state_artifact_ref).get("matched") is True and state_artifact_version == state_source_version
        code_matches_adopted_source = runtime_version == state_source_version
        code_version_relation = (
            "runtime_source_match"
            if code_matches_adopted_source
            else ("external_repo_baseline" if scope_repo_id else "runtime_source_mismatch")
        )
        code_version_match_applicable = not bool(scope_repo_id and not code_matches_adopted_source)
        return {
            "ok": True,
            "action": "artifact_current",
            "scope": {"kind": "repo", "repo_id": scope_repo_id or identity.repo_id, "project_id": identity.project_id},
            "runtime": {
                "package_version": CLI_VERSION,
                "version": runtime_version,
            },
            "state": state,
            "registry_current": registry_current,
            "baseline_roles": {
                "runtime_code_version": runtime_version,
                "adopted_artifact_ref": state_artifact_ref or None,
                "adopted_artifact_version": state_artifact_version or None,
                "adopted_source_ref": state_source_ref or None,
                "adopted_source_version": state_source_version or None,
                "registry_current_ref": registry_filename or None,
                "registry_current_version": registry_version or None,
                "registry_current_kind": (registry_current or {}).get("kind") if registry_current else None,
                "registry_current_repo_id": (registry_current or {}).get("repo_id") if registry_current else None,
                "code_matches_adopted_source": code_matches_adopted_source,
                "code_version_relation": code_version_relation,
                "code_version_match_applicable": code_version_match_applicable,
                "note": "runtime code release may intentionally differ from the adopted Project Source baseline",
            },
            "consistency": {
                "registry_current_matches_state_artifact": registry_matches_state,
                "state_source_matches_state_artifact": state_source_matches_artifact,
                "code_version_matches_state_source": code_matches_adopted_source,
                "code_version_relation": code_version_relation,
                "code_version_match_applicable": code_version_match_applicable,
                "code_version_match_status": "matches" if code_matches_adopted_source else ("not_applicable_external_repo_baseline" if not code_version_match_applicable else "mismatch"),
                "project_home_url_present": bool(state.get("project_home_url")),
            },
            "status": str(registry_state.get("status") or "artifact_registry_loaded"),
            "registry_source": "project_registry",
            "registry_file": str(registry.path),
            "registry_exists": True,
            "registry_valid": True,
            "registry_readable": True,
            "project_id": identity.project_id,
            "repo_id": identity.repo_id,
            "resolution_method": "identity_manifest",
            "fallback_used": False,
        }

    def all_payload(repo_filter: str | None = None) -> dict[str, Any]:
        selected_repo_ids = [repo_filter] if repo_filter else available_repo_ids()
        repos: dict[str, Any] = {}
        for current_repo_id in selected_repo_ids:
            if not current_repo_id:
                continue
            repos[current_repo_id] = single_payload(current_repo_id)
        scope = {
            "kind": "project",
            "project_id": identity.project_id,
            "project_home_url": identity.project_home_url,
            "repo_id": identity.repo_id,
        }
        if repo_filter:
            scope["repo_filter"] = repo_filter
        missing = [repo_id for repo_id, repo_payload in repos.items() if isinstance(repo_payload, dict) and not repo_payload.get("ok")]
        ok = not bool(repo_filter and missing)
        payload = {
            "ok": ok,
            "action": "artifact_current_all",
            "status": str(registry_state.get("status") or "artifact_registry_loaded"),
            "scope": scope,
            "repo_count": len(repos),
            "repos": repos,
            "missing_repo_count": len(missing),
            "missing_repos": missing,
            "registry_source": "project_registry",
            "registry_file": str(registry.path),
            "registry_exists": True,
            "registry_valid": True,
            "registry_readable": True,
            "project_id": identity.project_id,
            "repo_id": identity.repo_id,
            "resolution_method": "identity_manifest",
            "fallback_used": False,
        }
        if repo_filter and missing:
            payload["status"] = "repo_current_not_found"
            payload["available_repos"] = available_repo_ids()
        return payload

    return all_payload(normalized_repo_id or None)


def _version_tuple_for_operator_order(value: Any) -> tuple[int, ...] | None:
    normalized = _candidate_version_normalized(value)
    if not normalized:
        return None
    try:
        return tuple(int(part) for part in normalized.removeprefix("v").split("."))
    except ValueError:
        return None


def _compare_operator_versions(left: Any, right: Any) -> str:
    left_tuple = _version_tuple_for_operator_order(left)
    right_tuple = _version_tuple_for_operator_order(right)
    if left_tuple is None or right_tuple is None:
        return "unknown"
    max_len = max(len(left_tuple), len(right_tuple))
    left_padded = left_tuple + (0,) * (max_len - len(left_tuple))
    right_padded = right_tuple + (0,) * (max_len - len(right_tuple))
    if left_padded == right_padded:
        return "equal"
    return "left_newer" if left_padded > right_padded else "right_newer"


def _artifact_mvp_operator_classification(
    *,
    current_payload: dict[str, Any],
    completion: dict[str, Any],
    next_payload: dict[str, Any],
    precondition: dict[str, Any],
    candidate_count: int,
) -> dict[str, Any]:
    """Derive an operator-facing lifecycle classification from raw cockpit data."""

    current_sections = _artifact_current_selected_sections(current_payload)
    baseline_roles = current_sections["baseline_roles"]
    consistency = current_sections["consistency"]
    completion_status = str(completion.get("status") or "unknown")
    recommended = next_payload.get("recommended_next_command") if isinstance(next_payload.get("recommended_next_command"), dict) else {}
    recommended_kind = str(recommended.get("kind") or "")
    accepted_candidate = completion.get("accepted_candidate") if isinstance(completion.get("accepted_candidate"), dict) else None
    selected_candidate = next_payload.get("selected_candidate") if isinstance(next_payload.get("selected_candidate"), dict) else None

    runtime_version = baseline_roles.get("runtime_code_version")
    adopted_source_version = baseline_roles.get("adopted_source_version")
    adopted_artifact_version = baseline_roles.get("adopted_artifact_version")
    registry_current_version = baseline_roles.get("registry_current_version")
    code_matches_adopted_source = bool(baseline_roles.get("code_matches_adopted_source"))
    runtime_vs_adopted_source = _compare_operator_versions(runtime_version, adopted_source_version)

    warnings: list[dict[str, Any]] = []
    blockers: list[dict[str, Any]] = []

    has_artifact_state = bool(adopted_artifact_version or baseline_roles.get("adopted_artifact_ref"))
    has_source_state = bool(adopted_source_version or baseline_roles.get("adopted_source_ref"))
    has_registry_current = bool(registry_current_version or baseline_roles.get("registry_current_ref"))
    if has_registry_current and has_artifact_state and not consistency.get("registry_current_matches_state_artifact"):
        blockers.append({
            "code": "registry_current_state_artifact_mismatch",
            "severity": "blocked",
            "message": "Artifact registry current does not match Promptbranch artifact state.",
        })
    if has_artifact_state and has_source_state and not consistency.get("state_source_matches_state_artifact"):
        blockers.append({
            "code": "state_source_artifact_mismatch",
            "severity": "blocked",
            "message": "Promptbranch source state does not match artifact state.",
        })
    if adopted_source_version and not code_matches_adopted_source:
        warnings.append({
            "code": "runtime_source_baseline_mismatch",
            "severity": "warning",
            "message": "Runtime code version differs from the adopted Project Source baseline.",
            "runtime_code_version": runtime_version,
            "adopted_source_version": adopted_source_version,
            "version_relation": runtime_vs_adopted_source,
        })
    if precondition.get("blocks_intake"):
        warnings.append({
            "code": "no_artifact_candidate_available",
            "severity": "warning",
            "message": "Latest validated protocol reply declared no_artifact and contains zero artifact candidates.",
            "reply_status": precondition.get("reply_status"),
            "result_type": precondition.get("result_type"),
        })

    candidate_verdict = "candidate_state_unknown"
    if completion.get("ok") is True or completion_status == "candidate_mvp_complete":
        candidate_verdict = "candidate_mvp_complete"
    elif completion_status == "candidate_mvp_no_artifact_candidate" or recommended_kind == "no_artifact_candidate":
        candidate_verdict = "no_candidate_available"
    elif completion_status == "candidate_mvp_test_pending" or recommended_kind == "test_candidate":
        candidate_verdict = "candidate_pending_test"
    elif completion_status == "candidate_mvp_acceptance_pending" or recommended_kind == "accept_candidate":
        candidate_verdict = "candidate_ready_for_adoption"
    elif completion_status == "candidate_mvp_intake_pending" or recommended_kind == "intake_candidate":
        candidate_verdict = "candidate_ready_for_intake"
    elif completion_status == "candidate_mvp_scope_not_found":
        candidate_verdict = "candidate_scope_not_found"

    operator_verdict = candidate_verdict
    if blockers:
        operator_verdict = "state_blocked"
    elif any(item.get("code") == "runtime_source_baseline_mismatch" for item in warnings):
        operator_verdict = "runtime_source_baseline_mismatch"

    severity_order = {"ok": 0, "info": 1, "warning": 2, "blocked": 3}
    severity = "ok"
    if warnings:
        severity = "warning"
    if blockers:
        severity = "blocked"
    warning_codes = [str(item.get("code")) for item in warnings]
    blocker_codes = [str(item.get("code")) for item in blockers]

    return {
        "operator_verdict": operator_verdict,
        "candidate_verdict": candidate_verdict,
        "severity": severity,
        "status": completion_status,
        "recommended_next_kind": recommended_kind or None,
        "versions": {
            "runtime_code_version": runtime_version,
            "adopted_project_source_version": adopted_source_version,
            "adopted_artifact_version": adopted_artifact_version,
            "registry_current_version": registry_current_version,
            "selected_candidate_version": selected_candidate.get("artifact_version") if selected_candidate else None,
            "accepted_candidate_version": accepted_candidate.get("artifact_version") if accepted_candidate else None,
            "runtime_vs_adopted_source": runtime_vs_adopted_source,
        },
        "counts": {
            "candidate_count": candidate_count,
            "accepted_candidate_count": completion.get("accepted_candidate_count"),
            "pending_counts": completion.get("pending_counts") if isinstance(completion.get("pending_counts"), dict) else {},
        },
        "checks": {
            "runtime_code_matches_adopted_source": code_matches_adopted_source,
            "registry_current_matches_state_artifact": consistency.get("registry_current_matches_state_artifact"),
            "state_source_matches_state_artifact": consistency.get("state_source_matches_state_artifact"),
            "project_home_url_present": consistency.get("project_home_url_present"),
            "candidate_available": not bool(precondition.get("blocks_intake")),
            "mvp_complete": bool(completion.get("ok")),
        },
        "warnings": warnings,
        "blockers": blockers,
        "warning_codes": warning_codes,
        "blocker_codes": blocker_codes,
        "operator_message": (
            "State integrity is blocked; inspect blockers before running artifact intake."
            if blockers else
            "Runtime code is newer or different than the adopted Project Source baseline; this may be intentional after local install, but it should be explicit before the next release."
            if operator_verdict == "runtime_source_baseline_mismatch" else
            "No artifact candidate is available; run a real release-candidate protocol ask before candidate intake."
            if candidate_verdict == "no_candidate_available" else
            "Candidate lifecycle has a clear next manual step."
            if severity == "warning" else
            "Artifact Intake MVP state is consistent."
        ),
    }


def _read_only_action(kind: str, command: str, reason: str, *, priority: int = 50) -> dict[str, Any]:
    return {
        "kind": kind,
        "command": command,
        "priority": priority,
        "mutates_state": False,
        "risk": "read",
        "reason": reason,
    }


def _decision_action(kind: str, reason: str, *, priority: int = 90) -> dict[str, Any]:
    return {
        "kind": kind,
        "command": None,
        "priority": priority,
        "mutates_state": False,
        "risk": "operator_decision",
        "reason": reason,
    }




def _release_doctor_version_from_file(repo_root: Path) -> dict[str, Any]:
    version_file = repo_root / "VERSION"
    payload: dict[str, Any] = {
        "path": str(version_file),
        "present": version_file.is_file(),
        "version": None,
        "normalized_version": None,
    }
    if not version_file.is_file():
        payload["status"] = "missing"
        return payload
    try:
        value = version_file.read_text(encoding="utf-8").strip()
    except OSError as exc:
        payload.update({"status": "read_error", "error": str(exc)})
        return payload
    payload["version"] = value
    payload["normalized_version"] = _candidate_version_normalized(value)
    payload["status"] = "verified" if payload["normalized_version"] else "invalid"
    return payload


def _release_doctor_installed_distribution() -> dict[str, Any]:
    try:
        value = importlib.metadata.version("promptbranch")
    except importlib.metadata.PackageNotFoundError:
        return {"present": False, "version": None, "normalized_version": None, "status": "not_installed"}
    except Exception as exc:  # pragma: no cover - defensive metadata guard
        return {"present": False, "version": None, "normalized_version": None, "status": "read_error", "error": str(exc)}
    return {
        "present": True,
        "version": value,
        "normalized_version": _candidate_version_normalized(value),
        "status": "verified" if value else "missing",
    }


def _release_doctor_git_status(repo_root: Path) -> dict[str, Any]:
    payload: dict[str, Any] = {
        "repo_path": str(repo_root),
        "is_git_repo": False,
        "dirty": None,
        "branch": None,
        "short_sha": None,
        "upstream": None,
        "status_lines": [],
        "status": "unknown",
    }
    try:
        top = subprocess.run(["git", "rev-parse", "--show-toplevel"], cwd=str(repo_root), text=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=3.0, check=False)
    except (OSError, subprocess.SubprocessError) as exc:
        payload.update({"status": "git_unavailable", "error": str(exc)})
        return payload
    if top.returncode != 0:
        payload.update({"status": "not_git_repo", "error": top.stderr.strip()})
        return payload
    payload["is_git_repo"] = True
    payload["git_root"] = top.stdout.strip()
    try:
        branch = subprocess.run(["git", "branch", "--show-current"], cwd=str(repo_root), text=True, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, timeout=3.0, check=False)
        sha = subprocess.run(["git", "rev-parse", "--short", "HEAD"], cwd=str(repo_root), text=True, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, timeout=3.0, check=False)
        upstream = subprocess.run(["git", "rev-parse", "--abbrev-ref", "--symbolic-full-name", "@{u}"], cwd=str(repo_root), text=True, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, timeout=3.0, check=False)
        status = subprocess.run(["git", "status", "--short", "--branch"], cwd=str(repo_root), text=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=5.0, check=False)
    except (OSError, subprocess.SubprocessError) as exc:
        payload.update({"status": "git_status_error", "error": str(exc)})
        return payload
    lines = [line for line in status.stdout.splitlines() if line.strip()]
    dirty_lines = [line for line in lines if not line.startswith("##")]
    payload.update({
        "branch": branch.stdout.strip() if branch.returncode == 0 else None,
        "short_sha": sha.stdout.strip() if sha.returncode == 0 else None,
        "upstream": upstream.stdout.strip() if upstream.returncode == 0 else None,
        "dirty": bool(dirty_lines),
        "status_lines": lines[:80],
        "dirty_count": len(dirty_lines),
        "status": "verified" if status.returncode == 0 else "git_status_error",
    })
    if status.returncode != 0:
        payload["error"] = status.stderr.strip()
    return payload


def _release_doctor_http_json(url: str, *, timeout_seconds: float) -> dict[str, Any]:
    payload: dict[str, Any] = {
        "url": url,
        "attempted": True,
        "ok": False,
        "status": "unavailable",
        "http_status": None,
        "version": None,
        "normalized_version": None,
    }
    try:
        request = urllib.request.Request(url, headers={"Accept": "application/json"})
        with urllib.request.urlopen(request, timeout=max(0.2, float(timeout_seconds))) as response:
            body = response.read(256 * 1024)
            payload["http_status"] = getattr(response, "status", None)
    except Exception as exc:
        payload.update({"error": str(exc), "status": "request_failed"})
        return payload
    try:
        parsed = json.loads(body.decode("utf-8"))
    except Exception as exc:
        payload.update({"error": f"invalid json: {exc}", "body_preview": body[:300].decode("utf-8", errors="replace"), "status": "invalid_json"})
        return payload
    version = parsed.get("version") or parsed.get("service_version") or parsed.get("package_version")
    payload.update({
        "ok": bool(parsed.get("ok", True)),
        "status": "verified",
        "payload": parsed,
        "version": version,
        "normalized_version": _candidate_version_normalized(version),
    })
    return payload




def _release_doctor_artifact_summary(artifact_arg: str | None, *, repo_root: Path) -> dict[str, Any]:
    """Inspect a candidate artifact ZIP without mutating release state."""

    raw = str(artifact_arg or "").strip()
    if not raw:
        return {
            "attempted": False,
            "ok": None,
            "status": "not_requested",
            "path": None,
            "filename": None,
            "version": None,
            "normalized_version": None,
        }

    candidate_path = Path(raw).expanduser()
    if not candidate_path.is_absolute():
        candidate_path = repo_root / candidate_path
    try:
        resolved = candidate_path.resolve()
    except OSError:
        resolved = candidate_path.absolute()

    filename = resolved.name
    filename_version = _artifact_version_from_filename(filename)
    artifact_prefix = _artifact_prefix_from_filename(filename)
    filename_has_version_suffix = bool(filename_version)
    payload: dict[str, Any] = {
        "attempted": True,
        "path": str(resolved),
        "filename": filename,
        "artifact_prefix": artifact_prefix,
        "artifact_identity": artifact_prefix,
        "artifact_line": artifact_prefix,
        "zip_suffix": ".zip",
        "filename_has_version_suffix": filename_has_version_suffix,
        "present": resolved.is_file(),
        "filename_version": filename_version,
        "filename_version_normalized": _candidate_version_normalized(filename_version),
        "version_file": None,
        "version_file_normalized": None,
        "version": None,
        "normalized_version": None,
        "verification": None,
        "status": "missing" if not resolved.is_file() else "unknown",
        "ok": False,
        "read_only": True,
        "mutating_actions_executed": False,
    }
    if not resolved.is_file():
        payload["error"] = "artifact_not_found"
        return payload

    verification = verify_zip_artifact(resolved)
    zip_version = _read_zip_version_file(resolved)
    normalized_zip_version = _candidate_version_normalized(zip_version)
    normalized_filename_version = _candidate_version_normalized(filename_version)
    version = normalized_zip_version or normalized_filename_version
    version_mismatch = bool(normalized_zip_version and normalized_filename_version and normalized_zip_version != normalized_filename_version)
    blocking_errors: list[str] = []
    if not verification.get("ok"):
        blocking_errors.append("artifact_zip_verification_failed")
    if not normalized_zip_version:
        blocking_errors.append("artifact_version_file_missing_or_invalid")
    if version_mismatch:
        blocking_errors.append("artifact_filename_version_mismatch")
    if filename.lower().endswith(".zip") and not filename_has_version_suffix:
        blocking_errors.append("artifact_filename_version_missing_or_invalid")

    layout_checks = {
        "zip_opens": verification.get("error") != "bad_zip",
        "has_version_file": bool(verification.get("has_version_file")),
        "version_file_valid": bool(normalized_zip_version),
        "filename_version_valid": bool(normalized_filename_version),
        "version_file_matches_filename": not version_mismatch,
        "root_has_no_wrapper_folder": verification.get("wrapper_folder") is None,
        "no_unsafe_entries": not bool(verification.get("unsafe_entries")),
        "no_hygiene_violations": int(verification.get("hygiene_violation_count") or 0) == 0,
        "no_nested_zip_entries": int(verification.get("nested_zip_count") or 0) == 0,
    }

    payload.update({
        "verification": verification,
        "version_file": zip_version,
        "version_file_normalized": normalized_zip_version,
        "version": version,
        "normalized_version": version,
        "version_file_matches_filename": not version_mismatch,
        "sha256": verification.get("sha256"),
        "size_bytes": verification.get("size_bytes"),
        "entry_count": verification.get("entry_count"),
        "wrapper_folder": verification.get("wrapper_folder"),
        "hygiene_violation_count": verification.get("hygiene_violation_count"),
        "nested_zip_count": verification.get("nested_zip_count"),
        "layout_checks": layout_checks,
        "blocking_errors": blocking_errors,
        "ok": not blocking_errors,
        "status": "verified" if not blocking_errors else "blocked",
    })
    return payload


def _release_doctor_artifact_consistency(
    *,
    artifact: dict[str, Any],
    expected: dict[str, Any],
    version_file: dict[str, Any],
    artifact_current: dict[str, Any],
    project_sources: dict[str, Any],
) -> dict[str, Any]:
    """Compare an inspected ZIP against runtime, VERSION, source, and adopted state."""

    if not artifact.get("attempted"):
        return {
            "attempted": False,
            "ok": True,
            "severity": "not_requested",
            "warnings": [],
            "blockers": [],
            "warning_codes": [],
            "blocker_codes": [],
            "checks": {},
        }

    runtime_version = expected.get("runtime_version_normalized")
    requested_version = expected.get("requested_version_normalized")
    target_version = expected.get("target_version_normalized")
    version_file_value = version_file.get("normalized_version")
    artifact_version = artifact.get("normalized_version")
    artifact_current_sections = _artifact_current_selected_sections(artifact_current)
    baseline_roles = artifact_current_sections["baseline_roles"]
    adopted_source = baseline_roles.get("adopted_source_version")
    adopted_artifact = baseline_roles.get("adopted_artifact_version")
    registry_current = baseline_roles.get("registry_current_version")
    source_versions = [item.get("normalized_version") for item in project_sources.get("detected_versions", []) if item.get("normalized_version")]

    warnings: list[dict[str, Any]] = []
    blockers: list[dict[str, Any]] = []

    def warn(code: str, message: str, **extra: Any) -> None:
        warnings.append({"code": code, "severity": "warning", "message": message, **extra})

    def block(code: str, message: str, **extra: Any) -> None:
        blockers.append({"code": code, "severity": "blocked", "message": message, **extra})

    for code in artifact.get("blocking_errors") or []:
        block(str(code), "Candidate artifact ZIP failed release-doctor verification.", artifact_path=artifact.get("path"))

    if artifact_version and runtime_version and artifact_version != runtime_version:
        warn("artifact_runtime_version_mismatch", "Candidate ZIP version differs from runtime code version.", artifact_version=artifact_version, runtime_version=runtime_version, version_relation=_compare_operator_versions(runtime_version, artifact_version))
    if artifact_version and requested_version and artifact_version != requested_version:
        warn("artifact_requested_version_mismatch", "Candidate ZIP version differs from the requested release-doctor --version value.", artifact_version=artifact_version, requested_version=requested_version, version_relation=_compare_operator_versions(requested_version, artifact_version))
    if artifact_version and target_version and artifact_version != target_version:
        warn("artifact_target_version_mismatch", "Candidate ZIP version differs from the requested release-doctor --target-version value.", artifact_version=artifact_version, target_version=target_version, version_relation=_compare_operator_versions(target_version, artifact_version))
    if artifact_version and version_file_value and artifact_version != version_file_value:
        warn("artifact_version_file_mismatch", "Candidate ZIP version differs from working-tree VERSION file.", artifact_version=artifact_version, version_file_version=version_file_value)
    if project_sources.get("attempted") and artifact_version and artifact_version not in source_versions:
        warn("artifact_version_not_visible_in_project_sources", "Candidate ZIP version was not detected in Project Sources.", artifact_version=artifact_version, detected_versions=source_versions)

    checks = {
        "artifact_zip_verified": bool(artifact.get("ok")),
        "artifact_matches_runtime": not artifact_version or not runtime_version or artifact_version == runtime_version,
        "artifact_matches_requested_version": not artifact_version or not requested_version or artifact_version == requested_version,
        "artifact_matches_target_version": not artifact_version or not target_version or artifact_version == target_version,
        "artifact_matches_version_file": not artifact_version or not version_file_value or artifact_version == version_file_value,
        "artifact_visible_in_project_sources": (not project_sources.get("attempted")) or (not artifact_version) or artifact_version in source_versions,
        "artifact_matches_adopted_source": not artifact_version or not adopted_source or artifact_version == adopted_source,
        "artifact_matches_adopted_artifact": not artifact_version or not adopted_artifact or artifact_version == adopted_artifact,
        "artifact_matches_registry_current": not artifact_version or not registry_current or artifact_version == registry_current,
        "artifact_prefix_present": bool(artifact.get("artifact_prefix")),
        "artifact_filename_version_valid": bool(artifact.get("filename_version_normalized")),
    }
    severity = "blocked" if blockers else "warning" if warnings else "ok"
    return {
        "attempted": True,
        "ok": not blockers,
        "severity": severity,
        "warnings": warnings,
        "blockers": blockers,
        "warning_codes": [item["code"] for item in warnings],
        "blocker_codes": [item["code"] for item in blockers],
        "checks": checks,
    }



def _release_doctor_config_summary_for_doctor(config_payload: dict[str, Any]) -> dict[str, Any]:
    """Return the compact release-config linkage used by release doctor.

    The doctor consumes the same read-only config parser as ``pb release config``
    and exposes only the contract details needed to reason about a candidate ZIP.
    It must not execute hooks or mutate release state.
    """

    artifact = config_payload.get("artifact") if isinstance(config_payload.get("artifact"), dict) else {}
    config = config_payload.get("config") if isinstance(config_payload.get("config"), dict) else {}
    return {
        "ok": bool(config_payload.get("ok")),
        "status": config_payload.get("status") or ("verified" if config_payload.get("ok") else "missing"),
        "path": config_payload.get("path"),
        "present": bool(config_payload.get("present")),
        "schema_version": config.get("schema_version"),
        "artifact_prefix": artifact.get("prefix"),
        "artifact_version_prefix": artifact.get("version_prefix"),
        "artifact_suffix": artifact.get("suffix"),
        "version_file": artifact.get("version_file"),
        "policy_file": artifact.get("policy_file"),
        "read_only": True,
        "mutating_actions_executed": False,
        "warning_codes": list(config_payload.get("warning_codes") or []),
        "blocker_codes": list(config_payload.get("blocker_codes") or []),
    }



def _release_doctor_candidate_artifact_report(
    *,
    artifact: dict[str, Any],
    config_payload: dict[str, Any],
    expected: dict[str, Any],
    artifact_current: dict[str, Any],
) -> dict[str, Any]:
    """Summarize candidate ZIP prechecks using release config and current baseline.

    This is intentionally read-only. It converts the lower-level
    ``artifact_inspection`` result into a lifecycle-doctor-facing contract that
    is stable for scripts and future lifecycle phases.
    """

    attempted = bool(artifact.get("attempted"))
    release_config = _release_doctor_config_summary_for_doctor(config_payload)
    warnings: list[dict[str, Any]] = []
    blockers: list[dict[str, Any]] = []

    def warn(code: str, message: str, **extra: Any) -> None:
        warnings.append({"code": code, "severity": "warning", "message": message, **extra})

    def block(code: str, message: str, **extra: Any) -> None:
        blockers.append({"code": code, "severity": "blocked", "message": message, **extra})

    if not attempted:
        return {
            "attempted": False,
            "ok": None,
            "status": "not_requested",
            "read_only": True,
            "mutating_actions_executed": False,
            "release_config": release_config,
            "warning_codes": [],
            "blocker_codes": [],
            "warnings": [],
            "blockers": [],
        }

    artifact_path = artifact.get("path")
    filename = artifact.get("filename")
    artifact_version = _candidate_version_normalized(artifact.get("normalized_version") or artifact.get("version") or artifact.get("version_file") or artifact.get("filename_version"))
    requested_version = expected.get("requested_version_normalized")
    target_version = expected.get("target_version_normalized")
    version_file_value = artifact.get("version_file")
    version_file_normalized = _candidate_version_normalized(version_file_value)
    layout = artifact.get("layout_checks") if isinstance(artifact.get("layout_checks"), dict) else {}
    config = config_payload.get("config") if isinstance(config_payload.get("config"), dict) else {}
    artifact_cfg = config.get("artifact") if isinstance(config.get("artifact"), dict) else {}
    prefix = artifact_cfg.get("prefix")
    version_prefix = artifact_cfg.get("version_prefix")
    suffix = artifact_cfg.get("suffix")
    expected_filename = None
    if prefix and suffix and artifact_version:
        version_token = artifact_version
        if version_prefix and not version_token.startswith(str(version_prefix)):
            version_token = f"{version_prefix}{version_token.removeprefix('v')}"
        expected_filename = f"{prefix}{version_token}{suffix}"
    filename_matches_config = bool(expected_filename and filename == expected_filename)

    artifact_current_sections = _artifact_current_selected_sections(artifact_current)
    baseline_roles = artifact_current_sections["baseline_roles"]
    current_baseline_version = _candidate_version_normalized(
        baseline_roles.get("registry_current_version")
        or baseline_roles.get("adopted_source_version")
        or baseline_roles.get("adopted_artifact_version")
    )
    current_baseline_ref = (
        baseline_roles.get("registry_current_ref")
        or baseline_roles.get("adopted_source_ref")
        or baseline_roles.get("adopted_artifact_ref")
    )
    expected_next_normal = _release_expected_next_normal_version(current_baseline_version)
    candidate_shape = _release_version_shape(artifact_version)
    baseline_ok = True
    baseline_relation = _compare_operator_versions(current_baseline_version, artifact_version) if current_baseline_version and artifact_version else "unknown"
    if current_baseline_version and artifact_version:
        if candidate_shape == "normal":
            baseline_ok = artifact_version == expected_next_normal
        elif candidate_shape == "repair":
            baseline_ok = bool(artifact_version.startswith(f"{current_baseline_version}."))
        else:
            baseline_ok = False

    zip_opens = bool(layout.get("zip_opens"))
    wrapper_ok = bool(layout.get("root_has_no_wrapper_folder"))
    hygiene_ok = bool(layout.get("no_hygiene_violations"))
    nested_zip_ok = bool(layout.get("no_nested_zip_entries"))
    version_file_present = bool(layout.get("has_version_file"))
    version_matches_requested = (not requested_version) or (artifact_version == requested_version)
    version_matches_target = (not target_version) or (artifact_version == target_version)

    if not artifact.get("present"):
        block("candidate_artifact_missing", "Candidate artifact path does not exist.", path=artifact_path)
    if not zip_opens:
        block("candidate_artifact_zip_invalid", "Candidate artifact is not a readable ZIP.", path=artifact_path)
    if not wrapper_ok:
        block("candidate_artifact_wrapper_folder", "Candidate ZIP contains a wrapper folder instead of repo contents at root.", wrapper_folder=artifact.get("wrapper_folder"))
    if not hygiene_ok:
        block("candidate_artifact_hygiene_failed", "Candidate ZIP contains generated, cached, temporary, or local-environment files.", hygiene_violation_count=artifact.get("hygiene_violation_count"))
    if not nested_zip_ok:
        block("candidate_artifact_nested_zip", "Candidate ZIP contains nested ZIP entries.", nested_zip_count=artifact.get("nested_zip_count"))
    if not version_file_present or not version_file_normalized:
        block("candidate_artifact_wrong_version", "Candidate ZIP does not contain a valid VERSION file.", version_file_value=version_file_value)
    if requested_version and artifact_version and artifact_version != requested_version:
        warn("candidate_artifact_wrong_version", "Candidate ZIP version differs from requested --version.", artifact_version=artifact_version, requested_version=requested_version)
    if target_version and artifact_version and artifact_version != target_version:
        warn("candidate_artifact_target_version_mismatch", "Candidate ZIP version differs from requested --target-version.", artifact_version=artifact_version, target_version=target_version)
    if config_payload.get("present") and not config_payload.get("ok"):
        block("release_config_invalid", "Release config exists but did not validate.", blocker_codes=config_payload.get("blocker_codes") or [])
    if not config_payload.get("present"):
        warn("release_config_missing", "Release config is missing; filename/config matching was skipped.", path=config_payload.get("path"))
    elif expected_filename and not filename_matches_config:
        block("candidate_artifact_wrong_filename", "Candidate filename does not match .promptbranch-release.yml artifact naming policy.", filename=filename, expected_filename=expected_filename)
    if current_baseline_version and artifact_version and not baseline_ok:
        block("candidate_artifact_baseline_mismatch", "Candidate version does not match the expected next release from the accepted baseline.", current_baseline=current_baseline_version, expected_next_normal_version=expected_next_normal, candidate_version=artifact_version)

    status = "blocked" if blockers else "warning" if warnings else "verified"
    return {
        "attempted": True,
        "ok": not blockers,
        "status": status,
        "severity": "blocked" if blockers else ("warning" if warnings else "ok"),
        "path": artifact_path,
        "filename": filename,
        "exists": bool(artifact.get("present")),
        "sha256": artifact.get("sha256"),
        "size_bytes": artifact.get("size_bytes"),
        "file_count": artifact.get("entry_count"),
        "entry_count": artifact.get("entry_count"),
        "version": artifact_version,
        "normalized_version": artifact_version,
        "version_matches_requested": version_matches_requested,
        "version_matches_target": version_matches_target,
        "filename_matches_config": filename_matches_config,
        "expected_filename_from_config": expected_filename,
        "zip_opens": zip_opens,
        "zip_root_is_repo_contents": wrapper_ok,
        "version_file_present": version_file_present,
        "version_file_value": version_file_value,
        "hygiene_ok": hygiene_ok,
        "nested_zip_ok": nested_zip_ok,
        "release_config": release_config,
        "baseline_continuity": {
            "ok": baseline_ok,
            "current_baseline": current_baseline_ref,
            "current_baseline_version": current_baseline_version,
            "candidate_version": artifact_version,
            "candidate_shape": candidate_shape,
            "version_relation": baseline_relation,
            "expected_next_normal_version": expected_next_normal,
        },
        "read_only": True,
        "mutating_actions_executed": False,
        "warnings": warnings,
        "blockers": blockers,
        "warning_codes": [item["code"] for item in warnings],
        "blocker_codes": [item["code"] for item in blockers],
    }


def _release_doctor_lifecycle_phase(
    *,
    consistency: dict[str, Any],
    artifact_consistency: dict[str, Any],
    artifact: dict[str, Any],
    expected: dict[str, Any],
    artifact_current: dict[str, Any],
    project_sources: dict[str, Any],
) -> dict[str, Any]:
    runtime_version = expected.get("runtime_version_normalized")
    artifact_version = artifact.get("normalized_version") if artifact.get("attempted") else None
    artifact_current_sections = _artifact_current_selected_sections(artifact_current)
    baseline_roles = artifact_current_sections["baseline_roles"]
    adopted_source = baseline_roles.get("adopted_source_version")
    adopted_artifact = baseline_roles.get("adopted_artifact_version")
    registry_current = baseline_roles.get("registry_current_version")
    source_versions = [item.get("normalized_version") for item in project_sources.get("detected_versions", []) if item.get("normalized_version")]

    combined_blockers = list(consistency.get("blocker_codes") or []) + list(artifact_consistency.get("blocker_codes") or [])
    if combined_blockers:
        phase = "lifecycle_blocked"
    elif artifact.get("attempted") and artifact_version:
        artifact_visible = bool(project_sources.get("attempted")) and artifact_version in source_versions
        adopted_matches = artifact_version in {adopted_source, adopted_artifact, registry_current}
        source_visibility_satisfied = (not project_sources.get("attempted")) or artifact_visible
        all_aligned = (
            artifact.get("ok") is True
            and (not runtime_version or artifact_version == runtime_version)
            and source_visibility_satisfied
            and adopted_matches
        )
        if all_aligned:
            phase = "lifecycle_ready"
        elif adopted_matches:
            phase = "adopted_current"
        elif artifact_visible:
            phase = "project_source_uploaded"
        else:
            phase = "candidate_zip_available"
    elif runtime_version and runtime_version in {adopted_source, adopted_artifact, registry_current}:
        phase = "adopted_current"
    else:
        phase = "runtime_only"

    return {
        "phase": phase,
        "blocked": phase == "lifecycle_blocked",
        "artifact_version": artifact_version,
        "artifact_prefix": artifact.get("artifact_prefix") if artifact.get("attempted") else None,
        "artifact_filename": artifact.get("filename") if artifact.get("attempted") else None,
        "runtime_version": runtime_version,
        "adopted_source_version": adopted_source,
        "adopted_artifact_version": adopted_artifact,
        "registry_current_version": registry_current,
        "project_source_versions": source_versions,
        "artifact_requested": bool(artifact.get("attempted")),
        "artifact_verified": bool(artifact.get("ok")) if artifact.get("attempted") else None,
        "artifact_matches_adopted": artifact_version in {adopted_source, adopted_artifact, registry_current} if artifact_version else None,
        "artifact_visible_in_project_sources": (artifact_version in source_versions) if artifact_version and project_sources.get("attempted") else None,
    }

def _release_doctor_source_versions(sources: list[dict[str, Any]]) -> dict[str, Any]:
    versions: list[dict[str, Any]] = []
    seen: set[tuple[str | None, str | None]] = set()
    version_re = re.compile(r"(?P<version>v?\d+\.\d+\.\d+(?:\.\d+)?)")
    for item in sources:
        fields = [
            str(item.get("title") or ""),
            str(item.get("name") or ""),
            str(item.get("identity") or ""),
            str(item.get("filename") or ""),
            str(item.get("source_name") or ""),
        ]
        joined = " ".join(value for value in fields if value)
        match = version_re.search(joined)
        if not match:
            continue
        raw_version = match.group("version")
        normalized = _candidate_version_normalized(raw_version)
        title = next((value for value in fields if value), None)
        key = (title, normalized)
        if key in seen:
            continue
        seen.add(key)
        versions.append({
            "title": title,
            "version": raw_version,
            "normalized_version": normalized,
            "identity": item.get("identity"),
            "kind": item.get("kind") or item.get("source_kind") or item.get("type"),
        })
    return {
        "count": len(sources),
        "detected_version_count": len(versions),
        "detected_versions": versions,
    }


def _release_doctor_expected_versions(*, requested_version: str | None, target_version: str | None, runtime_version: str | None) -> dict[str, Any]:
    return {
        "requested_version": requested_version,
        "requested_version_normalized": _candidate_version_normalized(requested_version),
        "target_version": target_version,
        "target_version_normalized": _candidate_version_normalized(target_version),
        "runtime_version": runtime_version,
        "runtime_version_normalized": _candidate_version_normalized(runtime_version),
    }



_RELEASE_CONFIG_ALLOWED_PLACEHOLDERS = {"version", "target_version", "artifact", "repo_path"}
_RELEASE_CONFIG_REQUIRED_TOP_LEVEL = {"schema_version", "artifact", "install", "git", "hooks"}


def _strip_yaml_comment(line: str) -> str:
    """Strip YAML comments outside simple single/double quoted strings."""

    in_single = False
    in_double = False
    escaped = False
    for index, char in enumerate(line):
        if escaped:
            escaped = False
            continue
        if char == "\\" and in_double:
            escaped = True
            continue
        if char == "'" and not in_double:
            in_single = not in_single
            continue
        if char == '"' and not in_single:
            in_double = not in_double
            continue
        if char == "#" and not in_single and not in_double:
            return line[:index].rstrip()
    return line.rstrip()


def _parse_release_config_scalar(value: str) -> Any:
    value = value.strip()
    if value == "":
        return ""
    if (value.startswith('"') and value.endswith('"')) or (value.startswith("'") and value.endswith("'")):
        return value[1:-1]
    lowered = value.lower()
    if lowered in {"true", "false"}:
        return lowered == "true"
    if lowered in {"null", "none", "~"}:
        return None
    if re.fullmatch(r"-?[0-9]+", value):
        try:
            return int(value)
        except ValueError:
            pass
    if value.startswith("[") and value.endswith("]"):
        inner = value[1:-1].strip()
        if not inner:
            return []
        return [_parse_release_config_scalar(part.strip()) for part in inner.split(",")]
    return value


def _parse_release_config_yaml_subset(text: str) -> dict[str, Any]:
    """Parse the small .promptbranch-release.yml subset used by Promptbranch.

    This intentionally avoids an optional PyYAML dependency. Supported shapes are
    nested mappings, scalar values, and lists of scalar values. That is enough for
    artifact/install/git/hooks release lifecycle configuration.
    """

    logical_lines: list[tuple[int, str]] = []
    for raw_line in text.splitlines():
        line_without_comment = _strip_yaml_comment(raw_line)
        if not line_without_comment.strip():
            continue
        leading = line_without_comment[: len(line_without_comment) - len(line_without_comment.lstrip(" \t"))]
        if "\t" in leading:
            raise ValueError("tabs are not supported in release config indentation")
        logical_lines.append((len(leading), line_without_comment.strip()))

    def next_is_list(index: int, indent: int) -> bool:
        if index + 1 >= len(logical_lines):
            return False
        next_indent, next_stripped = logical_lines[index + 1]
        return next_indent > indent and next_stripped.startswith("- ")

    root: dict[str, Any] = {}
    stack: list[tuple[int, Any]] = [(-1, root)]

    for index, (indent, stripped) in enumerate(logical_lines):
        while stack and indent <= stack[-1][0]:
            stack.pop()
        if not stack:
            raise ValueError(f"invalid indentation near: {stripped}")
        parent = stack[-1][1]
        if stripped.startswith("- "):
            if not isinstance(parent, list):
                raise ValueError(f"list item without list parent near: {stripped}")
            item_value = stripped[2:].strip()
            if ":" in item_value and not item_value.startswith(('"', "'")):
                key, value = item_value.split(":", 1)
                item: dict[str, Any] = {}
                key = key.strip()
                if not key:
                    raise ValueError(f"empty list item key near: {stripped}")
                if value.strip():
                    item[key] = _parse_release_config_scalar(value.strip())
                else:
                    child: dict[str, Any] | list[Any]
                    child = [] if next_is_list(index, indent) else {}
                    item[key] = child
                    stack.append((indent, child))
                parent.append(item)
            else:
                parent.append(_parse_release_config_scalar(item_value))
            continue
        if ":" not in stripped:
            raise ValueError(f"expected key/value pair near: {stripped}")
        if not isinstance(parent, dict):
            raise ValueError(f"mapping entry parent is not a mapping near: {stripped}")
        key, value = stripped.split(":", 1)
        key = key.strip()
        value = value.strip()
        if not key:
            raise ValueError(f"empty key near: {stripped}")
        if key in parent:
            raise ValueError(f"duplicate key near: {stripped}")
        if value:
            parent[key] = _parse_release_config_scalar(value)
        else:
            child = [] if next_is_list(index, indent) else {}
            parent[key] = child
            stack.append((indent, child))
    return root

def _release_config_path_status(path_value: Any, *, allow_glob: bool = False) -> tuple[bool, str | None]:
    path_text = str(path_value or "").strip()
    if not path_text:
        return False, "path_empty"
    if path_text.startswith("/"):
        return False, "path_must_be_repo_relative"
    parts = Path(path_text).parts
    if ".." in parts:
        return False, "path_must_not_escape_repo"
    if not allow_glob and any(char in path_text for char in "*?["):
        return False, "glob_not_allowed_here"
    return True, None


def _release_config_command_placeholders(command: str) -> set[str]:
    names: set[str] = set()
    for match in re.finditer(r"(?<!\{)\{([A-Za-z_][A-Za-z0-9_]*)\}(?!\})", command):
        names.add(match.group(1))
    return names


def _release_config_artifact_token_status(value: Any, *, field: str) -> tuple[bool, str | None]:
    text = str(value or "").strip()
    if not text:
        return False, "token_empty"
    if text.startswith(("/", "~")):
        return False, "token_must_not_be_absolute_or_home_relative"
    if any(sep in text for sep in ("/", "\\")):
        return False, "token_must_not_contain_path_separator"
    if ".." in text:
        return False, "token_must_not_contain_parent_reference"
    if any(char in text for char in "*?[]{}"):
        return False, "token_must_not_contain_glob_or_template_chars"
    if field == "artifact.suffix" and not text.startswith("."):
        return True, "suffix_without_dot"
    return True, None


def _release_config_hook_name_status(value: Any) -> tuple[bool, str | None]:
    text = str(value or "").strip()
    if not text:
        return False, "hook_name_empty"
    if not re.fullmatch(r"[A-Za-z][A-Za-z0-9_-]*", text):
        return False, "hook_name_must_be_identifier"
    return True, None


def _release_config_hook_command_status(command: str) -> tuple[bool, str | None, str | None]:
    """Validate hook command as a static, repo-local template only.

    The release-config command is a read-only contract validator. It must not
    execute hooks, but it still rejects commands that embed operator-machine
    absolute/home-relative paths so future lifecycle execution remains portable.
    """

    try:
        tokens = shlex.split(command)
    except ValueError as exc:
        return False, "command_parse_error", str(exc)
    for token in tokens:
        stripped = token.strip()
        if not stripped:
            continue
        # Allow placeholders to stand in for runtime values; reject concrete
        # operator-machine paths in the checked-in config.
        if stripped in {"{artifact}", "{repo_path}", "{version}", "{target_version}"}:
            continue
        if stripped.startswith("/") or stripped.startswith("~/") or stripped == "~":
            return False, "command_must_not_embed_absolute_or_home_path", stripped
        # Also catch option assignment forms such as --path=/home/user/repo.
        if "=" in stripped:
            _, value = stripped.split("=", 1)
            if value.startswith("/") or value.startswith("~/") or value == "~":
                return False, "command_must_not_embed_absolute_or_home_path", stripped
    return True, None, None


def _release_config_summary(config: dict[str, Any], validation: dict[str, Any]) -> dict[str, Any]:
    artifact = config.get("artifact") if isinstance(config.get("artifact"), dict) else {}
    install = config.get("install") if isinstance(config.get("install"), dict) else {}
    git = config.get("git") if isinstance(config.get("git"), dict) else {}
    hooks = config.get("hooks") if isinstance(config.get("hooks"), dict) else {}

    prefix = str(artifact.get("prefix") or "")
    version_prefix = str(artifact.get("version_prefix") or "")
    suffix = str(artifact.get("suffix") or "")
    preserve = install.get("preserve") if isinstance(install.get("preserve"), list) else []
    unsafe_paths = git.get("unsafe_paths") if isinstance(git.get("unsafe_paths"), list) else []

    hook_summaries: list[dict[str, Any]] = []
    if isinstance(hooks, dict):
        for name in sorted(hooks):
            hook = hooks.get(name)
            command = hook.get("command") if isinstance(hook, dict) else None
            placeholders = sorted(_release_config_command_placeholders(command)) if isinstance(command, str) else []
            hook_summaries.append({
                "name": name,
                "command": command,
                "placeholders": placeholders,
                "placeholder_count": len(placeholders),
                "known_placeholders_only": not bool(set(placeholders) - _RELEASE_CONFIG_ALLOWED_PLACEHOLDERS),
                "repo_relative": True,
                "template_valid": not bool(set(placeholders) - _RELEASE_CONFIG_ALLOWED_PLACEHOLDERS),
            })

    return {
        "ok": bool(validation.get("ok")),
        "status": validation.get("status"),
        "severity": validation.get("severity"),
        "schema_version": config.get("schema_version"),
        "artifact": {
            "prefix": prefix,
            "version_prefix": version_prefix,
            "suffix": suffix,
            "filename_pattern": f"{prefix}{version_prefix}<version>{suffix}" if prefix or suffix or version_prefix else None,
            "version_file": artifact.get("version_file"),
            "policy_file": artifact.get("policy_file"),
        },
        "install": {
            "preserve": preserve,
            "preserve_count": len(preserve),
        },
        "git": {
            "commit_release": bool(git.get("commit_release")),
            "push_release": bool(git.get("push_release")),
            "unsafe_paths": unsafe_paths,
            "unsafe_path_count": len(unsafe_paths),
        },
        "hooks": hook_summaries,
        "hook_count": len(hook_summaries),
        "read_only_contract": {
            "config_parsed": True,
            "hooks_executed": False,
            "install_executed": False,
            "source_mutated": False,
            "adoption_performed": False,
            "git_mutated": False,
        },
    }


def _validate_release_config(config: dict[str, Any]) -> dict[str, Any]:
    warnings: list[dict[str, Any]] = []
    blockers: list[dict[str, Any]] = []

    def warn(code: str, message: str, **extra: Any) -> None:
        warnings.append({"code": code, "severity": "warning", "message": message, **extra})

    def block(code: str, message: str, **extra: Any) -> None:
        blockers.append({"code": code, "severity": "blocked", "message": message, **extra})

    if not isinstance(config, dict):
        block("release_config_not_mapping", "Release config root must be a mapping.")
        config = {}

    missing = sorted(_RELEASE_CONFIG_REQUIRED_TOP_LEVEL - set(config.keys()))
    for key in missing:
        block("release_config_missing_section", f"Missing required release config section: {key}.", section=key)

    if config.get("schema_version") != 1:
        block("release_config_schema_version_unsupported", "release config schema_version must be 1.", schema_version=config.get("schema_version"))

    artifact = config.get("artifact") if isinstance(config.get("artifact"), dict) else {}
    if not isinstance(config.get("artifact"), dict):
        block("release_config_artifact_not_mapping", "artifact section must be a mapping.")
    for key in ["prefix", "suffix", "version_file", "policy_file"]:
        if not str(artifact.get(key) or "").strip():
            block("release_config_artifact_field_missing", f"artifact.{key} is required.", field=f"artifact.{key}")
    for key in ["prefix", "suffix"]:
        if artifact.get(key) is not None:
            ok, reason = _release_config_artifact_token_status(artifact.get(key), field=f"artifact.{key}")
            if not ok:
                block("release_config_artifact_token_invalid", f"artifact.{key} must be a safe filename token, not a path or template.", field=f"artifact.{key}", reason=reason)
            elif reason == "suffix_without_dot":
                warn("release_config_suffix_without_dot", "artifact.suffix usually starts with a dot, for example .zip.", suffix=artifact.get("suffix"))
    if artifact.get("version_prefix") is not None:
        ok, reason = _release_config_artifact_token_status(artifact.get("version_prefix"), field="artifact.version_prefix")
        if not ok:
            block("release_config_artifact_token_invalid", "artifact.version_prefix must be a safe filename token, not a path or template.", field="artifact.version_prefix", reason=reason)
    for key in ["version_file", "policy_file"]:
        if artifact.get(key) is not None:
            ok, reason = _release_config_path_status(artifact.get(key))
            if not ok:
                block("release_config_artifact_path_invalid", f"artifact.{key} must be a safe repo-relative path.", field=f"artifact.{key}", reason=reason)

    install = config.get("install") if isinstance(config.get("install"), dict) else {}
    if not isinstance(config.get("install"), dict):
        block("release_config_install_not_mapping", "install section must be a mapping.")
    preserve = install.get("preserve")
    if not isinstance(preserve, list) or not preserve:
        block("release_config_install_preserve_invalid", "install.preserve must be a non-empty list of safe repo-relative paths.")
    else:
        for item in preserve:
            ok, reason = _release_config_path_status(item)
            if not ok:
                block("release_config_install_preserve_path_invalid", "install.preserve contains an unsafe path.", path=item, reason=reason)

    git = config.get("git") if isinstance(config.get("git"), dict) else {}
    if not isinstance(config.get("git"), dict):
        block("release_config_git_not_mapping", "git section must be a mapping.")
    unsafe_paths = git.get("unsafe_paths")
    if not isinstance(unsafe_paths, list) or not unsafe_paths:
        block("release_config_git_unsafe_paths_invalid", "git.unsafe_paths must be a non-empty list.")
    else:
        for item in unsafe_paths:
            ok, reason = _release_config_path_status(item, allow_glob=True)
            if not ok:
                block("release_config_git_unsafe_path_invalid", "git.unsafe_paths contains an unsafe path.", path=item, reason=reason)

    hooks = config.get("hooks") if isinstance(config.get("hooks"), dict) else {}
    if not isinstance(config.get("hooks"), dict):
        block("release_config_hooks_not_mapping", "hooks section must be a mapping.")
    if isinstance(hooks, dict):
        for name, hook in hooks.items():
            hook_name_ok, hook_name_reason = _release_config_hook_name_status(name)
            if not hook_name_ok:
                block("release_config_hook_name_invalid", "Hook names must be safe identifiers.", hook=name, reason=hook_name_reason)
            if not isinstance(hook, dict):
                block("release_config_hook_not_mapping", "Each hook must be a mapping.", hook=name)
                continue
            command = hook.get("command")
            if not isinstance(command, str) or not command.strip():
                block("release_config_hook_command_missing", "Each hook must define a non-empty command.", hook=name)
                continue
            unsupported = sorted(_release_config_command_placeholders(command) - _RELEASE_CONFIG_ALLOWED_PLACEHOLDERS)
            if unsupported:
                block("release_config_hook_placeholder_unsupported", "Hook command uses unsupported placeholders.", hook=name, placeholders=unsupported, allowed=sorted(_RELEASE_CONFIG_ALLOWED_PLACEHOLDERS))
            command_ok, command_reason, command_token = _release_config_hook_command_status(command)
            if not command_ok:
                block("release_config_hook_command_path_invalid", "Hook command must not embed absolute or home-relative local machine paths.", hook=name, reason=command_reason, token=command_token)

    severity = "blocked" if blockers else "warning" if warnings else "ok"
    return {
        "ok": not blockers,
        "status": "verified" if not blockers else "blocked",
        "severity": severity,
        "warnings": warnings,
        "blockers": blockers,
        "warning_codes": [item["code"] for item in warnings],
        "blocker_codes": [item["code"] for item in blockers],
    }


def _load_release_config(config_arg: str | None, *, repo_root: Path) -> dict[str, Any]:
    raw = str(config_arg or ".promptbranch-release.yml").strip() or ".promptbranch-release.yml"
    path = Path(raw).expanduser()
    if not path.is_absolute():
        path = repo_root / path
    try:
        resolved = path.resolve()
    except OSError:
        resolved = path.absolute()
    payload: dict[str, Any] = {
        "path": str(resolved),
        "present": resolved.is_file(),
        "read_only": True,
        "mutating_actions_executed": False,
    }
    if not resolved.is_file():
        payload.update({"ok": False, "status": "missing", "error": "release_config_missing"})
        return payload
    try:
        text = resolved.read_text(encoding="utf-8")
    except OSError as exc:
        payload.update({"ok": False, "status": "read_error", "error": str(exc)})
        return payload
    try:
        config = _parse_release_config_yaml_subset(text)
    except ValueError as exc:
        payload.update({"ok": False, "status": "parse_error", "error": str(exc), "config": None})
        return payload
    validation = _validate_release_config(config)
    config_summary = _release_config_summary(config, validation)
    payload.update({
        "ok": validation["ok"],
        "status": validation["status"],
        "severity": validation["severity"],
        "config": config,
        "config_summary": config_summary,
        "artifact": config_summary.get("artifact"),
        "install": config_summary.get("install"),
        "git": config_summary.get("git"),
        "hooks": {item.get("name"): {key: value for key, value in item.items() if key != "name"} for item in config_summary.get("hooks", []) if isinstance(item, dict)},
        "read_only_contract": config_summary.get("read_only_contract"),
        "validation": validation,
        "warning_codes": validation["warning_codes"],
        "blocker_codes": validation["blocker_codes"],
    })
    return payload


def _extract_markdown_code_values(text: str) -> list[str]:
    values: list[str] = []
    in_fence = False
    for line in (text or "").splitlines():
        stripped = line.strip()
        if stripped.startswith("```"):
            in_fence = not in_fence
            continue
        if in_fence:
            continue
        for match in re.finditer(r"`([^`]+)`", line):
            value = (match.group(1) or "").strip()
            if value:
                values.append(value)
    return values


def _extract_design_reference_paths(text: str) -> list[str]:
    """Extract repo-relative documentation references from the living design markdown."""

    references: list[str] = []
    seen: set[str] = set()
    for value in _extract_markdown_code_values(text):
        if not value or "\n" in value:
            continue
        if value.startswith(("http://", "https://", "#")):
            continue
        if value.startswith(("/", "~", ".")) or ".." in Path(value).parts:
            continue
        if not any(value.endswith(suffix) for suffix in (".md", ".txt", ".drawio")):
            continue
        if value not in seen:
            references.append(value)
            seen.add(value)
    return references


def _parse_drawio_source(path: Path) -> dict[str, Any]:
    payload: dict[str, Any] = {
        "path": str(path),
        "present": path.is_file(),
        "xml_parsed": False,
        "diagram_count": 0,
        "diagram_names": [],
        "cell_count": 0,
        "error": None,
    }
    if not path.is_file():
        payload["error"] = "drawio_missing"
        return payload
    try:
        root = ET.parse(path).getroot()
    except ET.ParseError as exc:
        payload["error"] = f"drawio_xml_parse_error: {exc}"
        return payload
    except OSError as exc:
        payload["error"] = f"drawio_read_error: {exc}"
        return payload
    diagrams = root.findall("diagram")
    cells = root.findall(".//mxCell")
    payload.update({
        "xml_parsed": True,
        "diagram_count": len(diagrams),
        "diagram_names": [str(item.attrib.get("name") or "") for item in diagrams],
        "cell_count": len(cells),
        "host": root.attrib.get("host"),
        "modified": root.attrib.get("modified"),
    })
    return payload


PB_APPLICATION_DESIGN_DOC = "docs/design/promptbranch-application-design.md"
PB_APPLICATION_DESIGN_DRAWIO_PAGES: dict[str, list[str]] = {
    "docs/design/promptbranch-class-diagram.drawio": [
        "PB Application Role Components",
    ],
    "docs/design/promptbranch-mvp-living-design.drawio": [
        "PB Application Activity — pb and ChatGPT Roles",
        "PB Application Data Flow",
        "PB Application State Transitions",
    ],
    "docs/diagrams/promptbranch-lifecycle/promptbranch_lifecycle_commands.drawio": [
        "PB Release State Transitions",
    ],
}
PB_APPLICATION_DESIGN_REQUIRED_PHRASES = [
    "pb          = local deterministic control plane",
    "ChatGPT     = reasoning/conversation surface",
    "Workspace = current ChatGPT Project",
    "Task      = current chat/conversation inside that project",
    "Artifact  = current repo/source bundle/release ZIP",
    "backend-first reads",
    "transactional writes",
    "accepted baseline / artifact continuity",
    "Activity diagram",
    "Data-flow diagram",
    "State-transition diagram",
]


def _pb_application_design_surface_status(*, repo_root: Path, expected_version: str | None) -> dict[str, Any]:
    """Read-only freshness guard for the PB application design document and diagrams."""

    warnings: list[dict[str, Any]] = []
    blockers: list[dict[str, Any]] = []

    def block(code: str, message: str, **extra: Any) -> None:
        blockers.append({"code": code, "severity": "blocked", "message": message, **extra})

    doc_rel = PB_APPLICATION_DESIGN_DOC
    doc_path = (repo_root / doc_rel).resolve()
    doc_text = ""
    try:
        doc_path.relative_to(repo_root)
    except ValueError:
        block("pb_application_design_doc_not_repo_bound", "PB application design document leaves the repository.", path=str(doc_path))
    if not doc_path.is_file():
        block("pb_application_design_doc_missing", "PB application design document is missing.", path=doc_rel)
    else:
        try:
            doc_text = doc_path.read_text(encoding="utf-8")
        except OSError as exc:
            block("pb_application_design_doc_read_error", "PB application design document could not be read.", path=doc_rel, error=str(exc))

    missing_phrases: list[str] = []
    if doc_text:
        for phrase in PB_APPLICATION_DESIGN_REQUIRED_PHRASES:
            if phrase not in doc_text:
                missing_phrases.append(phrase)
        if missing_phrases:
            block(
                "pb_application_design_required_phrase_missing",
                "PB application design document is missing release-checkable role/scope/freshness language.",
                missing_phrases=missing_phrases,
            )
        if expected_version and expected_version not in doc_text:
            block(
                "pb_application_design_release_marker_mismatch",
                "Expected version is not mentioned in the PB application design document.",
                expected_version=expected_version,
            )

    references = set(_extract_design_reference_paths(doc_text)) if doc_text else set()
    drawio_sources: list[dict[str, Any]] = []
    for rel_path, required_pages in PB_APPLICATION_DESIGN_DRAWIO_PAGES.items():
        abs_path = (repo_root / rel_path).resolve()
        try:
            abs_path.relative_to(repo_root)
            repo_bound = True
        except ValueError:
            repo_bound = False
        if not repo_bound:
            block("pb_application_design_drawio_not_repo_bound", "PB application draw.io source leaves the repository.", path=rel_path)
        status = _parse_drawio_source(abs_path)
        names = set(status.get("diagram_names") or [])
        missing_pages = [page for page in required_pages if page not in names]
        if not status.get("present"):
            block("pb_application_design_drawio_missing", "Required PB application draw.io source is missing.", path=rel_path)
        elif not status.get("xml_parsed"):
            block("pb_application_design_drawio_xml_invalid", "Required PB application draw.io source is not valid XML.", path=rel_path, error=status.get("error"))
        elif missing_pages:
            block(
                "pb_application_design_drawio_page_missing",
                "Required PB application draw.io page is missing.",
                path=rel_path,
                missing_pages=missing_pages,
            )
        if doc_text and rel_path not in references:
            block(
                "pb_application_design_drawio_reference_missing",
                "PB application design document does not reference a required draw.io source.",
                path=rel_path,
            )
        drawio_sources.append({
            "path": rel_path,
            "repo_bound": repo_bound,
            "present": bool(status.get("present")),
            "xml_parsed": bool(status.get("xml_parsed")),
            "diagram_count": status.get("diagram_count"),
            "required_pages": required_pages,
            "missing_pages": missing_pages,
        })

    severity = "blocked" if blockers else "warning" if warnings else "ok"
    return {
        "ok": not blockers,
        "status": "verified" if not blockers else "blocked",
        "severity": severity,
        "read_only": True,
        "mutating_actions_executed": False,
        "design_doc": {
            "path": doc_rel,
            "present": doc_path.is_file(),
            "size_bytes": doc_path.stat().st_size if doc_path.is_file() else None,
        },
        "drawio_sources": drawio_sources,
        "required_phrase_count": len(PB_APPLICATION_DESIGN_REQUIRED_PHRASES),
        "missing_phrase_count": len(missing_phrases),
        "warning_codes": [item["code"] for item in warnings],
        "blocker_codes": [item["code"] for item in blockers],
        "warnings": warnings,
        "blockers": blockers,
    }



