def _pb_living_design_overview_status(*, repo_root: Path, expected_version: str | None) -> dict[str, Any]:
    """Read-only guard for the repo-owned living-design HTML overview."""

    warnings: list[dict[str, Any]] = []
    blockers: list[dict[str, Any]] = []

    def block(code: str, message: str, **extra: Any) -> None:
        blockers.append({"code": code, "severity": "blocked", "message": message, **extra})

    html_rel = PB_LIVING_DESIGN_OVERVIEW_HTML
    html_path = (repo_root / html_rel).resolve()
    html_text = ""
    try:
        html_path.relative_to(repo_root)
    except ValueError:
        block("living_design_overview_not_repo_bound", "Living-design overview HTML leaves the repository.", path=str(html_path))
    if not html_path.is_file():
        block("living_design_overview_missing", "Living-design overview HTML is missing.", path=html_rel)
    else:
        try:
            html_text = html_path.read_text(encoding="utf-8")
        except OSError as exc:
            block("living_design_overview_read_error", "Living-design overview HTML could not be read.", path=html_rel, error=str(exc))

    missing_phrases: list[str] = []
    if html_text:
        for phrase in PB_LIVING_DESIGN_OVERVIEW_REQUIRED_PHRASES:
            if phrase not in html_text:
                missing_phrases.append(phrase)
        if missing_phrases:
            block(
                "living_design_overview_required_phrase_missing",
                "Living-design overview HTML is missing required draw.io/PB-authority documentation language.",
                missing_phrases=missing_phrases,
            )
        if expected_version and expected_version not in html_text:
            block(
                "living_design_overview_release_marker_mismatch",
                "Expected version is not mentioned in the living-design overview HTML.",
                expected_version=expected_version,
            )
        if "<html" not in html_text.lower() or "</html>" not in html_text.lower():
            block("living_design_overview_html_invalid", "Living-design overview does not look like a complete HTML document.", path=html_rel)

    severity = "blocked" if blockers else "warning" if warnings else "ok"
    return {
        "ok": not blockers,
        "status": "verified" if not blockers else "blocked",
        "severity": severity,
        "read_only": True,
        "mutating_actions_executed": False,
        "html": {
            "path": html_rel,
            "present": html_path.is_file(),
            "size_bytes": html_path.stat().st_size if html_path.is_file() else None,
        },
        "required_phrase_count": len(PB_LIVING_DESIGN_OVERVIEW_REQUIRED_PHRASES),
        "missing_phrase_count": len(missing_phrases),
        "warning_codes": [item["code"] for item in warnings],
        "blocker_codes": [item["code"] for item in blockers],
        "warnings": warnings,
        "blockers": blockers,
    }


PB_DOCS_SITE_CONFIG = "mkdocs.yml"
PB_DOCS_SITE_ENTRYPOINTS = [
    "docs/index.md",
    "docs/site.md",
    "docs/design/index.md",
    "docs/releases/index.md",
]
PB_DOCS_SITE_MARKDOWN_LINK_SOURCES = [
    "docs/index.md",
    "docs/site.md",
    "docs/design/index.md",
    "docs/releases/index.md",
    "docs/design/promptbranch-living-design-overview.md",
]
PB_DOCS_SITE_STATIC_REQUIRED_REFERENCES = [
    "docs/site.md",
    "docs/design/promptbranch-living-design-overview.html",
    "docs/design/promptbranch-living-design-overview.md",
    "docs/design/promptbranch-application-design.md",
    "docs/design/promptbranch-release-baseline-evidence.md",
    "docs/design/promptbranch-mvp-living-design.md",
    "docs/design/promptbranch-mvp-gap-analysis.md",
    "docs/design/orchestration/docs/current_status.md",
]
PB_DOCS_SITE_REQUIRED_PHRASES = [
    "Material for MkDocs",
    "Promptbranch is the deterministic control plane",
    "ChatGPT is the reasoning",
    "Workspace",
    "Task",
    "Artifact",
    "backend-first reads",
    "transactional writes",
    "artifact baseline semantics",
    "release lifecycle",
]
PB_DOCS_SITE_BUILD_POLICY = "docs/site.md"
PB_DOCS_SITE_BUILD_READINESS_REQUIRED_PHRASES = [
    "source-only documentation site policy",
    "Material for MkDocs",
    "mkdocs serve",
    "mkdocs build",
    "site/",
    "must not be committed",
    "pb release docs-status",
]
PB_DOCS_SITE_MARKDOWN_LINK_RE = re.compile(r"(?<!!)\[[^\]]+\]\(([^)]+)\)")
PB_DOCS_SITE_MKDOCS_NAV_TARGET_RE = re.compile(r":\s*([A-Za-z0-9_./-]+\.(?:md|html|drawio|png|svg))\s*(?:#.*)?$")


def _docs_site_release_reference(expected_version: str | None) -> str | None:
    if not expected_version:
        return None
    version = expected_version if str(expected_version).startswith("v") else f"v{expected_version}"
    return f"docs/release-{version}.md"


def _docs_site_target_is_external(target: str) -> bool:
    lowered = target.strip().lower()
    return (
        not lowered
        or lowered.startswith("#")
        or lowered.startswith("mailto:")
        or lowered.startswith("tel:")
        or lowered.startswith("data:")
        or "://" in lowered
    )


def _docs_site_target_without_fragment(target: str) -> str:
    return target.strip().split("#", 1)[0].split("?", 1)[0]


def _resolve_docs_site_target(repo_root: Path, *, source_rel: str, target: str, mkdocs_nav: bool = False) -> dict[str, Any] | None:
    """Resolve a docs-site source target to a repo-relative path without reading external resources."""

    raw_target = target.strip().strip('"').strip("'")
    if _docs_site_target_is_external(raw_target):
        return None
    target_no_fragment = _docs_site_target_without_fragment(raw_target)
    if not target_no_fragment:
        return None

    if target_no_fragment.startswith("/"):
        candidate_rel = target_no_fragment.lstrip("/")
    elif target_no_fragment.startswith("docs/"):
        candidate_rel = target_no_fragment
    elif mkdocs_nav:
        candidate_rel = f"docs/{target_no_fragment}"
    else:
        candidate_rel = str((Path(source_rel).parent / target_no_fragment).as_posix())

    abs_path = (repo_root / candidate_rel).resolve()
    repo_bound = True
    resolved_rel = candidate_rel
    try:
        resolved_rel = abs_path.relative_to(repo_root).as_posix()
    except ValueError:
        repo_bound = False

    return {
        "source": source_rel,
        "target": raw_target,
        "resolved_path": resolved_rel,
        "repo_bound": repo_bound,
        "exists": abs_path.is_file() if repo_bound else False,
    }


def _extract_docs_site_link_targets(*, repo_root: Path, config_text: str, markdown_texts: dict[str, str]) -> list[dict[str, Any]]:
    targets: list[dict[str, Any]] = []

    for line in config_text.splitlines():
        match = PB_DOCS_SITE_MKDOCS_NAV_TARGET_RE.search(line)
        if not match:
            continue
        resolved = _resolve_docs_site_target(
            repo_root,
            source_rel=PB_DOCS_SITE_CONFIG,
            target=match.group(1),
            mkdocs_nav=True,
        )
        if resolved is not None:
            resolved["kind"] = "mkdocs_nav"
            targets.append(resolved)

    for source_rel, text in markdown_texts.items():
        for match in PB_DOCS_SITE_MARKDOWN_LINK_RE.finditer(text):
            resolved = _resolve_docs_site_target(
                repo_root,
                source_rel=source_rel,
                target=match.group(1),
                mkdocs_nav=False,
            )
            if resolved is not None:
                resolved["kind"] = "markdown_link"
                targets.append(resolved)

    return targets


def _pb_docs_site_status(*, repo_root: Path, expected_version: str | None) -> dict[str, Any]:
    """Read-only guard for the source-controlled documentation site scaffold and its repo-local links."""

    warnings: list[dict[str, Any]] = []
    blockers: list[dict[str, Any]] = []

    def block(code: str, message: str, **extra: Any) -> None:
        blockers.append({"code": code, "severity": "blocked", "message": message, **extra})

    config_rel = PB_DOCS_SITE_CONFIG
    config_path = (repo_root / config_rel).resolve()
    config_text = ""
    try:
        config_path.relative_to(repo_root)
    except ValueError:
        block("docs_site_config_not_repo_bound", "Documentation site config leaves the repository.", path=str(config_path))
    if not config_path.is_file():
        block("docs_site_config_missing", "Documentation site config is missing.", path=config_rel)
    else:
        try:
            config_text = config_path.read_text(encoding="utf-8")
        except OSError as exc:
            block("docs_site_config_read_error", "Documentation site config could not be read.", path=config_rel, error=str(exc))

    entrypoints: list[dict[str, Any]] = []
    entrypoint_texts: dict[str, str] = {}
    for rel_path in PB_DOCS_SITE_ENTRYPOINTS:
        abs_path = (repo_root / rel_path).resolve()
        repo_bound = True
        try:
            abs_path.relative_to(repo_root)
        except ValueError:
            repo_bound = False
            block("docs_site_entrypoint_not_repo_bound", "Documentation site entrypoint leaves the repository.", path=rel_path)
        text = ""
        if not abs_path.is_file():
            block("docs_site_entrypoint_missing", "Documentation site entrypoint is missing.", path=rel_path)
        else:
            try:
                text = abs_path.read_text(encoding="utf-8")
            except OSError as exc:
                block("docs_site_entrypoint_read_error", "Documentation site entrypoint could not be read.", path=rel_path, error=str(exc))
        entrypoint_texts[rel_path] = text
        entrypoints.append({
            "path": rel_path,
            "repo_bound": repo_bound,
            "present": abs_path.is_file(),
            "size_bytes": abs_path.stat().st_size if abs_path.is_file() else None,
        })

    markdown_texts = dict(entrypoint_texts)
    for rel_path in PB_DOCS_SITE_MARKDOWN_LINK_SOURCES:
        if rel_path in markdown_texts:
            continue
        abs_path = (repo_root / rel_path).resolve()
        if not abs_path.is_file():
            block("docs_site_link_source_missing", "Documentation link-integrity source is missing.", path=rel_path)
            markdown_texts[rel_path] = ""
            continue
        try:
            markdown_texts[rel_path] = abs_path.read_text(encoding="utf-8")
        except OSError as exc:
            block("docs_site_link_source_read_error", "Documentation link-integrity source could not be read.", path=rel_path, error=str(exc))
            markdown_texts[rel_path] = ""

    combined_text = "\n".join([config_text, *markdown_texts.values()])
    required_references = list(PB_DOCS_SITE_STATIC_REQUIRED_REFERENCES)
    release_reference = _docs_site_release_reference(expected_version)
    if release_reference:
        required_references.append(release_reference)
    missing_references = [reference for reference in required_references if reference not in combined_text]
    if missing_references:
        block(
            "docs_site_required_reference_missing",
            "Documentation site scaffold does not reference required PB design/release surfaces.",
            missing_references=missing_references,
        )

    missing_phrases = [phrase for phrase in PB_DOCS_SITE_REQUIRED_PHRASES if phrase not in combined_text]
    if missing_phrases:
        block(
            "docs_site_required_phrase_missing",
            "Documentation site scaffold is missing required PB authority/navigation language.",
            missing_phrases=missing_phrases,
        )

    if config_text and "name: material" not in config_text:
        block("docs_site_material_theme_missing", "mkdocs.yml must declare Material for MkDocs as the intended theme.", path=config_rel)
    if config_text and "site_name:" not in config_text:
        block("docs_site_site_name_missing", "mkdocs.yml must declare site_name.", path=config_rel)
    if expected_version and expected_version not in combined_text:
        block(
            "docs_site_release_marker_mismatch",
            "Expected version is not mentioned in the documentation site scaffold.",
            expected_version=expected_version,
        )

    link_targets = _extract_docs_site_link_targets(
        repo_root=repo_root,
        config_text=config_text,
        markdown_texts=markdown_texts,
    )
    not_repo_bound_targets = [target for target in link_targets if not target.get("repo_bound")]
    missing_targets = [target for target in link_targets if target.get("repo_bound") and not target.get("exists")]
    if not_repo_bound_targets:
        block(
            "docs_site_link_target_not_repo_bound",
            "Documentation site link target leaves the repository.",
            targets=not_repo_bound_targets,
        )
    if missing_targets:
        block(
            "docs_site_link_target_missing",
            "Documentation site link target does not exist.",
            targets=missing_targets,
        )

    generated_site_path = repo_root / "site"
    if generated_site_path.exists():
        block("docs_site_generated_output_committed", "Generated MkDocs site output must not be committed or packaged as source.", path="site/")

    build_policy_text = markdown_texts.get(PB_DOCS_SITE_BUILD_POLICY, "")
    missing_build_readiness_phrases = [
        phrase for phrase in PB_DOCS_SITE_BUILD_READINESS_REQUIRED_PHRASES if phrase not in build_policy_text
    ]
    preview_command_documented = "mkdocs serve" in build_policy_text
    build_command_documented = "mkdocs build" in build_policy_text
    generated_site_forbidden = "site/" in build_policy_text and "must not be committed" in build_policy_text
    requires_committed_site_output = False
    if missing_build_readiness_phrases:
        block(
            "docs_site_build_readiness_phrase_missing",
            "Documentation site build-readiness policy is missing required source-only operation language.",
            path=PB_DOCS_SITE_BUILD_POLICY,
            missing_phrases=missing_build_readiness_phrases,
        )

    severity = "blocked" if blockers else "warning" if warnings else "ok"
    return {
        "ok": not blockers,
        "status": "verified" if not blockers else "blocked",
        "severity": severity,
        "read_only": True,
        "mutating_actions_executed": False,
        "config": {
            "path": config_rel,
            "present": config_path.is_file(),
            "size_bytes": config_path.stat().st_size if config_path.is_file() else None,
            "theme": "material" if "name: material" in config_text else None,
        },
        "entrypoints": entrypoints,
        "required_reference_count": len(required_references),
        "missing_reference_count": len(missing_references),
        "required_phrase_count": len(PB_DOCS_SITE_REQUIRED_PHRASES),
        "missing_phrase_count": len(missing_phrases),
        "generated_site_present": generated_site_path.exists(),
        "build_readiness": {
            "ok": not missing_build_readiness_phrases and preview_command_documented and build_command_documented and generated_site_forbidden and not requires_committed_site_output,
            "docs_site_policy": PB_DOCS_SITE_BUILD_POLICY,
            "preview_command_documented": preview_command_documented,
            "build_command_documented": build_command_documented,
            "generated_site_forbidden": generated_site_forbidden,
            "requires_committed_site_output": requires_committed_site_output,
            "missing_phrase_count": len(missing_build_readiness_phrases),
            "missing_phrases": missing_build_readiness_phrases,
        },
        "link_integrity": {
            "ok": not missing_targets and not not_repo_bound_targets,
            "checked_link_count": len(link_targets),
            "missing_target_count": len(missing_targets),
            "not_repo_bound_target_count": len(not_repo_bound_targets),
            "missing_targets": missing_targets,
            "not_repo_bound_targets": not_repo_bound_targets,
        },
        "warning_codes": [item["code"] for item in warnings],
        "blocker_codes": [item["code"] for item in blockers],
        "warnings": warnings,
        "blockers": blockers,
    }

def _living_design_status(*, repo_root: Path, design_doc: str, drawio: str, expected_version: str | None) -> dict[str, Any]:
    doc_path = (repo_root / design_doc).resolve()
    drawio_path = (repo_root / drawio).resolve()
    warnings: list[dict[str, Any]] = []
    blockers: list[dict[str, Any]] = []

    def warn(code: str, message: str, **extra: Any) -> None:
        warnings.append({"code": code, "severity": "warning", "message": message, **extra})

    def block(code: str, message: str, **extra: Any) -> None:
        blockers.append({"code": code, "severity": "blocked", "message": message, **extra})

    try:
        doc_path.relative_to(repo_root)
    except ValueError:
        block("living_design_doc_not_repo_bound", "Design document path must stay inside the repository.", path=str(doc_path))
    try:
        drawio_path.relative_to(repo_root)
    except ValueError:
        block("living_design_drawio_not_repo_bound", "draw.io source path must stay inside the repository.", path=str(drawio_path))

    doc_text = ""
    if not doc_path.is_file():
        block("living_design_doc_missing", "Living design Markdown document is missing.", path=design_doc)
    else:
        try:
            doc_text = doc_path.read_text(encoding="utf-8")
        except OSError as exc:
            block("living_design_doc_read_error", "Living design Markdown document could not be read.", path=design_doc, error=str(exc))

    drawio_status = _parse_drawio_source(drawio_path)
    if not drawio_status.get("present"):
        block("living_design_drawio_missing", "Editable draw.io source file is missing.", path=drawio)
    elif not drawio_status.get("xml_parsed"):
        block("living_design_drawio_xml_invalid", "Editable draw.io source file is not valid XML.", path=drawio, error=drawio_status.get("error"))
    elif int(drawio_status.get("diagram_count") or 0) < 1:
        block("living_design_drawio_no_diagrams", "Editable draw.io source contains no diagrams.", path=drawio)

    references = _extract_design_reference_paths(doc_text)
    reference_status: list[dict[str, Any]] = []
    for reference in references:
        ref_path = (repo_root / reference).resolve()
        try:
            ref_path.relative_to(repo_root)
            repo_bound = True
        except ValueError:
            repo_bound = False
        exists = ref_path.is_file()
        if not repo_bound:
            block("living_design_reference_not_repo_bound", "Living design reference leaves the repository.", reference=reference)
        elif not exists:
            block("living_design_reference_missing", "Living design reference is missing.", reference=reference)
        reference_status.append({"path": reference, "repo_bound": repo_bound, "exists": exists})

    if drawio not in references and doc_text:
        warn("living_design_drawio_not_listed_as_reference", "The draw.io source is not listed among extracted repo-relative references.", drawio=drawio)
    if expected_version and doc_text and expected_version not in doc_text:
        warn("living_design_release_marker_mismatch", "Expected version is not mentioned in the living design document.", expected_version=expected_version)
    if doc_text and "After each release slice" not in doc_text:
        warn("living_design_update_protocol_missing", "Living design document does not include the expected update protocol phrase.")

    application_design = _pb_application_design_surface_status(
        repo_root=repo_root,
        expected_version=expected_version,
    )
    for item in application_design.get("warnings") or []:
        warnings.append(item)
    for item in application_design.get("blockers") or []:
        blockers.append(item)

    baseline_evidence = _pb_release_baseline_evidence_status(
        repo_root=repo_root,
        expected_version=expected_version,
    )
    for item in baseline_evidence.get("warnings") or []:
        warnings.append(item)
    for item in baseline_evidence.get("blockers") or []:
        blockers.append(item)

    living_design_overview = _pb_living_design_overview_status(
        repo_root=repo_root,
        expected_version=expected_version,
    )
    for item in living_design_overview.get("warnings") or []:
        warnings.append(item)
    for item in living_design_overview.get("blockers") or []:
        blockers.append(item)

    docs_site = _pb_docs_site_status(
        repo_root=repo_root,
        expected_version=expected_version,
    )
    for item in docs_site.get("warnings") or []:
        warnings.append(item)
    for item in docs_site.get("blockers") or []:
        blockers.append(item)

    severity = "blocked" if blockers else "warning" if warnings else "ok"
    return {
        "ok": not blockers,
        "status": "verified" if not blockers else "blocked",
        "severity": severity,
        "read_only": True,
        "mutating_actions_executed": False,
        "design_doc": {
            "path": design_doc,
            "present": doc_path.is_file(),
            "size_bytes": doc_path.stat().st_size if doc_path.is_file() else None,
        },
        "drawio": drawio_status,
        "application_design": application_design,
        "baseline_evidence": baseline_evidence,
        "living_design_overview": living_design_overview,
        "docs_site": docs_site,
        "reference_count": len(references),
        "references": reference_status,
        "missing_reference_count": sum(1 for item in reference_status if not item.get("exists")),
        "warning_codes": [item["code"] for item in warnings],
        "blocker_codes": [item["code"] for item in blockers],
        "warnings": warnings,
        "blockers": blockers,
    }


async def cmd_release_config(backend: Any, args: argparse.Namespace) -> int:
    """Read-only parser/validator for .promptbranch-release.yml."""

    repo_root = Path(getattr(args, "repo_path", ".") or ".").expanduser().resolve()
    payload = _load_release_config(getattr(args, "config", None), repo_root=repo_root)
    payload.update({
        "schema": "promptbranch.release.config.report",
        "schema_version": "1.0",
        "action": "release_config",
        "repo_path": str(repo_root),
        "download_performed": False,
        "migration_performed": False,
        "candidate_test_performed": False,
        "adoption_performed": False,
        "project_source_mutated": False,
        "project_source_mutation": "not_requested",
        "source_upload_verification": None,
        "artifact_registry_updated": False,
        "state_artifact_updated": False,
        "state_source_updated": False,
        "git_commit_performed": False,
        "git_push_performed": False,
        "not_performed": [
            "artifact_download",
            "candidate_migration",
            "candidate_test_execution",
            "candidate_adoption",
            "project_source_mutation",
            "artifact_registry_update",
            "state_artifact_update",
            "state_source_update",
            "git_commit",
            "git_push",
        ],
    })
    if getattr(args, "json", False):
        print(json.dumps(payload, indent=2, ensure_ascii=False))
    else:
        print(f"status={payload.get('status')}")
        print(f"severity={payload.get('severity') or 'unknown'}")
        print(f"config_path={payload.get('path')}")
        print(f"warning_codes={','.join(payload.get('warning_codes') or []) or 'none'}")
        print(f"blocker_codes={','.join(payload.get('blocker_codes') or []) or 'none'}")
        usage = payload.get("baseline_status_usage") if isinstance(payload.get("baseline_status_usage"), dict) else {}
        print(f"intended_use={usage.get('intended_use') or 'post_adoption_only'}")
        print(f"detected_context={usage.get('detected_context') or 'unknown'}")
        context = payload.get("release_status_context") if isinstance(payload.get("release_status_context"), dict) else {}
        print(f"baseline_status_applicable={str(context.get('baseline_status_applicable')).lower() if 'baseline_status_applicable' in context else 'unknown'}")
        if context.get("primary_read_command"):
            print(f"primary_read_command={context.get('primary_read_command')}")
        suggested = payload.get("suggested_commands") if isinstance(payload.get("suggested_commands"), dict) else {}
        if payload.get("ok") is not True and suggested.get("development_checkpoint"):
            print(f"use_checkpoint={suggested.get('development_checkpoint')}")
        if payload.get("ok") is not True and suggested.get("development_overview"):
            print(f"use_dev_status={suggested.get('development_overview')}")
    return 0 if payload.get("ok") else 1


