def _current_project_identity_payload(args: argparse.Namespace) -> dict[str, Any]:
    try:
        identity = load_repo_identity(Path.cwd())
    except ValueError as exc:
        return {"ok": False, "status": "project_identity_invalid", "error": str(exc)}
    if identity is None:
        return {
            "ok": False,
            "status": "project_identity_not_found",
            "identity_file": REPO_IDENTITY_FILE_NAME,
            "next_safe_action": "Run pb project join from this repository.",
        }
    registry_file = project_registry_file(identity.project_id)
    return {
        "ok": True,
        "identity": identity.to_dict(),
        "project_id": identity.project_id,
        "project_home_url": identity.project_home_url,
        "repo_id": identity.repo_id,
        "registry_file": str(registry_file),
        "registry_source": "project_registry",
        "local_repo_config_file": str(project_repo_config_path(identity.project_id)),
    }


async def cmd_project(backend: Any, args: argparse.Namespace) -> int:
    if args.project_command == "join":
        repo_root = Path(getattr(args, "repo_root", ".") or ".").expanduser().resolve()
        try:
            identity = load_repo_identity(repo_root)
            binding_created = False
            if identity is None:
                required = {
                    "project_id": getattr(args, "project_id", None),
                    "project_home_url": getattr(args, "project_home_url", None),
                    "repo_id": getattr(args, "repo_id", None),
                }
                missing = sorted(key for key, value in required.items() if not value)
                if missing:
                    raise ValueError(
                        f"tracked {REPO_IDENTITY_FILE_NAME} is missing; provide {', '.join('--' + key.replace('_', '-') for key in missing)} once to create it, then commit it"
                    )
                identity_path = write_repo_identity(
                    repo_root,
                    project_id=str(required["project_id"]),
                    project_home_url=str(required["project_home_url"]),
                    repo_id=str(required["repo_id"]),
                    artifact_pattern=getattr(args, "artifact_pattern", None),
                    role=getattr(args, "role", None),
                )
                binding_created = True
                identity = load_repo_identity(repo_root)
                if identity is None:
                    raise ValueError("project identity was not readable after writing")
            else:
                identity_path = identity.path
                mismatches = repo_identity_mismatches(
                    identity,
                    project_id=getattr(args, "project_id", None),
                    project_home_url=getattr(args, "project_home_url", None),
                    repo_id=getattr(args, "repo_id", None),
                    artifact_pattern=getattr(args, "artifact_pattern", None),
                    role=getattr(args, "role", None),
                )
                if mismatches:
                    raise ValueError(
                        "tracked project binding mismatch; refusing to rewrite authority: " + "; ".join(mismatches)
                    )
            repo_config_file = join_local_repo(identity)
            ensure_project_registry(identity.project_id)
            ConversationStateStore(str(project_registry_dir(identity.project_id))).remember_project(identity.project_home_url, project_name=identity.project_id)
            payload = {
                "ok": True,
                "action": "project_join",
                "status": "joined",
                "project_id": identity.project_id,
                "project_home_url": identity.project_home_url,
                "repo_id": identity.repo_id,
                "identity_file": str(identity_path),
                "binding_source": "created_from_explicit_arguments" if binding_created else "tracked_repository_file",
                "binding_created": binding_created,
                "local_repo_config_file": str(repo_config_file),
                "registry_file": str(project_registry_file(identity.project_id)),
            }
        except Exception as exc:
            payload = {"ok": False, "action": "project_join", "status": "join_failed", "error": str(exc)}
        if getattr(args, "json", False):
            print(json.dumps(payload, indent=2, ensure_ascii=False))
        else:
            print(f"status={payload.get('status')}")
            if payload.get("project_id"):
                print(f"project_id={payload.get('project_id')}")
            if payload.get("repo_id"):
                print(f"repo_id={payload.get('repo_id')}")
            if payload.get("registry_file"):
                print(f"registry_file={payload.get('registry_file')}")
        return 0 if payload.get("ok") else 2
    if args.project_command == "status":
        identity_payload = _current_project_identity_payload(args)
        payload = {"action": "project_status", **identity_payload}
        if identity_payload.get("ok"):
            repo_payload = _repo_list_payload(args)
            payload.update({
                "management_model": "repo_loop",
                "repo_count": repo_payload.get("repo_count", 0),
                "repos": repo_payload.get("repos") or [],
                "registry_file": repo_payload.get("registry_file") or payload.get("registry_file"),
                "registry_source": repo_payload.get("registry_source") or payload.get("registry_source"),
            })
        if getattr(args, "json", False):
            print(json.dumps(payload, indent=2, ensure_ascii=False))
        else:
            print(f"status={payload.get('status') or ('ok' if payload.get('ok') else 'error')}")
            if payload.get("project_id"):
                print(f"project_id={payload.get('project_id')}")
            if payload.get("repo_id"):
                print(f"repo_id={payload.get('repo_id')}")
            if payload.get("repo_count") is not None:
                print(f"repo_count={payload.get('repo_count')}")
            for repo in payload.get("repos") or []:
                print(f"{repo.get('repo_id')}.current_artifact={repo.get('current_artifact') or 'none'}")
        return 0 if payload.get("ok") else 2
    if args.project_command == "validate-control-surface":
        payload = validate_project_control_surface(getattr(args, "repo_path", ".") or ".")
        if getattr(args, "json", False):
            print(json.dumps(payload, indent=2, ensure_ascii=False))
        else:
            print(f"status={payload.get('status')}")
            print(f"accepted_current_version={payload.get('accepted_current_version') or ''}")
            print(f"active_candidate_version={payload.get('active_candidate_version') or ''}")
            print(f"next_normal_version={payload.get('next_normal_version') or ''}")
            print(f"next_normal_slice={payload.get('next_normal_slice') or ''}")
            if payload.get("errors"):
                for error in payload.get("errors") or []:
                    print(f"error={error}")
        return 0 if payload.get("ok") else 2
    if args.project_command == "next-slice":
        payload = build_project_next_slice_payload(getattr(args, "repo_path", ".") or ".")
        if getattr(args, "json", False):
            print(json.dumps(payload, indent=2, ensure_ascii=False))
        else:
            print(f"status={payload.get('status')}")
            print(f"baseline={payload.get('baseline_artifact') or ''}")
            print(f"next_normal_version={payload.get('next_normal_version') or ''}")
            print(f"next_normal_slice={payload.get('next_normal_slice') or ''}")
            print(f"next_slice_after_acceptance={payload.get('next_slice_after_acceptance_version') or ''} — {payload.get('next_slice_after_acceptance') or ''}")
            if payload.get("errors"):
                for error in payload.get("errors") or []:
                    print(f"error={error}")
        return 0 if payload.get("ok") else 2
    if args.project_command == "behavioral-surface":
        repo_path = getattr(args, "repo_path", ".") or "."
        if args.project_behavioral_surface_command == "show":
            payload = build_behavioral_surface_show_payload(
                repo_path,
                kind=getattr(args, "kind", None),
                consumer=getattr(args, "consumer", None),
            )
        elif args.project_behavioral_surface_command == "validate":
            payload = validate_behavioral_surface(repo_path)
        else:
            raise RuntimeError(f"Unknown project behavioral-surface command: {args.project_behavioral_surface_command}")
        if getattr(args, "json", False):
            print(json.dumps(payload, indent=2, ensure_ascii=False))
        else:
            print(f"status={payload.get('status')}")
            print(f"registry_path={payload.get('registry_path') or ''}")
            print(f"entry_count={payload.get('entry_count') if payload.get('entry_count') is not None else ''}")
            for error in payload.get("errors") or []:
                print(f"error={error}")
            for warning in payload.get("warnings") or []:
                print(f"warning={warning}")
        return 0 if payload.get("ok") else 2
    if args.project_command == "authority":
        repo_path = getattr(args, "repo_path", ".") or "."
        if args.project_authority_command == "show":
            payload = build_project_authority_show_payload(repo_path)
        elif args.project_authority_command == "validate":
            payload = validate_project_authority_graph(
                repo_path,
                include_runtime=bool(getattr(args, "include_runtime", False)),
            )
        else:
            raise RuntimeError(f"Unknown project authority command: {args.project_authority_command}")
        if getattr(args, "json", False):
            print(json.dumps(payload, indent=2, ensure_ascii=False))
        else:
            print(f"status={payload.get('status')}")
            print(f"graph_path={payload.get('graph_path') or ''}")
            print(f"domain_count={payload.get('domain_count') if payload.get('domain_count') is not None else ''}")
            print(f"mutation_performed={str(bool(payload.get('mutation_performed'))).lower()}")
            for error in payload.get("errors") or []:
                print(f"error={error}")
            for warning in payload.get("warnings") or []:
                print(f"warning={warning}")
        return 0 if payload.get("ok") else 2
    raise RuntimeError(f"Unknown project command: {args.project_command}")


def _repo_list_payload(args: argparse.Namespace) -> dict[str, Any]:
    identity_payload = _current_project_identity_payload(args)
    if not identity_payload.get("ok"):
        return {
            "action": "repo_list",
            **identity_payload,
            "registry_source": "unresolved",
            "registry_exists": False,
            "registry_valid": False,
            "registry_readable": False,
            "resolution_method": "identity_manifest",
            "fallback_used": False,
        }
    project_id = str(identity_payload["project_id"])
    current_repo_id = str(identity_payload["repo_id"])
    registry = ArtifactRegistry(project_registry_dir(project_id))
    registry_state = registry.inspect()
    if not registry_state.get("ok"):
        return {
            "ok": False,
            "action": "repo_list",
            "status": registry_state.get("status"),
            "project_id": project_id,
            "repo_id": current_repo_id,
            "scope": {"kind": "project", "project_id": project_id, "repo_id": current_repo_id},
            "registry_source": "project_registry",
            "registry_file": str(registry.path),
            "registry_exists": bool(registry_state.get("registry_exists")),
            "registry_valid": bool(registry_state.get("registry_valid")),
            "registry_readable": bool(registry_state.get("registry_readable")),
            "resolution_method": "identity_manifest",
            "fallback_used": False,
            "repo_count": None,
            "repos": None,
            "error": registry_state.get("error"),
        }
    store = ConversationStateStore(str(project_registry_dir(project_id)))
    repos_cfg = configured_repos(project_id)
    registry_ids = registry.repo_ids()
    all_ids = sorted(set(repos_cfg) | set(registry_ids))
    repos: list[dict[str, Any]] = []
    for repo_id in all_ids:
        current = registry.current(repo_id=repo_id)
        state = store.snapshot(identity_payload.get("project_home_url"), repo_id=repo_id)
        cfg = repos_cfg.get(repo_id, {})
        repo_root = cfg.get("repo_root")
        identity_file = str(Path(str(repo_root)).expanduser() / REPO_IDENTITY_FILE_NAME) if repo_root else None
        legacy_registry_file = str(Path(str(repo_root)).expanduser() / ".pb_profile" / "promptbranch_artifacts.json") if repo_root else None
        repos.append({
            "repo_id": repo_id,
            "repo_root": repo_root,
            "role": cfg.get("role"),
            "artifact_pattern": cfg.get("artifact_pattern"),
            "configured": repo_id in repos_cfg,
            "identity_file": identity_file,
            "identity_exists": bool(identity_file and Path(identity_file).is_file()),
            "legacy_repo_local_registry_file": legacy_registry_file,
            "legacy_repo_local_registry_exists": bool(legacy_registry_file and Path(legacy_registry_file).exists()),
            "current_artifact": (current or {}).get("filename") or state.get("artifact_ref"),
            "current_version": (current or {}).get("version") or state.get("artifact_version"),
            "status": "current_found" if current else "missing_current_artifact",
        })
    return {
        "ok": True,
        "action": "repo_list",
        "status": registry_state.get("status"),
        "project_id": project_id,
        "project_home_url": identity_payload.get("project_home_url"),
        "current_repo_id": current_repo_id,
        "scope": {"kind": "project", "project_id": project_id, "repo_id": current_repo_id},
        "registry_file": str(registry.path),
        "registry_source": "project_registry",
        "registry_exists": True,
        "registry_valid": True,
        "registry_readable": True,
        "resolution_method": "identity_manifest",
        "fallback_used": False,
        "local_repo_config_file": str(project_repo_config_path(project_id)),
        "repo_count": len(repos),
        "repos": repos,
    }


def _repo_doctor_payload(args: argparse.Namespace) -> dict[str, Any]:
    base = _repo_list_payload(args)
    if not base.get("ok"):
        return {"action": "repo_doctor", **base, "status": base.get("status") or "failed"}
    checks: list[dict[str, Any]] = []

    def check(check_id: str, passed: bool, **details: Any) -> None:
        item = {"id": check_id, "status": "passed" if passed else "failed"}
        if details:
            item["details"] = details
        checks.append(item)

    project_id = str(base.get("project_id"))
    repos = base.get("repos") if isinstance(base.get("repos"), list) else []
    repo_ids = [str(item.get("repo_id")) for item in repos if isinstance(item, dict) and item.get("repo_id")]
    check("project_identity_found", True)
    check("project_registry_loaded", base.get("registry_valid") is True and base.get("registry_readable") is True, registry_file=base.get("registry_file"), registry_status=base.get("status"))
    check("repo_ids_unique", len(repo_ids) == len(set(repo_ids)), repo_ids=repo_ids)
    not_joined = [repo for repo in repos if isinstance(repo, dict) and not repo.get("configured")]
    check("registry_repos_are_configured", not not_joined, unconfigured_registry_repos=[r.get("repo_id") for r in not_joined])
    missing_identity = [repo.get("repo_id") for repo in repos if isinstance(repo, dict) and repo.get("configured") and not repo.get("identity_exists")]
    check("configured_repos_have_identity", not missing_identity, missing_identity_repos=missing_identity)
    legacy_registries = [repo.get("repo_id") for repo in repos if isinstance(repo, dict) and repo.get("legacy_repo_local_registry_exists")]
    check("legacy_repo_local_registries_absent", not legacy_registries, legacy_registry_repos=legacy_registries)
    missing_current = [repo.get("repo_id") for repo in repos if isinstance(repo, dict) and repo.get("status") != "current_found"]
    check("configured_repos_have_current_artifact", not missing_current, missing_current_artifact=missing_current)
    bad_roots: list[str] = []
    bad_patterns: list[str] = []
    mismatched_identities: list[str] = []
    for repo in repos:
        if not isinstance(repo, dict):
            continue
        repo_id = str(repo.get("repo_id") or "")
        root = repo.get("repo_root")
        if not root or not Path(str(root)).expanduser().is_dir():
            bad_roots.append(repo_id)
            continue
        if not artifact_prefix_matches(repo_id, repo.get("artifact_pattern") if isinstance(repo.get("artifact_pattern"), str) else None):
            bad_patterns.append(repo_id)
        try:
            identity = load_repo_identity(Path(str(root)))
        except ValueError:
            identity = None
        if identity is None or identity.project_id != project_id or identity.repo_id != repo_id or identity.repo_root.resolve() != Path(str(root)).expanduser().resolve():
            mismatched_identities.append(repo_id)
    check("repo_roots_exist", not bad_roots, missing_repo_roots=bad_roots)
    check("artifact_patterns_match_repo_ids", not bad_patterns, mismatched_patterns=bad_patterns)
    check("configured_repo_identities_match", not mismatched_identities, mismatched_identity_repos=mismatched_identities)
    missing_payload = _artifact_current_payload(
        None,
        ArtifactRegistry(project_registry_dir(project_id)),
        repo_id="__promptbranch_missing_repo_doctor__",
        state_store=ConversationStateStore(str(project_registry_dir(project_id))),
    )
    check("missing_repo_lookup_fails_closed", missing_payload.get("status") == "repo_current_not_found", observed_status=missing_payload.get("status"))
    ok = all(item.get("status") == "passed" for item in checks)
    return {**base, "action": "repo_doctor", "ok": ok, "status": "passed" if ok else "failed", "checks": checks}


