async def cmd_artifact_candidate_test(backend: Any, args: argparse.Namespace) -> int:
    """Run the migrated-candidate test gate without adopting or advancing state."""

    registry = _artifact_registry_from_args(args)
    profile_root = resolve_profile_dir(getattr(args, "profile_dir", None))
    repo_root = Path(getattr(args, "repo_path", ".") or ".").expanduser().resolve()
    artifact_arg = str(getattr(args, "artifact", "") or "").strip() or None
    version_arg = str(getattr(args, "version", "") or "").strip() or None
    registry_path, candidate, selection = _select_artifact_candidate_record(profile_root, artifact=artifact_arg, version=version_arg)

    base_payload: dict[str, Any] = {
        "ok": False,
        "action": "artifact_candidate_test",
        "repo_path": str(repo_root),
        "candidate_registry_path": str(registry_path),
        "candidate_selection": selection,
        "download_performed": False,
        "verification_performed": False,
        "migration_performed": False,
        "adoption_performed": False,
        "project_source_mutated": False,
        "project_source_mutation": "not_requested",
        "source_upload_verification": None,
        "artifact_registry_updated": False,
        "state_artifact_updated": False,
        "state_source_updated": False,
    }

    def emit(payload: dict[str, Any], code: int) -> int:
        if getattr(args, "json", False):
            print(json.dumps(payload, indent=2, ensure_ascii=False))
        else:
            print(f"status={payload.get('status')}")
            if payload.get("candidate_path"):
                print(f"candidate_path={payload.get('candidate_path')}")
            if payload.get("error"):
                print(f"error={payload.get('error')}")
        return code

    if candidate is None:
        return emit({**base_payload, "status": selection.get("status") or "candidate_not_found", "error": "candidate_release not found or ambiguous; pass --artifact or --version to select exactly one candidate"}, 1)

    filename = _safe_artifact_filename(candidate.get("filename") or Path(str(candidate.get("path") or "")).name)
    if not filename:
        return emit({**base_payload, "status": "artifact_wrong_filename", "candidate": candidate, "error": "candidate filename must be a basename ending in .zip"}, 1)
    candidate_version = _candidate_version_normalized(candidate.get("version") or candidate.get("zip_version") or candidate.get("filename_version") or _artifact_version_from_filename(filename))
    if not candidate_version:
        return emit({**base_payload, "status": "artifact_wrong_version", "candidate": candidate, "artifact_ref": filename, "error": "candidate version is missing or invalid"}, 1)

    candidate_path_value = str(candidate.get("path") or "")
    candidate_path = Path(candidate_path_value).expanduser().resolve() if candidate_path_value else (repo_root / filename).resolve()
    payload = {
        **base_payload,
        "status": "candidate_selected",
        "candidate": candidate,
        "artifact_ref": filename,
        "artifact_version": candidate_version,
        "candidate_path": str(candidate_path),
    }

    if candidate.get("kind") != "candidate_release" or candidate.get("status") not in {"candidate_release", "migrated_candidate"}:
        return emit({**payload, "ok": False, "status": "candidate_not_release", "error": "selected record is not an unaccepted candidate_release"}, 1)
    if candidate.get("accepted") is True or candidate.get("adoption_performed") is True:
        return emit({**payload, "ok": False, "status": "candidate_already_accepted", "error": "accepted candidates are outside the migrated-candidate test gate"}, 1)
    if candidate.get("verified") is not True:
        return emit({**payload, "ok": False, "status": "candidate_not_verified", "error": "candidate must be verified before candidate testing"}, 1)
    if not candidate_path.is_file():
        return emit({**payload, "ok": False, "status": "candidate_zip_missing", "error": "candidate ZIP does not exist at the registered path"}, 1)
    if candidate_path.parent != repo_root:
        return emit({**payload, "ok": False, "status": "candidate_not_repo_root", "error": "candidate ZIP must be migrated directly under the selected repo root before testing"}, 1)

    metadata = _artifact_file_metadata(candidate_path)
    expected_sha = str(candidate.get("sha256") or "")
    if expected_sha and metadata.get("sha256") != expected_sha:
        return emit({**payload, "ok": False, "status": "candidate_sha_mismatch", "file": metadata, "error": "candidate ZIP sha256 differs from candidate registry metadata"}, 1)

    zip_check = verify_zip_artifact(candidate_path)
    zip_version = _read_zip_version_file(candidate_path)
    if not bool(zip_check.get("ok")):
        return emit({**payload, "ok": False, "status": "candidate_zip_invalid", "zip": zip_check, "error": "candidate ZIP failed verification"}, 1)
    if zip_version != candidate_version:
        return emit({**payload, "ok": False, "status": "candidate_version_mismatch", "zip": zip_check, "zip_version": zip_version, "error": "candidate ZIP VERSION does not match candidate version"}, 1)

    release_control_script = repo_root / "chatgpt_claudecode_workflow_release_control.sh"
    if not release_control_script.is_file():
        return emit({**payload, "ok": False, "status": "release_control_missing", "zip": zip_check, "error": f"release-control script not found: {release_control_script}"}, 1)
    if not os.access(release_control_script, os.X_OK):
        return emit({**payload, "ok": False, "status": "release_control_not_executable", "zip": zip_check, "error": f"release-control script is not executable: {release_control_script}"}, 1)

    test_profile = str(getattr(args, "profile", "smoke") or "smoke").strip().lower()
    try:
        command = _candidate_test_command_for_profile(
            repo_root,
            version=candidate_version,
            profile=test_profile,
            release_log_keep=int(getattr(args, "release_log_keep", 12) or 12),
            skip_docker_logs=bool(getattr(args, "skip_docker_logs", True)),
            prune_release_logs=bool(getattr(args, "prune_release_logs", True)),
        )
    except ValueError as exc:
        return emit({**payload, "ok": False, "status": "candidate_test_profile_invalid", "test_profile": test_profile, "error": str(exc)}, 1)

    allowed_script = str((repo_root / "chatgpt_claudecode_workflow_release_control.sh").resolve())
    allowed_promptbranch = str(Path(_promptbranch_command_path()).resolve()) if Path(_promptbranch_command_path()).exists() else _promptbranch_command_path()
    command_kind = "release_control_full" if command and str(Path(command[0]).resolve()) == allowed_script else "promptbranch_smoke" if len(command) >= 4 and command[0] == sys.executable and command[2:5] == ["test", "smoke", "--json"] else "unknown"
    if command_kind == "promptbranch_smoke":
        try:
            if str(Path(command[1]).resolve()) != allowed_promptbranch:
                command_kind = "unknown"
        except Exception:
            command_kind = "unknown"
    if command_kind == "unknown":
        return emit({**payload, "ok": False, "status": "candidate_test_delegate_command_rejected", "test_profile": test_profile, "delegated_command": command, "error": "candidate-test may only delegate to pb test smoke --json or the repo-local release-control tests-only command"}, 1)

    preflight = {
        **payload,
        "ok": True,
        "status": "candidate_test_preflight_verified",
        "candidate_file": metadata,
        "zip": zip_check,
        "checks": {
            "candidate_record_selected": True,
            "candidate_unaccepted": True,
            "candidate_verified": True,
            "candidate_zip_exists": True,
            "candidate_sha_matches_registry": not expected_sha or metadata.get("sha256") == expected_sha,
            "zip_verified": bool(zip_check.get("ok")),
            "zip_version_matches_candidate": zip_version == candidate_version,
            "project_source_mutated": False,
            "adoption_performed": False,
        },
        "verification_performed": True,
        "test_profile": test_profile,
        "delegated_command": command,
        "delegated_command_kind": command_kind,
        "test_timeout_seconds": float(getattr(args, "test_timeout", 540.0) or 540.0),
        "operator_instruction": "Candidate test preflight verified. Running bounded candidate-test profile; adoption and Project Source mutation are disabled.",
    }

    if getattr(args, "preflight_only", False):
        return emit(preflight, 0)

    timeout_seconds = float(getattr(args, "test_timeout", 540.0) or 540.0)
    log_dir = _candidate_test_logs_dir(profile_root) / candidate_version
    timestamp = utc_now().replace(":", "").replace("-", "")
    stdout_log_path = log_dir / f"candidate_test.{timestamp}.stdout.log"
    stderr_log_path = log_dir / f"candidate_test.{timestamp}.stderr.log"
    test_result = _run_release_control_candidate_test(
        command,
        repo_root=repo_root,
        timeout_seconds=timeout_seconds,
        stdout_log_path=stdout_log_path,
        stderr_log_path=stderr_log_path,
    )
    record_path, updated_candidate = _record_artifact_candidate_test(profile_root, candidate=candidate, test_result=test_result)
    result = {
        **preflight,
        "ok": bool(test_result.get("ok")),
        "status": "candidate_test_passed" if test_result.get("ok") else (test_result.get("status") or "candidate_test_failed"),
        "candidate_test_status": test_result.get("status"),
        "candidate_test": test_result,
        "candidate_test_record_path": str(record_path),
        "candidate_registry_updated": True,
        "candidate_registry_entry": updated_candidate,
        "artifact_registry_updated": False,
        "state_artifact_updated": False,
        "state_source_updated": False,
        "project_source_mutated": False,
        "adoption_performed": False,
        "operator_instruction": "Migrated candidate was tested and recorded only. Adoption, Project Source mutation, and artifact/source current state advancement were not performed.",
    }
    return emit(result, 0 if result["ok"] else 1)


def _candidate_latest_test_gate(candidate: dict[str, Any], *, profile_dir: str | Path) -> tuple[bool, dict[str, Any]]:
    """Validate that a migrated candidate already passed the candidate-test gate."""

    latest_test = candidate.get("latest_test") if isinstance(candidate.get("latest_test"), dict) else {}
    record_path_value = str(latest_test.get("record_path") or "")
    record_path = Path(record_path_value).expanduser() if record_path_value else None
    record_payload: dict[str, Any] | None = None
    record_error: str | None = None
    if record_path is not None:
        try:
            if not record_path.is_absolute():
                record_path = Path(profile_dir).expanduser().resolve() / record_path
            if record_path.is_file():
                parsed = json.loads(record_path.read_text(encoding="utf-8"))
                if isinstance(parsed, dict):
                    record_payload = parsed
                else:
                    record_error = "candidate_test_record_not_object"
            else:
                record_error = "candidate_test_record_missing"
        except (OSError, json.JSONDecodeError) as exc:
            record_error = f"candidate_test_record_unreadable: {exc}"

    result = record_payload.get("result") if isinstance(record_payload, dict) and isinstance(record_payload.get("result"), dict) else {}
    checks = {
        "latest_test_present": bool(latest_test),
        "latest_test_ok": latest_test.get("ok") is True,
        "latest_test_status_passed": latest_test.get("status") == "candidate_test_passed",
        "latest_test_adoption_not_performed": latest_test.get("adoption_performed") is False,
        "record_path_present": bool(record_path_value),
        "record_path_exists": bool(record_path is not None and record_path.is_file()),
        "record_result_ok": result.get("ok") is True if result else False,
        "record_result_status_passed": result.get("status") == "candidate_test_passed" if result else False,
        "record_adoption_not_performed": record_payload.get("adoption_performed") is False if isinstance(record_payload, dict) else False,
    }
    ok = all(checks.values())
    diagnostic = {
        "ok": ok,
        "status": "candidate_test_gate_passed" if ok else "candidate_not_tested",
        "latest_test": latest_test,
        "record_path": str(record_path) if record_path is not None else None,
        "record_error": record_error,
        "checks": checks,
    }
    if record_payload is not None:
        diagnostic["record"] = {
            "schema": record_payload.get("schema"),
            "schema_version": record_payload.get("schema_version"),
            "result": result,
            "adoption_performed": record_payload.get("adoption_performed"),
            "project_source_mutated": record_payload.get("project_source_mutated"),
        }
    return ok, diagnostic


def _candidate_status_recommended_command(*, candidate_version: str | None, lifecycle: dict[str, Any]) -> dict[str, Any]:
    """Return the next readably actionable command for the candidate lifecycle."""

    if not lifecycle.get("candidate_selected"):
        return {
            "kind": "intake_candidate",
            "command": "pb artifact intake --from-last-answer --download --verify --migrate --json",
            "reason": "no migrated candidate is selected yet",
        }
    if lifecycle.get("candidate_accepted"):
        return {
            "kind": "candidate_already_accepted",
            "command": "pb artifact current --json",
            "reason": "candidate already appears accepted; inspect current baseline before continuing",
        }
    version_flag = f" --version {candidate_version}" if candidate_version else ""
    if lifecycle.get("candidate_zip_exists") is False or not lifecycle.get("candidate_verified"):
        return {
            "kind": "repair_or_remigrate_candidate",
            "command": "pb artifact intake --from-last-answer --download --verify --migrate --json",
            "reason": "candidate ZIP is missing or no longer verifies",
        }
    if not lifecycle.get("candidate_test_passed"):
        return {
            "kind": "test_candidate",
            "command": f"pb artifact candidate-test{version_flag} --json",
            "reason": "candidate is migrated and verified but has no passing candidate-test record",
        }
    return {
        "kind": "accept_candidate",
        "command": f"pb artifact accept-candidate{version_flag} --adopt-if-green --json",
        "reason": "candidate is migrated, verified, and tested but not yet accepted",
    }


def _artifact_candidate_lifecycle_status(
    backend: Any,
    *,
    registry: ArtifactRegistry,
    profile_root: Path,
    repo_root: Path,
    candidate: dict[str, Any] | None,
    selection: dict[str, Any],
) -> dict[str, Any]:
    current_payload = _artifact_current_payload(backend, registry)
    base = {
        "ok": True,
        "action": "artifact_candidate_status",
        "status": selection.get("status") or "candidate_not_found",
        "repo_path": str(repo_root),
        "candidate_registry_path": str(_artifact_candidates_registry_path(profile_root)),
        "candidate_selection": selection,
        "artifact_current": current_payload,
        "read_only": True,
        "mutating_actions_executed": False,
        "download_performed": False,
        "verification_performed": False,
        "migration_performed": False,
        "candidate_test_performed": False,
        "adoption_performed": False,
        "project_source_mutated": False,
        "project_source_mutation": "not_requested",
        "source_upload_verification": None,
        "artifact_registry_updated": False,
        "state_artifact_updated": False,
        "state_source_updated": False,
    }

    if candidate is None:
        lifecycle = {
            "candidate_selected": False,
            "candidate_downloaded": False,
            "candidate_verified": False,
            "candidate_migrated": False,
            "candidate_test_passed": False,
            "candidate_accepted": False,
            "adoption_eligible": False,
        }
        return {
            **base,
            "ok": True,
            "status": selection.get("status") or "candidate_not_found",
            "candidate": None,
            "lifecycle": lifecycle,
            "recommended_next_command": _candidate_status_recommended_command(candidate_version=None, lifecycle=lifecycle),
            "operator_instruction": "No migrated candidate was selected. Run artifact intake to download, verify, and migrate a candidate first.",
        }

    filename = _safe_artifact_filename(candidate.get("filename") or Path(str(candidate.get("path") or "")).name)
    candidate_version = _candidate_version_normalized(candidate.get("version") or candidate.get("zip_version") or candidate.get("filename_version") or _artifact_version_from_filename(filename or ""))
    candidate_path_value = str(candidate.get("path") or "")
    candidate_path = Path(candidate_path_value).expanduser().resolve() if candidate_path_value else ((repo_root / filename).resolve() if filename else repo_root)
    candidate_zip_exists = bool(filename and candidate_path.is_file())
    candidate_file: dict[str, Any] | None = None
    sha_matches_registry = False
    zip_check: dict[str, Any] | None = None
    zip_version: str | None = None
    zip_version_matches_candidate = False
    if candidate_zip_exists:
        candidate_file = _artifact_file_metadata(candidate_path)
        expected_sha = str(candidate.get("sha256") or "")
        sha_matches_registry = not expected_sha or candidate_file.get("sha256") == expected_sha
        zip_check = verify_zip_artifact(candidate_path)
        zip_version = _read_zip_version_file(candidate_path)
        zip_version_matches_candidate = bool(candidate_version and zip_version == candidate_version)

    inbox_path = Path(str(candidate.get("source_inbox_path") or "")).expanduser() if candidate.get("source_inbox_path") else None
    candidate_downloaded = bool(inbox_path and inbox_path.is_file())
    candidate_migrated = bool(candidate.get("migration_performed") is True and candidate_zip_exists and candidate_path.parent == repo_root)
    candidate_verified = bool(candidate.get("verified") is True and zip_check and zip_check.get("ok") and sha_matches_registry and zip_version_matches_candidate)
    test_gate_ok, test_gate = _candidate_latest_test_gate(candidate, profile_dir=profile_root)
    current_match_ok, current_checks = _report_artifact_current_matches_candidate(
        current_payload,
        filename=filename or "",
        version=candidate_version or "",
        require_runtime_code_match=False,
    )
    candidate_accepted = bool(candidate.get("accepted") is True or candidate.get("adoption_performed") is True or current_match_ok)
    adoption_eligible = bool(
        filename
        and candidate_version
        and candidate.get("kind") == "candidate_release"
        and not candidate_accepted
        and candidate_migrated
        and candidate_verified
        and test_gate_ok
    )
    lifecycle = {
        "candidate_selected": True,
        "candidate_downloaded": candidate_downloaded,
        "candidate_zip_exists": candidate_zip_exists,
        "candidate_verified": candidate_verified,
        "candidate_migrated": candidate_migrated,
        "candidate_test_passed": test_gate_ok,
        "candidate_accepted": candidate_accepted,
        "adoption_eligible": adoption_eligible,
    }
    checks = {
        "candidate_filename_valid": bool(filename),
        "candidate_version_valid": bool(candidate_version),
        "candidate_kind_is_release": candidate.get("kind") == "candidate_release",
        "candidate_unaccepted": not candidate_accepted,
        "candidate_zip_exists": candidate_zip_exists,
        "candidate_zip_in_repo_root": bool(candidate_zip_exists and candidate_path.parent == repo_root),
        "candidate_sha_matches_registry": sha_matches_registry,
        "zip_verified": bool(zip_check and zip_check.get("ok")),
        "zip_version_matches_candidate": zip_version_matches_candidate,
        "candidate_test_passed": test_gate_ok,
        "current_matches_candidate": current_match_ok,
    }
    status = "candidate_status_reported"
    if candidate_accepted:
        status = "candidate_already_accepted"
    elif adoption_eligible:
        status = "candidate_ready_for_acceptance"
    elif test_gate_ok:
        status = "candidate_tested_not_ready" if not candidate_verified else "candidate_tested_pending_acceptance"
    elif candidate_verified:
        status = "candidate_verified_pending_test"
    elif candidate_migrated:
        status = "candidate_migrated_needs_verification"

    selected_protocol_reply = _candidate_protocol_selection(candidate)
    return {
        **base,
        "status": status,
        "candidate": candidate,
        "selected_protocol_reply": selected_protocol_reply,
        "selected_request_id": selected_protocol_reply.get("request_id") if selected_protocol_reply else None,
        "selected_message_id": selected_protocol_reply.get("message_id") if selected_protocol_reply else None,
        "selected_answer_id": selected_protocol_reply.get("answer_id") if selected_protocol_reply else None,
        "artifact_ref": filename,
        "artifact_version": candidate_version,
        "candidate_path": str(candidate_path) if filename else None,
        "candidate_file": candidate_file,
        "source_inbox_path": str(inbox_path) if inbox_path else None,
        "zip": zip_check,
        "zip_version": zip_version,
        "candidate_test_gate": test_gate,
        "current_checks": current_checks,
        "checks": checks,
        "lifecycle": lifecycle,
        "recommended_next_command": _candidate_status_recommended_command(candidate_version=candidate_version, lifecycle=lifecycle),
        "operator_instruction": "Read-only candidate lifecycle status report. No download, verification write, migration, candidate-test, adoption, Project Source mutation, or state advancement was performed.",
    }


def _artifact_candidate_lifecycle_status_all(
    backend: Any,
    *,
    registry: ArtifactRegistry,
    profile_root: Path,
    repo_root: Path,
) -> dict[str, Any]:
    """Return a read-only lifecycle inventory for every registered candidate."""

    registry_path = _artifact_candidates_registry_path(profile_root)
    payload = _load_artifact_candidate_registry(profile_root)
    candidates = [item for item in payload.get("candidates", []) if isinstance(item, dict)]
    reports: list[dict[str, Any]] = []
    status_counts: dict[str, int] = {}
    lifecycle_counts = {
        "selected": 0,
        "downloaded": 0,
        "zip_exists": 0,
        "verified": 0,
        "migrated": 0,
        "tested": 0,
        "accepted": 0,
        "adoption_eligible": 0,
    }

    for index, candidate in enumerate(candidates, start=1):
        filename = str(candidate.get("filename") or Path(str(candidate.get("path") or "")).name)
        version = _candidate_version_normalized(
            candidate.get("version")
            or candidate.get("zip_version")
            or candidate.get("filename_version")
            or _artifact_version_from_filename(filename)
        )
        selection = {
            "status": "candidate_selected",
            "candidate_count": len(candidates),
            "match_count": 1,
            "index": index,
            "registry_path": str(registry_path),
        }
        report = _artifact_candidate_lifecycle_status(
            backend,
            registry=registry,
            profile_root=profile_root,
            repo_root=repo_root,
            candidate=candidate,
            selection=selection,
        )
        compact = {
            "index": index,
            "status": report.get("status"),
            "artifact_ref": report.get("artifact_ref") or filename or None,
            "artifact_version": report.get("artifact_version") or version,
            "candidate_path": report.get("candidate_path"),
            "lifecycle": report.get("lifecycle"),
            "checks": report.get("checks"),
            "recommended_next_command": report.get("recommended_next_command"),
            "selected_protocol_reply": report.get("selected_protocol_reply"),
        }
        reports.append(compact)
        status_text = str(compact.get("status") or "unknown")
        status_counts[status_text] = status_counts.get(status_text, 0) + 1
        lifecycle = compact.get("lifecycle") if isinstance(compact.get("lifecycle"), dict) else {}
        if lifecycle.get("candidate_selected"):
            lifecycle_counts["selected"] += 1
        if lifecycle.get("candidate_downloaded"):
            lifecycle_counts["downloaded"] += 1
        if lifecycle.get("candidate_zip_exists"):
            lifecycle_counts["zip_exists"] += 1
        if lifecycle.get("candidate_verified"):
            lifecycle_counts["verified"] += 1
        if lifecycle.get("candidate_migrated"):
            lifecycle_counts["migrated"] += 1
        if lifecycle.get("candidate_test_passed"):
            lifecycle_counts["tested"] += 1
        if lifecycle.get("candidate_accepted"):
            lifecycle_counts["accepted"] += 1
        if lifecycle.get("adoption_eligible"):
            lifecycle_counts["adoption_eligible"] += 1

    if not reports:
        lifecycle = {
            "candidate_selected": False,
            "candidate_downloaded": False,
            "candidate_verified": False,
            "candidate_migrated": False,
            "candidate_test_passed": False,
            "candidate_accepted": False,
            "adoption_eligible": False,
        }
        recommended = _candidate_status_recommended_command(candidate_version=None, lifecycle=lifecycle)
        status = "candidate_registry_empty"
    elif lifecycle_counts["adoption_eligible"] > 0:
        recommended = next(
            (item.get("recommended_next_command") for item in reports if isinstance(item.get("lifecycle"), dict) and item["lifecycle"].get("adoption_eligible")),
            {"kind": "inspect_candidate", "command": "pb artifact candidate-status --all --json", "reason": "inspect candidate lifecycle inventory"},
        )
        status = "candidate_inventory_has_adoption_ready"
    else:
        actionable_reports = _candidate_next_actionable_candidates(reports)
        if actionable_reports:
            selected_actionable = min(actionable_reports, key=_candidate_next_priority)
            recommended = selected_actionable.get("recommended_next_command") if isinstance(selected_actionable.get("recommended_next_command"), dict) else {"kind": "inspect_candidate", "command": "pb artifact candidate-status --all --json", "reason": "inspect candidate lifecycle inventory"}
            status = "candidate_inventory_reported"
        else:
            recommended = _candidate_next_no_actionable_recommendation(
                historical_count=_candidate_next_historical_candidate_count(reports),
                candidate_count=len(reports),
            )
            status = "candidate_inventory_history_only"

    return {
        "ok": True,
        "action": "artifact_candidate_status",
        "status": status,
        "repo_path": str(repo_root),
        "candidate_registry_path": str(registry_path),
        "candidate_count": len(candidates),
        "status_counts": status_counts,
        "lifecycle_counts": lifecycle_counts,
        "candidates": reports,
        "artifact_current": _artifact_current_payload(backend, registry),
        "read_only": True,
        "mutating_actions_executed": False,
        "download_performed": False,
        "verification_performed": False,
        "migration_performed": False,
        "candidate_test_performed": False,
        "adoption_performed": False,
        "project_source_mutated": False,
        "project_source_mutation": "not_requested",
        "source_upload_verification": None,
        "artifact_registry_updated": False,
        "state_artifact_updated": False,
        "state_source_updated": False,
        "recommended_next_command": recommended,
        "operator_instruction": "Read-only candidate lifecycle inventory. No download, verification write, migration, candidate-test, adoption, Project Source mutation, or state advancement was performed.",
    }

async def cmd_artifact_candidate_status(backend: Any, args: argparse.Namespace) -> int:
    """Report candidate lifecycle state without mutating anything."""

    registry = _artifact_registry_from_args(args)
    profile_root = resolve_profile_dir(getattr(args, "profile_dir", None))
    repo_root = Path(getattr(args, "repo_path", ".") or ".").expanduser().resolve()
    artifact_arg = str(getattr(args, "artifact", "") or "").strip() or None
    version_arg = str(getattr(args, "version", "") or "").strip() or None
    if getattr(args, "all", False):
        payload = _artifact_candidate_lifecycle_status_all(
            backend,
            registry=registry,
            profile_root=profile_root,
            repo_root=repo_root,
        )
    else:
        registry_path, candidate, selection = _select_artifact_candidate_record(profile_root, artifact=artifact_arg, version=version_arg)
        selection = {**selection, "registry_path": str(registry_path)}
        payload = _artifact_candidate_lifecycle_status(
            backend,
            registry=registry,
            profile_root=profile_root,
            repo_root=repo_root,
            candidate=candidate,
            selection=selection,
        )
    if getattr(args, "json", False):
        print(json.dumps(payload, indent=2, ensure_ascii=False))
    else:
        print(f"status={payload.get('status')}")
        if "candidate_count" in payload:
            print(f"candidate_count={payload.get('candidate_count')}")
        print(f"artifact_ref={payload.get('artifact_ref') or 'none'}")
        print(f"artifact_version={payload.get('artifact_version') or 'none'}")
        lifecycle = payload.get("lifecycle") if isinstance(payload.get("lifecycle"), dict) else {}
        if lifecycle:
            print(f"candidate_test_passed={lifecycle.get('candidate_test_passed')}")
            print(f"adoption_eligible={lifecycle.get('adoption_eligible')}")
        command = payload.get("recommended_next_command") if isinstance(payload.get("recommended_next_command"), dict) else {}
        if command.get("command"):
            print(f"recommended_next_command={command.get('command')}")
    return 0






MVP_DOD_DOC_RELATIVE_PATH = "docs/mvp-definition-of-done.md"
MVP_DOD_REQUIRED_SECTIONS = [
    "# Promptbranch MVP Definition of Done",
    "## MVP boundary",
    "## Required operator workflow",
    "## Required invariants",
    "## Required failure behavior",
    "## Required evidence artifacts",
    "## Out of scope for MVP",
    "## Final MVP verdict rule",
]
MVP_DOD_REQUIRED_WORKFLOW_MARKERS = [
    "pb ws use",
    "pb task use",
    "pb ask",
    "--protocol",
    "pb task answer parse",
    "pb artifact intake",
    "--download",
    "--verify",
    "--verify-smoke-zip",
    "--expect-entry",
    "--expect-content",
    "--migrate",
    "scripts/finalize-artifact-intake-mvp.sh",
    "--require-real-candidate-mvp",
    "pb artifact current",
    "--from-current-baseline",
]


def _mvp_dod_visibility_report(repo_root: Path) -> dict[str, Any]:
    """Return a read-only visibility/check report for the canonical MVP DoD doc."""

    repo_root = Path(repo_root).expanduser().resolve()
    doc_path = repo_root / MVP_DOD_DOC_RELATIVE_PATH
    text = ""
    read_error = None
    if doc_path.exists() and doc_path.is_file():
        try:
            text = doc_path.read_text(encoding="utf-8")
        except Exception as exc:  # pragma: no cover - defensive against unreadable files
            read_error = str(exc)

    sections = {section: (section in text) for section in MVP_DOD_REQUIRED_SECTIONS}
    workflow_markers = {marker: (marker in text) for marker in MVP_DOD_REQUIRED_WORKFLOW_MARKERS}
    final_verdict_present = "twice in a row" in text and "no manual ZIP repair" in text
    missing_sections = [section for section, present in sections.items() if not present]
    missing_workflow_markers = [marker for marker, present in workflow_markers.items() if not present]
    ok = bool(doc_path.exists() and doc_path.is_file() and not read_error and not missing_sections and not missing_workflow_markers and final_verdict_present)
    status = "mvp_dod_visible" if ok else "mvp_dod_incomplete"
    if not doc_path.exists():
        status = "mvp_dod_missing"
    elif read_error:
        status = "mvp_dod_unreadable"

    return {
        "ok": ok,
        "status": status,
        "path": MVP_DOD_DOC_RELATIVE_PATH,
        "absolute_path": str(doc_path),
        "exists": doc_path.exists(),
        "readable": bool(text) and read_error is None,
        "read_error": read_error,
        "read_only": True,
        "mutating_actions_executed": False,
        "sections": sections,
        "missing_sections": missing_sections,
        "workflow_markers": workflow_markers,
        "missing_workflow_markers": missing_workflow_markers,
        "final_verdict_rule_present": final_verdict_present,
        "summary": (
            "Canonical MVP Definition of Done is present and contains the required visibility sections."
            if ok else
            "Canonical MVP Definition of Done is missing, unreadable, or lacks required visibility markers."
        ),
    }


def _latest_smoke_zip_verification_report(profile_root: Path) -> dict[str, Any]:
    """Return the newest persisted smoke ZIP verification evidence, read-only.

    This evidence is intentionally separate from strict release verification. It
    proves the ChatGPT UI attachment transport path before the operator relies
    on release-candidate verification/migration.
    """

    root = Path(profile_root).expanduser().resolve()
    inbox_root = root / "artifact_inbox"
    records: list[dict[str, Any]] = []
    if inbox_root.exists():
        for path in inbox_root.rglob("intake.json"):
            try:
                data = json.loads(path.read_text(encoding="utf-8"))
            except (OSError, json.JSONDecodeError):
                continue
            if not isinstance(data, dict):
                continue
            if data.get("smoke_verification_performed") is not True:
                continue
            smoke = data.get("smoke_verification") if isinstance(data.get("smoke_verification"), dict) else {}
            records.append({
                "record_path": str(path),
                "verified_at": data.get("verified_at"),
                "ok": data.get("ok") is True and smoke.get("ok") is True,
                "status": data.get("status") or smoke.get("status"),
                "filename": (data.get("candidate") or {}).get("filename") if isinstance(data.get("candidate"), dict) else None,
                "download": data.get("download") if isinstance(data.get("download"), dict) else {},
                "smoke_verification": smoke,
                "reply_request_id": data.get("reply_request_id"),
                "conversation_id": data.get("conversation_id"),
                "answer_id": data.get("answer_id"),
            })
    records.sort(key=lambda item: str(item.get("verified_at") or item.get("record_path") or ""), reverse=True)
    latest = records[0] if records else None
    return {
        "ok": bool(latest and latest.get("ok") is True),
        "status": "smoke_zip_verified" if latest and latest.get("ok") is True else "smoke_zip_evidence_missing",
        "read_only": True,
        "mutating_actions_executed": False,
        "record_count": len(records),
        "latest": latest,
        "operator_instruction": (
            "Latest smoke ZIP evidence proves ChatGPT UI attachment download and expected ZIP contents."
            if latest and latest.get("ok") is True else
            "Run pb artifact intake --from-last-answer --download --verify-smoke-zip --expect-entry hello.txt --expect-content <text> --json to create transport proof."
        ),
    }


async def cmd_artifact_mvp_dod(backend: Any, args: argparse.Namespace) -> int:
    """Check the canonical MVP Definition of Done document without mutating anything."""

    repo_root = Path(getattr(args, "repo_path", ".") or ".").expanduser().resolve()
    report = _mvp_dod_visibility_report(repo_root)
    smoke_report = _latest_smoke_zip_verification_report(resolve_profile_dir(getattr(args, "profile_dir", None)))
    payload = {
        "ok": bool(report.get("ok")),
        "action": "artifact_mvp_dod",
        "status": report.get("status"),
        "repo_path": str(repo_root),
        "profile_dir": str(resolve_profile_dir(getattr(args, "profile_dir", None))),
        "read_only": True,
        "mutating_actions_executed": False,
        "mvp_definition_of_done": report,
        "smoke_zip_verification": smoke_report,
        "operator_instruction": (
            "Read-only MVP DoD visibility and smoke-evidence check. This command reports whether the canonical DoD document is present "
            "and whether a recent ChatGPT UI attachment smoke ZIP proof exists; it does not enforce the full MVP gate or mutate artifact/source state."
        ),
    }
    if getattr(args, "json", False):
        print(json.dumps(payload, indent=2, ensure_ascii=False))
    else:
        print("MVP Definition of Done")
        print("======================")
        print(f"status:             {payload.get('status')}")
        print(f"ok:                 {str(payload.get('ok')).lower()}")
        print(f"path:               {report.get('path')}")
        print(f"exists:             {str(report.get('exists')).lower()}")
        print(f"missing_sections:   {len(report.get('missing_sections') or [])}")
        print(f"missing_workflow:   {len(report.get('missing_workflow_markers') or [])}")
        print(f"final_verdict_rule: {str(report.get('final_verdict_rule_present')).lower()}")
        print(f"smoke_zip_status:    {smoke_report.get('status')}")
    return 0 if payload.get("ok") else 1


async def cmd_artifact_mvp_status(backend: Any, args: argparse.Namespace) -> int:
    """Report the Artifact Intake MVP cockpit state without mutating anything."""

    registry = _artifact_registry_from_args(args)
    profile_root = resolve_profile_dir(getattr(args, "profile_dir", None))
    repo_root = Path(getattr(args, "repo_path", ".") or ".").expanduser().resolve()
    artifact_arg = str(getattr(args, "artifact", "") or "").strip() or None
    version_arg = str(getattr(args, "version", "") or "").strip() or None

    completion = _candidate_run_mvp_completion_report(
        backend,
        registry=registry,
        profile_root=profile_root,
        repo_root=repo_root,
        artifact_arg=artifact_arg,
        version_arg=version_arg,
    )
    next_payload, candidate_count, inventory = _candidate_run_next_payload(
        backend,
        registry=registry,
        profile_root=profile_root,
        repo_root=repo_root,
        artifact_arg=artifact_arg,
        version_arg=version_arg,
    )
    precondition = _latest_protocol_artifact_candidate_precondition(profile_root)
    current_payload = _artifact_current_payload(backend, registry)
    lifecycle_classification = _artifact_mvp_operator_classification(
        current_payload=current_payload,
        completion=completion,
        next_payload=next_payload,
        precondition=precondition,
        candidate_count=candidate_count,
    )
    remediation_plan = _artifact_mvp_remediation_plan(
        lifecycle_classification=lifecycle_classification,
        current_payload=current_payload,
        completion=completion,
        next_payload=next_payload,
        precondition=precondition,
        repo_root=repo_root,
    )
    mvp_dod_report = _mvp_dod_visibility_report(repo_root)
    smoke_zip_report = _latest_smoke_zip_verification_report(profile_root)

    finalizer_command = None
    if current_payload.get("artifact_version"):
        finalizer_command = (
            "scripts/finalize-artifact-intake-mvp.sh "
            f"--version {current_payload.get('artifact_version')} --target-version <next-version>"
        )

    inventory_summary = {
        "candidate_count": inventory.get("candidate_count") if isinstance(inventory, dict) else candidate_count,
        "status": inventory.get("status") if isinstance(inventory, dict) else "scoped_candidate_next",
        "registry_path": inventory.get("candidate_registry_path") if isinstance(inventory, dict) else str(_artifact_candidates_registry_path(profile_root)),
    }

    payload = {
        "ok": True,
        "action": "artifact_mvp_status",
        "status": completion.get("status"),
        "operator_verdict": lifecycle_classification.get("operator_verdict"),
        "severity": lifecycle_classification.get("severity"),
        "warning_codes": lifecycle_classification.get("warning_codes"),
        "blocker_codes": lifecycle_classification.get("blocker_codes"),
        "mvp_complete": bool(completion.get("ok")),
        "repo_path": str(repo_root),
        "profile_dir": str(profile_root),
        "candidate_registry_path": str(_artifact_candidates_registry_path(profile_root)),
        "read_only": True,
        "mutating_actions_executed": False,
        "download_performed": False,
        "verification_performed": False,
        "migration_performed": False,
        "candidate_test_performed": False,
        "adoption_performed": False,
        "project_source_mutated": False,
        "project_source_mutation": "not_requested",
        "source_upload_verification": None,
        "artifact_registry_updated": False,
        "state_artifact_updated": False,
        "state_source_updated": False,
        "artifact_current": current_payload,
        "lifecycle_classification": lifecycle_classification,
        "remediation_plan": remediation_plan,
        "next_safe_actions": remediation_plan.get("next_safe_actions"),
        "candidate_count": candidate_count,
        "candidate_intake_precondition": precondition,
        "candidate_next": next_payload,
        "mvp_completion": completion,
        "inventory_summary": inventory_summary,
        "mvp_definition_of_done": mvp_dod_report,
        "smoke_zip_verification": smoke_zip_report,
        "commands": {
            "inspect_current": "pb artifact current --json",
            "inspect_candidates": "pb artifact candidate-status --all --json",
            "inspect_next": "pb artifact candidate-next --json",
            "execute_until_blocked": "pb artifact candidate-run --execute-until-blocked --require-complete --json",
            "finalize_mvp": finalizer_command,
            "inspect_mvp_dod": "pb artifact mvp-dod --json",
            "verify_smoke_zip": "pb artifact intake --from-last-answer --download --verify-smoke-zip --expect-entry hello.txt --expect-content 'durable ChatGPT UI attachment smoke test' --json",
        },
        "operator_instruction": (
            "Read-only Artifact Intake MVP cockpit. Use candidate_next.recommended_next_command "
            "for the next manual step, or execute the bounded lifecycle with candidate-run."
        ),
    }

    if getattr(args, "json", False):
        print(json.dumps(payload, indent=2, ensure_ascii=False))
    else:
        print(f"status={payload.get('status')}")
        print(f"operator_verdict={payload.get('operator_verdict')}")
        print(f"severity={payload.get('severity')}")
        print(f"mvp_complete={str(payload.get('mvp_complete')).lower()}")
