async def cmd_browser(backend: CommandBackend, args: argparse.Namespace) -> int:
    if args.browser_command == "status":
        result = await backend.browser_status()
        if isinstance(result, dict):
            result = dict(result)
            policy = service_browser_queue_policy("src_add")
            result.setdefault("service_queue", policy)
            result["queue_enabled"] = bool(result.get("queue_enabled") or policy.get("queue_enabled"))
            result.setdefault("queue_mode", policy.get("queue_mode"))
            result.setdefault("default_queue_wait_timeout_seconds", policy.get("default_wait_timeout_seconds"))
        if args.json:
            print(json.dumps(result, indent=2, ensure_ascii=False))
        else:
            print(f"status={result.get('status')}")
            print(f"profile_dir={result.get('profile_dir')}")
            if result.get("active_operation"):
                print(f"active_operation={result.get('active_operation')}")
            if result.get("active_elapsed_seconds") is not None:
                print(f"active_elapsed_seconds={result.get('active_elapsed_seconds')}")
            print(f"queue_enabled={str(result.get('queue_enabled')).lower()}")
        return 0
    if args.browser_command == "wait-idle":
        result = await _wait_for_browser_idle(
            backend,
            timeout_seconds=getattr(args, "timeout", DEFAULT_BROWSER_WAIT_IDLE_TIMEOUT_SECONDS),
            poll_seconds=getattr(args, "poll_seconds", DEFAULT_BROWSER_WAIT_IDLE_POLL_SECONDS),
        )
        if isinstance(result, dict):
            result = dict(result)
            policy = service_browser_queue_policy("src_add")
            result.setdefault("service_queue", policy)
            result.setdefault("queue_enabled", bool(policy.get("queue_enabled")))
            result.setdefault("queue_mode", policy.get("queue_mode"))
        if args.json:
            print(json.dumps(result, indent=2, ensure_ascii=False))
        else:
            print(f"status={result.get('status')}")
            print(f"idle={str(bool(result.get('idle'))).lower()}")
            browser = result.get("browser_status") if isinstance(result.get("browser_status"), dict) else {}
            if browser.get("active_operation"):
                print(f"active_operation={browser.get('active_operation')}")
        return 0 if result.get("ok") else 75
    raise RuntimeError(f"Unknown browser command: {args.browser_command}")


async def cmd_src_queue_plan(backend: CommandBackend, args: argparse.Namespace) -> int:
    snapshot = backend.state_snapshot() if hasattr(backend, "state_snapshot") else {}
    source_kind = getattr(args, "type", None) or "file"
    file_path = getattr(args, "file", None) or getattr(args, "file_path", None)
    display_name = getattr(args, "name", None)
    if source_kind == "file" and display_name:
        display_name = Path(display_name).name
    elif source_kind == "file" and file_path and not display_name:
        display_name = Path(file_path).name
    payload = build_source_mutation_queue_plan(
        operation=getattr(args, "operation", None),
        state_snapshot=snapshot,
        workspace_url=getattr(args, "workspace_url", None),
        account_id=getattr(args, "account_id", None) or "default",
        service_id=getattr(args, "service_id", None) or "default",
        repo_path=getattr(args, "repo_path", None),
        source_kind=source_kind,
        file_path=file_path,
        display_name=display_name,
        source_name=getattr(args, "source_name", None),
        sync_path=getattr(args, "path", None),
        overwrite_existing=not bool(getattr(args, "no_overwrite", False)),
        exact=bool(getattr(args, "exact", False)),
    )
    if getattr(args, "json", False):
        print(json.dumps(payload, indent=2, ensure_ascii=False))
    else:
        print(f"status={payload.get('status')}")
        print(f"workspace_id={(payload.get('workspace') or {}).get('workspace_id')}")
        print(f"scheduler_operation={payload.get('scheduler_operation')}")
        print(f"queue_required={str((payload.get('queue_policy') or {}).get('queue_required')).lower()}")
    return 0 if payload.get("ok") else 2


