ASK_LIVE_DEFAULT_STEPS: tuple[str, ...] = (
    "plain",
    "repeated_stale_first",
    "repeated_stale_second",
    "prompt_file",
    "file_attachment",
    "prompt_file_with_attachment",
)


def _selector_values(raw_values: list[str] | None) -> set[str]:
    values: set[str] = set()
    for raw in raw_values or []:
        for item in str(raw).split(","):
            value = item.strip()
            if value:
                values.add(value)
    return values


def _ask_live_selected_steps(args: argparse.Namespace) -> list[str]:
    only = _selector_values(getattr(args, "only", None))
    skip = _selector_values(getattr(args, "skip", None))
    unknown = sorted((only | skip).difference(ASK_LIVE_DEFAULT_STEPS))
    if unknown:
        raise ValueError(f"unknown ask-live step selector(s): {', '.join(unknown)}")
    steps = list(ASK_LIVE_DEFAULT_STEPS)
    if only:
        steps = [step for step in steps if step in only]
    if skip:
        steps = [step for step in steps if step not in skip]
    return steps


def _ask_live_sentinel(run_id: str, suffix: str) -> str:
    safe = re.sub(r"[^A-Za-z0-9_]+", "_", run_id).strip("_") or "RUN"
    return f"ASK_LIVE_{suffix.upper()}_{safe}"


def _ask_live_sentinel_visible_during_streaming_timeout(answer_text: str, expected_sentinel: str) -> bool:
    """Accept bounded timeout evidence only when the expected token is visibly present.

    ChatGPT can leave the stop button visible while a short sentinel answer is
    already rendered.  For ask-live only, that should not be treated as a
    missing-answer failure.  The acceptance remains fail-closed: the expected
    token must be present exactly and any remaining visible suffix may contain
    only streaming/cursor-like marker characters or whitespace.
    """
    text = str(answer_text or "").strip()
    expected = str(expected_sentinel or "").strip()
    if not text or not expected or expected not in text:
        return False
    if text == expected:
        return True
    prefix, _match, suffix = text.partition(expected)
    if prefix.strip():
        return False
    suffix = suffix.strip()
    return bool(suffix) and all(ch in {"_", "▌", "|", "█", "."} for ch in suffix)


def _ask_live_answer_text(response: Any) -> str:
    enriched = _enrich_ask_response_with_canonical_text(response)
    answer, _ = _split_ask_response(enriched)
    return _canonical_answer_text(answer)


def _ask_live_project_id_from_url(url: str | None) -> str | None:
    """Return the canonical ChatGPT Project id for ask-live comparisons.

    ChatGPT may return either the bare project id URL:

        /g/g-p-<32hex>/project

    or a slugged URL:

        /g/g-p-<32hex>-<project-name>/project

    Both identify the same project.  ask-live must compare the stable
    project id instead of the full slugged URL so temporary-project checks
    do not fail when ChatGPT rewrites URLs with a human-readable suffix.
    """
    if not url:
        return None
    home_url = project_home_url_from_url(url) or url
    parsed = urllib.parse.urlparse(str(home_url))
    parts = [part for part in parsed.path.split("/") if part]
    if len(parts) < 2 or parts[0] != "g":
        return None
    slug = parts[1]
    match = re.match(r"^(g-p-[0-9a-fA-F]{32})(?:-|$)", slug)
    if match:
        return match.group(1).lower()
    return slug or None


def _ask_live_in_expected_project(
    *,
    expected_project_home_url: str | None,
    response_project_home_url: str | None,
) -> tuple[bool, str | None, str | None]:
    expected_project_id = _ask_live_project_id_from_url(expected_project_home_url)
    response_project_id = _ask_live_project_id_from_url(response_project_home_url)
    if expected_project_id and response_project_id:
        return expected_project_id == response_project_id, expected_project_id, response_project_id
    if expected_project_home_url:
        expected_home = project_home_url_from_url(expected_project_home_url) or expected_project_home_url
        return (
            bool(response_project_home_url and str(response_project_home_url).rstrip("/") == str(expected_home).rstrip("/")),
            expected_project_id,
            response_project_id,
        )
    return True, expected_project_id, response_project_id


async def _run_ask_live_step_once(
    backend: CommandBackend,
    args: argparse.Namespace,
    *,
    name: str,
    prompt: str,
    expected_sentinel: str,
    attachment_paths: list[str] | None = None,
    forbidden_sentinels: list[str] | None = None,
    expected_project_home_url: str | None = None,
    prefer_button_submit: bool = False,
) -> dict[str, Any]:
    started = time.monotonic()
    response: Any
    try:
        response = await backend.ask(
            prompt=prompt,
            attachment_paths=list(attachment_paths or []),
            conversation_url=getattr(args, "conversation_url", None),
            expect_json=False,
            keep_open=bool(getattr(args, "keep_open", False)),
            retries=getattr(args, "retries", None),
            prefer_button_submit=prefer_button_submit,
        )
    except Exception as exc:
        status = "ask_failed"
        if isinstance(exc, (AuthChallengeRequiredError, BotChallengeError)):
            status = "docker_live_profile_challenged"
        return {
            "name": name,
            "ok": False,
            "status": status,
            "challenge_type": "docker_live_profile_challenged" if status == "docker_live_profile_challenged" else None,
            "error": str(exc),
            "error_type": exc.__class__.__name__,
            "duration_seconds": round(time.monotonic() - started, 3),
            "expected_sentinel": expected_sentinel,
            "attachment_paths": [str(path) for path in attachment_paths or []],
        }

    raw_answer_text = _ask_live_answer_text(response)
    response_ok = not (isinstance(response, dict) and response.get("ok") is False)
    response_status = str(response.get("status") or "") if isinstance(response, dict) else ""
    response_challenge_type = str(response.get("challenge_type") or "") if isinstance(response, dict) else ""
    response_error_type = str(response.get("error_type") or "") if isinstance(response, dict) else ""
    docker_live_challenged = bool(
        not response_ok
        and (
            response_status == "docker_live_profile_challenged"
            or response_challenge_type == "docker_live_profile_challenged"
            or response_error_type in {"BotChallengeError", "AuthChallengeRequiredError"}
        )
    )
    streaming_timeout_answer_visible = bool(
        not response_ok
        and response_status in {"submit_confirmed_answer_timeout", "assistant_response_timeout"}
        and _ask_live_sentinel_visible_during_streaming_timeout(raw_answer_text, expected_sentinel)
    )
    answer_text = raw_answer_text if (response_ok or streaming_timeout_answer_visible) else ""
    forbidden = list(forbidden_sentinels or [])
    contains_expected = bool((response_ok or streaming_timeout_answer_visible) and expected_sentinel in answer_text)
    forbidden_present = [item for item in forbidden if item and item in answer_text]
    response_conversation_url = response.get("conversation_url") if isinstance(response, dict) else None
    response_project_home_url = project_home_url_from_url(response_conversation_url)
    expected_home = project_home_url_from_url(expected_project_home_url) or expected_project_home_url
    in_expected_project, expected_project_id, response_project_id = _ask_live_in_expected_project(
        expected_project_home_url=expected_home,
        response_project_home_url=response_project_home_url,
    )
    rate_limit_telemetry = _rate_limit_telemetry_from_result(response)
    rate_limit_contaminated = _rate_limit_telemetry_contaminated(rate_limit_telemetry)
    rate_limit_recovered = _rate_limit_telemetry_recovered(rate_limit_telemetry)
    functionally_ok = bool((response_ok or streaming_timeout_answer_visible) and contains_expected and not forbidden_present and in_expected_project)
    ok = bool(functionally_ok and (not rate_limit_contaminated or rate_limit_recovered))
    if streaming_timeout_answer_visible and functionally_ok and rate_limit_contaminated and rate_limit_recovered:
        status = "verified_with_recovered_rate_limit"
    elif streaming_timeout_answer_visible and functionally_ok:
        status = "verified_with_streaming_timeout"
    elif docker_live_challenged:
        status = "docker_live_profile_challenged"
    elif not response_ok:
        status = "ask_failed"
    elif not in_expected_project:
        status = "wrong_project"
    elif not contains_expected or forbidden_present:
        status = "failed"
    elif rate_limit_contaminated and rate_limit_recovered:
        status = "verified_with_recovered_rate_limit"
    elif rate_limit_contaminated:
        status = "rate_limited_contaminated"
    else:
        status = "verified"
    submit_evidence = response.get("submit_evidence") if isinstance(response, dict) and isinstance(response.get("submit_evidence"), dict) else None
    return {
        "name": name,
        "ok": ok,
        "status": status,
        "expected_sentinel": expected_sentinel,
        "contains_expected_sentinel": contains_expected,
        "forbidden_sentinels_present": forbidden_present,
        "answer_text_preview": (answer_text if response_ok else raw_answer_text)[:240],
        "answer_text_length": len(answer_text),
        "conversation_url": response_conversation_url,
        "expected_project_home_url": expected_home,
        "response_project_home_url": response_project_home_url,
        "expected_project_id": expected_project_id,
        "response_project_id": response_project_id,
        "in_expected_project": in_expected_project,
        "rate_limit_telemetry": rate_limit_telemetry,
        "rate_limit_contaminated": rate_limit_contaminated,
        "rate_limit_recovered": rate_limit_recovered,
        "streaming_timeout_answer_visible": streaming_timeout_answer_visible,
        "response_status": response_status,
        "response_challenge_type": response_challenge_type,
        "response_error_type": response_error_type,
        "partial_answer_text_preview": raw_answer_text[:240] if streaming_timeout_answer_visible else "",
        "functional_status": "verified" if functionally_ok else status,
        "prefer_button_submit": submit_evidence.get("prefer_button_submit") if isinstance(submit_evidence, dict) else None,
        "submit_method": submit_evidence.get("submit_method") if isinstance(submit_evidence, dict) else None,
        "submit_confirmed": submit_evidence.get("submit_confirmed") if isinstance(submit_evidence, dict) else None,
        "submit_confirmation_mode": submit_evidence.get("submit_confirmation_mode") if isinstance(submit_evidence, dict) else None,
        "attachment_paths": [str(path) for path in attachment_paths or []],
        "duration_seconds": round(time.monotonic() - started, 3),
    }


def _ask_live_step_is_docker_live_profile_challenged(result: dict[str, Any]) -> bool:
    """Return True when an ask-live child result is a terminal Docker live profile challenge."""

    status = str(result.get("status") or "")
    challenge_type = str(result.get("challenge_type") or result.get("response_challenge_type") or "")
    error_type = str(result.get("error_type") or result.get("response_error_type") or "")
    return bool(
        status == "docker_live_profile_challenged"
        or challenge_type == "docker_live_profile_challenged"
        or error_type in {"BotChallengeError", "AuthChallengeRequiredError"}
    )


def _ask_live_steps_have_terminal_docker_live_profile_challenge(steps: list[dict[str, Any]]) -> bool:
    return any(_ask_live_step_is_docker_live_profile_challenged(step) for step in steps)


def _ask_live_transient_first_turn_retry_candidate(result: dict[str, Any], *, name: str, attachment_paths: list[str] | None) -> bool:
    """Return True for the bounded first-turn ChatGPT transient Retry page.

    This is intentionally narrow: a real wrong Project response remains
    release-blocking.  The only retried condition is the first plain ask-live
    step returning ChatGPT's generic Retry text without a conversation URL or
    project identity.  That condition has no usable Project evidence and is
    commonly a transient first-turn service response rather than a completed
    wrong-project answer.
    """
    if name != "plain":
        return False
    if attachment_paths:
        return False
    status = str(result.get("status") or "")
    if status not in {"wrong_project", "failed", "ask_failed"}:
        return False
    if result.get("contains_expected_sentinel") is True:
        return False
    if result.get("conversation_url"):
        return False
    if result.get("response_project_home_url") or result.get("response_project_id"):
        return False
    preview = str(result.get("answer_text_preview") or "").lower()
    if not preview:
        return False
    return "something went wrong" in preview and "try again" in preview and "retry" in preview


async def _run_ask_live_step(
    backend: CommandBackend,
    args: argparse.Namespace,
    *,
    name: str,
    prompt: str,
    expected_sentinel: str,
    attachment_paths: list[str] | None = None,
    forbidden_sentinels: list[str] | None = None,
    expected_project_home_url: str | None = None,
    prefer_button_submit: bool = False,
    transient_retry_attempts: int = 0,
) -> dict[str, Any]:
    max_attempts = max(0, int(transient_retry_attempts or 0)) + 1
    attempt_summaries: list[dict[str, Any]] = []
    last_result: dict[str, Any] | None = None
    for attempt_index in range(max_attempts):
        result = await _run_ask_live_step_once(
            backend,
            args,
            name=name,
            prompt=prompt,
            expected_sentinel=expected_sentinel,
            attachment_paths=attachment_paths,
            forbidden_sentinels=forbidden_sentinels,
            expected_project_home_url=expected_project_home_url,
            prefer_button_submit=prefer_button_submit,
        )
        last_result = result
        attempt_summaries.append({
            "attempt_index": attempt_index,
            "ok": bool(result.get("ok")),
            "status": result.get("status"),
            "conversation_url": result.get("conversation_url"),
            "response_project_home_url": result.get("response_project_home_url"),
            "response_project_id": result.get("response_project_id"),
            "contains_expected_sentinel": result.get("contains_expected_sentinel"),
            "answer_text_preview": result.get("answer_text_preview"),
            "duration_seconds": result.get("duration_seconds"),
        })
        should_retry = (
            attempt_index + 1 < max_attempts
            and _ask_live_transient_first_turn_retry_candidate(result, name=name, attachment_paths=attachment_paths)
        )
        if should_retry:
            continue
        if attempt_summaries:
            result["attempt_index"] = attempt_index
            result["retry_attempt_count"] = attempt_index
            result["transient_retry_attempted"] = attempt_index > 0
            result["transient_retry_reason"] = "first_turn_null_project_retry_response" if attempt_index > 0 else None
            result["attempts"] = attempt_summaries
        return result
    assert last_result is not None
    last_result["attempt_index"] = len(attempt_summaries) - 1
    last_result["retry_attempt_count"] = max(0, len(attempt_summaries) - 1)
    last_result["transient_retry_attempted"] = len(attempt_summaries) > 1
    last_result["transient_retry_reason"] = "first_turn_null_project_retry_response" if len(attempt_summaries) > 1 else None
    last_result["attempts"] = attempt_summaries
    return last_result


def _restore_ask_live_state(backend: Any, snapshot: dict[str, Any]) -> None:
    """Restore the operator-selected workspace/task after an ask-live temp project run."""
    store = getattr(backend, "_conversation_state", None)
    if store is None:
        return
    project_home_url = snapshot.get("current_project_home_url") or snapshot.get("resolved_project_home_url")
    conversation_url = snapshot.get("current_conversation_url") or snapshot.get("conversation_url")
    project_name = snapshot.get("project_name")
    if isinstance(conversation_url, str) and conversation_url:
        try:
            store.remember(project_home_url, conversation_url, project_name=project_name if isinstance(project_name, str) else None)
        except Exception:
            return
    elif isinstance(project_home_url, str) and project_home_url:
        try:
            store.remember_project(project_home_url, project_name=project_name if isinstance(project_name, str) else None)
        except Exception:
            return



def _default_live_test_project_prefix(profile: str) -> str:
    profile_key = str(profile or "").strip().lower()
    if profile_key == "ask-live":
        return ASK_LIVE_DELETE_FROZEN_PROJECT_PREFIX
    if profile_key == "release-live":
        return RELEASE_LIVE_DELETE_FROZEN_PROJECT_PREFIX
    if profile_key == "visual-artifact-roundtrip":
        return VISUAL_ARTIFACT_ROUNDTRIP_DELETE_FROZEN_PROJECT_PREFIX
    return DELETE_FROZEN_TEST_PROJECT_PREFIX


def _safe_live_test_name_component(value: object, *, fallback: str) -> str:
    safe = re.sub(r"[^A-Za-z0-9_-]+", "-", str(value or "")).strip("-_")
    return safe or fallback


def _bounded_generated_chatgpt_project_name(prefix: object, run_id: object, *, max_length: int = CHATGPT_PROJECT_NAME_MAX_LENGTH) -> str:
    """Build a fresh test Project name that respects ChatGPT's 50-char limit.

    The name must stay run-scoped while whole-project deletion is frozen, but
    ChatGPT rejects names longer than 50 characters.  Long prefix/run-id pairs
    are therefore shortened with a stable hash suffix instead of silently
    reusing a shared project.
    """

    safe_prefix = _safe_live_test_name_component(prefix, fallback=DELETE_FROZEN_TEST_PROJECT_PREFIX)
    safe_run = _safe_live_test_name_component(run_id, fallback="run")
    raw = f"{safe_prefix}-{safe_run}"
    if len(raw) <= max_length:
        return raw
    digest = hashlib.sha1(raw.encode("utf-8")).hexdigest()[:8]
    head_length = max(1, max_length - len(digest) - 1)
    head = raw[:head_length].rstrip("-_") or raw[:head_length]
    return f"{head}-{digest}"


def _elapsed_seconds_since(started_at: float) -> float:
    return round(max(0.0, time.monotonic() - started_at), 3)


def _phase_timings_with_total(phase_timings: dict[str, Any], started_at: float) -> dict[str, Any]:
    payload = dict(phase_timings)
    payload["total_seconds"] = _elapsed_seconds_since(started_at)
    return payload


RATE_LIMIT_CONTAMINATION_KEYS: tuple[str, ...] = (
    "rate_limit_modal_detected",
    "conversation_history_429_seen",
    "backend_api_guardrail_seen",
)


def _rate_limit_telemetry_from_result(result: Any) -> dict[str, Any]:
    """Return rate-limit telemetry carried by a browser/service result.

    Browser operations attach telemetry at the top level. Artifact intake wraps
    browser download results under ``download_transport.browser_result``; keep
    that path visible to live-test classification too.
    """

    if not isinstance(result, dict):
        return {}
    telemetry = result.get("rate_limit_telemetry")
    if isinstance(telemetry, dict):
        return dict(telemetry)
    transport = result.get("download_transport")
    if isinstance(transport, dict):
        browser_result = transport.get("browser_result")
        if isinstance(browser_result, dict) and isinstance(browser_result.get("rate_limit_telemetry"), dict):
            return dict(browser_result["rate_limit_telemetry"])
    return {}


def _rate_limit_event_fingerprint(event: Any) -> str:
    if not isinstance(event, dict):
        return repr(event)
    try:
        return json.dumps(event, sort_keys=True, separators=(",", ":"), default=str)
    except TypeError:
        return repr(sorted(event.items()))


def _rate_limit_telemetry_fingerprint(telemetry: dict[str, Any]) -> str | None:
    """Return a stable fingerprint for event-backed telemetry snapshots.

    Browser download telemetry can appear twice in visual roundtrip output: once
    in the direct download result and once in the smoke-verification result that
    carries the download payload forward.  Those are the same observation window,
    not two independent cooldown waits.  Only event-backed snapshots are
    fingerprinted so independent eventless counters, such as no-op navigation
    skips from separate operations, can still be accumulated.
    """

    events = telemetry.get("service_rate_limit_events")
    if not isinstance(events, list) or not events:
        return None
    event_fingerprints = [_rate_limit_event_fingerprint(event) for event in events]
    try:
        return json.dumps(event_fingerprints, sort_keys=True, separators=(",", ":"))
    except TypeError:
        return repr(event_fingerprints)


def _merge_rate_limit_telemetry(*items: Any) -> dict[str, Any]:
    merged: dict[str, Any] = {
        "rate_limit_modal_detected": False,
        "conversation_history_429_seen": False,
        "backend_api_guardrail_seen": False,
        "cooldown_wait_seconds_total": 0.0,
        "cooldown_wait_count": 0,
        "conversation_history_fetch_attempt_count": 0,
        "conversation_history_fetch_skipped_count": 0,
        "conversation_history_cooldown_skip_count": 0,
        "navigation_noop_skip_count": 0,
        "service_rate_limit_events": [],
    }
    seen = False
    seen_snapshot_fingerprints: set[str] = set()
    seen_event_fingerprints: set[str] = set()
    for item in items:
        telemetry = _rate_limit_telemetry_from_result(item) if not (isinstance(item, dict) and any(key in item for key in RATE_LIMIT_CONTAMINATION_KEYS)) else dict(item)
        if not telemetry:
            continue
        seen = True
        for key in RATE_LIMIT_CONTAMINATION_KEYS:
            merged[key] = bool(merged.get(key)) or bool(telemetry.get(key))

        snapshot_fingerprint = _rate_limit_telemetry_fingerprint(telemetry)
        duplicate_snapshot = bool(snapshot_fingerprint and snapshot_fingerprint in seen_snapshot_fingerprints)
        if snapshot_fingerprint:
            seen_snapshot_fingerprints.add(snapshot_fingerprint)

        if not duplicate_snapshot:
            for key in (
                "cooldown_wait_seconds_total",
                "cooldown_wait_count",
                "conversation_history_fetch_attempt_count",
                "conversation_history_fetch_skipped_count",
                "conversation_history_cooldown_skip_count",
                "navigation_noop_skip_count",
            ):
                value = telemetry.get(key)
                if isinstance(value, (int, float)) and not isinstance(value, bool):
                    if key.endswith("seconds_total"):
                        merged[key] = round(float(merged.get(key, 0.0)) + float(value), 3)
                    else:
                        merged[key] = int(merged.get(key, 0)) + int(value)

        events = telemetry.get("service_rate_limit_events")
        if isinstance(events, list):
            for event in events:
                event_fingerprint = _rate_limit_event_fingerprint(event)
                if event_fingerprint in seen_event_fingerprints:
                    continue
                seen_event_fingerprints.add(event_fingerprint)
                merged["service_rate_limit_events"].append(event)
    if not seen:
        return {}
    reasons = [key for key in RATE_LIMIT_CONTAMINATION_KEYS if bool(merged.get(key))]
    merged["rate_limit_contaminated"] = bool(reasons)
    merged["contamination_reasons"] = reasons
    return merged


def _rate_limit_telemetry_contaminated(telemetry: Any) -> bool:
    if not isinstance(telemetry, dict):
        return False
    return any(bool(telemetry.get(key)) for key in RATE_LIMIT_CONTAMINATION_KEYS)


def _rate_limit_event_kinds(telemetry: Any) -> set[str]:
    if not isinstance(telemetry, dict):
        return set()
    events = telemetry.get("service_rate_limit_events")
    if not isinstance(events, list):
        return set()
    kinds: set[str] = set()
    for event in events:
        if not isinstance(event, dict):
            continue
        kind = event.get("kind")
        if isinstance(kind, str) and kind:
            kinds.add(kind)
    return kinds


def _rate_limit_telemetry_recovered(telemetry: Any) -> bool:
    """Return true when observed 429 telemetry was handled in-place.

    ChatGPT's browser UI can show a recoverable "Too many requests" modal.
    For live tests we should not restart the whole test step after functional
    verification succeeded.  The successful path is: acknowledge the modal,
    wait/consume the persisted cooldown, keep the browser operation alive, and
    continue.  Unhandled 429 evidence remains non-clean and must fail closed.
    """

    if not _rate_limit_telemetry_contaminated(telemetry):
        return False
    if not isinstance(telemetry, dict):
        return False
    try:
        cooldown_count = int(telemetry.get("cooldown_wait_count") or 0)
    except (TypeError, ValueError):
        cooldown_count = 0
    try:
        cooldown_total = float(telemetry.get("cooldown_wait_seconds_total") or 0.0)
    except (TypeError, ValueError):
        cooldown_total = 0.0
    kinds = _rate_limit_event_kinds(telemetry)
    modal_acknowledged = "modal_acknowledged" in kinds
    modal_wait_satisfied = bool({
        "modal_ack_wait_satisfied_cooldown",
        "cooldown_wait_satisfied_by_modal_ack_wait",
    } & kinds)
    explicit_cooldown_wait = bool(cooldown_count > 0 and cooldown_total > 0.0)
    return bool(explicit_cooldown_wait or (modal_acknowledged and modal_wait_satisfied))


def _rate_limit_contamination_status(base_status: str, *, contaminated: bool, recovered: bool = False) -> str:
    if not contaminated:
        return base_status
    if recovered and base_status in {"verified", "smoke_zip_verified", "downloaded", "completed"}:
        return "verified_with_recovered_rate_limit"
    if base_status in {"verified", "smoke_zip_verified", "downloaded", "completed"}:
        return "rate_limited_contaminated"
    return base_status


def _live_test_project_setup_strategy(args: argparse.Namespace) -> str:
    if getattr(args, "conversation_url", None):
        return "explicit_conversation_url"
    return "direct_create_project"


def _apply_delete_frozen_live_test_defaults(args: argparse.Namespace, *, profile: str) -> None:
    """Apply delete-frozen live-test defaults.

    Whole ChatGPT Project deletion is frozen, so release/live tests must still
    keep any project they create.  To avoid browser history and Project data
    accumulating in one long-lived test Project, the default is now a fresh
    run-scoped project name derived from the profile prefix and run id.  An
    explicit ``--project-name`` or ``--conversation-url`` remains authoritative.
    """

    if not getattr(args, "conversation_url", None) and not getattr(args, "project_name", None):
        current_prefix = str(getattr(args, "project_name_prefix", "") or "")
        if not current_prefix or current_prefix == DELETE_FROZEN_RETAINED_TEST_PROJECT_NAME:
            setattr(args, "project_name_prefix", _default_live_test_project_prefix(profile))
    setattr(args, "keep_project", True)
    setattr(args, "cleanup_policy", DELETE_FROZEN_LIVE_TEST_CLEANUP_POLICY)
    setattr(args, "retained_project_default", False)
    setattr(args, "live_test_profile", profile)


def _delete_frozen_live_test_operator_note(profile: str) -> str:
    return (
        f"{profile} creates a fresh run-scoped delete-frozen ChatGPT Project "
        "by default. Whole-project deletion is disabled until a separately "
        "designed secure delete protocol exists; --keep-project is therefore "
        "enforced. Operators may still provide --conversation-url to target an "
        "exact existing conversation, or --project-name as a creation label only."
    )


def _delete_frozen_uses_retained_project(args: argparse.Namespace) -> bool:
    if bool(getattr(args, "retained_project_default", False)):
        return True
    return str(getattr(args, "project_name", "") or "") == DELETE_FROZEN_RETAINED_TEST_PROJECT_NAME


async def cmd_test_release_live_continuous(backend: CommandBackend, args: argparse.Namespace) -> int:
    run_id = getattr(args, "run_id", None) or datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ")
    bootstrap_sentinel = getattr(args, "bootstrap_sentinel", None) or f"LIVE_CONVERSATION_BOOTSTRAP_{run_id}"
    ask_sentinel = getattr(args, "ask_sentinel", None) or _ask_live_sentinel(run_id, "plain")
    bootstrap_prompt = f"Reply with exactly the single token {bootstrap_sentinel} and nothing else."
    ask_prompt = f"Return exactly the single token {ask_sentinel} and nothing else."
    started = time.monotonic()
    try:
        result = await backend.release_live_bootstrap_and_ask(
            project_name=args.project_name,
            bootstrap_prompt=bootstrap_prompt,
            ask_prompt=ask_prompt,
            icon=getattr(args, "project_icon", None),
            color=getattr(args, "project_color", None),
            memory_mode=getattr(args, "memory_mode", "project-only"),
            service_timeout_seconds=getattr(args, "service_timeout_seconds", None),
            warmup_conversation_url=getattr(args, "warmup_conversation_url", None),
        )
    except (AuthChallengeRequiredError, BotChallengeError) as exc:
        payload = {
            "ok": False,
            "action": "test_release_live_continuous",
            "status": "docker_live_profile_challenged",
            "challenge_type": "docker_live_profile_challenged",
            "error": str(exc),
            "error_type": exc.__class__.__name__,
            "run_id": run_id,
            "project_name": args.project_name,
            "duration_seconds": round(time.monotonic() - started, 3),
        }
        if args.json:
            print(json.dumps(payload, indent=2, ensure_ascii=False))
        else:
            print(f"release-live-continuous: {payload['status']}")
        return 1
    payload = dict(result) if isinstance(result, dict) else {"ok": False, "status": "invalid_result", "result": result}
    payload.setdefault("ok", False)
    payload.setdefault("action", "test_release_live_continuous")
    payload.setdefault("status", "verified" if payload.get("ok") else "failed")
    payload.setdefault("run_id", run_id)
    payload.setdefault("profile", "release-live-continuous")
    payload.setdefault("project_name", args.project_name)
    payload.setdefault("bootstrap_sentinel", bootstrap_sentinel)
    payload.setdefault("ask_sentinel", ask_sentinel)
    payload.setdefault("continuous_browser_session", True)
    if getattr(args, "warmup_conversation_url", None):
        payload.setdefault("warmup_conversation_url", getattr(args, "warmup_conversation_url", None))
        payload.setdefault("warmup_strategy", "trusted_preflight_conversation_url")
    payload.setdefault("duration_seconds", round(time.monotonic() - started, 3))
    ask_result = payload.get("ask_result") if isinstance(payload.get("ask_result"), dict) else {}
    answer_text = _ask_live_answer_text(ask_result) if isinstance(ask_result, dict) else ""
    if payload.get("ok") and ask_sentinel not in answer_text:
        payload["ok"] = False
        payload["status"] = "failed"
        payload["failed_phase"] = "ask_live"
        payload["error"] = "continuous ask did not return expected sentinel"
        payload["contains_expected_sentinel"] = False
    else:
        payload.setdefault("contains_expected_sentinel", bool(ask_sentinel in answer_text))
    if args.json:
        print(json.dumps(payload, indent=2, ensure_ascii=False))
    else:
        print(f"release-live-continuous: {payload.get('status')}")
    return 0 if payload.get("ok") else 1

async def cmd_test_ask_live(backend: CommandBackend, args: argparse.Namespace) -> int:
    """Run a visible/local operator ask workflow smoke profile.

    This profile exercises the repaired ask path in a run-scoped delete-frozen
    ChatGPT Project by default.  ChatGPT Project deletion is disabled, so the
    created Project is retained, but every default run uses a fresh name to
    avoid accumulating browser/project history in one reused Project.
    """

    try:
        selected_steps = _ask_live_selected_steps(args)
    except ValueError as exc:
        payload = {
            "ok": False,
            "action": "test_ask_live",
            "profile": "ask-live",
            "status": "invalid_step_selector",
            "error": str(exc),
            "valid_steps": list(ASK_LIVE_DEFAULT_STEPS),
        }
        print(json.dumps(payload, indent=2, ensure_ascii=False) if args.json else str(payload["error"]))
        return 2

    run_id = getattr(args, "run_id", None) or datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ")
    profile_dir = str(getattr(args, "profile_dir", "") or "")
    original_snapshot = backend.state_snapshot() if hasattr(backend, "state_snapshot") else {}
    explicit_conversation_url = getattr(args, "conversation_url", None)
    test_project_created = False
    test_project_removed = False
    test_project_url: str | None = None
    test_project_name: str | None = None
    setup_result: dict[str, Any] | None = None
    cleanup_result: dict[str, Any] | None = None
    project_setup_strategy = _live_test_project_setup_strategy(args)
    steps: list[dict[str, Any]] = []

    try:
        if explicit_conversation_url:
            test_project_url = project_home_url_from_url(explicit_conversation_url) or explicit_conversation_url
            test_project_name = "explicit-conversation-url"
        else:
            prefix = str(getattr(args, "project_name_prefix", None) or "ask-live-temp")
            test_project_name = str(
                getattr(args, "project_name", None)
                or _bounded_generated_chatgpt_project_name(prefix, run_id)
            )
            setup_result = await backend.create_project(
                name=test_project_name,
                icon=getattr(args, "project_icon", None),
                color=getattr(args, "project_color", None),
                memory_mode=getattr(args, "memory_mode", "project-only"),
                keep_open=False,
            )
            if not setup_result.get("ok"):
                payload = {
                    "ok": False,
                    "action": "test_ask_live",
                    "profile": "ask-live",
                    "status": "test_project_setup_failed",
                    "version": f"v{CLI_VERSION}",
                    "run_id": run_id,
                    "mode": "visible_local_debug_browser",
                    "profile_dir": profile_dir,
        "state_profile_dir": str(resolve_profile_dir(getattr(args, "profile_dir", None))),
        "profile_lease": getattr(args, "profile_lease", None),
                    "debug_browser": True,
                    "service_transport_used": False,
                    "test_project_name": test_project_name,
                    "test_project_setup_strategy": project_setup_strategy,
                    "test_project_identity_source": "created_project_url",
                    "test_project_setup": setup_result,
                    "operator_note": _delete_frozen_live_test_operator_note("ask-live"),
                }
                if args.json:
                    print(json.dumps(payload, indent=2, ensure_ascii=False))
                else:
                    print(f"ask-live: {payload['status']}")
                return 1
            test_project_created = True
            test_project_url = setup_result.get("project_url") if isinstance(setup_result.get("project_url"), str) else None
            if not test_project_url:
                payload = {
                    "ok": False,
                    "action": "test_ask_live",
                    "profile": "ask-live",
                    "status": "test_project_url_missing",
                    "version": f"v{CLI_VERSION}",
                    "run_id": run_id,
                    "test_project_name": test_project_name,
                    "test_project_setup_strategy": project_setup_strategy,
                    "test_project_identity_source": "created_project_url",
                    "test_project_setup": setup_result,
                }
                if args.json:
                    print(json.dumps(payload, indent=2, ensure_ascii=False))
                else:
                    print(f"ask-live: {payload['status']}")
                return 1
            setattr(args, "conversation_url", test_project_url)

        with tempfile.TemporaryDirectory(prefix="promptbranch_ask_live_") as temp_root:
            temp_dir = Path(temp_root)
            sentinels = {
                "plain": _ask_live_sentinel(run_id, "plain"),
                "repeat_first": _ask_live_sentinel(run_id, "repeat_first"),
                "repeat_second": _ask_live_sentinel(run_id, "repeat_second"),
                "prompt_file": _ask_live_sentinel(run_id, "prompt_file"),
                "file_attachment": _ask_live_sentinel(run_id, "file_attachment"),
                "prompt_file_with_attachment": _ask_live_sentinel(run_id, "prompt_file_with_attachment"),
            }

            if "plain" in selected_steps:
                steps.append(await _run_ask_live_step(
                    backend,
                    args,
                    name="plain",
                    prompt=f"Return exactly the single token {sentinels['plain']} and nothing else.",
                    expected_sentinel=sentinels["plain"],
                    expected_project_home_url=test_project_url,
                    transient_retry_attempts=1,
                ))

            if "repeated_stale_first" in selected_steps and not _ask_live_steps_have_terminal_docker_live_profile_challenge(steps):
                steps.append(await _run_ask_live_step(
                    backend,
                    args,
                    name="repeated_stale_first",
                    prompt=f"Return exactly the single token {sentinels['repeat_first']} and nothing else.",
                    expected_sentinel=sentinels["repeat_first"],
                    forbidden_sentinels=[sentinels["plain"]],
                    expected_project_home_url=test_project_url,
                ))

            if "repeated_stale_second" in selected_steps and not _ask_live_steps_have_terminal_docker_live_profile_challenge(steps):
                steps.append(await _run_ask_live_step(
                    backend,
                    args,
                    name="repeated_stale_second",
                    prompt=f"Return exactly the single token {sentinels['repeat_second']} and nothing else.",
                    expected_sentinel=sentinels["repeat_second"],
                    forbidden_sentinels=[sentinels["plain"], sentinels["repeat_first"]],
                    expected_project_home_url=test_project_url,
                ))

            if "prompt_file" in selected_steps and not _ask_live_steps_have_terminal_docker_live_profile_challenge(steps):
                prompt_file = temp_dir / "prompt_file.md"
                prompt_file.write_text(
                    f"Return exactly the single token {sentinels['prompt_file']} and nothing else.\n",
                    encoding="utf-8",
                )
                prompt = _read_prompt_file(str(prompt_file)).strip()
                steps.append(await _run_ask_live_step(
                    backend,
                    args,
                    name="prompt_file",
                    prompt=prompt,
                    expected_sentinel=sentinels["prompt_file"],
                    expected_project_home_url=test_project_url,
                    prefer_button_submit=True,
                ))

            if "file_attachment" in selected_steps and not _ask_live_steps_have_terminal_docker_live_profile_challenge(steps):
                attachment = temp_dir / "ask_live_attachment.txt"
                attachment.write_text(f"sentinel={sentinels['file_attachment']}\n", encoding="utf-8")
                steps.append(await _run_ask_live_step(
                    backend,
                    args,
                    name="file_attachment",
                    prompt=f"Read the attached file and return exactly the sentinel token {sentinels['file_attachment']} and nothing else.",
                    expected_sentinel=sentinels["file_attachment"],
                    attachment_paths=[str(attachment)],
                    expected_project_home_url=test_project_url,
                ))

            if "prompt_file_with_attachment" in selected_steps and not _ask_live_steps_have_terminal_docker_live_profile_challenge(steps):
                attachment = temp_dir / "ask_live_prompt_file_attachment.txt"
                attachment.write_text(f"sentinel={sentinels['prompt_file_with_attachment']}\n", encoding="utf-8")
                prompt_file = temp_dir / "read_attachment_prompt.md"
                prompt_file.write_text(
                    "Read the attached file and return exactly the sentinel token "
                    f"{sentinels['prompt_file_with_attachment']} and nothing else.\n",
                    encoding="utf-8",
                )
                prompt = _read_prompt_file(str(prompt_file)).strip()
                steps.append(await _run_ask_live_step(
                    backend,
                    args,
                    name="prompt_file_with_attachment",
                    prompt=prompt,
                    expected_sentinel=sentinels["prompt_file_with_attachment"],
                    attachment_paths=[str(attachment)],
                    expected_project_home_url=test_project_url,
                    prefer_button_submit=True,
                ))
    finally:
        if test_project_created and not bool(getattr(args, "keep_project", False)):
            try:
                cleanup_result = await backend.remove_project(keep_open=False)
                test_project_removed = bool(cleanup_result.get("ok", True))
            except Exception as exc:
                cleanup_result = {"ok": False, "status": "test_project_cleanup_failed", "error": str(exc), "error_type": exc.__class__.__name__}
        _restore_ask_live_state(backend, original_snapshot if isinstance(original_snapshot, dict) else {})
        if explicit_conversation_url:
            setattr(args, "conversation_url", explicit_conversation_url)

    rate_limit_telemetry = _merge_rate_limit_telemetry(setup_result, *(step.get("rate_limit_telemetry") for step in steps), cleanup_result)
    rate_limit_contaminated = _rate_limit_telemetry_contaminated(rate_limit_telemetry)
    rate_limit_recovered = _rate_limit_telemetry_recovered(rate_limit_telemetry)
    challenged = _ask_live_steps_have_terminal_docker_live_profile_challenge(steps)
    ask_steps_ok = bool(steps) and all(bool(step.get("ok")) for step in steps)
    functional_statuses = {"verified", "verified_with_recovered_rate_limit", "verified_with_streaming_timeout", "rate_limited_contaminated"}
    functional_steps_ok = bool(steps) and all(str(step.get("status")) in functional_statuses for step in steps)
    cleanup_ok = True
    if test_project_created and not bool(getattr(args, "keep_project", False)):
        cleanup_ok = bool(test_project_removed)
    ok = bool(ask_steps_ok and cleanup_ok and (not rate_limit_contaminated or rate_limit_recovered))
    if challenged:
        status = "docker_live_profile_challenged"
    elif not functional_steps_ok:
        status = "failed"
    elif not cleanup_ok:
        status = "cleanup_failed"
    elif rate_limit_contaminated and rate_limit_recovered:
        status = "verified_with_recovered_rate_limit"
    elif rate_limit_contaminated:
        status = "rate_limited_contaminated"
    else:
        status = "verified"
    payload = {
        "ok": ok,
        "action": "test_ask_live",
        "profile": "ask-live",
        "status": status,
        "version": f"v{CLI_VERSION}",
        "run_id": run_id,
        "mode": "visible_local_debug_browser",
        "profile_dir": profile_dir,
        "state_profile_dir": str(resolve_profile_dir(getattr(args, "profile_dir", None))),
        "profile_lease": getattr(args, "profile_lease", None),
        "debug_browser": True,
        "service_transport_used": False,
        "uses_temporary_project": not bool(explicit_conversation_url),
            "uses_retained_delete_frozen_project": _delete_frozen_uses_retained_project(args),
            "cleanup_policy": getattr(args, "cleanup_policy", DELETE_FROZEN_LIVE_TEST_CLEANUP_POLICY),
        "test_project_name": test_project_name,
        "test_project_url": test_project_url,
        "test_project_setup_strategy": project_setup_strategy,
        "test_project_identity_source": "explicit_conversation_url" if explicit_conversation_url else "created_project_url",
        "test_project_created": test_project_created,
        "test_project_removed": test_project_removed,
        "test_project_kept": bool(getattr(args, "keep_project", False)),
        "test_project_setup": setup_result,
        "test_project_cleanup": cleanup_result,
        "selected_steps": selected_steps,
        "step_count": len(steps),
        "failure_count": len([step for step in steps if not step.get("ok")]),
        "functional_failure_count": len([step for step in steps if str(step.get("status")) not in functional_statuses]),
        "terminal_challenge": challenged,
        "challenge_type": "docker_live_profile_challenged" if challenged else None,
        "rate_limit_telemetry": rate_limit_telemetry,
        "rate_limit_contaminated": rate_limit_contaminated,
        "rate_limit_recovered": rate_limit_recovered,
        "rate_limit_policy": "ask-live treats functionally verified runs with acknowledged/waited 429 telemetry as verified_with_recovered_rate_limit; unrecovered 429 evidence remains non-clean",
        "steps": steps,
        "operator_note": _delete_frozen_live_test_operator_note("ask-live"),
    }
    if args.json:
        print(json.dumps(payload, indent=2, ensure_ascii=False))
    else:
        print(f"ask-live: {payload['status']} steps={payload['step_count']} failures={payload['failure_count']}")
        if payload.get("test_project_name"):
            print(f"test_project={payload.get('test_project_name')} removed={payload.get('test_project_removed')}")
        for step in steps:
            print(f"- {step.get('name')}: {step.get('status')}")
    return 0 if ok else 1



def _visual_artifact_roundtrip_run_id(value: str | None) -> str:
    text = str(value or "").strip()
    if text:
        return re.sub(r"[^A-Za-z0-9_.-]+", "_", text).strip("._-")[:64] or "manual"
    return datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ")


def _create_visual_roundtrip_input_zip(
    *,
    run_id: str,
    input_entry: str,
    input_content: str,
    work_dir: Path,
) -> Path:
    safe_entry = Path(str(input_entry or "input.txt")).name or "input.txt"
    zip_path = work_dir / f"pb_visual_artifact_roundtrip_input_{run_id}.zip"
    payload_path = work_dir / safe_entry
    payload_path.write_text(input_content, encoding="utf-8")
    with zipfile.ZipFile(zip_path, "w", compression=zipfile.ZIP_DEFLATED) as zf:
        zf.write(payload_path, safe_entry)
    return zip_path


def _visual_artifact_roundtrip_scope(
    *,
    run_id: str,
    input_entry: str,
    input_content: str,
    output_filename: str,
    output_entry: str,
    output_content: str,
) -> str:
    request_id = f"visual-artifact-roundtrip-{run_id}"
    return f"""This is a real artifact-creation test, not a text-only protocol test.
The run fails if you only print a path or only claim that a ZIP exists.
Do not copy or invent a success envelope; construct the reply only after the downloadable ZIP exists.

Input attachment requirement:
- Read the attached ZIP.
- It should contain {input_entry!r} with exactly this UTF-8 text:
{input_content}

Hard execution rules:
1. Before writing the reply envelope, create an actual downloadable ZIP file using the available file/artifact creation capability.
2. The real downloadable file name must be exactly: {output_filename}
3. The ZIP must contain exactly one file at the ZIP root: {output_entry}
4. {output_entry} must contain exactly this UTF-8 text, with no extra characters:
{output_content}
5. Reopen the ZIP after creating it and verify that the ZIP contains exactly the requested output file and requested text before claiming success.
6. First line of the final response must be a Markdown download link to the actual created ZIP. The link target must be copied from the real downloadable artifact link exposed by the environment.
7. Do not put only a guessed local path in the JSON. A download candidate is valid only when the first-line Markdown link can be used to retrieve the file.

Reply envelope rules:
- Return exactly one Promptbranch reply envelope after the Markdown download link.
- Do not wrap the envelope in a Markdown code fence.
- The envelope must begin with the line BEGIN_PROMPTBRANCH_REPLY_JSON and end with the line END_PROMPTBRANCH_REPLY_JSON.
- The JSON inside the envelope must be valid JSON.
- request_id must be exactly: {request_id}
- correlation_id must be exactly: {request_id}
- artifacts[0].kind must be "zip".
- artifacts[0].filename must be exactly: {output_filename}
- artifacts[0].role must be "visual_artifact_roundtrip_output".
- artifacts[0].download.available must be true.
- artifacts[0].download.link_text must be exactly: {output_filename}
- artifacts[0].download.url must be a JSON string containing exactly the same raw downloadable URL/path used as the first-line Markdown link target.
- Do not put Markdown link syntax in artifacts[0].download.url. Bad: [name](sandbox:/mnt/data/name.zip). Good JSON value form: "sandbox:/mnt/data/name.zip".
- Every JSON string value must use double quotes with any inner quotes escaped; do not use Python None/True/False, comments, trailing commas, or unquoted paths.
- Keep validation.claimed and validation.not_claimed strings simple: do not include JSON arrays, bracketed lists, raw double quotes, or Markdown links inside those string values.
- Prefer simple validation strings such as zip_created, output_entry_present, and output_content_verified.
- Before returning, verify that the text between BEGIN_PROMPTBRANCH_REPLY_JSON and END_PROMPTBRANCH_REPLY_JSON would parse with Python json.loads.
- The baseline object must use input_artifact null, input_version null, output_artifact {output_filename!r}, output_version null, release_type "visual_artifact_roundtrip".
- The changes array must include one added path: {output_entry!r}.
- validation.claimed may claim ZIP creation only after the ZIP exists and was reopened successfully.
- If you cannot create a real downloadable ZIP, return status "failed", result_type "test_report", artifacts: [], and do not claim that the ZIP was created.
- Do not use placeholder URLs, example paths, or guessed artifact locations.
"""


def _visual_artifact_roundtrip_prompt(
    *,
    run_id: str,
    input_entry: str,
    input_content: str,
    output_filename: str,
    output_entry: str,
    output_content: str,
) -> str:
    return _build_zip_artifact_user_prompt(
        request_label="Visual artifact roundtrip request",
        expected_artifact=output_filename,
        baseline=None,
        current_version=None,
        target_version=None,
        result_type="test_report",
        expected_role="visual_artifact_roundtrip_output",
        prompt_text=_visual_artifact_roundtrip_scope(
            run_id=run_id,
            input_entry=input_entry,
            input_content=input_content,
            output_filename=output_filename,
            output_entry=output_entry,
            output_content=output_content,
        ),
        artifact_version_required=False,
        no_change_disallowed=True,
        forbidden_claims="Do not claim release validation, baseline adoption, Project Source mutation, Git commit, or Git push.",
    )



def _decode_literal_escaped_json_whitespace_outside_strings(value: str) -> tuple[str, bool]:
    """Decode only literal escaped JSON whitespace that appears outside strings."""

    source = str(value or "")
    output: list[str] = []
    in_string = False
    string_escape = False
    changed = False
    index = 0
    while index < len(source):
        char = source[index]
        if in_string:
            output.append(char)
            if string_escape:
                string_escape = False
            elif char == "\\":
                string_escape = True
            elif char == '"':
                in_string = False
            index += 1
            continue
        if char == '"':
            in_string = True
            output.append(char)
            index += 1
            continue
        if char == "\\" and index + 1 < len(source) and source[index + 1] in {"n", "r", "t"}:
            escaped = source[index + 1]
            output.append("\n" if escaped in {"n", "r"} else "\t")
            changed = True
            index += 2
            continue
        output.append(char)
        index += 1
    return "".join(output), changed


def _visual_reply_parse_with_bounded_normalization(
    answer_text: str,
    *,
    expected_request_id: str,
) -> tuple[dict[str, Any], dict[str, Any]]:
    """Parse once normally, then apply one visual-only deterministic normalization."""

    source = str(answer_text or "")
    initial = parse_promptbranch_reply(source)
    diagnostics: dict[str, Any] = {
        "initial_status": initial.get("status"),
        "normalization_attempted": False,
        "normalization_applied": False,
        "normalization_status": "not_needed",
        "expected_request_id": expected_request_id,
    }

    def identity_ok(parsed: dict[str, Any]) -> bool:
        return bool(
            parsed.get("ok")
            and parsed.get("schema") == REPLY_SCHEMA
            and parsed.get("request_id") == expected_request_id
            and parsed.get("correlation_id") == expected_request_id
        )

    if identity_ok(initial):
        diagnostics["status"] = "valid_without_normalization"
        return initial, diagnostics

    diagnostics["normalization_attempted"] = True
    blocks = extract_reply_blocks(source)
    diagnostics["block_count"] = len(blocks)
    if len(blocks) != 1:
        diagnostics["normalization_status"] = "requires_exactly_one_marked_block"
        diagnostics["status"] = "invalid"
        return initial, diagnostics

    normalized_block, changed = _decode_literal_escaped_json_whitespace_outside_strings(blocks[0].text)
    diagnostics["normalization_applied"] = changed
    diagnostics["original_block_length"] = len(blocks[0].text)
    diagnostics["normalized_block_length"] = len(normalized_block)
    if not changed:
        diagnostics["normalization_status"] = "no_supported_literal_escaped_whitespace"
        diagnostics["status"] = "invalid"
        return initial, diagnostics

    decoder = json.JSONDecoder()
    candidate = normalized_block.strip()
    try:
        normalized_object, end = decoder.raw_decode(candidate)
    except json.JSONDecodeError as exc:
        diagnostics["normalization_status"] = "normalized_json_invalid"
        diagnostics["normalization_error"] = str(exc)
        diagnostics["status"] = "invalid"
        return initial, diagnostics
    if candidate[end:].strip():
        diagnostics["normalization_status"] = "normalized_block_contains_trailing_non_whitespace"
        diagnostics["status"] = "invalid"
        return initial, diagnostics
    if not isinstance(normalized_object, dict):
        diagnostics["normalization_status"] = "normalized_json_root_not_object"
        diagnostics["status"] = "invalid"
        return initial, diagnostics
    if normalized_object.get("schema") != REPLY_SCHEMA:
        diagnostics["normalization_status"] = "normalized_schema_mismatch"
        diagnostics["status"] = "invalid"
        return initial, diagnostics
    if normalized_object.get("request_id") != expected_request_id:
        diagnostics["normalization_status"] = "normalized_request_id_mismatch"
        diagnostics["status"] = "invalid"
        return initial, diagnostics
    if normalized_object.get("correlation_id") != expected_request_id:
        diagnostics["normalization_status"] = "normalized_correlation_id_mismatch"
        diagnostics["status"] = "invalid"
        return initial, diagnostics

    canonical_answer = (
        f"{BEGIN_REPLY_MARKER}\n"
        + json.dumps(normalized_object, ensure_ascii=False, separators=(",", ":"))
        + f"\n{END_REPLY_MARKER}"
    )
    normalized_parsed = parse_promptbranch_reply(canonical_answer)
    if not identity_ok(normalized_parsed):
        diagnostics["normalization_status"] = "normalized_envelope_failed_schema_validation"
        diagnostics["normalized_parse_status"] = normalized_parsed.get("status")
        diagnostics["status"] = "invalid"
        return normalized_parsed, diagnostics

    diagnostics["normalization_status"] = "literal_escaped_whitespace_normalized"
    diagnostics["status"] = "valid_after_normalization"
    return normalized_parsed, diagnostics


def _visual_artifact_roundtrip_envelope_retry_prompt(
    *,
    request_id: str,
    output_filename: str,
) -> str:
    return f"""Your previous visual-artifact response is complete, but its Promptbranch reply envelope is invalid.
Do not recreate, rename, or modify the already-created artifact.
Do not start another conversation and do not repeat any historical prompt.
Return exactly one corrected Promptbranch reply envelope for the existing artifact.
Do not use a Markdown code fence.
The block must begin with {BEGIN_REPLY_MARKER} and end with {END_REPLY_MARKER}.
The JSON must parse directly without literal escaped newlines outside JSON strings.
The schema must be exactly {REPLY_SCHEMA}.
request_id must be exactly {request_id}.
correlation_id must be exactly {request_id}.
artifacts must contain exactly one ZIP candidate named {output_filename} with its existing real downloadable URL.
If that exact existing artifact cannot be referenced, return status failed, result_type test_report, and artifacts as an empty array.
"""


async def cmd_test_artifact_roundtrip(args: argparse.Namespace) -> int:
    payload = artifact_roundtrip_smoke(
        repo_path=getattr(args, "path", "."),
        profile_dir=getattr(args, "profile_dir", None),
        run_id=getattr(args, "run_id", None),
    )
    if getattr(args, "json", False):
        print(json.dumps(payload, indent=2, ensure_ascii=False))
    else:
        print(f"artifact-roundtrip: {payload.get('status')} steps={payload.get('step_count')} failures={payload.get('failure_count')}")
        for step in payload.get("steps", []):
            if isinstance(step, dict):
                print(f"- {step.get('name')}: {step.get('status')}")
    return 0 if payload.get("ok") else 1


async def cmd_test_visual_artifact_roundtrip(backend: CommandBackend, args: argparse.Namespace) -> int:
    """Visible local ZIP send/retrieve proof.

    The live browser-backed test runs in a run-scoped delete-frozen ChatGPT
    Project by default.  The project-scoped conversation URL is important:
    ChatGPT artifact links are conversation/project scoped, and the
    browser-assisted downloader cannot reliably retrieve a generated ZIP from
    a plain chatgpt.com task.
    """

    total_started_at = time.monotonic()
    phase_timings: dict[str, Any] = {}

    run_id = _visual_artifact_roundtrip_run_id(getattr(args, "run_id", None))
    input_entry = Path(str(getattr(args, "input_entry", "input.txt") or "input.txt")).name or "input.txt"
    output_entry = Path(str(getattr(args, "expect_entry", "output.txt") or "output.txt")).name or "output.txt"
    input_content = str(getattr(args, "input_content", None) or f"ZIP_VISUAL_ROUNDTRIP_INPUT_OK_{run_id}")
    output_content = str(getattr(args, "expect_content", None) or f"ZIP_VISUAL_ROUNDTRIP_OUTPUT_OK_{run_id}")
    output_filename = Path(str(getattr(args, "output_filename", None) or f"pb_visual_artifact_roundtrip_{run_id}.zip")).name
    if not output_filename.endswith(".zip"):
        output_filename += ".zip"

    input_zip_started_at = time.monotonic()
    temp_root = Path(tempfile.mkdtemp(prefix="promptbranch_visual_artifact_roundtrip_"))
    input_zip = _create_visual_roundtrip_input_zip(
        run_id=run_id,
        input_entry=input_entry,
        input_content=input_content,
        work_dir=temp_root,
    )
    phase_timings["input_zip_seconds"] = _elapsed_seconds_since(input_zip_started_at)
    prompt = _visual_artifact_roundtrip_prompt(
        run_id=run_id,
        input_entry=input_entry,
        input_content=input_content,
        output_filename=output_filename,
        output_entry=output_entry,
        output_content=output_content,
    )

    profile_dir = str(getattr(args, "profile_dir", "") or "")
    resolved_profile_dir = resolve_profile_dir(getattr(args, "profile_dir", None))
    service_transport_used = isinstance(backend, ServiceBackend)
    physical_profile_dir = "/app/profile" if service_transport_used else str(resolved_profile_dir)
    profile_resolution_mode = (
        "exact_resolved_slot_without_profile_lease"
        if _is_resolved_profile_pool_slot(resolved_profile_dir) and getattr(args, "profile_lease", None) is None
        else "leased_or_unresolved_profile"
    )
    original_snapshot = backend.state_snapshot() if hasattr(backend, "state_snapshot") else {}
    explicit_conversation_url = getattr(args, "conversation_url", None)
    test_project_created = False
    test_project_removed = False
    test_project_url: str | None = None
    test_project_name: str | None = None
    setup_result: dict[str, Any] | None = None
    cleanup_result: dict[str, Any] | None = None
    project_setup_strategy = _live_test_project_setup_strategy(args)
    ask_result: Any = None
    answer_text: str | None = None
    conversation_url: str | None = None
    parsed: dict[str, Any] | None = None
    reply_parse_diagnostics: dict[str, Any] | None = None
    malformed_envelope_retry: dict[str, Any] | None = None
    intake: dict[str, Any] | None = None
    download: dict[str, Any] | None = None
    verified: dict[str, Any] | None = None
    response_project_home_url: str | None = None
    in_expected_project = True
    expected_project_id: str | None = None
    response_project_id: str | None = None

    ask_equivalent_command = (
        "pb ask --debug-browser "
        f"--profile-dir {shlex.quote(str(resolved_profile_dir))} "
        f"--attach {shlex.quote(str(input_zip))} "
        "--keep-open "
        f"--text {shlex.quote('Promptbranch visual artifact roundtrip prompt')}"
    )
    intake_equivalent_command = (
        "pb artifact intake --from-last-answer --download --verify-smoke-zip "
        f"--expect-entry {shlex.quote(output_entry)} "
        f"--expect-content {shlex.quote(output_content)} --json"
    )

    async def emit_failure(status: str, *, error: str | None = None, error_type: str | None = None, extra: dict[str, Any] | None = None) -> int:
        nonlocal cleanup_result, test_project_removed
        if test_project_created and not bool(getattr(args, "keep_project", False)) and not test_project_removed:
            cleanup_started_at = time.monotonic()
            try:
                cleanup_result = await backend.remove_project(keep_open=False)
                test_project_removed = bool(cleanup_result.get("ok", True))
                phase_timings["cleanup_seconds"] = _elapsed_seconds_since(cleanup_started_at)
            except Exception as exc:  # noqa: BLE001 - cleanup failure must be included in the emitted failure payload
                cleanup_result = {
                    "ok": False,
                    "status": "test_project_cleanup_failed",
                    "error": str(exc),
                    "error_type": exc.__class__.__name__,
                }
                test_project_removed = False
        cleanup_ok = True
        if test_project_created and not bool(getattr(args, "keep_project", False)):
            cleanup_ok = bool(test_project_removed)
        failure_rate_limit_telemetry = _merge_rate_limit_telemetry(setup_result, ask_result, download, verified, cleanup_result)
        failure_rate_limit_contaminated = _rate_limit_telemetry_contaminated(failure_rate_limit_telemetry)
        emitted_status = status if cleanup_ok else "cleanup_failed"
        failure_rate_limit_recovered = _rate_limit_telemetry_recovered(failure_rate_limit_telemetry)
        emitted_status = _rate_limit_contamination_status(
            emitted_status,
            contaminated=failure_rate_limit_contaminated,
            recovered=failure_rate_limit_recovered,
        )
        payload = {
            "ok": False,
            "action": "test_visual_artifact_roundtrip",
            "profile": getattr(args, "result_profile", None) or "visual-artifact-roundtrip",
            "status": emitted_status,
            "version": f"v{CLI_VERSION}",
            "run_id": run_id,
            "debug_browser": True,
            "service_transport_used": service_transport_used,
            "mode": "docker_service_exact_profile" if service_transport_used else "visible_local_debug_browser",
            "profile_dir": profile_dir,
            "physical_profile_dir": physical_profile_dir,
            "profile_resolution_mode": profile_resolution_mode,
        "state_profile_dir": str(resolve_profile_dir(getattr(args, "profile_dir", None))),
        "profile_lease": getattr(args, "profile_lease", None),
            "input_zip": str(input_zip),
            "phase_timings": _phase_timings_with_total(phase_timings, total_started_at),
            "input_entry": input_entry,
            "input_content": input_content,
            "expected_output_filename": output_filename,
            "expected_entry": output_entry,
            "expected_content": output_content,
            "conversation_url": conversation_url,
            "response_project_home_url": response_project_home_url,
            "expected_project_home_url": project_home_url_from_url(test_project_url) or test_project_url,
            "expected_project_id": expected_project_id,
            "response_project_id": response_project_id,
            "in_expected_project": in_expected_project,
            "uses_temporary_project": not bool(explicit_conversation_url),
            "uses_retained_delete_frozen_project": _delete_frozen_uses_retained_project(args),
            "cleanup_policy": getattr(args, "cleanup_policy", DELETE_FROZEN_LIVE_TEST_CLEANUP_POLICY),
            "test_project_name": test_project_name,
            "test_project_url": test_project_url,
            "test_project_setup_strategy": project_setup_strategy,
            "test_project_identity_source": "explicit_conversation_url" if explicit_conversation_url else "created_project_url",
            "test_project_created": test_project_created,
            "test_project_removed": test_project_removed,
            "test_project_kept": bool(getattr(args, "keep_project", False)),
            "test_project_setup": setup_result,
            "test_project_cleanup": cleanup_result,
            "ask_equivalent_command": ask_equivalent_command,
            "intake_equivalent_command": intake_equivalent_command,
            "error": error,
            "error_type": error_type,
            "reply_parse_diagnostics": reply_parse_diagnostics,
            "malformed_envelope_retry": malformed_envelope_retry,
            "ask_result_summary": {
                "type": ask_result.__class__.__name__ if ask_result is not None else None,
                "ok": ask_result.get("ok") if isinstance(ask_result, dict) else None,
            },
            "rate_limit_telemetry": failure_rate_limit_telemetry,
            "rate_limit_contaminated": failure_rate_limit_contaminated,
            "rate_limit_recovered": failure_rate_limit_recovered,
            "rate_limit_policy": "visual-artifact-roundtrip treats functionally verified runs with acknowledged/waited 429 telemetry as verified_with_recovered_rate_limit; unrecovered 429 evidence remains non-clean",
            "operator_note": _delete_frozen_live_test_operator_note(str(getattr(args, "result_profile", None) or "visual-artifact-roundtrip")),
        }
        if isinstance(extra, dict):
            payload.update(extra)
        if getattr(args, "json", False):
            print(json.dumps(payload, indent=2, ensure_ascii=False))
        else:
            print(f"visual-artifact-roundtrip: {payload['status']}")
            if payload.get("error"):
                print(f"error={payload['error']}")
        return 1

    try:
        project_setup_started_at = time.monotonic()
        if explicit_conversation_url:
            test_project_url = project_home_url_from_url(explicit_conversation_url) or explicit_conversation_url
            test_project_name = "explicit-conversation-url"
            setattr(args, "conversation_url", explicit_conversation_url)
            phase_timings["project_setup_seconds"] = _elapsed_seconds_since(project_setup_started_at)
        else:
            prefix = str(getattr(args, "project_name_prefix", None) or "visual-artifact-roundtrip-temp")
            test_project_name = str(
                getattr(args, "project_name", None)
                or _bounded_generated_chatgpt_project_name(prefix, run_id)
            )
            setup_result = await backend.create_project(
                name=test_project_name,
                icon=getattr(args, "project_icon", None),
                color=getattr(args, "project_color", None),
                memory_mode=getattr(args, "memory_mode", "project-only"),
                keep_open=False,
            )
            if not setup_result.get("ok"):
                phase_timings["project_setup_seconds"] = _elapsed_seconds_since(project_setup_started_at)
                return await emit_failure(
                    "test_project_setup_failed",
                    error=str(setup_result.get("error") or setup_result.get("status") or "test project setup failed"),
                    error_type=str(setup_result.get("error_type") or "ProjectSetupFailed"),
                )
            test_project_created = True
            test_project_url = setup_result.get("project_url") if isinstance(setup_result.get("project_url"), str) else None
            if not test_project_url:
                phase_timings["project_setup_seconds"] = _elapsed_seconds_since(project_setup_started_at)
                return await emit_failure(
                    "test_project_url_missing",
                    error="temporary project setup did not return project_url",
                    error_type="ProjectUrlMissing",
                )
            setattr(args, "conversation_url", test_project_url)
            phase_timings["project_setup_seconds"] = _elapsed_seconds_since(project_setup_started_at)

        ask_started_at = time.monotonic()
        ask_result = await backend.ask(
            prompt=prompt,
            attachment_paths=[str(input_zip)],
            conversation_url=getattr(args, "conversation_url", None),
            expect_json=False,
            keep_open=bool(getattr(args, "keep_open", False)),
            retries=getattr(args, "retries", None),
        )
        answer_text, conversation_url = _split_ask_response(ask_result)
        phase_timings["ask_seconds"] = _elapsed_seconds_since(ask_started_at)
        if isinstance(ask_result, dict) and ask_result.get("ok") is False and not conversation_url:
            return await emit_failure(
                "ask_failed",
                error=str(ask_result.get("error") or ask_result.get("status") or "visual artifact roundtrip ask failed before returning a project conversation_url"),
                error_type=str(ask_result.get("error_type") or ask_result.get("status") or "AskFailed"),
                extra={
                    "answer_text_length": len(str(answer_text or "")),
                    "ask_result_status": ask_result.get("status"),
                    "ask_result_conversation_url": ask_result.get("conversation_url"),
                    "ask_result_submit_confirmed": (ask_result.get("submit_evidence") or {}).get("submit_confirmed") if isinstance(ask_result.get("submit_evidence"), dict) else None,
                    "ask_result_submit_reason": (ask_result.get("submit_evidence") or {}).get("submit_causal_confirmation_reason") if isinstance(ask_result.get("submit_evidence"), dict) else None,
                    "ask_result_attachment_fallback_status": (ask_result.get("ask_phase_timings") or {}).get("attachment_visible_answer_fallback_status") if isinstance(ask_result.get("ask_phase_timings"), dict) else None,
                    "ask_result_attachment_fallback_current_url": (ask_result.get("ask_phase_timings") or {}).get("attachment_visible_answer_fallback_current_url") if isinstance(ask_result.get("ask_phase_timings"), dict) else None,
                    "ask_result_attachment_fallback_post_response_url": (ask_result.get("ask_phase_timings") or {}).get("attachment_visible_answer_fallback_post_response_url") if isinstance(ask_result.get("ask_phase_timings"), dict) else None,
                },
            )
        response_project_home_url = project_home_url_from_url(conversation_url)
        in_expected_project, expected_project_id, response_project_id = _ask_live_in_expected_project(
            expected_project_home_url=project_home_url_from_url(test_project_url) or test_project_url,
            response_project_home_url=response_project_home_url,
        )
        if not in_expected_project:
            return await emit_failure(
                "wrong_project",
                error="visual artifact roundtrip answer came from a conversation outside the expected project",
                error_type="WrongProject",
                extra={"answer_text_length": len(str(answer_text or ""))},
            )

        parse_started_at = time.monotonic()
        expected_request_id = f"visual-artifact-roundtrip-{run_id}"
        parsed, reply_parse_diagnostics = _visual_reply_parse_with_bounded_normalization(
            str(answer_text or ""),
            expected_request_id=expected_request_id,
        )
        if not parsed.get("ok") or parsed.get("request_id") != expected_request_id or parsed.get("correlation_id") != expected_request_id:
            retry_started_at = time.monotonic()
            retry_prompt = _visual_artifact_roundtrip_envelope_retry_prompt(
                request_id=expected_request_id,
                output_filename=output_filename,
            )
            retry_result = await backend.ask(
                prompt=retry_prompt,
                attachment_paths=None,
                conversation_url=conversation_url,
                expect_json=False,
                keep_open=bool(getattr(args, "keep_open", False)),
                retries=0,
                service_timeout_seconds=90.0,
            )
            retry_answer_text, retry_conversation_url = _split_ask_response(retry_result)
            phase_timings["malformed_envelope_retry_seconds"] = _elapsed_seconds_since(retry_started_at)
            retry_parsed, retry_diagnostics = _visual_reply_parse_with_bounded_normalization(
                str(retry_answer_text or ""),
                expected_request_id=expected_request_id,
            )
            malformed_envelope_retry = {
                "attempted": True,
                "max_attempts": 1,
                "bounded_service_timeout_seconds": 90.0,
                "result_ok": retry_result.get("ok") if isinstance(retry_result, dict) else None,
                "answer_text_length": len(str(retry_answer_text or "")),
                "conversation_url_preserved": bool(retry_conversation_url == conversation_url),
                "parse_diagnostics": retry_diagnostics,
            }
            if retry_conversation_url and retry_conversation_url != conversation_url:
                return await emit_failure(
                    "malformed_envelope_retry_wrong_conversation",
                    error="bounded malformed-envelope retry returned a different conversation",
                    error_type="WrongConversation",
                    extra={
                        "answer_text_length": len(str(answer_text or "")),
                        "reply_parse_diagnostics": reply_parse_diagnostics,
                        "malformed_envelope_retry": malformed_envelope_retry,
                    },
                )
            parsed = retry_parsed
            answer_text = retry_answer_text
            reply_parse_diagnostics = {
                "initial": reply_parse_diagnostics,
                "retry": retry_diagnostics,
                "status": "valid_after_single_bounded_retry" if retry_parsed.get("ok") else "invalid_after_single_bounded_retry",
            }
        else:
            malformed_envelope_retry = {"attempted": False, "max_attempts": 1}

        intake = _artifact_intake_from_parsed_answer(parsed, expected_filename=output_filename)
        phase_timings["reply_parse_seconds"] = _elapsed_seconds_since(parse_started_at)
        if not intake.get("ok") or int(intake.get("valid_zip_candidate_count") or 0) != 1:
            return await emit_failure(
                "artifact_candidate_not_selected",
                error=str(intake.get("status") or parsed.get("status") or "exactly one valid ZIP candidate was not available"),
                error_type="ArtifactCandidateInvalid",
                extra={
                    "answer_text_length": len(str(answer_text or "")),
                    "reply_parse_diagnostics": reply_parse_diagnostics,
                    "malformed_envelope_retry": malformed_envelope_retry,
                    "parsed_reply": parsed,
                    "artifact_intake": intake,
                    "download_performed": False,
                    "verification_performed": False,
                },
            )
        conversation_id = conversation_id_from_url(conversation_url or "") or "conversation_unknown"
        answer_id = parsed.get("answer_id") or "answer_unknown"
        intake.update({
            "conversation_url": conversation_url,
            "conversation_id": conversation_id,
            "answer_id": answer_id,
            "reply_request_id": parsed.get("request_id"),
            "reply_correlation_id": parsed.get("correlation_id"),
            "source": "visual_artifact_roundtrip_ask_answer",
        })

        download_started_at = time.monotonic()
        download = await _download_selected_artifact_candidate_via_browser(
            backend,
            intake,
            profile_dir=getattr(args, "profile_dir", None) or PROFILE_DIR_NAME,
            conversation_id=conversation_id,
            answer_id=answer_id,
            timeout_seconds=float(getattr(args, "download_timeout", 120.0) or 120.0),
            keep_open=bool(getattr(args, "keep_open", False)),
        )
        phase_timings["artifact_download_seconds"] = _elapsed_seconds_since(download_started_at)
        verification_started_at = time.monotonic()
        verified = _verify_intake_smoke_zip_candidate(
            download,
            profile_dir=getattr(args, "profile_dir", None) or PROFILE_DIR_NAME,
            conversation_id=conversation_id,
            answer_id=answer_id,
            expected_entries=[output_entry],
            expected_content=output_content,
        )
        verified = _artifact_intake_no_state_mutation_flags(verified)
        phase_timings["smoke_verify_seconds"] = _elapsed_seconds_since(verification_started_at)
    except Exception as exc:  # noqa: BLE001 - live browser test must report structured failures
        return await emit_failure(
            "ask_or_intake_failed",
            error=str(exc),
            error_type=exc.__class__.__name__,
        )
    finally:
        if test_project_created and not bool(getattr(args, "keep_project", False)) and not test_project_removed:
            cleanup_started_at = time.monotonic()
            try:
                cleanup_result = await backend.remove_project(keep_open=False)
                test_project_removed = bool(cleanup_result.get("ok", True))
                phase_timings["cleanup_seconds"] = _elapsed_seconds_since(cleanup_started_at)
            except Exception as exc:  # noqa: BLE001 - cleanup failure must be reported, not raised
                cleanup_result = {
                    "ok": False,
                    "status": "test_project_cleanup_failed",
                    "error": str(exc),
                    "error_type": exc.__class__.__name__,
                }
                phase_timings["cleanup_seconds"] = _elapsed_seconds_since(cleanup_started_at)
        _restore_ask_live_state(backend, original_snapshot if isinstance(original_snapshot, dict) else {})
        if explicit_conversation_url:
            setattr(args, "conversation_url", explicit_conversation_url)

    cleanup_ok = True
    if test_project_created and not bool(getattr(args, "keep_project", False)):
        cleanup_ok = bool(test_project_removed)
    rate_limit_telemetry = _merge_rate_limit_telemetry(setup_result, ask_result, download, verified, cleanup_result)
    rate_limit_contaminated = _rate_limit_telemetry_contaminated(rate_limit_telemetry)
    rate_limit_recovered = _rate_limit_telemetry_recovered(rate_limit_telemetry)
    functional_ok = bool(verified and verified.get("ok") and cleanup_ok)
    ok = bool(functional_ok and (not rate_limit_contaminated or rate_limit_recovered))
    if not cleanup_ok:
        status = "cleanup_failed"
    elif verified and verified.get("ok") and rate_limit_contaminated and rate_limit_recovered:
        status = "verified_with_recovered_rate_limit"
    elif verified and verified.get("ok") and rate_limit_contaminated:
        status = "rate_limited_contaminated"
    elif verified and verified.get("ok"):
        status = "verified"
    else:
        status = (verified or {}).get("status") or "failed"
    conversation_id = conversation_id_from_url(conversation_url or "") or "conversation_unknown"
    payload = {
        "ok": ok,
        "action": "test_visual_artifact_roundtrip",
        "profile": getattr(args, "result_profile", None) or "visual-artifact-roundtrip",
        "status": status,
        "version": f"v{CLI_VERSION}",
        "run_id": run_id,
        "debug_browser": True,
        "service_transport_used": service_transport_used,
        "mode": "docker_service_exact_profile" if service_transport_used else "visible_local_debug_browser",
        "profile_dir": profile_dir,
        "physical_profile_dir": physical_profile_dir,
        "profile_resolution_mode": profile_resolution_mode,
        "state_profile_dir": str(resolve_profile_dir(getattr(args, "profile_dir", None))),
        "profile_lease": getattr(args, "profile_lease", None),
        "input_zip": str(input_zip),
        "phase_timings": _phase_timings_with_total(phase_timings, total_started_at),
        "input_entry": input_entry,
        "input_content": input_content,
        "expected_output_filename": output_filename,
        "expected_entry": output_entry,
        "expected_content": output_content,
        "conversation_url": conversation_url,
        "conversation_id": conversation_id,
        "response_project_home_url": response_project_home_url,
        "expected_project_home_url": project_home_url_from_url(test_project_url) or test_project_url,
        "expected_project_id": expected_project_id,
        "response_project_id": response_project_id,
        "in_expected_project": in_expected_project,
        "uses_temporary_project": not bool(explicit_conversation_url),
            "uses_retained_delete_frozen_project": _delete_frozen_uses_retained_project(args),
            "cleanup_policy": getattr(args, "cleanup_policy", DELETE_FROZEN_LIVE_TEST_CLEANUP_POLICY),
        "test_project_name": test_project_name,
        "test_project_url": test_project_url,
        "test_project_setup_strategy": project_setup_strategy,
        "test_project_identity_source": "explicit_conversation_url" if explicit_conversation_url else "created_project_url",
        "test_project_created": test_project_created,
        "test_project_removed": test_project_removed,
        "test_project_kept": bool(getattr(args, "keep_project", False)),
        "test_project_setup": setup_result,
        "test_project_cleanup": cleanup_result,
        "answer_text_length": len(str(answer_text or "")),
        "reply_parse_status": (parsed or {}).get("status"),
        "artifact_candidate_status": (intake or {}).get("status"),
        "download_status": (download or {}).get("status"),
        "verification_status": (verified or {}).get("status"),
        "functional_status": "verified" if functional_ok else ((verified or {}).get("status") or "failed"),
        "rate_limit_telemetry": rate_limit_telemetry,
        "rate_limit_contaminated": rate_limit_contaminated,
        "rate_limit_recovered": rate_limit_recovered,
        "rate_limit_policy": "visual-artifact-roundtrip treats functionally verified runs with acknowledged/waited 429 telemetry as verified_with_recovered_rate_limit; unrecovered 429 evidence remains non-clean",
        "download_performed": bool((verified or {}).get("download_performed")),
        "verification_performed": bool((verified or {}).get("smoke_verification_performed") or (verified or {}).get("verification_performed")),
        "download": (verified or {}).get("download"),
        "smoke_verification": (verified or {}).get("smoke_verification"),
        "intake_record_path": (verified or {}).get("intake_record_path"),
        "ask_equivalent_command": ask_equivalent_command,
        "intake_equivalent_command": intake_equivalent_command,
        "ask_result_summary": {
            "type": ask_result.__class__.__name__ if ask_result is not None else None,
            "ok": ask_result.get("ok") if isinstance(ask_result, dict) else None,
        },
        "reply_parse_diagnostics": reply_parse_diagnostics,
        "malformed_envelope_retry": malformed_envelope_retry,
        "parsed_reply": parsed,
        "artifact_intake": verified,
        "operator_note": _delete_frozen_live_test_operator_note(str(getattr(args, "result_profile", None) or "visual-artifact-roundtrip")),
    }
    if getattr(args, "json", False):
        print(json.dumps(payload, indent=2, ensure_ascii=False))
    else:
        print(f"visual-artifact-roundtrip: {payload['status']}")
        print(f"conversation_url={conversation_url or 'unknown'}")
        print(f"test_project={test_project_name or 'none'} removed={test_project_removed}")
        print(f"input_zip={input_zip}")
        print(f"downloaded={((verified or {}).get('download') or {}).get('path') if isinstance((verified or {}).get('download'), dict) else 'unknown'}")
    return 0 if payload.get("ok") else 1



async def cmd_test_api(args: argparse.Namespace) -> int:
    # Run the API coverage runner as an installed package module.
    # The previous v0.1.103.10.18 implementation looked for
    # an installed site-packages script path, but top-level repo
    # scripts are not installed by pipx/setuptools. Keeping this as a module
    # makes `pb test api` work both from a source tree and from an installed wheel.
    cmd = [sys.executable, "-m", "promptbranch.api_coverage_test"]

    # v0.1.103.10.26: `pb test api` is a host-side service client too.  It
    # must use the same normal CLI service config defaults as `pb ask` and
    # other service-backed commands.  Operators keep the bearer token in the
    # mapped promptbranch config volume, not in a repo .env file.  Resolve the
    # child runner's transport flags here, without ever printing or reporting
    # the token value.
    resolved_base_url = (
        getattr(args, "base_url", None)
        or getattr(args, "service_base_url", None)
        or os.getenv("PROMPTBRANCH_SERVICE_BASE_URL")
        or "http://localhost:8000"
    )
    resolved_token = getattr(args, "token", None) or getattr(args, "service_token", None)
    if resolved_base_url:
        cmd.extend(["--base-url", str(resolved_base_url)])
    if resolved_token:
        cmd.extend(["--token", str(resolved_token)])

    option_map = [
        ("state_file", "--state-file"),
        ("project_url", "--project-url"),
        ("conversation_url", "--conversation-url"),
        ("project_name", "--project-name"),
        ("run_id", "--run-id"),
        ("report_dir", "--report-dir"),
        ("timeout_seconds", "--timeout-seconds"),
        ("step_delay_seconds", "--step-delay-seconds"),
        ("ask_token", "--ask-token"),
        ("ask_timeout_seconds", "--ask-timeout-seconds"),
        ("source_file", "--source-file"),
        ("source_name", "--source-name"),
        ("remove_source_name", "--remove-source-name"),
    ]
    for attr, flag in option_map:
        value = getattr(args, attr, None)
        if value is not None and value != "":
            cmd.extend([flag, str(value)])
    if getattr(args, "keep_open", False):
        cmd.append("--keep-open")
    if getattr(args, "no_browser", False):
        cmd.append("--no-browser")
    if getattr(args, "no_ask", False):
        cmd.append("--no-ask")
    if getattr(args, "allow_source_add", False):
        cmd.append("--allow-source-add")
    if getattr(args, "allow_source_remove", False):
        cmd.append("--allow-source-remove")
    if getattr(args, "include_source_gate_test", False):
        cmd.append("--include-source-gate-test")
    if getattr(args, "reuse_held_session", False):
        cmd.append("--reuse-held-session")
    if getattr(args, "no_auto_reuse_compatible_held_session", False):
        cmd.append("--no-auto-reuse-compatible-held-session")
    if getattr(args, "json", False):
        cmd.append("--json")
    if getattr(args, "summary", False):
        cmd.append("--summary")
    completed = subprocess.run(cmd)
    return int(completed.returncode)

async def cmd_test_import_smoke(args: argparse.Namespace) -> int:
    result = package_import_smoke(repo_path=getattr(args, "path", "."), python_executable=getattr(args, "python_executable", None))
    if getattr(args, "json", False):
        print(json.dumps(result, indent=2, ensure_ascii=False))
    else:
        print(f"package_import_smoke: {result.get('status')}")
        for failure in result.get("failures") or []:
            print(f"- {failure.get('module')}: {failure.get('error_type')} {failure.get('error')}")
    return 0 if result.get("ok") else 1


async def cmd_test_impacted(args: argparse.Namespace) -> int:
    try:
        plan = build_impact_plan(
            repo_path=getattr(args, "path", "."),
            base=getattr(args, "base", "HEAD"),
            mode=getattr(args, "mode", "edit"),
            map_path=getattr(args, "map", ".promptbranch/test-impact-map.json"),
        )
        payload = plan if getattr(args, "plan_only", False) else execute_impact_plan(
            plan,
            timeout_seconds=float(getattr(args, "timeout_seconds", 600.0)),
            evidence_dir=getattr(args, "evidence_dir", None),
        )
    except ImpactTestingError as exc:
        payload = {
            "ok": False,
            "action": "test_impacted",
            "status": "impact_plan_blocked",
            "errors": [str(exc)],
            "full_release_validation_required": True,
            "strict_adoption_gate_unchanged": True,
        }
    if getattr(args, "json", False):
        print(json.dumps(payload, indent=2, ensure_ascii=False, sort_keys=True))
    else:
        print(f"status={payload.get('status')}")
        print(f"mode={payload.get('mode')}")
        print(f"selected_groups={','.join(payload.get('selected_groups') or []) or 'none'}")
        for error in payload.get("errors") or []:
            print(f"error={error}", file=sys.stderr)
    return 0 if payload.get("ok") else 1


async def cmd_test(backend: CommandBackend, args: argparse.Namespace) -> int:
    if args.test_command == "impacted":
        return await cmd_test_impacted(args)
    if args.test_command == "report":
        return await cmd_test_report(args)
    if args.test_command == "status":
        return await cmd_test_status(args)
    if args.test_command == "import-smoke":
        return await cmd_test_import_smoke(args)
    if args.test_command == "api":
        return await cmd_test_api(args)
    if args.test_command == "ask-live":
        _apply_delete_frozen_live_test_defaults(args, profile="ask-live")
        return await cmd_test_ask_live(backend, args)
    if args.test_command == "artifact-roundtrip":
        return await cmd_test_artifact_roundtrip(args)
    if args.test_command == "release-live":
        args.result_profile = "release-live"
        if not getattr(args, "project_name_prefix", None):
            args.project_name_prefix = RELEASE_LIVE_DELETE_FROZEN_PROJECT_PREFIX
        _apply_delete_frozen_live_test_defaults(args, profile="release-live")
        return await cmd_test_visual_artifact_roundtrip(backend, args)
    if args.test_command == "release-live-continuous":
        return await cmd_test_release_live_continuous(backend, args)
    if args.test_command == "visual-artifact-roundtrip":
        _apply_delete_frozen_live_test_defaults(args, profile="visual-artifact-roundtrip")
        return await cmd_test_visual_artifact_roundtrip(backend, args)
    if args.test_command == "smoke":
        _apply_test_suite_defaults(args)
        return await cmd_test_smoke(args)
    if args.test_command == "project-source-file-reliability":
        _apply_test_suite_defaults(args)
        return await cmd_test_project_source_file_reliability(args)
    if args.test_command in {"browser", "agent", "full"}:
        _apply_test_suite_defaults(args)
        args.profile = args.test_command
        return await cmd_test_suite(args)
    raise RuntimeError(f"Unknown test command: {args.test_command}")


