def _extract_bootstrap_config(argv: list[str]) -> tuple[Optional[str], Optional[str]]:
    bootstrap = argparse.ArgumentParser(add_help=False)
    bootstrap.add_argument("--dotenv", default=".env")
    bootstrap.add_argument("--config", default=os.getenv("CHATGPT_CLI_CONFIG", DEFAULT_CONFIG_PATH))
    args, _ = bootstrap.parse_known_args(argv)
    return args.dotenv, args.config


def _max_retries_was_configured(argv: list[str]) -> bool:
    if "CHATGPT_MAX_RETRIES" in os.environ:
        return True
    for token in argv:
        if token == "--max-retries" or token.startswith("--max-retries="):
            return True
    return False

def _debug_option_was_provided(argv: list[str]) -> bool:
    return any(token == "--debug" or token.startswith("--debug=") for token in argv)


def _json_output_requested(args: argparse.Namespace) -> bool:
    return bool(getattr(args, "json", False))


def _command_action_name(args: argparse.Namespace) -> str:
    command = str(getattr(args, "command", "command") or "command")
    for attr in ("src_command", "task_command", "parallel_command", "parallel_task_command", "ws_command", "artifact_command", "release_command", "debug_command", "browser_command", "queue_command", "test_command", "agent_command", "skill_command", "mcp_command", "orchestration_command"):
        value = getattr(args, attr, None)
        if value:
            return f"{command}_{value}".replace("-", "_")
    return command.replace("-", "_")


def _http_status_detail_payload(exc: httpx.HTTPStatusError) -> dict[str, Any] | None:
    try:
        raw = exc.response.json()
    except Exception:
        return None
    if not isinstance(raw, dict):
        return None
    detail = raw.get("detail")
    if isinstance(detail, dict):
        payload = dict(detail)
        payload.setdefault("http_status_code", exc.response.status_code)
        return payload
    if detail is not None:
        return {
            "ok": False,
            "status": "service_http_error",
            "error": str(detail),
            "error_type": "HTTPStatusError",
            "http_status_code": exc.response.status_code,
        }
    return None


def _service_exception_payload(exc: Exception, args: argparse.Namespace) -> dict[str, Any] | None:
    action = _command_action_name(args)
    if isinstance(exc, BrowserProfileBusyError):
        payload = exc.to_payload()
        payload.setdefault("action", action)
        return payload
    if isinstance(exc, httpx.HTTPStatusError):
        payload = _http_status_detail_payload(exc)
        if payload is None:
            payload = {
                "ok": False,
                "status": "service_http_error",
                "error": str(exc),
                "error_type": type(exc).__name__,
                "http_status_code": getattr(exc.response, "status_code", None),
            }
        payload.setdefault("ok", False)
        payload.setdefault("action", action)
        if payload.get("status") == "browser_profile_busy":
            payload.setdefault("timeout_layer", "browser_profile_lock")
            payload.setdefault("operator_action", "retry_after_active_browser_operation_or_use_async_job_status")
        return payload
    if isinstance(exc, (httpx.ReadTimeout, httpx.TimeoutException)):
        service_timeout_seconds = float(getattr(args, "service_timeout_seconds", DEFAULT_SERVICE_TIMEOUT_SECONDS) or DEFAULT_SERVICE_TIMEOUT_SECONDS)
        payload: dict[str, Any] = {
            "ok": False,
            "action": action,
            "status": "service_client_read_timeout",
            "error": str(exc) or "service request timed out while waiting for response headers",
            "error_type": type(exc).__name__,
            "timeout_layer": "service_client",
            "service_timeout_seconds": service_timeout_seconds,
            "configured_timeout_seconds": service_timeout_seconds,
            "operator_action": "do_not_assume_failure; inspect task/source state before retrying",
            "recovery_hint": "The browser service may still finish after the CLI timed out. Use task show/message inspection for ask operations; retry browser-backed reads after the active operation completes.",
        }
        if action in {"source_add", "src_add"}:
            file_path = getattr(args, "file", None) or getattr(args, "file_path", None)
            display_name = getattr(args, "name", None) or (Path(file_path).name if file_path else None)
            payload["active_operation"] = {
                "name": "project_source_add",
                "state": "service_request_may_still_be_running",
                "source_kind": getattr(args, "type", None) or "file",
                "file_path": file_path,
                "display_name": display_name,
                "overwrite_existing": not bool(getattr(args, "no_overwrite", False)),
                "project_url": getattr(args, "project_url", None),
                "configured_timeout_seconds": service_timeout_seconds,
            }
            payload["recovery_hint"] = (
                "The Project Source browser operation may still be classifying or rolling back a backend-renamed source. "
                "Do not retry the same filename until the active browser operation is idle and `pb src list --json` has been inspected."
            )
        return payload
    return None


def _emit_service_exception(exc: Exception, args: argparse.Namespace) -> int | None:
    payload = _service_exception_payload(exc, args)
    if payload is None:
        return None
    if _json_output_requested(args):
        print(json.dumps(payload, indent=2, ensure_ascii=False))
    else:
        status_text = payload.get("status") or "service_error"
        print(f"{status_text}: {payload.get('error') or exc}", file=sys.stderr)
        if payload.get("active_operation"):
            print(f"active_operation={payload.get('active_operation')}", file=sys.stderr)
        if payload.get("challenge_type"):
            print(f"challenge_type={payload.get('challenge_type')}", file=sys.stderr)
        if payload.get("retry_after_seconds") is not None:
            print(f"retry_after_seconds={payload.get('retry_after_seconds')}", file=sys.stderr)
        if payload.get("recovery_hint"):
            print(str(payload.get("recovery_hint")), file=sys.stderr)
    return 75 if payload.get("status") == "browser_profile_busy" else 12



def _try_handle_help_command(parser: argparse.ArgumentParser, argv: list[str]) -> Optional[int]:
    if not argv or argv[0] != "help":
        return None
    help_target = argv[1:]
    if not help_target or help_target[0] in {"-h", "--help"}:
        parser.print_help()
        return 0
    try:
        parser.parse_args([help_target[0], "--help", *help_target[1:]])
    except SystemExit as exc:
        return int(exc.code)
    return 0


async def _async_main(args: argparse.Namespace) -> int:
    if args.command == "version":
        print(f"promptbranch {CLI_VERSION}")
        return 0
    if args.command == "completion":
        print(_render_completion(args.shell, _cli_command_name()), end="")
        return 0
    if args.command == "test-suite":
        return await cmd_test_suite(args)
    if args.command == "test" and getattr(args, "test_command", None) == "smoke":
        _apply_test_suite_defaults(args)
        return await cmd_test_smoke(args)
    if args.command == "test" and getattr(args, "test_command", None) == "report":
        return await cmd_test_report(args)
    if args.command == "test" and getattr(args, "test_command", None) == "status":
        return await cmd_test_status(args)
    if args.command == "test" and getattr(args, "test_command", None) == "import-smoke":
        return await cmd_test_import_smoke(args)
    if args.command == "profile":
        return await cmd_profile(args)
    if args.command == "queue":
        return await cmd_queue(args)

    _apply_protocol_timeout(args)
    profile_lease: PromptbranchProfileLease | None = None
    try:
        lease_settings = _profile_lease_settings_from_args(args)
        if lease_settings:
            profile_resolution_mode = str(lease_settings.pop("profile_resolution_mode", "direct_profile"))
            profile_lease = PromptbranchProfileLease(**lease_settings)
            profile_lease.__enter__()
            args._browser_profile_dir = str(profile_lease.leased_profile_dir or lease_settings.get("profile_dir"))
            args.profile_lease = profile_lease.to_payload(ok=True)
            args.profile_lease["profile_resolution_mode"] = profile_resolution_mode
            # Profile-pool slots are local filesystem browser profiles. Most
            # headed live commands intentionally run through the direct local
            # browser backend.  release-live-continuous is the exception: release
            # control maps the exact slot to /app/profile and routes it through
            # the Docker service so preflight and continuous validation share the
            # same browser envelope.
            if (lease_settings.get("pool_name") or bool(getattr(args, "profile_lease", False))) and not (getattr(args, "command", None) == "test" and getattr(args, "test_command", None) == "release-live-continuous"):
                args.service_base_url = None
        backend = build_backend(args)
        if args.command == "login-check":
            return await cmd_login_check(backend, args)
        if args.command == "ws":
            return await cmd_ws(backend, args)
        if args.command == "task":
            return await cmd_task(backend, args)
        if args.command == "parallel":
            return await cmd_parallel(backend, args)
        if args.command == "src":
            return await cmd_src(backend, args)
        if args.command == "application":
            return await cmd_application(backend, args)
        if args.command == "project":
            return await cmd_project(backend, args)
        if args.command == "repo":
            return await cmd_repo(backend, args)
        if args.command == "artifact":
            return await cmd_artifact(backend, args)
        if args.command == "orchestration":
            return await cmd_orchestration(backend, args)
        if args.command == "ask-release":
            return await cmd_ask_release(backend, args)
        if args.command == "release":
            return await cmd_release(backend, args)
        if args.command == "agent":
            return await cmd_agent(backend, args)
        if args.command == "skill":
            return await cmd_skill(backend, args)
        if args.command == "mcp":
            return await cmd_mcp(backend, args)
        if args.command == "test":
            return await cmd_test(backend, args)
        if args.command == "doctor":
            return await cmd_doctor(backend, args)
        if args.command == "debug":
            return await cmd_debug(backend, args)
        if args.command == "browser":
            return await cmd_browser(backend, args)
        if args.command == "project-create":
            return await cmd_project_create(backend, args)
        if args.command == "project-list":
            return await cmd_project_list(backend, args)
        if args.command == "project-resolve":
            return await cmd_project_resolve(backend, args)
        if args.command == "project-ensure":
            return await cmd_project_ensure(backend, args)
        if args.command == "project-remove":
            return await cmd_project_remove(backend, args)
        if args.command == "project-source-add":
            return await cmd_project_source_add(backend, args)
        if args.command == "project-source-list":
            return await cmd_project_source_list(backend, args)
        if args.command == "project-source-remove":
            return await cmd_project_source_remove(backend, args)
        if args.command in {"chat-list", "chats"}:
            return await cmd_chat_list(backend, args)
        if args.command in {"chat-use", "use-chat"}:
            return await cmd_chat_use(backend, args)
        if args.command in {"chat-leave", "cq"}:
            return await cmd_chat_leave(backend, args)
        if args.command in {"chat-show", "show"}:
            return await cmd_chat_show(backend, args)
        if args.command in {"chat-summarize", "summarize"}:
            return await cmd_chat_summarize(backend, args)
        if args.command == "loop":
            return await cmd_loop(backend, args)
        if args.command == "state":
            return await cmd_state(backend, args)
        if args.command == "prompt":
            return await cmd_prompt(backend, args)
        if args.command == "state-clear":
            return await cmd_state_clear(backend, args)
        if args.command == "use":
            return await cmd_use(backend, args)
        if args.command == "completion":
            return await cmd_completion(backend, args)
        if args.command == "version":
            print(f"promptbranch {CLI_VERSION}")
            return 0
        if args.command == "test-suite":
            return await cmd_test_suite(args)
        if args.command == "ask":
            return await cmd_ask(backend, args)
        if args.command == "shell":
            return await cmd_shell(backend, args)
        raise RuntimeError(f"Unknown command: {args.command}")
    except ProjectRegistryResolutionError as exc:
        payload = dict(exc.payload)
        payload["command"] = getattr(args, "command", None)
        if _json_output_requested(args):
            print(json.dumps(payload, indent=2, ensure_ascii=False))
        else:
            print(f"{payload.get('status')}: {payload.get('error')}", file=sys.stderr)
        return 2
    except ArtifactRegistryStateError as exc:
        payload = exc.to_payload(action="artifact_registry")
        payload["command"] = getattr(args, "command", None)
        if _json_output_requested(args):
            print(json.dumps(payload, indent=2, ensure_ascii=False))
        else:
            print(f"{payload.get('status')}: {payload.get('error')}", file=sys.stderr)
        return 2
    except ProfileLeaseError as exc:
        return _emit_profile_lease_error(exc, args)
    finally:
        if profile_lease is not None:
            profile_lease.release()

def main(argv: Optional[list[str]] = None) -> int:
    raw_argv = list(sys.argv[1:] if argv is None else argv)
    normalized_argv = _normalize_global_options(raw_argv)

    dotenv_path, _ = _extract_bootstrap_config(normalized_argv)
    if dotenv_path:
        load_dotenv(dotenv_path, override=False)

    parser = make_parser()
    help_exit_code = _try_handle_help_command(parser, normalized_argv)
    if help_exit_code is not None:
        return help_exit_code
    args = parser.parse_args(normalized_argv)
    args = _apply_cli_config_defaults(args, normalized_argv)
    args._profile_dir_explicit = _option_was_provided(normalized_argv, "--profile-dir")
    if getattr(args, "command", None) == "test" and getattr(args, "test_command", None) in {"ask-live", "visual-artifact-roundtrip", "release-live"}:
        args.debug_browser = True
        args.headless = False
        if not _option_was_provided(normalized_argv, "--profile-dir"):
            args.profile_dir = "./.pb_profile_local_debug"
    args.profile_dir = str(resolve_profile_dir(args.profile_dir))
    debug_option_provided = _debug_option_was_provided(normalized_argv)
    if _json_output_requested(args) and not debug_option_provided:
        args.debug = False
    if args.debug and not _max_retries_was_configured(normalized_argv):
        args.max_retries = 1
    _configure_logging(args.debug)

    try:
        return asyncio.run(_async_main(args))
    except (BrowserProfileBusyError, httpx.HTTPStatusError, httpx.ReadTimeout, httpx.TimeoutException) as exc:
        handled = _emit_service_exception(exc, args)
        if handled is not None:
            return handled
        raise
    except AuthChallengeRequiredError as exc:
        payload = exc.to_payload()
        if _json_output_requested(args):
            print(json.dumps(payload, indent=2, ensure_ascii=False))
        else:
            print(f"auth challenge required: {exc}", file=sys.stderr)
            if payload.get("challenge_type"):
                print(f"challenge_type={payload.get('challenge_type')}", file=sys.stderr)
        return 10
    except ManualLoginRequiredError as exc:
        print(f"manual login required: {exc}", file=sys.stderr)
        return 10
    except BotChallengeError as exc:
        print(f"browser challenge detected: {exc}", file=sys.stderr)
        return 11
    except ResponseTimeoutError as exc:
        print(f"response timeout: {exc}", file=sys.stderr)
        return 12
    except UnsupportedOperationError as exc:
        print(f"unsupported operation: {exc}", file=sys.stderr)
        return 15
    except AuthenticationError as exc:
        print(f"authentication error: {exc}", file=sys.stderr)
        return 13
    except FileNotFoundError as exc:
        print(f"file not found: {exc}", file=sys.stderr)
        return 14


if __name__ == "__main__":
    raise SystemExit(main())
